


SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "public";


ALTER SCHEMA "public" OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."maintenance_custom_proposals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "company_id" "uuid" NOT NULL,
    "plan_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "titulo" "text" NOT NULL,
    "descripcion_necesidad" "text",
    "objetivos" "text",
    "prioridades" "text",
    "soluciones_actuales" "text",
    "proyectos_relacionados" "text",
    "automatizaciones_actuales" "text",
    "integraciones_actuales" "text",
    "tecnologias" "text",
    "sistemas_criticos" "text",
    "alcance_tecnico_solicitado" "text",
    "horas_mensuales_solicitadas" numeric(8,2),
    "tipo_trabajo" "text",
    "nivel_soporte_solicitado" "text",
    "tiempo_respuesta_deseado" "text",
    "horario_soporte" "text",
    "soporte_fuera_horario" boolean DEFAULT false NOT NULL,
    "sla_solicitado" "text",
    "nivel_criticidad" "text",
    "impacto_incidencia" "text",
    "necesidad_monitorizacion" boolean DEFAULT false NOT NULL,
    "requisitos_seguridad" "text",
    "informacion_adicional" "text",
    "request_data" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "quoted_monthly_price" numeric(12,2),
    "quoted_currency" "text" DEFAULT 'EUR'::"text" NOT NULL,
    "quoted_hours_monthly" numeric(8,2),
    "quoted_scope_level" "text",
    "quoted_service_level" "text",
    "quoted_sla" "text",
    "quoted_response_time" "text",
    "quoted_support_hours" "text",
    "quoted_description" "text",
    "quoted_terms" "text",
    "quoted_valid_until" "date",
    "quote_snapshot" "jsonb",
    "accepted_at" timestamp with time zone,
    "accepted_by" "uuid",
    "rejected_at" timestamp with time zone,
    "rejected_by" "uuid",
    "rejection_reason" "text",
    "maintenance_contract_id" "uuid",
    "stripe_product_id" "text",
    "stripe_price_id" "text",
    "stripe_customer_id" "text",
    "stripe_subscription_id" "text",
    "stripe_subscription_item_id" "text",
    "submitted_at" timestamp with time zone,
    "reviewed_at" timestamp with time zone,
    "quoted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "reviewed_by" "uuid",
    "quoted_by" "uuid",
    "clarification_requested_at" timestamp with time zone,
    "clarification_requested_by" "uuid",
    "clarification_message" "text",
    "response_notes" "text",
    "response_version" integer DEFAULT 0 NOT NULL,
    "current_document_id" "uuid",
    CONSTRAINT "maintenance_custom_proposals_clarification_message_check" CHECK ((("clarification_message" IS NULL) OR (("length"("btrim"("clarification_message")) > 0) AND ("length"("clarification_message") <= 4000)))),
    CONSTRAINT "maintenance_custom_proposals_currency_check" CHECK (("quoted_currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "maintenance_custom_proposals_hours_check" CHECK ((("horas_mensuales_solicitadas" IS NULL) OR ("horas_mensuales_solicitadas" > (0)::numeric))),
    CONSTRAINT "maintenance_custom_proposals_hours_upper_bound_check" CHECK ((("horas_mensuales_solicitadas" IS NULL) OR (("horas_mensuales_solicitadas" > (0)::numeric) AND ("horas_mensuales_solicitadas" <= (744)::numeric)))),
    CONSTRAINT "maintenance_custom_proposals_plan_custom_check" CHECK (("plan_id" IS NOT NULL)),
    CONSTRAINT "maintenance_custom_proposals_price_check" CHECK ((("quoted_monthly_price" IS NULL) OR ("quoted_monthly_price" >= (0)::numeric))),
    CONSTRAINT "maintenance_custom_proposals_quote_snapshot_object_check" CHECK ((("quote_snapshot" IS NULL) OR ("jsonb_typeof"("quote_snapshot") = 'object'::"text"))),
    CONSTRAINT "maintenance_custom_proposals_quoted_hours_check" CHECK ((("quoted_hours_monthly" IS NULL) OR ("quoted_hours_monthly" > (0)::numeric))),
    CONSTRAINT "maintenance_custom_proposals_quoted_hours_upper_bound_check" CHECK ((("quoted_hours_monthly" IS NULL) OR (("quoted_hours_monthly" > (0)::numeric) AND ("quoted_hours_monthly" <= (744)::numeric)))),
    CONSTRAINT "maintenance_custom_proposals_quoted_price_upper_bound_check" CHECK ((("quoted_monthly_price" IS NULL) OR (("quoted_monthly_price" >= (0)::numeric) AND ("quoted_monthly_price" <= (1000000)::numeric)))),
    CONSTRAINT "maintenance_custom_proposals_request_data_object_check" CHECK (("jsonb_typeof"("request_data") = 'object'::"text")),
    CONSTRAINT "maintenance_custom_proposals_response_notes_check" CHECK ((("response_notes" IS NULL) OR ("length"("response_notes") <= 5000))),
    CONSTRAINT "maintenance_custom_proposals_response_version_check" CHECK (("response_version" >= 0)),
    CONSTRAINT "maintenance_custom_proposals_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'in_review'::"text", 'clarification_requested'::"text", 'quoted'::"text", 'accepted'::"text", 'rejected'::"text", 'cancelled'::"text", 'expired'::"text"])))
);


ALTER TABLE "public"."maintenance_custom_proposals" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_custom_maintenance_proposal"("p_proposal_id" "uuid") RETURNS "public"."maintenance_custom_proposals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$

DECLARE

    v_proposal public.maintenance_custom_proposals;

    v_document public.maintenance_custom_proposal_documents;

    v_ack_count INTEGER := 0;

BEGIN

    -- ========================================================
    -- 1. AUTENTICACIÓN
    -- ========================================================

    IF auth.uid() IS NULL THEN

        RAISE EXCEPTION
            'Debes iniciar sesión';

    END IF;


    -- ========================================================
    -- 2. SOLO CLIENTES
    -- ========================================================

    IF public.current_user_is_worker() THEN

        RAISE EXCEPTION
            'Un trabajador no puede aceptar una propuesta como cliente';

    END IF;


    IF NOT public.current_user_is_active() THEN

        RAISE EXCEPTION
            'El usuario no está activo';

    END IF;


    -- ========================================================
    -- 3. OBTENER PROPUESTA
    -- ========================================================

    SELECT *
    INTO v_proposal
    FROM public.maintenance_custom_proposals
    WHERE id = p_proposal_id
      AND user_id = auth.uid()
      AND company_id = public.current_user_company_id()
    FOR UPDATE;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'La propuesta no existe o no tienes acceso a ella';

    END IF;


    -- ========================================================
    -- 4. COMPROBAR ESTADO
    -- ========================================================

    IF v_proposal.status <> 'quoted' THEN

        RAISE EXCEPTION
            'La propuesta todavía no puede aceptarse';

    END IF;


    -- ========================================================
    -- 5. PRECIO OBLIGATORIO
    -- ========================================================

    IF v_proposal.quoted_monthly_price IS NULL
       OR v_proposal.quoted_monthly_price <= 0
    THEN

        RAISE EXCEPTION
            'La propuesta no tiene un precio válido';

    END IF;


    -- ========================================================
    -- 6. VALIDEZ DE LA PROPUESTA
    -- ========================================================

    IF v_proposal.quoted_valid_until IS NOT NULL
       AND v_proposal.quoted_valid_until < CURRENT_DATE
    THEN

        UPDATE public.maintenance_custom_proposals
        SET
            status = 'expired',
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_proposal.id;

        RAISE EXCEPTION
            'La propuesta ha caducado';

    END IF;


    -- ========================================================
    -- 7. PDF ACTUAL OBLIGATORIO
    -- ========================================================

    IF v_proposal.current_document_id IS NULL THEN

        RAISE EXCEPTION
            'La propuesta no tiene un PDF publicado que pueda ser aceptado';

    END IF;


    -- ========================================================
    -- 8. OBTENER EL DOCUMENTO ACTUAL
    -- ========================================================

    SELECT *
    INTO v_document
    FROM public.maintenance_custom_proposal_documents
    WHERE id = v_proposal.current_document_id
      AND proposal_id = v_proposal.id
      AND published_at IS NOT NULL;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'El PDF actual de la propuesta no está publicado o no existe';

    END IF;


    -- ========================================================
    -- 9. PDF DEBE TENER SHA-256
    -- ========================================================

    IF v_document.document_sha256 IS NULL
       OR BTRIM(v_document.document_sha256) = ''
    THEN

        RAISE EXCEPTION
            'El PDF de la propuesta todavía no está validado';

    END IF;


    IF LOWER(BTRIM(v_document.document_sha256))
       !~ '^[0-9a-f]{64}$'
    THEN

        RAISE EXCEPTION
            'El SHA-256 del PDF de la propuesta no es válido';

    END IF;


    -- ========================================================
    -- 10. COMPROBAR ACKNOWLEDGEMENT DEL PDF ACTUAL
    -- ========================================================
    --
    -- El acknowledgement debe corresponder exactamente al PDF
    -- que actualmente está publicado.
    --
    -- No basta con que el usuario haya aceptado un PDF anterior.
    --
    -- ========================================================

    SELECT COUNT(*)
    INTO v_ack_count
    FROM public.maintenance_custom_proposal_document_acknowledgements a
    WHERE a.proposal_id = v_proposal.id
      AND a.document_id = v_document.id
      AND a.user_id = auth.uid()
      AND a.company_id = public.current_user_company_id()
      AND BTRIM(a.document_path) = BTRIM(v_document.document_path)
      AND LOWER(BTRIM(a.document_sha256))
          = LOWER(BTRIM(v_document.document_sha256));


    IF v_ack_count = 0 THEN

        RAISE EXCEPTION
            'No se puede aceptar la propuesta sin haber aceptado previamente el PDF actualmente publicado';

    END IF;


    -- ========================================================
    -- 11. ACEPTAR PROPUESTA
    -- ========================================================

    UPDATE public.maintenance_custom_proposals
    SET
        status = 'accepted',
        accepted_at = CURRENT_TIMESTAMP,
        accepted_by = auth.uid(),
        updated_at = CURRENT_TIMESTAMP
    WHERE id = v_proposal.id
    RETURNING *
    INTO v_proposal;


    -- ========================================================
    -- 12. COMPROBACIÓN FINAL
    -- ========================================================

    IF v_proposal.id IS NULL THEN

        RAISE EXCEPTION
            'No se ha podido aceptar la propuesta';

    END IF;


    RETURN v_proposal;

END;
$_$;


ALTER FUNCTION "public"."accept_custom_maintenance_proposal"("p_proposal_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_custom_maintenance_proposal"("p_proposal_id" "uuid") IS 'Acepta una propuesta Custom de mantenimiento únicamente después de verificar server-side que el cliente ha registrado la aceptación del PDF actualmente publicado, incluyendo document_id, document_path y SHA-256.';



CREATE OR REPLACE FUNCTION "public"."accept_custom_maintenance_proposal_for_user"("p_proposal_id" "uuid", "p_user_id" "uuid") RETURNS "public"."maintenance_custom_proposals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$

DECLARE
    v_proposal public.maintenance_custom_proposals;
    v_profile_status TEXT;

BEGIN

    IF p_proposal_id IS NULL
       OR p_user_id IS NULL
    THEN
        RAISE EXCEPTION
            'proposal_id y user_id son obligatorios';
    END IF;

    SELECT status
    INTO v_profile_status
    FROM public.profiles
    WHERE id = p_user_id;

    IF v_profile_status IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION
            'El usuario cliente no está activo';
    END IF;

    SELECT *
    INTO v_proposal
    FROM public.maintenance_custom_proposals
    WHERE id = p_proposal_id
      AND user_id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La propuesta no existe o no pertenece al usuario indicado';
    END IF;

    IF v_proposal.status <> 'quoted' THEN
        RAISE EXCEPTION
            'La propuesta todavía no puede aceptarse';
    END IF;

    PERFORM public.enforce_security_rate_limit(
        'maintenance_proposal_accept_backend:' || p_user_id::TEXT || ':' || p_proposal_id::TEXT,
        5,
        86400
    );



    IF v_proposal.quoted_monthly_price IS NULL
       OR v_proposal.quoted_monthly_price <= 0
    THEN
        RAISE EXCEPTION
            'La propuesta no tiene un precio válido';
    END IF;

    IF v_proposal.quoted_valid_until IS NOT NULL
       AND v_proposal.quoted_valid_until < CURRENT_DATE
    THEN
        UPDATE public.maintenance_custom_proposals
        SET
            status = 'expired',
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_proposal.id;

        RAISE EXCEPTION
            'La propuesta ha caducado';
    END IF;

    IF v_proposal.current_document_id IS NULL THEN
        RAISE EXCEPTION
            'La propuesta no tiene un PDF publicado';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.maintenance_custom_proposal_document_acknowledgements a
        JOIN public.maintenance_custom_proposal_documents d
          ON d.id = a.document_id
        WHERE a.proposal_id = v_proposal.id
          AND a.user_id = p_user_id
          AND a.document_id = v_proposal.current_document_id
          AND d.proposal_id = v_proposal.id
          AND d.published_at IS NOT NULL
          AND LOWER(a.document_sha256)
              = LOWER(d.document_sha256)
    )
    THEN
        RAISE EXCEPTION
            'El cliente debe confirmar primero que ha leído el PDF de la propuesta';
    END IF;

    UPDATE public.maintenance_custom_proposals
    SET
        status = 'accepted',
        accepted_at = CURRENT_TIMESTAMP,
        accepted_by = p_user_id,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = v_proposal.id
    RETURNING *
    INTO v_proposal;

    RETURN v_proposal;

END;
$$;


ALTER FUNCTION "public"."accept_custom_maintenance_proposal_for_user"("p_proposal_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."project_ownership_transfers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "company_id" "uuid" NOT NULL,
    "previous_owner_id" "uuid" NOT NULL,
    "requested_new_owner_id" "uuid" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "requested_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "accepted_by" "uuid",
    "accepted_at" timestamp with time zone,
    "status" "text" DEFAULT 'pending_approval'::"text" NOT NULL,
    "reason" "text",
    "acknowledgement_text_version" "text",
    "terms_snapshot" "jsonb",
    "terms_hash" "text",
    "project_snapshot" "jsonb",
    "project_snapshot_hash" "text",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "project_ownership_transfers_hash_check" CHECK ((("terms_hash" IS NULL) OR ("terms_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "project_ownership_transfers_project_hash_check" CHECK ((("project_snapshot_hash" IS NULL) OR ("project_snapshot_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "project_ownership_transfers_status_check" CHECK (("status" = ANY (ARRAY['pending_approval'::"text", 'pending_acceptance'::"text", 'accepted'::"text", 'rejected'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."project_ownership_transfers" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_project_ownership_transfer"("p_transfer_id" "uuid") RETURNS "public"."project_ownership_transfers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$

DECLARE
    v_transfer public.project_ownership_transfers;
    v_project public.projects;
    v_snapshot JSONB;
    v_hash TEXT;

BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado';
    END IF;

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION 'La cuenta no está activa';
    END IF;


    SELECT *
    INTO v_transfer
    FROM public.project_ownership_transfers
    WHERE id = p_transfer_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transferencia no encontrada';
    END IF;


    IF v_transfer.status <> 'pending_acceptance' THEN
        RAISE EXCEPTION
            'La transferencia no está pendiente de aceptación';
    END IF;


    IF v_transfer.requested_new_owner_id IS DISTINCT FROM auth.uid() THEN
        RAISE EXCEPTION
            'Solo el nuevo propietario puede aceptar esta transferencia';
    END IF;


    SELECT *
    INTO v_project
    FROM public.projects
    WHERE id = v_transfer.project_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION 'Proyecto no encontrado';
    END IF;


    IF v_project.user_id IS DISTINCT FROM v_transfer.previous_owner_id THEN
        RAISE EXCEPTION
            'El propietario actual del proyecto ya no coincide con la transferencia';
    END IF;


    v_snapshot := jsonb_build_object(
        'transfer_id', v_transfer.id,
        'project_id', v_project.id,
        'company_id', v_project.company_id,
        'previous_owner_id', v_transfer.previous_owner_id,
        'new_owner_id', auth.uid(),
        'project_state', v_project.state,
        'project_client_id', v_project.client_id,
        'transfer_project_snapshot',
            v_transfer.project_snapshot,
        'accepted_at', CURRENT_TIMESTAMP
    );

    v_hash := encode(
        extensions.digest(
            v_snapshot::text,
            'sha256'
        ),
        'hex'
    );


    -- Cerrar propietario anterior.

    UPDATE public.project_ownership_history
    SET ended_at = CURRENT_TIMESTAMP
    WHERE project_id = v_project.id
      AND ended_at IS NULL;


    -- Crear nuevo periodo de propiedad.

    INSERT INTO public.project_ownership_history (
        project_id,
        owner_user_id,
        started_at,
        reason
    )
    VALUES (
        v_project.id,
        auth.uid(),
        CURRENT_TIMESTAMP,
        'ownership_transfer'
    );


    -- El cambio real de propietario ocurre SOLO aquí.

    UPDATE public.projects
    SET
        user_id = auth.uid(),
        updated_at = CURRENT_TIMESTAMP
    WHERE id = v_project.id;


    UPDATE public.project_ownership_transfers
    SET
        status = 'accepted',
        accepted_by = auth.uid(),
        accepted_at = CURRENT_TIMESTAMP,
        terms_snapshot = v_snapshot,
        terms_hash = v_hash,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_transfer_id
    RETURNING *
    INTO v_transfer;


    RETURN v_transfer;

END;
$$;


ALTER FUNCTION "public"."accept_project_ownership_transfer"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."internal_task_updates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "task_id" "uuid" NOT NULL,
    "actor_worker_id" "uuid" NOT NULL,
    "action" "text" NOT NULL,
    "old_status" "text",
    "old_progress" integer,
    "new_status" "text",
    "new_progress" integer,
    "comment" "text",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "internal_task_updates_new_progress_check" CHECK ((("new_progress" IS NULL) OR (("new_progress" >= 0) AND ("new_progress" <= 100)))),
    CONSTRAINT "internal_task_updates_old_progress_check" CHECK ((("old_progress" IS NULL) OR (("old_progress" >= 0) AND ("old_progress" <= 100))))
);


ALTER TABLE "public"."internal_task_updates" OWNER TO "postgres";


COMMENT ON TABLE "public"."internal_task_updates" IS 'Immutable internal task audit/history. Frontend users cannot insert, update or delete records directly.';



COMMENT ON COLUMN "public"."internal_task_updates"."action" IS 'Action/event performed against the task. The authoritative transition rules are enforced by later RPCs.';



CREATE OR REPLACE FUNCTION "public"."add_internal_task_comment"("p_task_id" "uuid", "p_comment" "text") RETURNS "public"."internal_task_updates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_worker_id UUID;
    v_task public.internal_tasks;
    v_update public.internal_task_updates;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.update'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:comment:' || auth.uid()::TEXT,
        120,
        600
    );


    IF NULLIF(BTRIM(p_comment), '') IS NULL THEN
        RAISE EXCEPTION
            'El comentario no puede estar vacío';
    END IF;


    IF LENGTH(p_comment) > 5000 THEN
        RAISE EXCEPTION
            'El comentario no puede superar 5000 caracteres';
    END IF;


    IF NOT public.internal_task_can_current_worker_view(p_task_id) THEN
        RAISE EXCEPTION
            'No tienes acceso a esta tarea';
    END IF;


    v_worker_id := public.internal_task_current_worker_id();


    SELECT *
    INTO v_task
    FROM public.internal_tasks
    WHERE id = p_task_id;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tarea no existe';
    END IF;


    INSERT INTO public.internal_task_updates (
        task_id,
        actor_worker_id,
        action,
        old_status,
        old_progress,
        new_status,
        new_progress,
        comment
    )
    VALUES (
        p_task_id,
        v_worker_id,
        'comment',
        v_task.status,
        v_task.progress,
        v_task.status,
        v_task.progress,
        BTRIM(p_comment)
    )
    RETURNING *
    INTO v_update;


    RETURN v_update;

END;
$$;


ALTER FUNCTION "public"."add_internal_task_comment"("p_task_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."project_task_updates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "task_id" "uuid" NOT NULL,
    "actor_worker_id" "uuid" NOT NULL,
    "action" "text" NOT NULL,
    "old_status" "text",
    "old_progress" integer,
    "new_status" "text",
    "new_progress" integer,
    "comment" "text",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "project_task_updates_action_check" CHECK (("action" = ANY (ARRAY['created'::"text", 'started'::"text", 'updated'::"text", 'reassigned'::"text", 'progress_updated'::"text", 'submitted_for_review'::"text", 'review_approved'::"text", 'review_returned'::"text", 'direction_state_change'::"text", 'comment'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "project_task_updates_comment_max_length" CHECK ((("comment" IS NULL) OR ("char_length"("comment") <= 5000))),
    CONSTRAINT "project_task_updates_new_progress_check" CHECK ((("new_progress" IS NULL) OR (("new_progress" >= 0) AND ("new_progress" <= 100)))),
    CONSTRAINT "project_task_updates_new_status_check" CHECK ((("new_status" IS NULL) OR ("new_status" = ANY (ARRAY['to_do'::"text", 'in_progress'::"text", 'pending_review'::"text", 'completed'::"text", 'cancelled'::"text"])))),
    CONSTRAINT "project_task_updates_old_progress_check" CHECK ((("old_progress" IS NULL) OR (("old_progress" >= 0) AND ("old_progress" <= 100)))),
    CONSTRAINT "project_task_updates_old_status_check" CHECK ((("old_status" IS NULL) OR ("old_status" = ANY (ARRAY['to_do'::"text", 'in_progress'::"text", 'pending_review'::"text", 'completed'::"text", 'cancelled'::"text"]))))
);


ALTER TABLE "public"."project_task_updates" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_project_task_comment"("p_task_id" "uuid", "p_comment" "text") RETURNS "public"."project_task_updates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_worker_id UUID;
    v_task public.project_tasks;
    v_comment TEXT;
    v_update public.project_task_updates;
BEGIN

    v_worker_id := public.current_project_task_worker_id();

    IF v_worker_id IS NULL THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.update'
    );

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:comment:' || auth.uid()::TEXT,
        120,
        600
    );

    v_comment := NULLIF(BTRIM(p_comment), '');

    IF v_comment IS NULL THEN
        RAISE EXCEPTION
            'El comentario es obligatorio';
    END IF;

    IF LENGTH(v_comment) > 5000 THEN
        RAISE EXCEPTION
            'El comentario no puede superar 5000 caracteres';
    END IF;

    SELECT *
    INTO v_task
    FROM public.project_tasks
    WHERE id = p_task_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Tarea no encontrada';
    END IF;

    INSERT INTO public.project_task_updates (
        task_id,
        actor_worker_id,
        action,
        old_status,
        old_progress,
        new_status,
        new_progress,
        comment
    )
    VALUES (
        v_task.id,
        v_worker_id,
        'comment',
        v_task.status,
        v_task.progress,
        v_task.status,
        v_task.progress,
        v_comment
    )
    RETURNING *
    INTO v_update;

    RETURN v_update;

END;
$$;


ALTER FUNCTION "public"."add_project_task_comment"("p_task_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_profiles"() RETURNS TABLE("id" "uuid", "nombre" "text", "email" character varying, "empresa" "text", "company_id" "uuid", "rol" "text", "status" "text", "created_at" timestamp with time zone, "fecha_ultimo_login" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado.';
    END IF;

    IF NOT public.current_user_is_admin() THEN
        RAISE EXCEPTION 'No tienes permisos para consultar perfiles.';
    END IF;

    RETURN QUERY
    SELECT
        p.id,
        p.nombre,
        p.email,
        p.empresa,
        p.company_id,
        p.rol,
        p.status,
        p.created_at,
        p.fecha_ultimo_login
    FROM public.profiles p
    ORDER BY p.created_at ASC;

END;
$$;


ALTER FUNCTION "public"."admin_list_profiles"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_profile_role"("p_user_id" "uuid", "p_role" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_caller UUID;
    v_target_role TEXT;
BEGIN

    v_caller := auth.uid();

    IF v_caller IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado.';
    END IF;

    IF NOT public.current_user_is_admin() THEN
        RAISE EXCEPTION
            'No tienes permisos para cambiar roles.';
    END IF;

    IF p_user_id IS NULL THEN
        RAISE EXCEPTION
            'El usuario es obligatorio.';
    END IF;

    IF p_role NOT IN ('user', 'admin') THEN
        RAISE EXCEPTION
            'Rol no válido.';
    END IF;

    IF p_user_id = v_caller THEN
        RAISE EXCEPTION
            'No puedes cambiar tu propio rol.';
    END IF;

    SELECT rol
    INTO v_target_role
    FROM public.profiles
    WHERE id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El perfil indicado no existe.';
    END IF;

    IF v_target_role = 'admin' THEN
        RAISE EXCEPTION
            'Un administrador no puede modificar el rol de otro administrador.';
    END IF;

    UPDATE public.profiles
    SET
        rol = p_role,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_user_id;

    RETURN TRUE;

END;
$$;


ALTER FUNCTION "public"."admin_set_profile_role"("p_user_id" "uuid", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_profile_status"("p_user_id" "uuid", "p_status" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_caller UUID;
    v_target_role TEXT;
    v_active_admins INTEGER;
BEGIN

    v_caller := auth.uid();

    IF v_caller IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado.';
    END IF;

    IF NOT public.current_user_is_admin() THEN
        RAISE EXCEPTION
            'No tienes permisos para cambiar el estado de cuentas.';
    END IF;

    IF p_user_id IS NULL THEN
        RAISE EXCEPTION
            'El usuario es obligatorio.';
    END IF;

    IF p_status NOT IN ('active', 'blocked') THEN
        RAISE EXCEPTION
            'Estado no válido.';
    END IF;

    IF p_user_id = v_caller THEN
        RAISE EXCEPTION
            'No puedes cambiar tu propio estado.';
    END IF;

    SELECT rol
    INTO v_target_role
    FROM public.profiles
    WHERE id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El perfil indicado no existe.';
    END IF;

    IF v_target_role = 'admin' THEN
        RAISE EXCEPTION
            'Un administrador no puede modificar el estado de otro administrador.';
    END IF;

    -- Defensa adicional.
    IF p_status = 'blocked'
       AND v_target_role = 'admin'
    THEN

        SELECT COUNT(*)
        INTO v_active_admins
        FROM public.profiles
        WHERE rol = 'admin'
          AND status = 'active';

        IF v_active_admins <= 1 THEN
            RAISE EXCEPTION
                'No se puede bloquear al último administrador activo.';
        END IF;

    END IF;

    UPDATE public.profiles
    SET
        status = p_status,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_user_id;

    IF p_status = 'blocked' THEN
        PERFORM public.revoke_user_sessions(p_user_id);
    END IF;

    RETURN TRUE;

END;
$$;


ALTER FUNCTION "public"."admin_set_profile_status"("p_user_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_worker_status"("p_user_id" "uuid", "p_is_active" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_target_role TEXT;
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado.';
    END IF;

    IF NOT public.current_user_is_admin() THEN
        RAISE EXCEPTION
            'Solo un administrador puede gestionar trabajadores.';
    END IF;

    IF p_user_id IS NULL THEN
        RAISE EXCEPTION
            'El usuario es obligatorio.';
    END IF;

    IF p_is_active IS NULL THEN
        RAISE EXCEPTION
            'El estado del worker es obligatorio.';
    END IF;

    IF p_user_id = auth.uid() THEN
        RAISE EXCEPTION
            'No puedes modificar tu propio estado de worker.';
    END IF;

    SELECT rol
    INTO v_target_role
    FROM public.profiles
    WHERE id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El perfil indicado no existe.';
    END IF;

    IF v_target_role = 'admin' THEN
        RAISE EXCEPTION
            'Un administrador no puede gestionar otro administrador.';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.workers
        WHERE auth_user_id = p_user_id
    ) THEN
        RAISE EXCEPTION
            'El usuario indicado no es un trabajador.';
    END IF;

    UPDATE public.workers
    SET
        is_active = p_is_active,
        updated_at = CURRENT_TIMESTAMP
    WHERE auth_user_id = p_user_id;

    RETURN TRUE;

END;
$$;


ALTER FUNCTION "public"."admin_set_worker_status"("p_user_id" "uuid", "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_profile_company"("p_user_id" "uuid", "p_company_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'companies.update'
    );

    RETURN public.admin_update_profile_company__legacy_113(
        p_user_id,
        p_company_id
    );

END;
$$;


ALTER FUNCTION "public"."admin_update_profile_company"("p_user_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_profile_company__legacy_113"("p_user_id" "uuid", "p_company_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado.';
    END IF;


    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'No tienes permisos para modificar empresas de clientes.';
    END IF;


    IF p_user_id IS NULL THEN
        RAISE EXCEPTION
            'El usuario es obligatorio.';
    END IF;


    IF p_company_id IS NULL THEN
        RAISE EXCEPTION
            'La empresa es obligatoria.';
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM public.profiles
        WHERE id = p_user_id
    ) THEN
        RAISE EXCEPTION
            'El perfil indicado no existe.';
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM public.companies
        WHERE id = p_company_id
          AND is_active = TRUE
    ) THEN
        RAISE EXCEPTION
            'La empresa indicada no existe o está inactiva.';
    END IF;


    UPDATE public.profiles
    SET
        company_id = p_company_id,
        empresa = (
            SELECT c.company_name
            FROM public.companies c
            WHERE c.id = p_company_id
        ),
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_user_id;


    RETURN TRUE;

END;
$$;


ALTER FUNCTION "public"."admin_update_profile_company__legacy_113"("p_user_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_update_profile_company__legacy_113"("p_user_id" "uuid", "p_company_id" "uuid") IS 'Permite a un trabajador activo de MODIRA cambiar la empresa de un perfil.';



CREATE OR REPLACE FUNCTION "public"."apply_approved_company_change_fiscal_data"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_target_company_id UUID;
    v_profile_company_id UUID;
BEGIN

    -- ========================================================
    -- 1. ESTE TRIGGER SOLO DEBE ACTUAR EN:
    --
    --    pending → approved
    -- ========================================================

    IF OLD.status IS DISTINCT FROM 'pending'
       OR NEW.status IS DISTINCT FROM 'approved'
    THEN
        RETURN NEW;
    END IF;


    -- ========================================================
    -- 2. SEGURIDAD
    --
    -- La aprobación debe proceder de un worker activo.
    -- ========================================================

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            '066: no se puede aplicar un cambio fiscal sin usuario autenticado';
    END IF;


    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            '066: solo un trabajador activo puede aprobar cambios fiscales';
    END IF;


    -- ========================================================
    -- 3. DETERMINAR EMPRESA DESTINO
    --
    -- Primera opción:
    --     requested_company_id
    --
    -- Si todavía es NULL:
    --     profiles.company_id
    --
    -- Esto permite funcionar tanto si la empresa destino
    -- ya existía como si la 065 acaba de crearla.
    -- ========================================================

    v_target_company_id := NEW.requested_company_id;


    IF v_target_company_id IS NULL THEN

        SELECT p.company_id
        INTO v_profile_company_id
        FROM public.profiles p
        WHERE p.id = NEW.user_id
        LIMIT 1;

        v_target_company_id := v_profile_company_id;

    END IF;


    -- ========================================================
    -- 4. LA EMPRESA DESTINO DEBE EXISTIR
    -- ========================================================

    IF v_target_company_id IS NULL THEN
        RAISE EXCEPTION
            '066: no se pudo determinar la empresa destino de la solicitud aprobada';
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM public.companies c
        WHERE c.id = v_target_company_id
    ) THEN
        RAISE EXCEPTION
            '066: la empresa destino de la solicitud aprobada no existe';
    END IF;


    -- ========================================================
    -- 5. APLICAR LOS DATOS FISCALES APROBADOS
    --
    -- IMPORTANTE:
    --
    -- Aquí requested_* deja de ser únicamente una propuesta
    -- y pasa a convertirse en el estado actual de companies.
    --
    -- La solicitud NO se modifica.
    -- Solo se actualiza la empresa.
    -- ========================================================

    UPDATE public.companies
    SET
        legal_name = NEW.requested_legal_name,
        cif_vat = NEW.requested_cif_vat,
        billing_email = NEW.requested_billing_email,
        address = NEW.requested_address,
        postal_code = NEW.requested_postal_code,
        city = NEW.requested_city,
        province = NEW.requested_province,
        country = NEW.requested_country,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = v_target_company_id;


    -- ========================================================
    -- 6. DEVOLVER LA SOLICITUD SIN MODIFICARLA
    -- ========================================================

    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."apply_approved_company_change_fiscal_data"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."maintenance_contract_project_change_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "maintenance_contract_id" "uuid" NOT NULL,
    "company_id" "uuid" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "current_project_id" "uuid",
    "requested_project_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "requested_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "effective_at" "date",
    "rejection_reason" "text",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "maintenance_contract_project_change_approval_check" CHECK ((("status" <> ALL (ARRAY['approved'::"text", 'applied'::"text"])) OR ("effective_at" IS NOT NULL))),
    CONSTRAINT "maintenance_contract_project_change_rejection_check" CHECK ((("status" <> 'rejected'::"text") OR (NULLIF("btrim"("rejection_reason"), ''::"text") IS NOT NULL))),
    CONSTRAINT "maintenance_contract_project_change_review_check" CHECK ((("status" = ANY (ARRAY['pending'::"text", 'cancelled'::"text"])) OR ("reviewed_at" IS NOT NULL))),
    CONSTRAINT "maintenance_contract_project_change_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'applied'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."maintenance_contract_project_change_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_maintenance_contract_project_change"("p_contract_id" "uuid") RETURNS "public"."maintenance_contract_project_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request public.maintenance_contract_project_change_requests;
  v_contract public.maintenance_contracts;
  v_old_project_id UUID;
BEGIN
  SELECT *
  INTO v_contract
  FROM public.maintenance_contracts
  WHERE id = p_contract_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'El contrato de mantenimiento no existe';
  END IF;

  IF v_contract.pending_project_id IS NULL
     OR v_contract.pending_project_change_effective_at IS NULL
  THEN
    RAISE EXCEPTION 'El contrato no tiene un cambio de proyecto pendiente';
  END IF;

  IF CURRENT_DATE < v_contract.pending_project_change_effective_at THEN
    RAISE EXCEPTION 'El cambio de proyecto todavía no es efectivo';
  END IF;

  SELECT *
  INTO v_request
  FROM public.maintenance_contract_project_change_requests
  WHERE maintenance_contract_id = v_contract.id
    AND status = 'approved'
    AND requested_project_id = v_contract.pending_project_id
    AND effective_at = v_contract.pending_project_change_effective_at
  ORDER BY reviewed_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No existe una solicitud aprobada válida para el cambio pendiente';
  END IF;

  -- El nuevo proyecto no puede haber sido ocupado por otro contrato
  -- mientras la solicitud estaba pendiente.
  IF EXISTS (
    SELECT 1
    FROM public.maintenance_contract_projects mcp
    JOIN public.maintenance_contracts other_mc
      ON other_mc.id = mcp.maintenance_contract_id
    WHERE mcp.project_id = v_contract.pending_project_id
      AND other_mc.id <> v_contract.id
      AND public.is_live_maintenance_contract_status(other_mc.estado)
  ) THEN
    RAISE EXCEPTION 'El proyecto solicitado ya está ocupado por otro mantenimiento activo o pausado';
  END IF;

  SELECT mcp.project_id
  INTO v_old_project_id
  FROM public.maintenance_contract_projects mcp
  WHERE mcp.maintenance_contract_id = v_contract.id
  ORDER BY mcp.created_at DESC
  LIMIT 1;

  IF v_old_project_id IS NULL THEN
    RAISE EXCEPTION 'El contrato no tiene un proyecto actual que sustituir';
  END IF;

  IF v_old_project_id = v_contract.pending_project_id THEN
    UPDATE public.maintenance_contracts
    SET
      pending_project_id = NULL,
      pending_project_change_effective_at = NULL,
      updated_at = CURRENT_TIMESTAMP
    WHERE id = v_contract.id;

    UPDATE public.maintenance_contract_project_change_requests
    SET
      status = 'applied',
      updated_at = CURRENT_TIMESTAMP
    WHERE id = v_request.id
    RETURNING *
    INTO v_request;

    RETURN v_request;
  END IF;

  -- Locks compatibles con 089.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'maintenance-contract:' || v_contract.id::TEXT,
      0
    )
  );

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'maintenance-project:' || v_old_project_id::TEXT,
      0
    )
  );

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'maintenance-project:' || v_contract.pending_project_id::TEXT,
      0
    )
  );

  -- Primero se elimina la relación viva anterior. La operación completa
  -- permanece dentro de esta misma transacción.
  DELETE FROM public.maintenance_contract_projects
  WHERE maintenance_contract_id = v_contract.id
    AND project_id = v_old_project_id;

  INSERT INTO public.maintenance_contract_projects (
    maintenance_contract_id,
    project_id
  )
  VALUES (
    v_contract.id,
    v_contract.pending_project_id
  );

  UPDATE public.maintenance_contracts
  SET
    pending_project_id = NULL,
    pending_project_change_effective_at = NULL,
    updated_at = CURRENT_TIMESTAMP
  WHERE id = v_contract.id;

  UPDATE public.maintenance_contract_project_change_requests
  SET
    status = 'applied',
    updated_at = CURRENT_TIMESTAMP
  WHERE id = v_request.id
  RETURNING *
  INTO v_request;

  RETURN v_request;
END;
$$;


ALTER FUNCTION "public"."apply_maintenance_contract_project_change"("p_contract_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_expense_number"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_number BIGINT;
BEGIN

    v_number := nextval('public.expense_number_seq');

    RETURN 'G-' || LPAD(
        v_number::TEXT,
        6,
        '0'
    );

END;
$$;


ALTER FUNCTION "public"."generate_expense_number"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_expense_number"() IS 'Genera el número interno único de un gasto de MODIRA. El frontend no proporciona el número.';



CREATE TABLE IF NOT EXISTS "public"."expenses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "expense_number" "text" DEFAULT "public"."generate_expense_number"() NOT NULL,
    "expense_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "description" "text" NOT NULL,
    "expense_type" "text" NOT NULL,
    "category_id" "uuid" NOT NULL,
    "supplier_id" "uuid",
    "project_id" "uuid",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "currency" character varying(3) DEFAULT 'EUR'::character varying NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "subtotal" numeric(14,2) DEFAULT 0 NOT NULL,
    "total_tax" numeric(14,2) DEFAULT 0 NOT NULL,
    "total_withholding" numeric(14,2) DEFAULT 0 NOT NULL,
    "total_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    CONSTRAINT "expenses_currency_check" CHECK ((("currency")::"text" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "expenses_description_check" CHECK ((("length"("btrim"("description")) >= 1) AND ("length"("btrim"("description")) <= 5000))),
    CONSTRAINT "expenses_number_check" CHECK ((("length"("btrim"("expense_number")) >= 1) AND ("length"("btrim"("expense_number")) <= 50))),
    CONSTRAINT "expenses_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'pending_review'::"text", 'approved'::"text", 'rejected'::"text", 'pending_payment'::"text", 'partially_paid'::"text", 'paid'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "expenses_subtotal_check" CHECK (("subtotal" >= (0)::numeric)),
    CONSTRAINT "expenses_total_amount_check" CHECK (("total_amount" >= (0)::numeric)),
    CONSTRAINT "expenses_total_tax_check" CHECK (("total_tax" >= (0)::numeric)),
    CONSTRAINT "expenses_total_withholding_check" CHECK (("total_withholding" >= (0)::numeric)),
    CONSTRAINT "expenses_type_check" CHECK (("expense_type" = ANY (ARRAY['supplier_invoice'::"text", 'employee_expense'::"text", 'travel'::"text", 'meals'::"text", 'corporate_card'::"text", 'subscription'::"text", 'tax'::"text", 'other'::"text"])))
);


