COMMENT ON TABLE "public"."expenses" IS 'Gastos internos de MODIRA. No pertenecen a empresas cliente. Los workers consultan mediante RBAC y las escrituras se realizan mediante RPCs protegidas.';



COMMENT ON COLUMN "public"."expenses"."expense_number" IS 'Número interno único del gasto. Generado automáticamente por backend.';



COMMENT ON COLUMN "public"."expenses"."expense_type" IS 'Naturaleza del gasto: supplier_invoice, employee_expense, travel, meals, corporate_card, subscription, tax u other.';



COMMENT ON COLUMN "public"."expenses"."category_id" IS 'Categoría interna del gasto.';



COMMENT ON COLUMN "public"."expenses"."supplier_id" IS 'Proveedor asociado al gasto, cuando exista.';



COMMENT ON COLUMN "public"."expenses"."project_id" IS 'Proyecto de MODIRA al que se imputa directamente el gasto, cuando corresponda.';



COMMENT ON COLUMN "public"."expenses"."subtotal" IS 'Base económica del gasto antes de impuestos y retenciones.';



COMMENT ON COLUMN "public"."expenses"."total_tax" IS 'Total de impuestos que incrementan el coste del gasto. No incluye retenciones.';



COMMENT ON COLUMN "public"."expenses"."total_withholding" IS 'Total de retenciones practicadas. Se resta del subtotal e impuestos para obtener el importe final.';



COMMENT ON COLUMN "public"."expenses"."total_amount" IS 'Importe final del gasto: subtotal + impuestos - retenciones.';



CREATE OR REPLACE FUNCTION "public"."approve_expense"("p_expense_id" "uuid") RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_expense public.expenses;
BEGIN
  -- Mantener los controles de permisos y seguridad existentes.
  PERFORM public.require_expense_permission(
    'expenses.approve'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:approve'
  );

  -- Bloquear el gasto durante la aprobación.
  SELECT *
  INTO v_expense
  FROM public.expenses
  WHERE id = p_expense_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'El gasto % no existe',
      p_expense_id;
  END IF;

  -- Solo se pueden aprobar gastos pendientes de revisión.
  IF v_expense.status <> 'pending_review' THEN
    RAISE EXCEPTION
      'Solo se pueden aprobar gastos en estado pending_review';
  END IF;

  IF v_expense.total_amount <= 0 THEN
    RAISE EXCEPTION
      'No se puede aprobar un gasto cuyo importe total sea 0';
  END IF;

  -- La aprobación autoriza el gasto, pero no implica por sí sola
  -- que esté pagado.
  UPDATE public.expenses
  SET
    status = 'pending_payment',
    updated_by = auth.uid(),
    updated_at = CURRENT_TIMESTAMP
  WHERE id = p_expense_id
  RETURNING *
  INTO v_expense;

  -- Si existen pagos pendientes cuya fecha ya ha llegado,
  -- procesarlos inmediatamente después de aprobar el gasto.
  -- Los pagos con fecha futura permanecen pendientes.
  UPDATE public.expense_payments
  SET
    status = 'succeeded',
    updated_at = CURRENT_TIMESTAMP
  WHERE expense_id = p_expense_id
    AND status = 'pending'
    AND payment_date <= CURRENT_TIMESTAMP;

  -- Volver a leer el gasto para devolver su estado definitivo,
  -- actualizado por los mecanismos de sincronización de pagos.
  SELECT *
  INTO v_expense
  FROM public.expenses
  WHERE id = p_expense_id;

  RETURN v_expense;
END;
$$;


ALTER FUNCTION "public"."approve_expense"("p_expense_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_expense"("p_expense_id" "uuid") IS 'Approves a reviewed internal Modira expense and moves it to pending_payment.';



CREATE OR REPLACE FUNCTION "public"."approve_maintenance_contract_project_change"("p_request_id" "uuid") RETURNS "public"."maintenance_contract_project_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'maintenance.update'
    );

    RETURN public.approve_maintenance_contract_project_change__legacy_113(
        p_request_id
    );

END;
$$;


ALTER FUNCTION "public"."approve_maintenance_contract_project_change"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_maintenance_contract_project_change__legacy_113"("p_request_id" "uuid") RETURNS "public"."maintenance_contract_project_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_worker_id UUID := auth.uid();
  v_request public.maintenance_contract_project_change_requests;
  v_contract public.maintenance_contracts;
  v_current_project_id UUID;
  v_effective_at DATE;
BEGIN
  IF v_worker_id IS NULL THEN
    RAISE EXCEPTION 'Debes iniciar sesión';
  END IF;

  IF NOT public.current_user_is_worker() THEN
    RAISE EXCEPTION 'Se requiere un trabajador activo';
  END IF;

  SELECT *
  INTO v_request
  FROM public.maintenance_contract_project_change_requests
  WHERE id = p_request_id
    AND status = 'pending'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'La solicitud no existe o ya ha sido revisada';
  END IF;

  SELECT *
  INTO v_contract
  FROM public.maintenance_contracts
  WHERE id = v_request.maintenance_contract_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'El contrato asociado ya no existe';
  END IF;

  IF v_contract.company_id IS DISTINCT FROM v_request.company_id THEN
    RAISE EXCEPTION 'La solicitud y el contrato no pertenecen a la misma empresa';
  END IF;

  IF NOT public.is_live_maintenance_contract_status(v_contract.estado) THEN
    RAISE EXCEPTION 'El contrato ya no está activo o pausado';
  END IF;

  SELECT mcp.project_id
  INTO v_current_project_id
  FROM public.maintenance_contract_projects mcp
  WHERE mcp.maintenance_contract_id = v_contract.id
  ORDER BY mcp.created_at DESC
  LIMIT 1;

  IF v_current_project_id IS NULL THEN
    RAISE EXCEPTION 'El contrato ya no tiene un proyecto actual';
  END IF;

  IF v_current_project_id IS DISTINCT FROM v_request.current_project_id THEN
    RAISE EXCEPTION 'El proyecto actual del contrato ha cambiado desde que se creó la solicitud';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.maintenance_contract_projects mcp
    JOIN public.maintenance_contracts other_mc
      ON other_mc.id = mcp.maintenance_contract_id
    WHERE mcp.project_id = v_request.requested_project_id
      AND other_mc.id <> v_contract.id
      AND public.is_live_maintenance_contract_status(other_mc.estado)
  ) THEN
    RAISE EXCEPTION 'El proyecto solicitado ya está ocupado por otro mantenimiento activo o pausado';
  END IF;

  IF v_contract.current_period_end IS NULL THEN
    RAISE EXCEPTION 'El contrato no tiene una fecha de fin de periodo válida';
  END IF;

  IF CURRENT_DATE < v_contract.current_period_end THEN
    v_effective_at := v_contract.current_period_end;
  ELSE
    v_effective_at :=
      (
        v_contract.current_period_end
        + INTERVAL '1 month'
      )::DATE;
  END IF;

  UPDATE public.maintenance_contract_project_change_requests
  SET
    status = 'approved',
    reviewed_at = CURRENT_TIMESTAMP,
    reviewed_by = v_worker_id,
    effective_at = v_effective_at,
    updated_at = CURRENT_TIMESTAMP
  WHERE id = v_request.id
  RETURNING *
  INTO v_request;

  UPDATE public.maintenance_contracts
  SET
    pending_project_id = v_request.requested_project_id,
    pending_project_change_effective_at = v_effective_at,
    updated_at = CURRENT_TIMESTAMP
  WHERE id = v_contract.id;

  RETURN v_request;
END;
$$;


ALTER FUNCTION "public"."approve_maintenance_contract_project_change__legacy_113"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_project_ownership_transfer"("p_transfer_id" "uuid") RETURNS "public"."project_ownership_transfers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_transfer public.project_ownership_transfers;

BEGIN

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Solo un trabajador autorizado puede aprobar la transferencia';
    END IF;


    IF NOT public.current_worker_has_permission(
        'projects.update'
    ) THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere el permiso projects.update';
    END IF;


    SELECT *
    INTO v_transfer
    FROM public.project_ownership_transfers
    WHERE id = p_transfer_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Transferencia no encontrada';
    END IF;


    IF v_transfer.status <> 'pending_approval' THEN
        RAISE EXCEPTION
            'La transferencia no está pendiente de aprobación';
    END IF;


    UPDATE public.project_ownership_transfers
    SET
        status = 'pending_acceptance',
        approved_by = auth.uid(),
        approved_at = CURRENT_TIMESTAMP,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_transfer_id
    RETURNING *
    INTO v_transfer;


    RETURN v_transfer;

END;
$$;


ALTER FUNCTION "public"."approve_project_ownership_transfer"("p_transfer_id" "uuid") OWNER TO "postgres";


