    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "maintenance_contract_id" "uuid" NOT NULL,
    "project_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


ALTER TABLE "public"."maintenance_contract_projects" OWNER TO "postgres";


COMMENT ON TABLE "public"."maintenance_contract_projects" IS 'Relación entre contratos de mantenimiento y proyectos. Los contratos activos o pausados solo pueden cubrir un proyecto y un proyecto solo puede tener un contrato activo o pausado. Los contratos históricos pueden conservar sus relaciones.';



CREATE OR REPLACE FUNCTION "public"."assign_maintenance_contract_project"("p_contract_id" "uuid", "p_project_id" "uuid") RETURNS "public"."maintenance_contract_projects"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
  v_contract public.maintenance_contracts;
  v_project public.projects;
  v_row public.maintenance_contract_projects;

BEGIN

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF NOT public.current_user_is_active() THEN
    RAISE EXCEPTION 'El usuario no está activo';
  END IF;

  IF public.current_user_is_worker() THEN
    RAISE EXCEPTION
      'Un worker debe utilizar la RPC de gestión de mantenimiento';
  END IF;


  -- ----------------------------------------------------------
  -- CONTRATO
  -- ----------------------------------------------------------

  SELECT *
  INTO v_contract
  FROM public.maintenance_contracts
  WHERE id = p_contract_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'El contrato de mantenimiento no existe';
  END IF;

  IF v_contract.company_id IS DISTINCT FROM public.current_user_company_id() THEN
    RAISE EXCEPTION
      'El contrato no pertenece a la empresa del usuario actual';
  END IF;


  -- ----------------------------------------------------------
  -- PROYECTO
  -- ----------------------------------------------------------

  SELECT *
  INTO v_project
  FROM public.projects
  WHERE id = p_project_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'El proyecto no existe';
  END IF;

  IF v_project.company_id IS NULL
     OR v_project.company_id IS DISTINCT FROM v_contract.company_id
  THEN
    RAISE EXCEPTION
      'El proyecto no pertenece a la empresa del contrato';
  END IF;


  -- ----------------------------------------------------------
  -- ASOCIACIÓN IDEMPOTENTE
  -- ----------------------------------------------------------

  INSERT INTO public.maintenance_contract_projects (
    maintenance_contract_id,
    project_id
  )
  VALUES (
    p_contract_id,
    p_project_id
  )
  ON CONFLICT (
    maintenance_contract_id,
    project_id
  )
  DO NOTHING
  RETURNING *
  INTO v_row;


  -- Si ya existía, devolvemos la fila existente.
  IF v_row.id IS NULL THEN
    SELECT *
    INTO v_row
    FROM public.maintenance_contract_projects
    WHERE maintenance_contract_id = p_contract_id
      AND project_id = p_project_id;
  END IF;

  RETURN v_row;

END;
$$;


ALTER FUNCTION "public"."assign_maintenance_contract_project"("p_contract_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_maintenance_contract_project"("p_contract_id" "uuid", "p_project_id" "uuid") IS 'Permite al cliente activo asociar opcionalmente un proyecto de su empresa a su contrato de mantenimiento.';



CREATE OR REPLACE FUNCTION "public"."assign_worker_role"("p_worker_auth_user_id" "uuid", "p_role_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_role_id UUID;
    v_worker_exists BOOLEAN;
    v_normalized_role TEXT;
BEGIN

    -- --------------------------------------------------------
    -- Autenticación
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Authentication required'
            USING ERRCODE = '42501';
    END IF;


    -- --------------------------------------------------------
    -- Autorización
    -- --------------------------------------------------------

    IF NOT public.current_user_can_manage_worker_roles() THEN
        RAISE EXCEPTION
            'Insufficient permissions to manage worker roles'
            USING ERRCODE = '42501';
    END IF;


    -- --------------------------------------------------------
    -- Validación worker
    -- --------------------------------------------------------

    IF p_worker_auth_user_id IS NULL THEN
        RAISE EXCEPTION
            'Worker auth user id is required'
            USING ERRCODE = '22023';
    END IF;


    SELECT EXISTS (
        SELECT 1
        FROM public.workers w
        WHERE w.auth_user_id = p_worker_auth_user_id
    )
    INTO v_worker_exists;


    IF NOT v_worker_exists THEN
        RAISE EXCEPTION
            'Worker does not exist'
            USING ERRCODE = '22023';
    END IF;


    -- --------------------------------------------------------
    -- Normalización del rol
    -- --------------------------------------------------------

    v_normalized_role := LOWER(BTRIM(p_role_code));


    IF v_normalized_role = '' THEN
        RAISE EXCEPTION
            'Role code is required'
            USING ERRCODE = '22023';
    END IF;


    -- --------------------------------------------------------
    -- Buscar rol
    -- --------------------------------------------------------

    SELECT r.id
    INTO v_role_id
    FROM public.worker_roles r
    WHERE r.code = v_normalized_role
      AND r.is_active = TRUE;


    IF v_role_id IS NULL THEN
        RAISE EXCEPTION
            'Role does not exist or is inactive: %',
            v_normalized_role
            USING ERRCODE = '22023';
    END IF;


    -- --------------------------------------------------------
    -- Asignación
    -- --------------------------------------------------------

    INSERT INTO public.worker_role_assignments (
        worker_auth_user_id,
        role_id
    )
    VALUES (
        p_worker_auth_user_id,
        v_role_id
    )
    ON CONFLICT (
        worker_auth_user_id,
        role_id
    )
    DO NOTHING;


    RETURN TRUE;

END;
$$;


ALTER FUNCTION "public"."assign_worker_role"("p_worker_auth_user_id" "uuid", "p_role_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_worker_role"("p_worker_auth_user_id" "uuid", "p_role_code" "text") IS 'Asigna un rol RBAC activo a un worker existente.';



