    "file_name" "text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "mime_type" "text" DEFAULT 'application/pdf'::"text" NOT NULL,
    "file_size" bigint NOT NULL,
    "document_sha256" "text" NOT NULL,
    "uploaded_by" "uuid",
    "uploaded_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "expense_documents_file_name_check" CHECK ((("length"("btrim"("file_name")) >= 1) AND ("length"("btrim"("file_name")) <= 255))),
    CONSTRAINT "expense_documents_file_size_check" CHECK ((("file_size" > 0) AND ("file_size" <= 20971520))),
    CONSTRAINT "expense_documents_mime_type_check" CHECK (("mime_type" = 'application/pdf'::"text")),
    CONSTRAINT "expense_documents_sha256_check" CHECK (("document_sha256" ~ '^[0-9A-Fa-f]{64}$'::"text")),
    CONSTRAINT "expense_documents_storage_path_check" CHECK ((("length"("btrim"("storage_path")) >= 1) AND ("length"("btrim"("storage_path")) <= 1024))),
    CONSTRAINT "expense_documents_type_check" CHECK (("document_type" = ANY (ARRAY['invoice'::"text", 'receipt'::"text", 'payment_proof'::"text", 'delivery_note'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."expense_documents" OWNER TO "postgres";


COMMENT ON TABLE "public"."expense_documents" IS 'Documentación interna asociada a gastos de MODIRA.';



COMMENT ON COLUMN "public"."expense_documents"."expense_id" IS 'Gasto interno de Modira al que pertenece el documento.';



COMMENT ON COLUMN "public"."expense_documents"."document_type" IS 'Tipo de documento: invoice, receipt, payment_proof, delivery_note u other.';



COMMENT ON COLUMN "public"."expense_documents"."storage_path" IS 'Ruta privada del documento dentro del bucket expense-documents.';



COMMENT ON COLUMN "public"."expense_documents"."file_size" IS 'Tamaño del archivo en bytes. Máximo 20 MiB.';



COMMENT ON COLUMN "public"."expense_documents"."document_sha256" IS 'Hash SHA-256 del contenido real del documento, calculado por el backend.';



CREATE OR REPLACE FUNCTION "public"."attach_expense_document"("p_expense_id" "uuid", "p_document_type" "text", "p_file_name" "text", "p_storage_path" "text", "p_mime_type" "text", "p_file_size" bigint, "p_document_sha256" "text") RETURNS "public"."expense_documents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE

  v_document public.expense_documents;

  v_status TEXT;

  v_object_exists BOOLEAN;

  v_object_size BIGINT;

  v_object_mime TEXT;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.documents'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:document_attach'
  );


  SELECT status
  INTO v_status

  FROM public.expenses

  WHERE id = p_expense_id

  FOR UPDATE;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El gasto % no existe',
      p_expense_id;

  END IF;


  IF v_status = 'cancelled' THEN

    RAISE EXCEPTION
      'No se pueden adjuntar documentos a un gasto cancelado';

  END IF;


  IF p_mime_type <> 'application/pdf' THEN

    RAISE EXCEPTION
      'El documento debe ser PDF';

  END IF;


  IF p_file_size <= 0
     OR p_file_size > 20971520 THEN

    RAISE EXCEPTION
      'El documento debe tener un tamaño entre 1 byte y 20 MiB';

  END IF;


  IF p_document_sha256 !~ '^[0-9A-Fa-f]{64}$' THEN

    RAISE EXCEPTION
      'El SHA-256 del documento no tiene un formato válido';

  END IF;


  -- ----------------------------------------------------------
  -- El objeto debe existir físicamente.
  -- ----------------------------------------------------------

  SELECT EXISTS (
    SELECT 1
    FROM storage.objects
    WHERE bucket_id = 'expense-documents'
      AND name = p_storage_path
  )
  INTO v_object_exists;


  IF NOT v_object_exists THEN

    RAISE EXCEPTION
      'El documento no existe en Storage';

  END IF;


  -- ----------------------------------------------------------
  -- Comprobar metadatos reales del objeto.
  -- ----------------------------------------------------------

  SELECT
    COALESCE(
      (metadata ->> 'size')::BIGINT,
      NULL
    ),
    COALESCE(
      metadata ->> 'mimetype',
      NULL
    )

  INTO
    v_object_size,
    v_object_mime

  FROM storage.objects

  WHERE bucket_id = 'expense-documents'
    AND name = p_storage_path;


  IF v_object_size IS NOT NULL
     AND v_object_size <> p_file_size THEN

    RAISE EXCEPTION
      'El tamaño declarado no coincide con el objeto de Storage';

  END IF;


  IF v_object_mime IS NOT NULL
     AND v_object_mime <> 'application/pdf' THEN

    RAISE EXCEPTION
      'El objeto de Storage no es un PDF';

  END IF;


  INSERT INTO public.expense_documents (
    expense_id,
    document_type,
    file_name,
    storage_path,
    mime_type,
    file_size,
    document_sha256,
    uploaded_by,
    uploaded_at
  )
  VALUES (
    p_expense_id,
    p_document_type,
    BTRIM(p_file_name),
    p_storage_path,
    p_mime_type,
    p_file_size,
    LOWER(p_document_sha256),
    auth.uid(),
    CURRENT_TIMESTAMP
  )
  RETURNING *
  INTO v_document;


  RETURN v_document;

END;
$_$;


ALTER FUNCTION "public"."attach_expense_document"("p_expense_id" "uuid", "p_document_type" "text", "p_file_name" "text", "p_storage_path" "text", "p_mime_type" "text", "p_file_size" bigint, "p_document_sha256" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."attach_expense_document"("p_expense_id" "uuid", "p_document_type" "text", "p_file_name" "text", "p_storage_path" "text", "p_mime_type" "text", "p_file_size" bigint, "p_document_sha256" "text") IS 'Registers a PDF already uploaded to the private expense-documents bucket and validates its metadata.';



