    "customer_province" "text",
    "customer_country" "text",
    "customer_contact_name" "text",
    "rectifies_invoice_id" "uuid",
    "rectification_reason" "text",
    "rectification_customer_data_source" "text" DEFAULT 'original_invoice'::"text" NOT NULL,
    CONSTRAINT "invoices_amount_check" CHECK (("monto" >= (0)::numeric)),
    CONSTRAINT "invoices_descripcion_length_check" CHECK ((("descripcion" IS NULL) OR ("length"("descripcion") <= 5000))),
    CONSTRAINT "invoices_document_path_length_check" CHECK ((("document_path" IS NULL) OR ("length"("document_path") <= 500))),
    CONSTRAINT "invoices_document_sha256_format" CHECK ((("document_sha256" IS NULL) OR ("document_sha256" ~ '^[0-9a-fA-F]{64}$'::"text"))),
    CONSTRAINT "invoices_due_date_after_issue_check" CHECK ((("fecha_vencimiento" IS NULL) OR ("fecha_vencimiento" >= "fecha_emision"))),
    CONSTRAINT "invoices_importe_a_pagar_check" CHECK ((("importe_a_pagar" >= (0)::numeric) AND ("importe_a_pagar" = "round"(("monto" - "irpf_importe"), 2)))),
    CONSTRAINT "invoices_irpf_aplicado_check" CHECK (((("irpf_aplicado" = true) AND ("irpf_porcentaje" > (0)::numeric) AND ("irpf_porcentaje" <= (100)::numeric) AND ("irpf_importe" >= (0)::numeric) AND ("irpf_importe" <= COALESCE("subtotal", (0)::numeric))) OR (("irpf_aplicado" = false) AND ("irpf_porcentaje" = (0)::numeric) AND ("irpf_importe" = (0)::numeric)))),
    CONSTRAINT "invoices_iva_aplicado_check" CHECK (((("iva_aplicado" = true) AND (COALESCE("iva_porcentaje", (0)::numeric) >= (0)::numeric) AND (COALESCE("iva_porcentaje", (0)::numeric) <= (100)::numeric) AND (COALESCE("iva_importe", (0)::numeric) >= (0)::numeric)) OR (("iva_aplicado" = false) AND (COALESCE("iva_porcentaje", (0)::numeric) = (0)::numeric) AND (COALESCE("iva_importe", (0)::numeric) = (0)::numeric)))),
    CONSTRAINT "invoices_not_self_rectifying_check" CHECK ((("rectifies_invoice_id" IS NULL) OR ("rectifies_invoice_id" <> "id"))),
    CONSTRAINT "invoices_numero_factura_length_check" CHECK ((("numero_factura" IS NULL) OR ("length"("numero_factura") <= 50))),
    CONSTRAINT "invoices_rectification_customer_data_source_check" CHECK (("rectification_customer_data_source" = ANY (ARRAY['original_invoice'::"text", 'current_company'::"text"]))),
    CONSTRAINT "invoices_rectification_reason_consistency" CHECK (((("rectifies_invoice_id" IS NULL) AND ("rectification_reason" IS NULL)) OR (("rectifies_invoice_id" IS NOT NULL) AND ("rectification_reason" IS NOT NULL) AND ("length"("btrim"("rectification_reason")) > 0) AND ("length"("rectification_reason") <= 2000))))
);


