CREATE OR REPLACE FUNCTION "public"."attach_invoice_document"("p_invoice_id" "uuid", "p_document_path" "text") RETURNS "public"."invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_invoice public.invoices;
BEGIN

    PERFORM public.require_current_worker_permission(
        'invoices.update'
    );

    IF p_document_path IS NULL
       OR TRIM(p_document_path) = ''
    THEN
        RAISE EXCEPTION
            'El documento es obligatorio';
    END IF;

    UPDATE public.invoices
    SET
        document_path = TRIM(p_document_path),
        document_sha256 = NULL,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_invoice_id
    RETURNING *
    INTO v_invoice;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La factura no existe';
    END IF;

    RETURN v_invoice;

END;
$$;


