    CONSTRAINT "maintenance_custom_proposal_documents_mime_check" CHECK (("lower"(TRIM(BOTH FROM "document_mime_type")) = 'application/pdf'::"text")),
    CONSTRAINT "maintenance_custom_proposal_documents_path_check" CHECK ((("length"("btrim"("document_path")) > 0) AND ("length"("document_path") <= 500) AND ("document_path" ~ '^[0-9a-fA-F-]{36}/[^/]+\.pdf$'::"text"))),
    CONSTRAINT "maintenance_custom_proposal_documents_sha256_check" CHECK (("document_sha256" ~ '^[0-9a-fA-F]{64}$'::"text")),
    CONSTRAINT "maintenance_custom_proposal_documents_size_check" CHECK ((("document_file_size" IS NULL) OR (("document_file_size" > 0) AND ("document_file_size" <= 20971520)))),
    CONSTRAINT "maintenance_custom_proposal_documents_version_check" CHECK (("version" > 0))
);


