COMMENT ON TABLE "public"."maintenance_invoices" IS 'Facturas de mantenimiento conservadas como registros históricos. El PDF de Modira lo adjunta un trabajador; el PDF de Stripe se conserva separadamente como documento auxiliar.';



COMMENT ON COLUMN "public"."maintenance_invoices"."electronic_document_storage_path" IS 'Ruta del documento electrónico original de la factura cuando se utilice un formato electrónico estructurado u otro formato válido.';



COMMENT ON COLUMN "public"."maintenance_invoices"."pdf_storage_path" IS 'Representación PDF de la factura para visualización/entrega al cliente. No se considera por sí sola el único formato legal de la factura electrónica B2B cuando sea obligatorio un formato estructurado.';



COMMENT ON COLUMN "public"."maintenance_invoices"."document_path" IS 'PDF de la factura de mantenimiento emitida por Modira y adjuntada por un trabajador. Es independiente del PDF generado por Stripe.';



COMMENT ON COLUMN "public"."maintenance_invoices"."document_sha256" IS 'Hash SHA-256 del PDF de la factura de Modira, registrado para reforzar la trazabilidad e integridad del documento.';



COMMENT ON COLUMN "public"."maintenance_invoices"."stripe_pdf_storage_path" IS 'PDF auxiliar generado por Stripe para su propia invoice de Billing. No sustituye automáticamente la factura emitida por Modira.';



CREATE OR REPLACE FUNCTION "public"."attach_maintenance_invoice_document"("p_invoice_id" "uuid", "p_document_path" "text") RETURNS "public"."maintenance_invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$

DECLARE
    v_invoice public.maintenance_invoices;
    v_object storage.objects;
    v_path TEXT;

BEGIN

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    IF NOT public.current_worker_has_permission(
        'maintenance.update'
    ) THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere el permiso maintenance.update';
    END IF;


    v_path := BTRIM(
        COALESCE(
            p_document_path,
            ''
        )
    );


    IF v_path = '' THEN
        RAISE EXCEPTION
            'El documento es obligatorio';
    END IF;


    IF v_path !~ (
        '^'
        || p_invoice_id::TEXT
        || '/.+\.pdf$'
    ) THEN
        RAISE EXCEPTION
            'La ruta del documento no corresponde a la factura indicada';
    END IF;


    SELECT *
    INTO v_invoice
    FROM public.maintenance_invoices
    WHERE id = p_invoice_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La factura de mantenimiento no existe';
    END IF;


    SELECT *
    INTO v_object
    FROM storage.objects
    WHERE bucket_id = 'maintenance-invoices'
      AND name = v_path;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El PDF no existe en el bucket maintenance-invoices';
    END IF;


    IF LOWER(
        COALESCE(
            v_object.metadata->>'mimetype',
            ''
        )
    ) <> 'application/pdf' THEN
        RAISE EXCEPTION
            'El documento de factura debe ser un PDF';
    END IF;


    IF v_invoice.document_path IS NOT NULL
       AND v_invoice.document_path <> v_path
    THEN
        RAISE EXCEPTION
            'La factura ya tiene un documento asociado; no se permite sustituirlo desde esta operación';
    END IF;


    UPDATE public.maintenance_invoices
    SET
        document_path = v_path,
        document_mime_type = 'application/pdf',
        document_file_size =
            COALESCE(
                (v_object.metadata->>'size')::BIGINT,
                NULL
            ),
        document_uploaded_at = CURRENT_TIMESTAMP,
        document_uploaded_by = auth.uid(),
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_invoice_id
    RETURNING *
    INTO v_invoice;


    RETURN v_invoice;

END;
$_$;


ALTER FUNCTION "public"."attach_maintenance_invoice_document"("p_invoice_id" "uuid", "p_document_path" "text") OWNER TO "postgres";


