    "id" "uuid" NOT NULL,
    "project_id" "uuid" NOT NULL,
    "file_name" "text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "mime_type" "text" DEFAULT 'application/pdf'::"text" NOT NULL,
    "file_size" bigint NOT NULL,
    "uploaded_by" "uuid",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "project_documents_file_name_check" CHECK (("length"("btrim"("file_name")) > 0)),
    CONSTRAINT "project_documents_file_name_length_check" CHECK ((("file_name" IS NULL) OR ("length"("file_name") <= 255))),
    CONSTRAINT "project_documents_file_size_check" CHECK (("file_size" > 0)),
    CONSTRAINT "project_documents_mime_type_check" CHECK (("mime_type" = 'application/pdf'::"text")),
    CONSTRAINT "project_documents_mime_type_length_check" CHECK ((("mime_type" IS NULL) OR ("length"("mime_type") <= 100))),
    CONSTRAINT "project_documents_storage_path_length_check" CHECK ((("storage_path" IS NULL) OR ("length"("storage_path") <= 500)))
);


ALTER TABLE "public"."project_documents" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_project_document"("p_project_id" "uuid", "p_document_id" "uuid", "p_file_name" "text", "p_file_size" bigint) RETURNS "public"."project_documents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_document public.project_documents;
    v_storage_path TEXT;
BEGIN

    PERFORM public.require_current_worker_permission(
        'projects.update'
    );

    IF p_project_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto es obligatorio';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.projects
        WHERE id = p_project_id
    ) THEN
        RAISE EXCEPTION
            'Proyecto no encontrado';
    END IF;

    IF p_document_id IS NULL THEN
        RAISE EXCEPTION
            'El identificador del documento es obligatorio';
    END IF;

    IF p_file_name IS NULL
       OR btrim(p_file_name) = ''
    THEN
        RAISE EXCEPTION
            'El nombre del documento es obligatorio';
    END IF;

    IF length(btrim(p_file_name)) > 255 THEN
        RAISE EXCEPTION
            'El nombre del documento no puede superar 255 caracteres';
    END IF;

    IF p_file_size IS NULL
       OR p_file_size <= 0
    THEN
        RAISE EXCEPTION
            'El tamaño del documento debe ser mayor que cero';
    END IF;

    v_storage_path :=
        p_project_id::TEXT
        || '/'
        || p_document_id::TEXT
        || '.pdf';

    IF NOT EXISTS (
        SELECT 1
        FROM storage.objects
        WHERE bucket_id = 'project-documents'
          AND name = v_storage_path
    ) THEN
        RAISE EXCEPTION
            'El documento no existe en el bucket de proyectos';
    END IF;

    SELECT *
    INTO v_document
    FROM public.project_documents
    WHERE id = p_document_id
    FOR UPDATE;

    IF FOUND THEN

        IF v_document.project_id <> p_project_id THEN
            RAISE EXCEPTION
                'El documento ya pertenece a otro proyecto';
        END IF;

        UPDATE public.project_documents
        SET
            file_name = btrim(p_file_name),
            storage_path = v_storage_path,
            mime_type = 'application/pdf',
            file_size = p_file_size,
            uploaded_by = auth.uid(),
            updated_at = CURRENT_TIMESTAMP
        WHERE id = p_document_id
        RETURNING *
        INTO v_document;

        RETURN v_document;

    END IF;

    INSERT INTO public.project_documents (
        id,
        project_id,
        file_name,
        storage_path,
        mime_type,
        file_size,
        uploaded_by
    )
    VALUES (
        p_document_id,
        p_project_id,
        btrim(p_file_name),
        v_storage_path,
        'application/pdf',
        p_file_size,
        auth.uid()
    )
    RETURNING *
    INTO v_document;

    RETURN v_document;

END;
$$;


ALTER FUNCTION "public"."attach_project_document"("p_project_id" "uuid", "p_document_id" "uuid", "p_file_name" "text", "p_file_size" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_quotation_number"() RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN
        'PRES-' ||
        TO_CHAR(CURRENT_DATE, 'YY') ||
        '-' ||
        UPPER(
            SUBSTRING(
                REPLACE(gen_random_uuid()::TEXT, '-', '')
                FROM 1 FOR 6
            )
        );
END;
$$;


