    "fecha_emision" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "fecha_validez" timestamp with time zone,
    "notas" "text",
    "stripe_session_id" "text",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "document_path" "text",
    "quotation_version" integer DEFAULT 1 NOT NULL,
    "irpf_aplicado" boolean DEFAULT false NOT NULL,
    "irpf_porcentaje" numeric(5,2) DEFAULT 0 NOT NULL,
    "irpf_importe" numeric(12,2) DEFAULT 0 NOT NULL,
    "document_sha256" "text",
    "issuer_legal_name" "text",
    "issuer_tax_id" "text",
    "issuer_address" "text",
    "issuer_postal_code" "text",
    "issuer_city" "text",
    "issuer_province" "text",
    "issuer_country" "text",
    "customer_legal_name" "text",
    "customer_tax_id" "text",
    "customer_address" "text",
    "customer_postal_code" "text",
    "customer_city" "text",
    "customer_province" "text",
    "customer_country" "text",
    "customer_contact_name" "text",
    CONSTRAINT "quotations_descripcion_detallada_length_check" CHECK ((("descripcion_detallada" IS NULL) OR ("length"("descripcion_detallada") <= 10000))),
    CONSTRAINT "quotations_document_path_length_check" CHECK ((("document_path" IS NULL) OR ("length"("document_path") <= 500))),
    CONSTRAINT "quotations_document_sha256_check" CHECK ((("document_sha256" IS NULL) OR ("document_sha256" ~ '^[0-9a-fA-F]{64}$'::"text"))),
    CONSTRAINT "quotations_estado_check" CHECK ((("estado")::"text" = ANY ((ARRAY['Pendiente'::character varying, 'Aceptado'::character varying, 'Rechazado'::character varying])::"text"[]))),
    CONSTRAINT "quotations_irpf_check" CHECK ((("irpf_porcentaje" >= (0)::numeric) AND ("irpf_porcentaje" <= (100)::numeric) AND ("irpf_importe" >= (0)::numeric) AND ("irpf_importe" <= "precio_base"))),
    CONSTRAINT "quotations_notas_length_check" CHECK ((("notas" IS NULL) OR ("length"("notas") <= 5000))),
    CONSTRAINT "quotations_numero_presupuesto_length_check" CHECK ((("numero_presupuesto" IS NULL) OR ("length"("numero_presupuesto") <= 50))),
    CONSTRAINT "quotations_price_check" CHECK ((("precio_base" >= (0)::numeric) AND ("iva_porcentaje" >= (0)::numeric) AND ("precio_total" >= (0)::numeric))),
    CONSTRAINT "quotations_titulo_length_check" CHECK ((("titulo" IS NULL) OR ("length"("titulo") <= 200))),
    CONSTRAINT "quotations_version_check" CHECK (("quotation_version" >= 1))
);


