CREATE OR REPLACE FUNCTION "public"."attach_quotation_document"("p_quotation_id" "uuid", "p_document_path" "text") RETURNS "public"."quotations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_quotation public.quotations;
    v_expected_path TEXT;
BEGIN

    PERFORM public.require_current_worker_permission(
        'quotations.update'
    );

    SELECT *
    INTO v_quotation
    FROM public.quotations
    WHERE id = p_quotation_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Presupuesto no encontrado';
    END IF;

    v_expected_path :=
        v_quotation.company_id::TEXT
        || '/'
        || v_quotation.numero_presupuesto
        || '.pdf';

    IF p_document_path IS NULL
       OR TRIM(p_document_path) = ''
    THEN
        RAISE EXCEPTION
            'El documento del presupuesto es obligatorio';
    END IF;

    IF p_document_path <> v_expected_path THEN
        RAISE EXCEPTION
            'La ruta del documento no coincide con el presupuesto';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM storage.objects
        WHERE bucket_id = 'quotations'
          AND name = p_document_path
    ) THEN
        RAISE EXCEPTION
            'El documento no existe en el bucket de presupuestos';
    END IF;

    UPDATE public.quotations
    SET
        document_path = TRIM(p_document_path),
        document_sha256 = NULL,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_quotation_id
    RETURNING *
    INTO v_quotation;

    RETURN v_quotation;

END;
$$;


ALTER FUNCTION "public"."attach_quotation_document"("p_quotation_id" "uuid", "p_document_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_expense_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_action TEXT;
    v_description TEXT;
    v_metadata JSONB;
    v_expense_id UUID;
    v_expense_number TEXT;

BEGIN

    -- ========================================================
    -- 1. DETERMINAR EXPENSE ID
    -- ========================================================

    IF TG_OP = 'DELETE' THEN
        v_expense_id := OLD.id;
        v_expense_number := OLD.expense_number;
    ELSE
        v_expense_id := NEW.id;
        v_expense_number := NEW.expense_number;
    END IF;


    -- ========================================================
    -- 2. DETERMINAR ACCIÓN
    -- ========================================================

    IF TG_OP = 'INSERT' THEN

        v_action := 'expense_created';

        v_description :=
            'Se ha creado un gasto interno.';

        v_metadata := jsonb_build_object(
            'operation', 'INSERT',
            'expense_number', v_expense_number,
            'expense_type',
                NEW.expense_type,
            'status',
                NEW.status,
            'category_id',
                NEW.category_id,
            'supplier_id',
                NEW.supplier_id,
            'project_id',
                NEW.project_id
        );


    ELSIF TG_OP = 'DELETE' THEN

        v_action := 'expense_deleted';

        v_description :=
            'Se ha eliminado un gasto interno.';

        v_metadata := jsonb_build_object(
            'operation', 'DELETE',
            'expense_number', v_expense_number,
            'expense_type',
                OLD.expense_type,
            'status',
                OLD.status,
            'category_id',
                OLD.category_id,
            'supplier_id',
                OLD.supplier_id,
            'project_id',
                OLD.project_id
        );


    ELSE

        -- ----------------------------------------------------
        -- UPDATE NORMAL
        -- ----------------------------------------------------

        v_action := 'expense_updated';

        v_description :=
            'Se ha modificado un gasto interno.';

        v_metadata := jsonb_build_object(
            'operation', 'UPDATE',
            'expense_number', NEW.expense_number,
            'previous_status', OLD.status,
            'new_status', NEW.status,
            'previous_project_id', OLD.project_id,
            'new_project_id', NEW.project_id,
            'previous_category_id', OLD.category_id,
            'new_category_id', NEW.category_id,
            'previous_supplier_id', OLD.supplier_id,
            'new_supplier_id', NEW.supplier_id
        );

        -- ----------------------------------------------------
        -- CAMBIO DE ESTADO
        -- ----------------------------------------------------

        IF OLD.status IS DISTINCT FROM NEW.status THEN

            v_action := 'expense_status_changed';

            v_description :=
                'Ha cambiado el estado de un gasto interno.';

            v_metadata := v_metadata
                || jsonb_build_object(
                    'status_changed', TRUE
                );

        END IF;

    END IF;


    -- ========================================================
    -- 3. REGISTRAR EN ACTIVITY_LOG
    -- ========================================================

    PERFORM public.log_activity(
        v_action,
        'expense',
        v_expense_id,
        v_description,
        v_metadata
    );


    -- ========================================================
    -- 4. DEVOLVER FILA
    -- ========================================================

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."audit_expense_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_expense_change"() IS 'Registra en activity_log las operaciones INSERT, UPDATE y DELETE realizadas sobre expenses. Función interna ejecutada exclusivamente mediante trigger.';



CREATE OR REPLACE FUNCTION "public"."audit_expense_related_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_expense_id UUID;
    v_action TEXT;
    v_resource_type TEXT;
    v_description TEXT;
    v_metadata JSONB;

BEGIN

    -- ========================================================
    -- 1. EXPENSE ID
    -- ========================================================

    IF TG_OP = 'DELETE' THEN
        v_expense_id := OLD.expense_id;
    ELSE
        v_expense_id := NEW.expense_id;
    END IF;


    -- ========================================================
    -- 2. RESOURCE TYPE
    -- ========================================================

    CASE TG_TABLE_NAME

        WHEN 'expense_documents' THEN
            v_resource_type := 'expense_document';

        WHEN 'expense_payments' THEN
            v_resource_type := 'expense_payment';

        WHEN 'expense_tax_lines' THEN
            v_resource_type := 'expense_tax_line';

        WHEN 'expense_allocations' THEN
            v_resource_type := 'expense_allocation';

        ELSE
            RAISE EXCEPTION
                '126: tabla de gasto relacionada no soportada: %',
                TG_TABLE_NAME;

    END CASE;


    -- ========================================================
    -- 3. ACTION
    -- ========================================================

    v_action :=
        'expense_' ||
        CASE TG_TABLE_NAME
            WHEN 'expense_documents' THEN 'document'
            WHEN 'expense_payments' THEN 'payment'
            WHEN 'expense_tax_lines' THEN 'tax'
            WHEN 'expense_allocations' THEN 'allocation'
        END
        || '_' ||
        LOWER(TG_OP);


    -- ========================================================
    -- 4. DESCRIPTION
    -- ========================================================

    v_description :=
        CASE TG_OP
            WHEN 'INSERT'
                THEN 'Se ha creado un elemento relacionado con un gasto interno.'
            WHEN 'UPDATE'
                THEN 'Se ha modificado un elemento relacionado con un gasto interno.'
            WHEN 'DELETE'
                THEN 'Se ha eliminado un elemento relacionado con un gasto interno.'
        END;


    -- ========================================================
    -- 5. METADATA
    -- ========================================================

    v_metadata := jsonb_build_object(
        'operation', TG_OP,
        'table_name', TG_TABLE_NAME,
        'expense_id', v_expense_id
    );


    -- ========================================================
    -- DOCUMENTOS
    -- ========================================================

    IF TG_TABLE_NAME = 'expense_documents' THEN

        v_metadata := v_metadata
            || jsonb_build_object(
                'document_type',
                    CASE
                        WHEN TG_OP = 'DELETE'
                        THEN OLD.document_type
                        ELSE NEW.document_type
                    END,
                'file_name',
                    CASE
                        WHEN TG_OP = 'DELETE'
                        THEN OLD.file_name
                        ELSE NEW.file_name
                    END
            );

    END IF;


    -- ========================================================
    -- PAYMENTS
    -- ========================================================

    IF TG_TABLE_NAME = 'expense_payments' THEN

        v_metadata := v_metadata
            || jsonb_build_object(
                'amount',
                    CASE
                        WHEN TG_OP = 'DELETE'
                        THEN OLD.amount
                        ELSE NEW.amount
                    END,
                'payment_method',
                    CASE
                        WHEN TG_OP = 'DELETE'
                        THEN OLD.payment_method
                        ELSE NEW.payment_method
                    END,
                'status',
                    CASE
                        WHEN TG_OP = 'DELETE'
                        THEN OLD.status
                        ELSE NEW.status
                    END
            );

    END IF;


    -- ========================================================
    -- TAX
    -- ========================================================

    IF TG_TABLE_NAME = 'expense_tax_lines' THEN

        v_metadata := v_metadata
            || jsonb_build_object(
                'tax_type',
                    CASE
                        WHEN TG_OP = 'DELETE'
                        THEN OLD.tax_type
                        ELSE NEW.tax_type
                    END,
                'tax_rate',
                    CASE
                        WHEN TG_OP = 'DELETE'
                        THEN OLD.tax_rate
                        ELSE NEW.tax_rate
                    END,
                'tax_amount',
                    CASE
                        WHEN TG_OP = 'DELETE'
                        THEN OLD.tax_amount
                        ELSE NEW.tax_amount
                    END
            );

    END IF;


    -- ========================================================
    -- ALLOCATIONS
    -- ========================================================

    IF TG_TABLE_NAME = 'expense_allocations' THEN

        v_metadata := v_metadata
            || jsonb_build_object(
                'project_id',
                    CASE
                        WHEN TG_OP = 'DELETE'
                        THEN OLD.project_id
                        ELSE NEW.project_id
                    END,
                'amount',
                    CASE
                        WHEN TG_OP = 'DELETE'
                        THEN OLD.amount
                        ELSE NEW.amount
                    END,
                'percentage',
                    CASE
                        WHEN TG_OP = 'DELETE'
                        THEN OLD.percentage
                        ELSE NEW.percentage
                    END
            );

    END IF;


    -- ========================================================
    -- 6. REGISTRAR
    -- ========================================================

    PERFORM public.log_activity(
        v_action,
        v_resource_type,
        v_expense_id,
        v_description,
        v_metadata
    );


    -- ========================================================
    -- 7. RETURN
    -- ========================================================

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."audit_expense_related_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_expense_related_change"() IS 'Registra en activity_log las operaciones sobre documentos, pagos, impuestos y asignaciones de gastos. Función interna ejecutada exclusivamente mediante trigger.';



CREATE OR REPLACE FUNCTION "public"."calculate_maintenance_invoice_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Las facturas de Stripe conservan los importes recibidos.
  IF NEW.stripe_invoice_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Mantener el cálculo actual para las demás facturas.
  NEW.iva_porcentaje = COALESCE(NEW.iva_porcentaje, 0);

  NEW.iva_importe = CASE
    WHEN COALESCE(NEW.iva_aplicado, FALSE)
    THEN ROUND(
      COALESCE(NEW.subtotal, 0) * NEW.iva_porcentaje / 100,
      2
    )
    ELSE 0
  END;

  NEW.irpf_porcentaje = COALESCE(NEW.irpf_porcentaje, 0);

  NEW.irpf_importe = CASE
    WHEN COALESCE(NEW.irpf_aplicado, FALSE)
    THEN ROUND(
      COALESCE(NEW.subtotal, 0) * NEW.irpf_porcentaje / 100,
      2
    )
    ELSE 0
  END;

  NEW.monto = ROUND(
    COALESCE(NEW.subtotal, 0) + COALESCE(NEW.iva_importe, 0),
    2
  );

  NEW.importe_a_pagar = ROUND(
    NEW.monto - COALESCE(NEW.irpf_importe, 0),
    2
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_maintenance_invoice_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_user_pay_project_invoice"("p_invoice_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_invoice public.invoices;
    v_project public.projects;

BEGIN

    IF p_user_id IS NULL THEN
        RETURN FALSE;
    END IF;


    SELECT *
    INTO v_invoice
    FROM public.invoices
    WHERE id = p_invoice_id;


    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;


    -- Las facturas de mantenimiento tienen su propia
    -- autorización económica.

    IF v_invoice.project_id IS NULL THEN
        RETURN FALSE;
    END IF;


    SELECT *
    INTO v_project
    FROM public.projects
    WHERE id = v_invoice.project_id;


    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;


    RETURN
        v_project.user_id = p_user_id
        AND v_project.company_id =
            public.current_user_company_id();

END;
$$;


ALTER FUNCTION "public"."can_user_pay_project_invoice"("p_invoice_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_expense"("p_expense_id" "uuid") RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_expense public.expenses;

  v_paid_amount NUMERIC(14,2);

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.update'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:cancel'
  );


  SELECT *
  INTO v_expense

  FROM public.expenses

  WHERE id = p_expense_id

  FOR UPDATE;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El gasto % no existe',
      p_expense_id;

  END IF;


  IF v_expense.status IN (
    'paid',
    'cancelled'
  ) THEN

    RAISE EXCEPTION
      'No se puede cancelar un gasto en estado %',
      v_expense.status;

  END IF;


  SELECT public.get_expense_paid_amount(
    p_expense_id
  )
  INTO v_paid_amount;


  IF v_paid_amount > 0 THEN

    RAISE EXCEPTION
      'No se puede cancelar un gasto que ya tiene pagos confirmados';

  END IF;


  UPDATE public.expenses

  SET
    status = 'cancelled',
    updated_by = auth.uid(),
    updated_at = CURRENT_TIMESTAMP

  WHERE id = p_expense_id

  RETURNING *
  INTO v_expense;


  RETURN v_expense;

END;
$$;


ALTER FUNCTION "public"."cancel_expense"("p_expense_id" "uuid") OWNER TO "postgres";


