    "payment_date" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "payment_method" "text" NOT NULL,
    "reference" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "is_automatic" boolean DEFAULT false NOT NULL,
    CONSTRAINT "expense_payments_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "expense_payments_method_check" CHECK (("payment_method" = ANY (ARRAY['bank_transfer'::"text", 'card'::"text", 'cash'::"text", 'direct_debit'::"text", 'other'::"text"]))),
    CONSTRAINT "expense_payments_reference_check" CHECK ((("reference" IS NULL) OR (("length"("btrim"("reference")) >= 1) AND ("length"("btrim"("reference")) <= 255)))),
    CONSTRAINT "expense_payments_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'succeeded'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


