COMMENT ON COLUMN "public"."expense_payments"."amount" IS 'Importe del pago realizado por Modira.';



COMMENT ON COLUMN "public"."expense_payments"."payment_method" IS 'Método de pago: bank_transfer, card, cash, direct_debit u other.';



COMMENT ON COLUMN "public"."expense_payments"."reference" IS 'Referencia bancaria, número de operación o identificador externo del pago.';



COMMENT ON COLUMN "public"."expense_payments"."status" IS 'Estado del pago: pending, succeeded, failed o cancelled.';



CREATE OR REPLACE FUNCTION "public"."cancel_expense_payment"("p_payment_id" "uuid") RETURNS "public"."expense_payments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_payment public.expense_payments;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.pay'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:payment_cancel'
  );


  SELECT *
  INTO v_payment

  FROM public.expense_payments

  WHERE id = p_payment_id

  FOR UPDATE;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El pago % no existe',
      p_payment_id;

  END IF;


  IF v_payment.status <> 'pending' THEN

    RAISE EXCEPTION
      'Solo se pueden cancelar pagos pending';

  END IF;


  UPDATE public.expense_payments

  SET
    status = 'cancelled',
    updated_at = CURRENT_TIMESTAMP

  WHERE id = p_payment_id

  RETURNING *
  INTO v_payment;


  RETURN v_payment;

END;
$$;


