CREATE OR REPLACE FUNCTION "public"."cancel_maintenance_contract_project_change"("p_request_id" "uuid") RETURNS "public"."maintenance_contract_project_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_company_id UUID;
  v_request public.maintenance_contract_project_change_requests;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Debes iniciar sesión';
  END IF;

  IF public.current_user_is_worker() THEN
    RAISE EXCEPTION 'Los trabajadores no utilizan esta vía';
  END IF;

  IF NOT public.current_user_is_active() THEN
    RAISE EXCEPTION 'El usuario no está activo';
  END IF;

  v_company_id := public.current_user_company_id();

  SELECT *
  INTO v_request
  FROM public.maintenance_contract_project_change_requests
  WHERE id = p_request_id
    AND company_id = v_company_id
    AND requested_by = v_user_id
    AND status = 'pending'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'La solicitud no existe o no puede cancelarse';
  END IF;

  UPDATE public.maintenance_contract_project_change_requests
  SET
    status = 'cancelled',
    updated_at = CURRENT_TIMESTAMP
  WHERE id = v_request.id
  RETURNING *
  INTO v_request;

  RETURN v_request;
END;
$$;


ALTER FUNCTION "public"."cancel_maintenance_contract_project_change"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_ai_rate_limits"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_deleted INTEGER;
BEGIN

    DELETE FROM public.ai_rate_limits
    WHERE updated_at < (
        clock_timestamp()
        - INTERVAL '24 hours'
    );

    GET DIAGNOSTICS
        v_deleted = ROW_COUNT;

    RETURN v_deleted;

END;
$$;


ALTER FUNCTION "public"."cleanup_ai_rate_limits"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_ai_usage_reservations"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$

DECLARE

    r public.ai_usage_reservations;

    v_now TIMESTAMPTZ := clock_timestamp();

    v_count INTEGER := 0;

BEGIN

    /*
     * Procesamos únicamente reservas todavía pendientes.
     *
     * FOR UPDATE SKIP LOCKED evita competir con otra ejecución
     * simultánea del cleanup o con finalize_ai_quota().
     */

    FOR r IN

        SELECT *

        FROM public.ai_usage_reservations

        WHERE status = 'reserved'
          AND expires_at <= v_now

        ORDER BY expires_at

        FOR UPDATE SKIP LOCKED

    LOOP

        -- ====================================================
        -- RESERVA ANÓNIMA
        -- ====================================================

        IF r.scope_key LIKE 'anon-ip:%'
        THEN

            /*
             * El advisory lock es el mismo utilizado por
             * reserve_ai_anonymous_quota().
             *
             * Esto evita modificar los contadores mientras
             * otra reserva para la misma identidad está siendo
             * creada.
             */

            PERFORM pg_advisory_xact_lock(
                hashtextextended(
                    r.scope_key,
                    19020
                )
            );


            /*
             * Solo liberamos contadores si la fila actual
             * corresponde todavía al período en el que nació
             * la reserva.
             *
             * Si el período ya terminó y fue renovado, sus
             * reserved_* ya fueron reiniciados y NO debemos
             * restarlos de nuevo.
             */

            UPDATE public.ai_anonymous_quota_periods

            SET

                reserved_requests =
                    GREATEST(
                        0,
                        reserved_requests - 1
                    ),

                reserved_input_tokens =
                    GREATEST(
                        0,
                        reserved_input_tokens
                        - r.estimated_input_tokens
                    ),

                reserved_output_tokens =
                    GREATEST(
                        0,
                        reserved_output_tokens
                        - r.estimated_output_tokens
                    ),

                reserved_cost_cents =
                    GREATEST(
                        0,
                        reserved_cost_cents
                        - r.estimated_cost_cents
                    ),

                updated_at = v_now

            WHERE identity_key = r.scope_key

              AND period_started_at <= r.expires_at

              AND period_ends_at > r.expires_at;


        ELSE

            -- =================================================
            -- RESERVA AUTENTICADA
            -- =================================================

            PERFORM pg_advisory_xact_lock(
                hashtextextended(
                    r.scope_key,
                    19019
                )
            );


            /*
             * Liberar solamente si la reserva pertenece al
             * período actualmente almacenado.
             */

            UPDATE public.ai_usage_periods

            SET

                reserved_requests =
                    GREATEST(
                        0,
                        reserved_requests - 1
                    ),

                reserved_input_tokens =
                    GREATEST(
                        0,
                        reserved_input_tokens
                        - r.estimated_input_tokens
                    ),

                reserved_output_tokens =
                    GREATEST(
                        0,
                        reserved_output_tokens
                        - r.estimated_output_tokens
                    ),

                reserved_cost_cents =
                    GREATEST(
                        0,
                        reserved_cost_cents
                        - r.estimated_cost_cents
                    ),

                updated_at = v_now

            WHERE scope_key = r.scope_key

              AND period_started_at <= r.expires_at

              AND period_ends_at > r.expires_at;


            -- ================================================
            -- CUOTA EMPRESA
            -- ================================================
            --
            -- La reserva de empresa se libera si existe
            -- company_id, independientemente de la configuración
            -- actual de company_request_limit.
            --
            -- Esto evita dejar contadores bloqueados si la
            -- configuración cambia después de crear la reserva.
            --

            IF r.company_id IS NOT NULL
            THEN

                PERFORM pg_advisory_xact_lock(
                    hashtextextended(
                        'company:' || r.company_id::TEXT,
                        19019
                    )
                );


                UPDATE public.ai_usage_periods

                SET

                    reserved_requests =
                        GREATEST(
                            0,
                            reserved_requests - 1
                        ),

                    reserved_input_tokens =
                        GREATEST(
                            0,
                            reserved_input_tokens
                            - r.estimated_input_tokens
                        ),

                    reserved_output_tokens =
                        GREATEST(
                            0,
                            reserved_output_tokens
                            - r.estimated_output_tokens
                        ),

                    reserved_cost_cents =
                        GREATEST(
                            0,
                            reserved_cost_cents
                            - r.estimated_cost_cents
                        ),

                    updated_at = v_now

                WHERE scope_key =
                    'company:' || r.company_id::TEXT

                  AND period_started_at <= r.expires_at

                  AND period_ends_at > r.expires_at;

            END IF;

        END IF;


        -- ====================================================
        -- MARCAR RESERVA COMO EXPIRADA
        -- ====================================================

        UPDATE public.ai_usage_reservations

        SET

            status = 'expired',

            finalized_at = v_now

        WHERE id = r.id

          AND status = 'reserved';


        IF FOUND
        THEN
            v_count := v_count + 1;
        END IF;

    END LOOP;


    RETURN v_count;

END;

$$;


ALTER FUNCTION "public"."cleanup_ai_usage_reservations"() OWNER TO "postgres";


