    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'support.update'
    );

    RETURN public.close_support_ticket__legacy_113(
        p_ticket_id
    );

END;
