CREATE OR REPLACE FUNCTION "public"."close_support_ticket__legacy_113"("p_ticket_id" "uuid") RETURNS "public"."support_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
v_ticket public.support_tickets;
BEGIN
IF NOT public.current_user_is_worker() THEN
RAISE EXCEPTION
'Acceso denegado: se requiere un trabajador activo';
END IF;
UPDATE public.support_tickets
SET
estado = 'cerrado',
fecha_cierre = CURRENT_TIMESTAMP,
updated_at = CURRENT_TIMESTAMP
WHERE id = p_ticket_id
RETURNING *
INTO v_ticket;

IF NOT FOUND THEN
RAISE EXCEPTION
'El ticket no existe';
END IF;
INSERT INTO public.activity_log (
user_id,
company_id,
action,
resource_type,
resource_id,
description
)
VALUES (
auth.uid(),
v_ticket.company_id,
'ticket.closed',
'support_ticket',
v_ticket.id,
'Ticket cerrado por un trabajador'
);
RETURN v_ticket;
END;
$$;


