CREATE OR REPLACE FUNCTION "public"."complete_registration_legal_requirements"("p_terms_accepted" boolean, "p_privacy_acknowledged" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_profile public.profiles;

    v_terms_id UUID;
    v_terms_hash TEXT;

    v_privacy_id UUID;
    v_privacy_hash TEXT;

    v_ip TEXT;
    v_user_agent TEXT;
BEGIN
    -- --------------------------------------------------------
    -- 1. USUARIO AUTENTICADO
    -- --------------------------------------------------------

    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- 2. LAS DOS CASILLAS SON OBLIGATORIAS
    -- --------------------------------------------------------

    IF p_terms_accepted IS NOT TRUE THEN
        RAISE EXCEPTION
            'Las Condiciones de Uso deben ser aceptadas';
    END IF;

    IF p_privacy_acknowledged IS NOT TRUE THEN
        RAISE EXCEPTION
            'La Información de Privacidad debe ser reconocida';
    END IF;


    -- --------------------------------------------------------
    -- 3. BLOQUEAR EL PERFIL DURANTE LA OPERACIÓN
    -- --------------------------------------------------------

    SELECT *
    INTO v_profile
    FROM public.profiles
    WHERE id = v_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Perfil no encontrado';
    END IF;

    IF v_profile.status = 'active' THEN
        -- La cuenta ya está finalizada.
        -- No se vuelven a crear aceptaciones.
        RETURN;
    END IF;

    IF v_profile.status <> 'pending_legal' THEN
        RAISE EXCEPTION
            'La cuenta no está pendiente de completar los requisitos legales';
    END IF;


    -- --------------------------------------------------------
    -- 4. OBTENER CONDICIONES DE USO VIGENTES
    -- --------------------------------------------------------

    SELECT
        id,
        content_hash
    INTO
        v_terms_id,
        v_terms_hash
    FROM public.legal_documents
    WHERE document_type = 'terms_of_use'
      AND is_current = TRUE
      AND effective_from <= clock_timestamp()
      AND (
          effective_until IS NULL
          OR effective_until > clock_timestamp()
      )
    ORDER BY
        effective_from DESC,
        created_at DESC
    LIMIT 1;

    IF v_terms_id IS NULL THEN
        RAISE EXCEPTION
            'No existen Condiciones de Uso vigentes';
    END IF;


    -- --------------------------------------------------------
    -- 5. OBTENER INFORMACIÓN DE PRIVACIDAD VIGENTE
    -- --------------------------------------------------------

    SELECT
        id,
        content_hash
    INTO
        v_privacy_id,
        v_privacy_hash
    FROM public.legal_documents
    WHERE document_type = 'privacy_information'
      AND is_current = TRUE
      AND effective_from <= clock_timestamp()
      AND (
          effective_until IS NULL
          OR effective_until > clock_timestamp()
      )
    ORDER BY
        effective_from DESC,
        created_at DESC
    LIMIT 1;

    IF v_privacy_id IS NULL THEN
        RAISE EXCEPTION
            'No existe Información de Privacidad vigente';
    END IF;


    -- --------------------------------------------------------
    -- 6. IDENTIDAD TÉCNICA OBSERVADA POR BACKEND
    -- --------------------------------------------------------

    v_ip := public.observed_request_ip();
    v_user_agent := public.observed_request_user_agent();


    -- --------------------------------------------------------
    -- 7. REGISTRAR ACEPTACIÓN DE CONDICIONES DE USO
    -- --------------------------------------------------------

    INSERT INTO public.legal_acceptances (
        user_id,
        company_id,
        document_id,
        action_type,
        accepted_at,
        ip,
        user_agent,
        context,
        source,
        document_hash
    )
    VALUES (
        v_user_id,
        v_profile.company_id,
        v_terms_id,
        'accepted',
        clock_timestamp(),
        v_ip,
        v_user_agent,
        'registration',
        'account_creation',
        v_terms_hash
    );


    -- --------------------------------------------------------
    -- 8. REGISTRAR ACUSE DE INFORMACIÓN DE PRIVACIDAD
    -- --------------------------------------------------------

    INSERT INTO public.legal_acceptances (
        user_id,
        company_id,
        document_id,
        action_type,
        accepted_at,
        ip,
        user_agent,
        context,
        source,
        document_hash
    )
    VALUES (
        v_user_id,
        v_profile.company_id,
        v_privacy_id,
        'acknowledged',
        clock_timestamp(),
        v_ip,
        v_user_agent,
        'registration',
        'account_creation',
        v_privacy_hash
    );


    -- --------------------------------------------------------
    -- 9. ACTIVAR CUENTA SOLO DESPUÉS DE LAS DOS EVIDENCIAS
    -- --------------------------------------------------------

    UPDATE public.profiles
    SET
        status = 'active',
        updated_at = CURRENT_TIMESTAMP
    WHERE id = v_user_id
      AND status = 'pending_legal';

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No se pudo activar la cuenta';
    END IF;

END;
$$;


ALTER FUNCTION "public"."complete_registration_legal_requirements"("p_terms_accepted" boolean, "p_privacy_acknowledged" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_registration_legal_requirements"("p_terms_accepted" boolean, "p_privacy_acknowledged" boolean) IS 'Completa los requisitos legales del registro: acepta Condiciones de Uso, registra el acuse de Información de Privacidad y activa la cuenta.';



