    "client_id" "uuid",
    "nombre" "text" NOT NULL,
    "descripcion" "text",
    "estado" "text" DEFAULT 'Pendiente'::"text" NOT NULL,
    "fecha_inicio" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "fecha_fin" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "change_requests_enabled" boolean DEFAULT false NOT NULL,
    "change_requests_deadline" timestamp with time zone,
    CONSTRAINT "projects_change_requests_config_check" CHECK ((("change_requests_enabled" = false) OR ("change_requests_deadline" IS NOT NULL))),
    CONSTRAINT "projects_descripcion_length_check" CHECK ((("descripcion" IS NULL) OR ("length"("descripcion") <= 10000))),
    CONSTRAINT "projects_estado_check" CHECK (("estado" = ANY (ARRAY['Pendiente'::"text", 'Activo'::"text", 'Pausado'::"text", 'Entregado'::"text", 'Completado'::"text"]))),
    CONSTRAINT "projects_nombre_length_check" CHECK ((("nombre" IS NULL) OR ("length"("nombre") <= 200)))
);


ALTER TABLE "public"."projects" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."configure_project_change_requests"("p_project_id" "uuid", "p_enabled" boolean, "p_deadline" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."projects"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_project public.projects;

BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    IF NOT public.current_worker_has_permission(
        'projects.update'
    ) THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere el permiso projects.update';
    END IF;


    IF p_project_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto es obligatorio';
    END IF;


    IF p_enabled IS NULL THEN
        RAISE EXCEPTION
            'La configuración de solicitudes es obligatoria';
    END IF;


    IF p_enabled = TRUE
       AND p_deadline IS NULL
    THEN
        RAISE EXCEPTION
            'Debe establecerse una fecha límite cuando las solicitudes están habilitadas';
    END IF;


    SELECT *
    INTO v_project
    FROM public.projects
    WHERE id = p_project_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Proyecto no encontrado';
    END IF;


    UPDATE public.projects
    SET
        change_requests_enabled = p_enabled,
        change_requests_deadline =
            CASE
                WHEN p_enabled = FALSE
                    THEN p_deadline
                ELSE
                    p_deadline
            END,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_project_id
    RETURNING *
    INTO v_project;


    INSERT INTO public.activity_log (
        user_id,
        company_id,
        action,
        resource_type,
        resource_id,
        description,
        metadata
    )
    VALUES (
        auth.uid(),
        v_project.company_id,
        'project.change_requests_configured',
        'project',
        v_project.id,
        CASE
            WHEN p_enabled = TRUE
                THEN 'Periodo de solicitudes de cambio habilitado'
            ELSE
                'Solicitudes de cambio deshabilitadas'
        END,
        jsonb_build_object(
            'enabled', p_enabled,
            'deadline', p_deadline
        )
    );


    RETURN v_project;

END;
$$;


ALTER FUNCTION "public"."configure_project_change_requests"("p_project_id" "uuid", "p_enabled" boolean, "p_deadline" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_expense_payment"("p_payment_id" "uuid") RETURNS "public"."expense_payments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_payment public.expense_payments;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.pay'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:payment_confirm'
  );


  SELECT *
  INTO v_payment

  FROM public.expense_payments

  WHERE id = p_payment_id

  FOR UPDATE;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El pago % no existe',
      p_payment_id;

  END IF;


  IF v_payment.status <> 'pending' THEN

    RAISE EXCEPTION
      'Solo se pueden confirmar pagos pending';

  END IF;


  UPDATE public.expense_payments

  SET
    status = 'succeeded',
    updated_at = CURRENT_TIMESTAMP

  WHERE id = p_payment_id

  RETURNING *
  INTO v_payment;


  RETURN v_payment;

END;
$$;


ALTER FUNCTION "public"."confirm_expense_payment"("p_payment_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."confirm_expense_payment"("p_payment_id" "uuid") IS 'Confirms a pending internal Modira expense payment.';



CREATE OR REPLACE FUNCTION "public"."consume_ai_rate_limit"("p_rate_key" "text", "p_limit" integer, "p_window_seconds" integer) RETURNS TABLE("allowed" boolean, "remaining" integer, "retry_after_seconds" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_now TIMESTAMPTZ := clock_timestamp();

    v_window_started_at TIMESTAMPTZ;

    v_request_count INTEGER;

    v_elapsed_seconds NUMERIC;

    v_retry_after INTEGER;
BEGIN

    -- ========================================================
    -- VALIDACIÓN DE CLAVE
    -- ========================================================

    IF p_rate_key IS NULL
       OR LENGTH(TRIM(p_rate_key)) = 0
       OR LENGTH(p_rate_key) > 200
    THEN
        RAISE EXCEPTION
            'Invalid rate limit key';
    END IF;


    -- ========================================================
    -- VALIDACIÓN DEL LÍMITE
    -- ========================================================

    IF p_limit IS NULL
       OR p_limit < 1
       OR p_limit > 1000
    THEN
        RAISE EXCEPTION
            'Invalid rate limit limit';
    END IF;


    -- ========================================================
    -- VALIDACIÓN DE LA VENTANA
    -- ========================================================

    IF p_window_seconds IS NULL
       OR p_window_seconds < 1
       OR p_window_seconds > 86400
    THEN
        RAISE EXCEPTION
            'Invalid rate limit window';
    END IF;


    -- ========================================================
    -- LOCK ATÓMICO POR CLAVE
    -- ========================================================
    --
    -- hashtextextended genera una clave bigint para el
    -- advisory lock.
    --
    -- Las peticiones concurrentes de la misma clave quedan
    -- serializadas durante esta transacción.
    --
    -- No utilizamos locks de tabla porque queremos mantener
    -- concurrencia entre diferentes sesiones/IPs.
    -- ========================================================

    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            p_rate_key,
            0
        )
    );


    -- ========================================================
    -- OBTENER CONTADOR ACTUAL
    -- ========================================================

    SELECT
        ar.window_started_at,
        ar.request_count
    INTO
        v_window_started_at,
        v_request_count
    FROM public.ai_rate_limits ar
    WHERE ar.rate_key = p_rate_key
    FOR UPDATE;


    -- ========================================================
    -- PRIMERA PETICIÓN PARA ESTA CLAVE
    -- ========================================================

    IF NOT FOUND THEN

        INSERT INTO public.ai_rate_limits (
            rate_key,
            window_started_at,
            request_count
        )
        VALUES (
            p_rate_key,
            v_now,
            1
        );

        RETURN QUERY
        SELECT
            TRUE,
            p_limit - 1,
            0;

        RETURN;

    END IF;


    -- ========================================================
    -- CALCULAR TIEMPO TRANSCURRIDO
    -- ========================================================

    v_elapsed_seconds :=
        EXTRACT(
            EPOCH
            FROM (
                v_now - v_window_started_at
            )
        );


    -- ========================================================
    -- VENTANA EXPIRADA
    -- ========================================================

    IF v_elapsed_seconds >= p_window_seconds THEN

        UPDATE public.ai_rate_limits
        SET
            window_started_at = v_now,
            request_count = 1,
            updated_at = v_now
        WHERE rate_key = p_rate_key;

        RETURN QUERY
        SELECT
            TRUE,
            p_limit - 1,
            0;

        RETURN;

    END IF;


    -- ========================================================
    -- LÍMITE ALCANZADO
    -- ========================================================

    IF v_request_count >= p_limit THEN

        v_retry_after :=
            GREATEST(
                1,
                CEIL(
                    p_window_seconds
                    - v_elapsed_seconds
                )::INTEGER
            );

        RETURN QUERY
        SELECT
            FALSE,
            0,
            v_retry_after;

        RETURN;

    END IF;


    -- ========================================================
    -- PETICIÓN PERMITIDA
    -- ========================================================

    UPDATE public.ai_rate_limits
    SET
        request_count = request_count + 1,
        updated_at = v_now
    WHERE rate_key = p_rate_key;


    RETURN QUERY
    SELECT
        TRUE,
        GREATEST(
            0,
            p_limit - (v_request_count + 1)
        ),
        0;

END;
$$;


ALTER FUNCTION "public"."consume_ai_rate_limit"("p_rate_key" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_expense_worker_rate_limit"("p_operation" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_function_exists BOOLEAN;

  v_allowed BOOLEAN;

BEGIN

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION
      'Usuario no autenticado';
  END IF;


  SELECT EXISTS (
    SELECT 1
    FROM pg_proc
    WHERE proname = 'consume_worker_write_rate_limit'
      AND pronamespace = 'public'::regnamespace
  )
  INTO v_function_exists;


  IF NOT v_function_exists THEN
    RETURN;
  END IF;


  /*
   * Límite específico para operaciones del módulo de gastos.
   *
   * 100 operaciones / 10 minutos / worker.
   */

  SELECT public.consume_worker_write_rate_limit(
    p_operation,
    100,
    600
  )
  INTO v_allowed;


  IF NOT COALESCE(v_allowed, FALSE) THEN
    RAISE EXCEPTION
      'Demasiadas operaciones sobre gastos. Inténtalo de nuevo más tarde.';
  END IF;

END;
$$;


ALTER FUNCTION "public"."consume_expense_worker_rate_limit"("p_operation" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_maintenance_change_rate_limit"("p_company_id" "uuid", "p_action" "text", "p_limit" integer DEFAULT 1, "p_window_seconds" integer DEFAULT 604800) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_key TEXT;
  v_row public.security_rate_limits;
  v_now TIMESTAMPTZ := CURRENT_TIMESTAMP;
  v_remaining INTEGER;
  v_retry_after INTEGER;
BEGIN
  IF p_company_id IS NULL THEN
    RAISE EXCEPTION 'La empresa es obligatoria';
  END IF;

  IF p_action NOT IN (
    'maintenance_project_change',
    'maintenance_plan_change'
  ) THEN
    RAISE EXCEPTION 'Acción de rate limit no válida';
  END IF;

  IF p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION 'Límite de rate limit no válido';
  END IF;

  IF p_window_seconds < 1 OR p_window_seconds > 2592000 THEN
    RAISE EXCEPTION 'Ventana de rate limit no válida';
  END IF;

  v_key :=
    'maintenance-change:' ||
    p_action ||
    ':company:' ||
    p_company_id::TEXT;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(v_key, 0)
  );

  SELECT *
  INTO v_row
  FROM public.security_rate_limits
  WHERE rate_key = v_key
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.security_rate_limits (
      rate_key,
      window_started_at,
      request_count,
      updated_at
    )
    VALUES (
      v_key,
      v_now,
      1,
      v_now
    )
    RETURNING *
    INTO v_row;

    RETURN jsonb_build_object(
      'allowed', TRUE,
      'remaining', GREATEST(p_limit - 1, 0),
      'retry_after_seconds', 0
    );
  END IF;

  IF v_row.window_started_at + make_interval(secs => p_window_seconds) <= v_now THEN
    UPDATE public.security_rate_limits
    SET
      window_started_at = v_now,
      request_count = 1,
      updated_at = v_now
    WHERE rate_key = v_key;

    RETURN jsonb_build_object(
      'allowed', TRUE,
      'remaining', GREATEST(p_limit - 1, 0),
      'retry_after_seconds', 0
    );
  END IF;

  IF v_row.request_count >= p_limit THEN
    v_retry_after := GREATEST(
      1,
      CEIL(
        EXTRACT(
          EPOCH FROM (
            v_row.window_started_at
            + make_interval(secs => p_window_seconds)
            - v_now
          )
        )
      )::INTEGER
    );

    RETURN jsonb_build_object(
      'allowed', FALSE,
      'remaining', 0,
      'retry_after_seconds', v_retry_after
    );
  END IF;

  UPDATE public.security_rate_limits
  SET
    request_count = request_count + 1,
    updated_at = v_now
  WHERE rate_key = v_key;

  v_remaining := GREATEST(
    p_limit - (v_row.request_count + 1),
    0
  );

  RETURN jsonb_build_object(
    'allowed', TRUE,
    'remaining', v_remaining,
    'retry_after_seconds', 0
  );
END;
$$;


ALTER FUNCTION "public"."consume_maintenance_change_rate_limit"("p_company_id" "uuid", "p_action" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


