CREATE OR REPLACE FUNCTION "public"."consume_worker_write_rate_limit"("p_operation_key" "text", "p_limit" integer, "p_window_seconds" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_worker_id UUID;
    v_now TIMESTAMPTZ := clock_timestamp();
    v_window_started_at TIMESTAMPTZ;
    v_request_count INTEGER;
BEGIN

    IF auth.uid() IS NULL THEN
        RETURN TRUE;
    END IF;

    IF p_operation_key IS NULL
       OR LENGTH(TRIM(p_operation_key)) = 0
       OR LENGTH(p_operation_key) > 100
    THEN
        RAISE EXCEPTION 'Invalid worker rate limit operation';
    END IF;

    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 10000 THEN
        RAISE EXCEPTION 'Invalid worker rate limit limit';
    END IF;

    IF p_window_seconds IS NULL
       OR p_window_seconds < 1
       OR p_window_seconds > 86400
    THEN
        RAISE EXCEPTION 'Invalid worker rate limit window';
    END IF;

    IF NOT public.current_user_is_worker() THEN
        RETURN TRUE;
    END IF;

    v_worker_id := auth.uid();

    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            v_worker_id::TEXT || ':' || p_operation_key,
            42042
        )
    );

    SELECT
        window_started_at,
        request_count
    INTO
        v_window_started_at,
        v_request_count
    FROM public.worker_write_rate_limits
    WHERE worker_id = v_worker_id
      AND operation_key = p_operation_key
    FOR UPDATE;

    IF NOT FOUND THEN
        INSERT INTO public.worker_write_rate_limits (
            worker_id,
            operation_key,
            window_started_at,
            request_count,
            updated_at
        )
        VALUES (
            v_worker_id,
            p_operation_key,
            v_now,
            1,
            v_now
        );

        RETURN TRUE;
    END IF;

    IF EXTRACT(
        EPOCH FROM (v_now - v_window_started_at)
    ) >= p_window_seconds
    THEN
        UPDATE public.worker_write_rate_limits
        SET
            window_started_at = v_now,
            request_count = 1,
            updated_at = v_now
        WHERE worker_id = v_worker_id
          AND operation_key = p_operation_key;

        RETURN TRUE;
    END IF;

    IF v_request_count >= p_limit THEN
        RETURN FALSE;
    END IF;

    UPDATE public.worker_write_rate_limits
    SET
        request_count = request_count + 1,
        updated_at = v_now
    WHERE worker_id = v_worker_id
      AND operation_key = p_operation_key;

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."consume_worker_write_rate_limit"("p_operation_key" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."consume_worker_write_rate_limit"("p_operation_key" "text", "p_limit" integer, "p_window_seconds" integer) IS 'Rate limit atómico interno para escrituras de workers. Utiliza auth.uid() y advisory locks para impedir bypass por concurrencia.';



CREATE TABLE IF NOT EXISTS "public"."automation_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "automation_id" "uuid" NOT NULL,
    "company_id" "uuid" NOT NULL,
    "estado" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "inicio" timestamp with time zone,
    "finalizacion" timestamp with time zone,
    "duracion_ms" integer,
    "resultado" "jsonb",
    "error" "text",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "automation_runs_dates_check" CHECK ((("finalizacion" IS NULL) OR ("inicio" IS NULL) OR ("finalizacion" >= "inicio"))),
    CONSTRAINT "automation_runs_duration_check" CHECK ((("duracion_ms" IS NULL) OR ("duracion_ms" >= 0))),
    CONSTRAINT "automation_runs_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'ejecutando'::"text", 'exito'::"text", 'error'::"text"])))
);


ALTER TABLE "public"."automation_runs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_automation_run"("p_automation_id" "uuid") RETURNS "public"."automation_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_automation public.automations;
    v_run public.automation_runs;

BEGIN

    -- ========================================================
    -- 1. AUTENTICACIÓN
    -- ========================================================

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado';
    END IF;


    -- ========================================================
    -- 2. CUENTA ACTIVA
    -- ========================================================

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION
            'Acceso denegado: la cuenta no está activa';
    END IF;


    -- ========================================================
    -- 3. COMPROBAR QUE EXISTE LA AUTOMATIZACIÓN
    -- ========================================================

    SELECT *
    INTO v_automation
    FROM public.automations
    WHERE id = p_automation_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La automatización indicada no existe';
    END IF;


    -- ========================================================
    -- 4. AUTORIZACIÓN
    -- ========================================================
    --
    -- Worker:
    --     necesita explícitamente automations.execute.
    --
    -- Cliente:
    --     solamente puede crear ejecuciones de una
    --     automatización cuyo propietario sea él mismo.
    --

    IF public.current_user_is_worker() THEN

        IF NOT public.current_worker_has_permission(
            'automations.execute'
        ) THEN
            RAISE EXCEPTION
                'Acceso denegado: se requiere el permiso automations.execute';
        END IF;

    ELSIF v_automation.user_id <> auth.uid() THEN

        RAISE EXCEPTION
            'Acceso denegado';

    END IF;


    -- ========================================================
    -- 5. CREAR EJECUCIÓN
    -- ========================================================

    INSERT INTO public.automation_runs (
        automation_id,
        company_id,
        estado,
        inicio
    )
    VALUES (
        v_automation.id,
        v_automation.company_id,
        'pendiente',
        CURRENT_TIMESTAMP
    )
    RETURNING *
    INTO v_run;


    RETURN v_run;

END;

$$;


ALTER FUNCTION "public"."create_automation_run"("p_automation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_automation_run"("p_automation_id" "uuid") IS 'Crea ejecuciones de automatizaciones únicamente para cuentas autenticadas y activas. Los workers activos pueden crear ejecuciones; los clientes activos únicamente pueden crear ejecuciones de sus propias automatizaciones.';



CREATE TABLE IF NOT EXISTS "public"."notifications" (
