    "tipo" "text" NOT NULL,
    "titulo" "text" NOT NULL,
    "mensaje" "text" NOT NULL,
    "metadata" "jsonb",
    "read_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "notifications_mensaje_check" CHECK ((("length"("btrim"("mensaje")) > 0) AND ("length"("mensaje") <= 2000))),
    CONSTRAINT "notifications_mensaje_length_check" CHECK ((("mensaje" IS NULL) OR ("length"("mensaje") <= 2000))),
    CONSTRAINT "notifications_metadata_size_check" CHECK ((("metadata" IS NULL) OR ("pg_column_size"("metadata") <= 8192))),
    CONSTRAINT "notifications_tipo_check" CHECK (("tipo" = ANY (ARRAY['milestone_completed'::"text", 'information_requested'::"text", 'project_update'::"text", 'document_available'::"text", 'quotation'::"text", 'invoice'::"text", 'project_change_request'::"text", 'maintenance_proposal'::"text", 'system'::"text"]))),
    CONSTRAINT "notifications_tipo_length_check" CHECK ((("tipo" IS NULL) OR ("length"("tipo") <= 100))),
    CONSTRAINT "notifications_titulo_check" CHECK ((("length"("btrim"("titulo")) > 0) AND ("length"("titulo") <= 200))),
    CONSTRAINT "notifications_titulo_length_check" CHECK ((("titulo" IS NULL) OR ("length"("titulo") <= 200)))
);


