COMMENT ON COLUMN "public"."notifications"."project_id" IS 'Proyecto relacionado con la notificación. Puede ser NULL para notificaciones generales del sistema.';



COMMENT ON COLUMN "public"."notifications"."tipo" IS 'Tipo controlado de notificación: milestone_completed, information_requested, project_update, document_available, quotation, invoice, project_change_request o system.';



COMMENT ON COLUMN "public"."notifications"."metadata" IS 'Metadatos internos de la notificación. Limitados a 8 KiB.';



COMMENT ON COLUMN "public"."notifications"."read_at" IS 'Momento en que el usuario marcó la notificación como leída. NULL significa no leída.';



CREATE OR REPLACE FUNCTION "public"."create_client_notification"("p_project_id" "uuid", "p_tipo" "text", "p_titulo" "text", "p_mensaje" "text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."notifications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- WORKER ACTIVO
    -- --------------------------------------------------------

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    -- --------------------------------------------------------
    -- CREAR NOTIFICACIÓN
    -- --------------------------------------------------------

    RETURN public.emit_project_client_notification(
        p_project_id,
        p_tipo,
        p_titulo,
        p_mensaje,
        p_metadata
    );

END;
$$;


