CREATE OR REPLACE FUNCTION "public"."create_custom_maintenance_proposal"("p_titulo" "text", "p_descripcion_necesidad" "text" DEFAULT NULL::"text", "p_objetivos" "text" DEFAULT NULL::"text", "p_prioridades" "text" DEFAULT NULL::"text", "p_soluciones_actuales" "text" DEFAULT NULL::"text", "p_proyectos_relacionados" "text" DEFAULT NULL::"text", "p_automatizaciones_actuales" "text" DEFAULT NULL::"text", "p_integraciones_actuales" "text" DEFAULT NULL::"text", "p_tecnologias" "text" DEFAULT NULL::"text", "p_sistemas_criticos" "text" DEFAULT NULL::"text", "p_alcance_tecnico_solicitado" "text" DEFAULT NULL::"text", "p_horas_mensuales_solicitadas" numeric DEFAULT NULL::numeric, "p_tipo_trabajo" "text" DEFAULT NULL::"text", "p_nivel_soporte_solicitado" "text" DEFAULT NULL::"text", "p_tiempo_respuesta_deseado" "text" DEFAULT NULL::"text", "p_horario_soporte" "text" DEFAULT NULL::"text", "p_soporte_fuera_horario" boolean DEFAULT false, "p_sla_solicitado" "text" DEFAULT NULL::"text", "p_nivel_criticidad" "text" DEFAULT NULL::"text", "p_impacto_incidencia" "text" DEFAULT NULL::"text", "p_necesidad_monitorizacion" boolean DEFAULT false, "p_requisitos_seguridad" "text" DEFAULT NULL::"text", "p_informacion_adicional" "text" DEFAULT NULL::"text", "p_request_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."maintenance_custom_proposals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_user_id UUID;
    v_company_id UUID;
    v_plan_id UUID;
    v_proposal public.maintenance_custom_proposals;

BEGIN

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION
            'Debes iniciar sesión para crear una propuesta';
    END IF;


    -- --------------------------------------------------------
    -- SOLO CLIENTES
    -- --------------------------------------------------------

    IF public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Los trabajadores no utilizan esta vía para crear propuestas de cliente';
    END IF;


    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION
            'El usuario no está activo';
    END IF;


    -- --------------------------------------------------------
    -- EMPRESA
    -- --------------------------------------------------------

    v_company_id := public.current_user_company_id();

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION
            'El usuario no pertenece a ninguna empresa';
    END IF;


    -- --------------------------------------------------------
    -- PLAN CUSTOM
    -- --------------------------------------------------------

    SELECT id
    INTO v_plan_id
    FROM public.maintenance_plans
    WHERE code = 'custom'
      AND es_personalizado = TRUE
      AND activo = TRUE
    LIMIT 1;


    IF v_plan_id IS NULL THEN
        RAISE EXCEPTION
            'El plan personalizado no está disponible';
    END IF;


    -- --------------------------------------------------------
    -- EVITAR VARIAS PROPUESTAS ABIERTAS
    -- --------------------------------------------------------

    IF EXISTS (
        SELECT 1
        FROM public.maintenance_custom_proposals
        WHERE company_id = v_company_id
          AND status IN (
              'draft',
              'submitted',
              'in_review',
              'quoted'
          )
    ) THEN
        RAISE EXCEPTION
            'Ya existe una propuesta personalizada abierta para esta empresa';
    END IF;


    -- --------------------------------------------------------
    -- VALIDACIONES
    -- --------------------------------------------------------

    IF NULLIF(BTRIM(p_titulo), '') IS NULL THEN
        RAISE EXCEPTION
            'El título de la propuesta es obligatorio';
    END IF;


    IF LENGTH(BTRIM(p_titulo)) > 300 THEN
        RAISE EXCEPTION
            'El título no puede superar 300 caracteres';
    END IF;


    IF p_horas_mensuales_solicitadas IS NOT NULL
       AND p_horas_mensuales_solicitadas <= 0
    THEN
        RAISE EXCEPTION
            'Las horas mensuales solicitadas deben ser mayores que 0';
    END IF;


    IF p_request_data IS NULL
       OR jsonb_typeof(p_request_data) <> 'object'
    THEN
        RAISE EXCEPTION
            'request_data debe ser un objeto JSON';
    END IF;


    -- --------------------------------------------------------
    -- CREACIÓN
    -- --------------------------------------------------------

    INSERT INTO public.maintenance_custom_proposals (
        user_id,
        company_id,
        plan_id,
        status,
        titulo,
        descripcion_necesidad,
        objetivos,
        prioridades,
        soluciones_actuales,
        proyectos_relacionados,
        automatizaciones_actuales,
        integraciones_actuales,
        tecnologias,
        sistemas_criticos,
        alcance_tecnico_solicitado,
        horas_mensuales_solicitadas,
        tipo_trabajo,
        nivel_soporte_solicitado,
        tiempo_respuesta_deseado,
        horario_soporte,
        soporte_fuera_horario,
        sla_solicitado,
        nivel_criticidad,
        impacto_incidencia,
        necesidad_monitorizacion,
        requisitos_seguridad,
        informacion_adicional,
        request_data
    )
    VALUES (
        v_user_id,
        v_company_id,
        v_plan_id,
        'draft',
        BTRIM(p_titulo),
        NULLIF(BTRIM(p_descripcion_necesidad), ''),
        NULLIF(BTRIM(p_objetivos), ''),
        NULLIF(BTRIM(p_prioridades), ''),
        NULLIF(BTRIM(p_soluciones_actuales), ''),
        NULLIF(BTRIM(p_proyectos_relacionados), ''),
        NULLIF(BTRIM(p_automatizaciones_actuales), ''),
        NULLIF(BTRIM(p_integraciones_actuales), ''),
        NULLIF(BTRIM(p_tecnologias), ''),
        NULLIF(BTRIM(p_sistemas_criticos), ''),
        NULLIF(BTRIM(p_alcance_tecnico_solicitado), ''),
        p_horas_mensuales_solicitadas,
        NULLIF(BTRIM(p_tipo_trabajo), ''),
        NULLIF(BTRIM(p_nivel_soporte_solicitado), ''),
        NULLIF(BTRIM(p_tiempo_respuesta_deseado), ''),
        NULLIF(BTRIM(p_horario_soporte), ''),
        COALESCE(p_soporte_fuera_horario, FALSE),
        NULLIF(BTRIM(p_sla_solicitado), ''),
        NULLIF(BTRIM(p_nivel_criticidad), ''),
        NULLIF(BTRIM(p_impacto_incidencia), ''),
        COALESCE(p_necesidad_monitorizacion, FALSE),
        NULLIF(BTRIM(p_requisitos_seguridad), ''),
        NULLIF(BTRIM(p_informacion_adicional), ''),
        p_request_data
    )
    RETURNING *
    INTO v_proposal;


    RETURN v_proposal;

END;
$$;


