CREATE OR REPLACE FUNCTION "public"."create_expense"("p_expense_date" "date", "p_description" "text", "p_expense_type" "text", "p_category_id" "uuid", "p_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_currency" "text" DEFAULT 'EUR'::"text", "p_subtotal" numeric DEFAULT 0) RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE

  v_expense public.expenses;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.create'
  );

