CREATE OR REPLACE FUNCTION "public"."create_expense_allocation"("p_expense_id" "uuid", "p_project_id" "uuid", "p_amount" numeric, "p_description" "text" DEFAULT NULL::"text") RETURNS "public"."expense_allocations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_allocation public.expense_allocations;

  v_status TEXT;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.allocate'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:allocate'
  );


  SELECT status
  INTO v_status

  FROM public.expenses

  WHERE id = p_expense_id

  FOR UPDATE;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El gasto % no existe',
      p_expense_id;

  END IF;


  IF v_status IN (
    'paid',
    'cancelled'
  ) THEN

    RAISE EXCEPTION
      'No se puede modificar la asignación de un gasto en estado %',
      v_status;

  END IF;


  INSERT INTO public.expense_allocations (
    expense_id,
    project_id,
    amount,
    description
  )
  VALUES (
    p_expense_id,
    p_project_id,
    ROUND(p_amount, 2),
    NULLIF(BTRIM(p_description), '')
  )
  RETURNING *
  INTO v_allocation;


  RETURN v_allocation;

END;
$$;


