CREATE OR REPLACE FUNCTION "public"."create_expense_payment"("p_expense_id" "uuid", "p_amount" numeric, "p_payment_date" timestamp with time zone DEFAULT CURRENT_TIMESTAMP, "p_payment_method" "text" DEFAULT 'bank_transfer'::"text", "p_reference" "text" DEFAULT NULL::"text") RETURNS "public"."expense_payments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_payment public.expense_payments;
  v_expense_status text;
  v_effective_payment_date timestamptz;
  v_payment_status text;
BEGIN
  PERFORM public.require_expense_permission('expenses.pay');
  PERFORM public.consume_expense_worker_rate_limit('expenses:payment_create');

  SELECT status
    INTO v_expense_status
  FROM public.expenses
  WHERE id = p_expense_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'El gasto % no existe', p_expense_id;
  END IF;

  IF v_expense_status NOT IN ('pending_payment', 'partially_paid') THEN
    RAISE EXCEPTION
      'El gasto no está pendiente de pago. Estado actual: %',
      v_expense_status;
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'El importe del pago debe ser mayor que 0';
  END IF;

  IF p_payment_method IS NULL OR p_payment_method NOT IN (
    'bank_transfer', 'card', 'cash', 'direct_debit', 'other'
  ) THEN
    RAISE EXCEPTION 'El método de pago no es válido';
  END IF;

  v_effective_payment_date := COALESCE(p_payment_date, CURRENT_TIMESTAMP);
  v_payment_status := CASE
    WHEN v_effective_payment_date <= CURRENT_TIMESTAMP THEN 'succeeded'
    ELSE 'pending'
  END;

  INSERT INTO public.expense_payments (
    expense_id, amount, payment_date, payment_method, reference, status, created_by
  )
  VALUES (
    p_expense_id,
    ROUND(p_amount, 2),
    v_effective_payment_date,
    p_payment_method,
    NULLIF(BTRIM(p_reference), ''),
    v_payment_status,
    auth.uid()
  )
  RETURNING * INTO v_payment;

  RETURN v_payment;
END;
$$;


ALTER FUNCTION "public"."create_expense_payment"("p_expense_id" "uuid", "p_amount" numeric, "p_payment_date" timestamp with time zone, "p_payment_method" "text", "p_reference" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_expense_payment"("p_expense_id" "uuid", "p_amount" numeric, "p_payment_date" timestamp with time zone, "p_payment_method" "text", "p_reference" "text") IS 'Creates a pending payment for an internal Modira expense.';



