    "tax_rate" numeric(7,4) DEFAULT 0 NOT NULL,
    "taxable_base" numeric(14,2) DEFAULT 0 NOT NULL,
    "tax_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "deductible_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "expense_tax_lines_amount_check" CHECK (("tax_amount" >= (0)::numeric)),
    CONSTRAINT "expense_tax_lines_deductible_check" CHECK ((("deductible_amount" >= (0)::numeric) AND ("deductible_amount" <= "tax_amount"))),
    CONSTRAINT "expense_tax_lines_rate_check" CHECK ((("tax_rate" >= (0)::numeric) AND ("tax_rate" <= (100)::numeric))),
    CONSTRAINT "expense_tax_lines_taxable_base_check" CHECK (("taxable_base" >= (0)::numeric)),
    CONSTRAINT "expense_tax_lines_type_check" CHECK (("tax_type" = ANY (ARRAY['vat'::"text", 'withholding'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."expense_tax_lines" OWNER TO "postgres";


COMMENT ON TABLE "public"."expense_tax_lines" IS 'Líneas fiscales de los gastos internos de Modira. Permite representar IVA, retenciones y otros impuestos.';



COMMENT ON COLUMN "public"."expense_tax_lines"."tax_type" IS 'Tipo fiscal: vat, withholding u other.';



COMMENT ON COLUMN "public"."expense_tax_lines"."tax_rate" IS 'Porcentaje fiscal aplicado a la base imponible.';



COMMENT ON COLUMN "public"."expense_tax_lines"."taxable_base" IS 'Base imponible sobre la que se calcula la línea fiscal.';



COMMENT ON COLUMN "public"."expense_tax_lines"."tax_amount" IS 'Importe fiscal positivo. Su tratamiento depende de tax_type.';



COMMENT ON COLUMN "public"."expense_tax_lines"."deductible_amount" IS 'Parte del impuesto que puede considerarse fiscalmente deducible.';



CREATE OR REPLACE FUNCTION "public"."create_expense_tax_line"("p_expense_id" "uuid", "p_tax_type" "text", "p_tax_rate" numeric, "p_taxable_base" numeric, "p_tax_amount" numeric, "p_deductible_amount" numeric DEFAULT 0) RETURNS "public"."expense_tax_lines"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_line public.expense_tax_lines;

  v_status TEXT;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.update'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:tax'
  );


  SELECT status
  INTO v_status

  FROM public.expenses

  WHERE id = p_expense_id

  FOR UPDATE;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El gasto % no existe',
      p_expense_id;

  END IF;


  IF v_status IN (
    'paid',
    'cancelled'
  ) THEN

    RAISE EXCEPTION
      'No se pueden modificar impuestos de un gasto en estado %',
      v_status;

  END IF;


  IF p_tax_rate < 0
     OR p_tax_rate > 100 THEN

    RAISE EXCEPTION
      'El porcentaje fiscal debe estar entre 0 y 100';

  END IF;


  IF p_taxable_base < 0
     OR p_tax_amount < 0
     OR p_deductible_amount < 0 THEN

    RAISE EXCEPTION
      'Los importes fiscales no pueden ser negativos';

  END IF;


  INSERT INTO public.expense_tax_lines (
    expense_id,
    tax_type,
    tax_rate,
    taxable_base,
    tax_amount,
    deductible_amount
  )
  VALUES (
    p_expense_id,
    p_tax_type,
    ROUND(p_tax_rate, 4),
    ROUND(p_taxable_base, 2),
    ROUND(p_tax_amount, 2),
    ROUND(p_deductible_amount, 2)
  )
  RETURNING *
  INTO v_line;


  RETURN v_line;

END;
$$;


ALTER FUNCTION "public"."create_expense_tax_line"("p_expense_id" "uuid", "p_tax_type" "text", "p_tax_rate" numeric, "p_taxable_base" numeric, "p_tax_amount" numeric, "p_deductible_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_expense_with_scheduled_payment"("p_expense_date" "date", "p_description" "text", "p_expense_type" "text", "p_category_id" "uuid", "p_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_currency" "text" DEFAULT 'EUR'::"text", "p_subtotal" numeric DEFAULT 0, "p_payment_date" timestamp with time zone DEFAULT CURRENT_TIMESTAMP, "p_payment_method" "text" DEFAULT 'bank_transfer'::"text", "p_reference" "text" DEFAULT NULL::"text") RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_expense public.expenses;
  v_payment_date timestamptz;
  v_requires_approval boolean;
  v_payment_status text;
BEGIN
  PERFORM public.require_expense_permission('expenses.create');
  PERFORM public.consume_expense_worker_rate_limit('expenses:create');

  IF p_description IS NULL OR BTRIM(p_description) = '' THEN
    RAISE EXCEPTION 'La descripción del gasto es obligatoria';
  END IF;

  IF LENGTH(BTRIM(p_description)) > 2000 THEN
    RAISE EXCEPTION 'La descripción del gasto no puede superar 2.000 caracteres';
  END IF;

  IF p_currency IS NULL OR p_currency !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'La moneda debe tener formato ISO de 3 letras';
  END IF;

  IF p_subtotal IS NULL OR p_subtotal < 0 THEN
    RAISE EXCEPTION 'El subtotal no puede ser negativo';
  END IF;

  IF p_payment_method IS NULL OR p_payment_method NOT IN (
    'bank_transfer', 'card', 'cash', 'direct_debit', 'other'
  ) THEN
    RAISE EXCEPTION 'El método de pago no es válido';
  END IF;

  v_payment_date := COALESCE(p_payment_date, CURRENT_TIMESTAMP);

  INSERT INTO public.expenses (
    expense_date,
    description,
    expense_type,
    category_id,
    supplier_id,
    project_id,
    status,
    currency,
    subtotal,
    created_by,
    updated_by
  )
  VALUES (
    COALESCE(p_expense_date, CURRENT_DATE),
    BTRIM(p_description),
    p_expense_type,
    p_category_id,
    p_supplier_id,
    p_project_id,
    'draft',
    p_currency,
    ROUND(p_subtotal, 2),
    auth.uid(),
    auth.uid()
  )
  RETURNING * INTO v_expense;

  IF COALESCE(v_expense.total_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'El gasto debe tener un importe total superior a 0';
  END IF;

  v_requires_approval := public.expense_requires_approval(
    v_expense.total_amount,
    v_expense.category_id
  );

  UPDATE public.expenses
  SET status = CASE
        WHEN v_requires_approval THEN 'pending_review'
        ELSE 'pending_payment'
      END,
      updated_by = auth.uid(),
      updated_at = CURRENT_TIMESTAMP
  WHERE id = v_expense.id
  RETURNING * INTO v_expense;

  v_payment_status := CASE
    WHEN v_requires_approval THEN 'pending'
    WHEN v_payment_date > CURRENT_TIMESTAMP THEN 'pending'
    ELSE 'succeeded'
  END;

  INSERT INTO public.expense_payments (
    expense_id,
    amount,
    payment_date,
    payment_method,
    reference,
    status,
    created_by,
    is_automatic
  )
  VALUES (
    v_expense.id,
    ROUND(v_expense.total_amount, 2),
    v_payment_date,
    p_payment_method,
    NULLIF(BTRIM(p_reference), ''),
    v_payment_status,
    auth.uid(),
    true
  );

  -- The payment trigger updates the expense status if this payment succeeded.
  -- Fetch again so the RPC returns the final status (e.g. paid).
  SELECT * INTO v_expense
  FROM public.expenses
  WHERE id = v_expense.id;

  RETURN v_expense;
END;
$_$;


ALTER FUNCTION "public"."create_expense_with_scheduled_payment"("p_expense_date" "date", "p_description" "text", "p_expense_type" "text", "p_category_id" "uuid", "p_supplier_id" "uuid", "p_project_id" "uuid", "p_currency" "text", "p_subtotal" numeric, "p_payment_date" timestamp with time zone, "p_payment_method" "text", "p_reference" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."internal_tasks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "created_by_worker_id" "uuid" NOT NULL,
    "assigned_to_worker_id" "uuid",
    "status" "text" DEFAULT 'to_do'::"text" NOT NULL,
    "progress" integer DEFAULT 0 NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "due_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "submitted_for_review_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "completed_by_worker_id" "uuid",
    "cancelled_by_worker_id" "uuid",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "internal_tasks_cancelled_timestamp_check" CHECK ((("status" <> 'cancelled'::"text") OR ("cancelled_at" IS NOT NULL))),
    CONSTRAINT "internal_tasks_completed_progress_check" CHECK ((("status" <> 'completed'::"text") OR ("progress" = 100))),
    CONSTRAINT "internal_tasks_completed_timestamp_check" CHECK ((("status" <> 'completed'::"text") OR ("completed_at" IS NOT NULL))),
    CONSTRAINT "internal_tasks_pending_review_progress_check" CHECK ((("status" <> 'pending_review'::"text") OR ("progress" = 100))),
    CONSTRAINT "internal_tasks_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "internal_tasks_progress_check" CHECK ((("progress" >= 0) AND ("progress" <= 100))),
    CONSTRAINT "internal_tasks_status_check" CHECK (("status" = ANY (ARRAY['to_do'::"text", 'in_progress'::"text", 'pending_review'::"text", 'completed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."internal_tasks" OWNER TO "postgres";


COMMENT ON TABLE "public"."internal_tasks" IS 'Internal MODIRA tasks. Business access is controlled by later RBAC/RLS/RPC migrations.';



COMMENT ON COLUMN "public"."internal_tasks"."assigned_to_worker_id" IS 'Worker responsible for executing the task. NULL means the task has not yet been assigned.';



COMMENT ON COLUMN "public"."internal_tasks"."status" IS 'Task lifecycle: to_do, in_progress, pending_review, completed or cancelled.';



COMMENT ON COLUMN "public"."internal_tasks"."progress" IS 'Task completion percentage from 0 to 100.';



CREATE OR REPLACE FUNCTION "public"."create_internal_task"("p_title" "text", "p_description" "text" DEFAULT NULL::"text", "p_assigned_to_worker_id" "uuid" DEFAULT NULL::"uuid", "p_priority" "text" DEFAULT 'normal'::"text", "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_viewer_worker_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_viewer_role_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "public"."internal_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_worker_id UUID;
    v_task public.internal_tasks;
    v_viewer_worker_id UUID;
    v_viewer_role_id UUID;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.create'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:create:' || auth.uid()::TEXT,
        30,
        3600
    );


    v_worker_id := public.internal_task_current_worker_id();


    IF v_worker_id IS NULL THEN
        RAISE EXCEPTION
            'No se pudo determinar el trabajador actual';
    END IF;


    IF NULLIF(BTRIM(p_title), '') IS NULL THEN
        RAISE EXCEPTION
            'El título es obligatorio';
    END IF;


    IF LENGTH(BTRIM(p_title)) > 200 THEN
        RAISE EXCEPTION
            'El título no puede superar 200 caracteres';
    END IF;


    IF p_description IS NOT NULL
       AND LENGTH(p_description) > 5000
    THEN
        RAISE EXCEPTION
            'La descripción no puede superar 5000 caracteres';
    END IF;


    IF p_priority IS NULL
       OR p_priority NOT IN (
           'low',
           'normal',
           'high',
           'urgent'
       )
    THEN
        RAISE EXCEPTION
            'Prioridad no válida';
    END IF;


    IF p_assigned_to_worker_id IS NOT NULL THEN

        IF NOT EXISTS (
            SELECT 1
            FROM public.workers w
            WHERE w.id = p_assigned_to_worker_id
              AND w.is_active = TRUE
        ) THEN
            RAISE EXCEPTION
                'El trabajador asignado no existe o no está activo';
        END IF;


        IF NOT public.internal_task_current_worker_is_direction()
           AND NOT public.internal_task_current_worker_is_developer()
           AND p_assigned_to_worker_id IS DISTINCT FROM v_worker_id
        THEN
            RAISE EXCEPTION
                'No puedes asignar una nueva tarea a otro trabajador';
        END IF;

    END IF;


    IF NOT public.internal_task_current_worker_is_direction()
       AND (
            COALESCE(array_length(p_viewer_worker_ids, 1), 0) > 0
            OR COALESCE(array_length(p_viewer_role_ids, 1), 0) > 0
       )
    THEN
        RAISE EXCEPTION
            'Solo Dirección puede definir la visibilidad de una tarea';
    END IF;


    INSERT INTO public.internal_tasks (
        title,
        description,
        created_by_worker_id,
        assigned_to_worker_id,
        status,
        progress,
        priority,
        due_at
    )
    VALUES (
        BTRIM(p_title),
        NULLIF(BTRIM(p_description), ''),
        v_worker_id,
        p_assigned_to_worker_id,
        'to_do',
        0,
        p_priority,
        p_due_at
    )
    RETURNING *
    INTO v_task;


    PERFORM public.internal_task_record_update(
        v_task.id,
        v_worker_id,
        'created',
        NULL,
        NULL,
        v_task.status,
        v_task.progress,
        NULL
    );


    IF public.internal_task_current_worker_is_direction() THEN

        IF p_viewer_worker_ids IS NOT NULL THEN

            FOREACH v_viewer_worker_id IN
                ARRAY p_viewer_worker_ids
            LOOP

                IF NOT EXISTS (
                    SELECT 1
                    FROM public.workers w
                    WHERE w.id = v_viewer_worker_id
                      AND w.is_active = TRUE
                ) THEN
                    RAISE EXCEPTION
                        'Uno de los trabajadores de visibilidad no existe o no está activo';
                END IF;


                INSERT INTO public.internal_task_user_access (
                    task_id,
                    worker_id
                )
                VALUES (
                    v_task.id,
                    v_viewer_worker_id
                )
                ON CONFLICT DO NOTHING;

            END LOOP;

        END IF;


        IF p_viewer_role_ids IS NOT NULL THEN

            FOREACH v_viewer_role_id IN
                ARRAY p_viewer_role_ids
            LOOP

                IF NOT EXISTS (
                    SELECT 1
                    FROM public.worker_roles wr
                    WHERE wr.id = v_viewer_role_id
                      AND wr.is_active = TRUE
                ) THEN
                    RAISE EXCEPTION
                        'Uno de los roles de visibilidad no existe o no está activo';
                END IF;


                INSERT INTO public.internal_task_role_access (
                    task_id,
                    role_id
                )
                VALUES (
                    v_task.id,
                    v_viewer_role_id
                )
                ON CONFLICT DO NOTHING;

            END LOOP;

        END IF;

    END IF;


    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."create_internal_task"("p_title" "text", "p_description" "text", "p_assigned_to_worker_id" "uuid", "p_priority" "text", "p_due_at" timestamp with time zone, "p_viewer_worker_ids" "uuid"[], "p_viewer_role_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_internal_task"("p_title" "text", "p_description" "text", "p_assigned_to_worker_id" "uuid", "p_priority" "text", "p_due_at" timestamp with time zone, "p_viewer_worker_ids" "uuid"[], "p_viewer_role_ids" "uuid"[]) IS 'Creates an internal task through the controlled worker RBAC flow. Applies task creation rate limiting and optional Direction-only visibility configuration.';



CREATE OR REPLACE FUNCTION "public"."create_invoice_by_worker"("p_company_id" "uuid", "p_project_id" "uuid", "p_fecha_emision" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_fecha_vencimiento" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_descripcion" "text" DEFAULT NULL::"text", "p_subtotal" numeric DEFAULT 0, "p_iva_porcentaje" numeric DEFAULT 21) RETURNS "public"."invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE

    v_invoice public.invoices;

    v_project_user_id UUID;
    v_project_client_id UUID;
    v_project_company_id UUID;

    v_numero_factura TEXT;

    v_subtotal NUMERIC(12,2);
    v_iva_porcentaje NUMERIC(5,2);
    v_iva_importe NUMERIC(12,2);
    v_monto NUMERIC(12,2);

    -- --------------------------------------------------------
    -- Fiscal issuer
    -- --------------------------------------------------------

    v_issuer_legal_name TEXT;
    v_issuer_tax_id TEXT;
    v_issuer_address TEXT;
    v_issuer_postal_code TEXT;
    v_issuer_city TEXT;
    v_issuer_province TEXT;
    v_issuer_country TEXT;

    -- --------------------------------------------------------
    -- Fiscal customer
    -- --------------------------------------------------------

    v_customer_legal_name TEXT;
    v_customer_tax_id TEXT;
    v_customer_address TEXT;
    v_customer_postal_code TEXT;
    v_customer_city TEXT;
    v_customer_province TEXT;
    v_customer_country TEXT;
    v_customer_contact_name TEXT;

BEGIN


    -- ========================================================
    -- 1. PERMISSION
    -- ========================================================

    PERFORM public.require_current_worker_permission(
        'invoices.create'
    );


    -- ========================================================
    -- 2. COMPANY
    -- ========================================================

    IF p_company_id IS NULL THEN

        RAISE EXCEPTION
            'La empresa es obligatoria';

    END IF;


    SELECT
        COALESCE(
            NULLIF(TRIM(c.legal_name), ''),
            NULLIF(TRIM(c.company_name), '')
        ),
        NULLIF(TRIM(c.cif_vat), ''),
        NULLIF(TRIM(c.address), ''),
        NULLIF(TRIM(c.postal_code), ''),
        NULLIF(TRIM(c.city), ''),
        NULLIF(TRIM(c.province), ''),
        COALESCE(
            NULLIF(TRIM(c.country), ''),
            'ES'
        )
    INTO
        v_issuer_legal_name,
        v_issuer_tax_id,
        v_issuer_address,
        v_issuer_postal_code,
        v_issuer_city,
        v_issuer_province,
        v_issuer_country
    FROM public.companies c
    WHERE c.id = p_company_id;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'La empresa seleccionada no existe';

    END IF;


    -- ========================================================
    -- 3. PROJECT
    -- ========================================================

    IF p_project_id IS NULL THEN

        RAISE EXCEPTION
            'El proyecto es obligatorio';

    END IF;


    SELECT
        p.user_id,
        p.client_id,
        p.company_id
    INTO
        v_project_user_id,
        v_project_client_id,
        v_project_company_id
    FROM public.projects p
    WHERE p.id = p_project_id;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'El proyecto seleccionado no existe';

    END IF;


    IF v_project_company_id IS DISTINCT FROM p_company_id THEN

        RAISE EXCEPTION
            'El proyecto no pertenece a la empresa seleccionada';

    END IF;


    IF v_project_user_id IS NULL THEN

        RAISE EXCEPTION
            'El proyecto no tiene un usuario propietario válido';

    END IF;


    -- ========================================================
    -- 4. CLIENT SNAPSHOT
    -- ========================================================
    --
    -- Si el proyecto no tiene cliente, mantenemos el
    -- comportamiento permisivo actual:
    --
    --   client_id = NULL
    --   customer snapshot = NULL
    --
    -- No hacemos obligatorio un cliente porque actualmente
    -- projects.client_id puede ser NULL.
    --
    -- ========================================================

    IF v_project_client_id IS NOT NULL THEN

        SELECT
            COALESCE(
                NULLIF(TRIM(c.empresa), ''),
                NULLIF(TRIM(c.nombre), '')
            ),
            NULLIF(TRIM(c.cif_vat), ''),
            NULLIF(TRIM(c.direccion), ''),
            NULLIF(TRIM(c.codigo_postal), ''),
            NULLIF(TRIM(c.ciudad), ''),
            NULLIF(TRIM(c.provincia), ''),
            COALESCE(
                NULLIF(TRIM(c.pais), ''),
                'ES'
            ),
            NULLIF(TRIM(c.nombre), '')
        INTO
            v_customer_legal_name,
            v_customer_tax_id,
            v_customer_address,
            v_customer_postal_code,
            v_customer_city,
            v_customer_province,
            v_customer_country,
            v_customer_contact_name
        FROM public.clients c
        WHERE c.id = v_project_client_id
          AND c.company_id = p_company_id;


        IF NOT FOUND THEN

            RAISE EXCEPTION
                'El cliente del proyecto no existe o no pertenece a la empresa seleccionada';

        END IF;

    END IF;


    -- ========================================================
    -- 5. ECONOMIC VALUES
    -- ========================================================

    v_subtotal :=
        COALESCE(
            p_subtotal,
            0
        );


    v_iva_porcentaje :=
        COALESCE(
            p_iva_porcentaje,
            0
        );


    IF v_subtotal < 0 THEN

        RAISE EXCEPTION
            'El importe no puede ser negativo';

    END IF;


    IF v_iva_porcentaje < 0
       OR v_iva_porcentaje > 100
    THEN

        RAISE EXCEPTION
            'El IVA debe estar entre 0 y 100';

    END IF;


    -- ========================================================
    -- 6. DATES
    -- ========================================================

    IF p_fecha_vencimiento IS NOT NULL
       AND COALESCE(
           p_fecha_emision,
           CURRENT_TIMESTAMP
       ) > p_fecha_vencimiento
    THEN

        RAISE EXCEPTION
            'La fecha de vencimiento no puede ser anterior a la fecha de emisión';

    END IF;


    -- ========================================================
    -- 7. CALCULATE IVA
    -- ========================================================

    v_iva_importe :=
        ROUND(
            v_subtotal
            *
            v_iva_porcentaje
            /
            100,
            2
        );


    -- ========================================================
    -- 8. CALCULATE TOTAL
    -- ========================================================

    v_monto :=
        ROUND(
            v_subtotal
            +
            v_iva_importe,
            2
        );


    -- ========================================================
    -- 9. GENERATE NUMBER
    -- ========================================================

    v_numero_factura :=
        public.generate_invoice_number();


    -- ========================================================
    -- 10. INSERT
    -- ========================================================

    INSERT INTO public.invoices (
        user_id,
        company_id,
        project_id,
        client_id,

        numero_factura,
        monto,
        estado,

        fecha_emision,
        fecha_vencimiento,

        descripcion,

        subtotal,
        iva_porcentaje,
        iva_importe,

        -- ----------------------------------------------------
        -- Issuer fiscal snapshot
        -- ----------------------------------------------------

        issuer_legal_name,
        issuer_tax_id,
        issuer_address,
        issuer_postal_code,
        issuer_city,
        issuer_province,
        issuer_country,

        -- ----------------------------------------------------
        -- Customer fiscal snapshot
        -- ----------------------------------------------------

        customer_legal_name,
        customer_tax_id,
        customer_address,
        customer_postal_code,
        customer_city,
        customer_province,
        customer_country,
        customer_contact_name
    )
    VALUES (
        v_project_user_id,
        p_company_id,
        p_project_id,
        v_project_client_id,

        v_numero_factura,
        v_monto,
        'pendiente',

        COALESCE(
            p_fecha_emision,
            CURRENT_TIMESTAMP
        ),
        p_fecha_vencimiento,

        NULLIF(
            TRIM(p_descripcion),
            ''
        ),

        v_subtotal,
        v_iva_porcentaje,
        v_iva_importe,

        -- issuer
        v_issuer_legal_name,
        v_issuer_tax_id,
        v_issuer_address,
        v_issuer_postal_code,
        v_issuer_city,
        v_issuer_province,
        v_issuer_country,

        -- customer
        v_customer_legal_name,
        v_customer_tax_id,
        v_customer_address,
        v_customer_postal_code,
        v_customer_city,
        v_customer_province,
        v_customer_country,
        v_customer_contact_name
    )
    RETURNING *
    INTO v_invoice;


    -- ========================================================
    -- 11. RETURN
    -- ========================================================

    RETURN v_invoice;


END;
$$;


ALTER FUNCTION "public"."create_invoice_by_worker"("p_company_id" "uuid", "p_project_id" "uuid", "p_fecha_emision" timestamp with time zone, "p_fecha_vencimiento" timestamp with time zone, "p_descripcion" "text", "p_subtotal" numeric, "p_iva_porcentaje" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project"("p_descripcion" "text", "p_fecha_inicio" timestamp with time zone DEFAULT CURRENT_TIMESTAMP, "p_fecha_fin" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."projects"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_project public.projects;
    v_company_id UUID;
    v_fecha_inicio TIMESTAMPTZ;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado';
    END IF;

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION 'Acceso denegado: la cuenta está bloqueada';
    END IF;

    IF public.current_user_is_worker() THEN
        RAISE EXCEPTION 'Los trabajadores no pueden crear proyectos mediante create_project()';
    END IF;

    IF p_descripcion IS NULL OR TRIM(p_descripcion) = '' THEN
        RAISE EXCEPTION 'La descripción del proyecto es obligatoria';
    END IF;

    v_fecha_inicio := COALESCE(p_fecha_inicio, CURRENT_TIMESTAMP);

    IF p_fecha_fin IS NOT NULL AND p_fecha_fin < v_fecha_inicio THEN
        RAISE EXCEPTION 'La fecha de fin no puede ser anterior a la fecha de inicio';
    END IF;

    v_company_id := public.current_user_company_id();

    INSERT INTO public.projects (
        user_id,
        company_id,
        nombre,
        descripcion,
        estado,
        fecha_inicio,
        fecha_fin
    )
    VALUES (
        auth.uid(),
        v_company_id,
        'Proyecto sin título',
        TRIM(p_descripcion),
        'Pendiente',
        v_fecha_inicio,
        p_fecha_fin
    )
    RETURNING * INTO v_project;

    RETURN v_project;
END;
$$;


ALTER FUNCTION "public"."create_project"("p_descripcion" "text", "p_fecha_inicio" timestamp with time zone, "p_fecha_fin" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project_by_worker"("p_client_id" "uuid", "p_descripcion" "text", "p_fecha_inicio" timestamp with time zone DEFAULT CURRENT_TIMESTAMP, "p_fecha_fin" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."projects"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'projects.create'
    );

    RETURN public.create_project_by_worker__legacy_113(
        p_client_id,
        p_descripcion,
        p_fecha_inicio,
        p_fecha_fin
    );

END;
$$;


ALTER FUNCTION "public"."create_project_by_worker"("p_client_id" "uuid", "p_descripcion" "text", "p_fecha_inicio" timestamp with time zone, "p_fecha_fin" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project_by_worker__legacy_113"("p_client_id" "uuid", "p_descripcion" "text", "p_fecha_inicio" timestamp with time zone DEFAULT CURRENT_TIMESTAMP, "p_fecha_fin" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."projects"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_project public.projects;
    v_client_company_id UUID;
    v_client_profile_id UUID;
    v_fecha_inicio TIMESTAMPTZ;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado';
    END IF;

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION 'Acceso denegado: se requiere un trabajador activo';
    END IF;

    IF p_client_id IS NULL THEN
        RAISE EXCEPTION 'El cliente es obligatorio';
    END IF;

    IF p_descripcion IS NULL OR TRIM(p_descripcion) = '' THEN
        RAISE EXCEPTION 'La descripción del proyecto es obligatoria';
    END IF;

    -- 009 añade clients.profile_id. Se usa SQL dinámico para que
    -- la definición de esta RPC no rompa el reset antes de 009.
    EXECUTE '
        SELECT c.company_id, c.profile_id
        FROM public.clients c
        WHERE c.id = $1
    '
    INTO v_client_company_id, v_client_profile_id
    USING p_client_id;

    IF v_client_company_id IS NULL THEN
        RAISE EXCEPTION 'El cliente seleccionado no existe';
    END IF;

    IF v_client_profile_id IS NULL THEN
        RAISE EXCEPTION
            'El cliente seleccionado no está vinculado a un usuario de Modira';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.profiles p
        WHERE p.id = v_client_profile_id
          AND p.company_id = v_client_company_id
          AND p.rol = 'user'
    ) THEN
        RAISE EXCEPTION
            'El usuario asociado al cliente no es válido para esta empresa';
    END IF;

    v_fecha_inicio := COALESCE(p_fecha_inicio, CURRENT_TIMESTAMP);

    IF p_fecha_fin IS NOT NULL AND p_fecha_fin < v_fecha_inicio THEN
        RAISE EXCEPTION 'La fecha de fin no puede ser anterior a la fecha de inicio';
    END IF;

    INSERT INTO public.projects (
        user_id,
        company_id,
        client_id,
        nombre,
        descripcion,
        estado,
        fecha_inicio,
        fecha_fin
    )
    VALUES (
        v_client_profile_id,
        v_client_company_id,
        p_client_id,
        'Proyecto sin título',
        TRIM(p_descripcion),
        'Pendiente',
        v_fecha_inicio,
        p_fecha_fin
    )
    RETURNING * INTO v_project;

    RETURN v_project;
END;
$_$;


ALTER FUNCTION "public"."create_project_by_worker__legacy_113"("p_client_id" "uuid", "p_descripcion" "text", "p_fecha_inicio" timestamp with time zone, "p_fecha_fin" timestamp with time zone) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."project_milestones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "descripcion" "text",
    "fecha_prevista" timestamp with time zone NOT NULL,
    "orden" integer DEFAULT 1 NOT NULL,
    "estado" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "completed_at" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "project_milestones_completed_at_check" CHECK (((("estado" = 'completado'::"text") AND ("completed_at" IS NOT NULL)) OR (("estado" <> 'completado'::"text") AND ("completed_at" IS NULL)))),
    CONSTRAINT "project_milestones_descripcion_check" CHECK ((("descripcion" IS NULL) OR ("length"("descripcion") <= 2000))),
    CONSTRAINT "project_milestones_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'en_curso'::"text", 'completado'::"text"]))),
    CONSTRAINT "project_milestones_nombre_check" CHECK ((("length"("btrim"("nombre")) > 0) AND ("length"("nombre") <= 200))),
    CONSTRAINT "project_milestones_orden_check" CHECK ((("orden" >= 1) AND ("orden" <= 10000)))
);


ALTER TABLE "public"."project_milestones" OWNER TO "postgres";


COMMENT ON TABLE "public"."project_milestones" IS 'Metas e hitos de los proyectos de Modira. Los trabajadores activos los gestionan mediante RPC y los clientes activos únicamente pueden consultar los hitos de sus propios proyectos.';



COMMENT ON COLUMN "public"."project_milestones"."fecha_prevista" IS 'Fecha y hora prevista para alcanzar el hito. Se utiliza también como fuente de datos para el calendario del proyecto.';



COMMENT ON COLUMN "public"."project_milestones"."orden" IS 'Orden visual del hito dentro de la línea temporal del proyecto.';



COMMENT ON COLUMN "public"."project_milestones"."estado" IS 'Estado del hito: pendiente, en_curso o completado.';



COMMENT ON COLUMN "public"."project_milestones"."completed_at" IS 'Momento en el que el hito pasó a estado completado. Se mantiene automáticamente mediante trigger.';



CREATE OR REPLACE FUNCTION "public"."create_project_milestone"("p_project_id" "uuid", "p_nombre" "text", "p_descripcion" "text" DEFAULT NULL::"text", "p_fecha_prevista" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."project_milestones"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'project_milestones.create'
    );

    RETURN public.create_project_milestone__legacy_113(
        p_project_id,
        p_nombre,
        p_descripcion,
        p_fecha_prevista
    );

END;
$$;


ALTER FUNCTION "public"."create_project_milestone"("p_project_id" "uuid", "p_nombre" "text", "p_descripcion" "text", "p_fecha_prevista" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project_milestone__legacy_113"("p_project_id" "uuid", "p_nombre" "text", "p_descripcion" "text" DEFAULT NULL::"text", "p_fecha_prevista" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."project_milestones"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

    v_milestone public.project_milestones;

    v_next_order INTEGER;

BEGIN

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- WORKER ACTIVO
    -- --------------------------------------------------------

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    -- --------------------------------------------------------
    -- PROJECT ID
    -- --------------------------------------------------------

    IF p_project_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto es obligatorio';
    END IF;


    -- --------------------------------------------------------
    -- NOMBRE
    -- --------------------------------------------------------

    IF p_nombre IS NULL
       OR LENGTH(BTRIM(p_nombre)) = 0
       OR LENGTH(p_nombre) > 200
    THEN
        RAISE EXCEPTION
            'El nombre del hito no es válido';
    END IF;


    -- --------------------------------------------------------
    -- DESCRIPCIÓN
    -- --------------------------------------------------------

    IF p_descripcion IS NOT NULL
       AND LENGTH(p_descripcion) > 2000
    THEN
        RAISE EXCEPTION
            'La descripción del hito no puede superar 2000 caracteres';
    END IF;


    -- --------------------------------------------------------
    -- FECHA
    -- --------------------------------------------------------

    IF p_fecha_prevista IS NULL THEN
        RAISE EXCEPTION
            'La fecha prevista del hito es obligatoria';
    END IF;


    -- --------------------------------------------------------
    -- PROYECTO
    -- --------------------------------------------------------

    IF NOT EXISTS (
        SELECT 1
        FROM public.projects
        WHERE id = p_project_id
    ) THEN
        RAISE EXCEPTION
            'El proyecto indicado no existe';
    END IF;


    -- --------------------------------------------------------
    -- SIGUIENTE ORDEN
    -- --------------------------------------------------------

    SELECT
        COALESCE(MAX(orden), 0) + 1
    INTO
        v_next_order
    FROM public.project_milestones
    WHERE project_id = p_project_id;


    -- --------------------------------------------------------
    -- CREAR HITO
    -- --------------------------------------------------------

    INSERT INTO public.project_milestones (
        project_id,
        nombre,
        descripcion,
        fecha_prevista,
        orden,
        estado,
        created_by
    )
    VALUES (
        p_project_id,
        BTRIM(p_nombre),
        NULLIF(BTRIM(p_descripcion), ''),
        p_fecha_prevista,
        v_next_order,
        'pendiente',
        auth.uid()
    )
    RETURNING *
    INTO v_milestone;


    RETURN v_milestone;

END;
$$;


ALTER FUNCTION "public"."create_project_milestone__legacy_113"("p_project_id" "uuid", "p_nombre" "text", "p_descripcion" "text", "p_fecha_prevista" timestamp with time zone) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."project_tasks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "milestone_id" "uuid",
    "title" "text" NOT NULL,
    "description" "text",
    "created_by_worker_id" "uuid" NOT NULL,
    "assigned_to_worker_id" "uuid",
    "status" "text" DEFAULT 'to_do'::"text" NOT NULL,
    "progress" integer DEFAULT 0 NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "due_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "submitted_for_review_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "completed_by_worker_id" "uuid",
    "cancelled_by_worker_id" "uuid",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "recommended_worker_id" "uuid",
    CONSTRAINT "project_tasks_completed_progress_check" CHECK ((("status" <> 'completed'::"text") OR ("progress" = 100))),
    CONSTRAINT "project_tasks_description_max_length" CHECK ((("description" IS NULL) OR ("char_length"("description") <= 5000))),
    CONSTRAINT "project_tasks_pending_review_progress_check" CHECK ((("status" <> 'pending_review'::"text") OR ("progress" = 100))),
    CONSTRAINT "project_tasks_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "project_tasks_progress_check" CHECK ((("progress" >= 0) AND ("progress" <= 100))),
    CONSTRAINT "project_tasks_status_check" CHECK (("status" = ANY (ARRAY['to_do'::"text", 'in_progress'::"text", 'pending_review'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "project_tasks_title_max_length" CHECK (("char_length"("title") <= 200)),
    CONSTRAINT "project_tasks_title_not_blank" CHECK ((NULLIF("btrim"("title"), ''::"text") IS NOT NULL))
);


ALTER TABLE "public"."project_tasks" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project_task"("p_project_id" "uuid", "p_title" "text", "p_description" "text" DEFAULT NULL::"text", "p_milestone_id" "uuid" DEFAULT NULL::"uuid", "p_assigned_to_worker_id" "uuid" DEFAULT NULL::"uuid", "p_recommended_worker_id" "uuid" DEFAULT NULL::"uuid", "p_priority" "text" DEFAULT 'normal'::"text", "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."project_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_worker_id UUID;
    v_task public.project_tasks;
    v_title TEXT;
    v_description TEXT;
    v_priority TEXT;
BEGIN
    v_worker_id := public.current_project_task_worker_id();

    IF v_worker_id IS NULL THEN
        RAISE EXCEPTION 'Acceso denegado: se requiere un trabajador activo';
    END IF;

    PERFORM public.require_current_worker_permission('project_tasks.create');

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:create:' || auth.uid()::TEXT,
        30,
        3600
    );

    IF p_project_id IS NULL THEN
        RAISE EXCEPTION 'El proyecto es obligatorio';
    END IF;

    IF NOT public.project_task_project_exists(p_project_id) THEN
        RAISE EXCEPTION 'El proyecto no existe';
    END IF;

    v_title := NULLIF(BTRIM(p_title), '');

    IF v_title IS NULL THEN
        RAISE EXCEPTION 'El título es obligatorio';
    END IF;

    IF LENGTH(v_title) > 200 THEN
        RAISE EXCEPTION 'El título no puede superar 200 caracteres';
    END IF;

    v_description := NULLIF(BTRIM(p_description), '');

    IF v_description IS NOT NULL
       AND LENGTH(v_description) > 5000
    THEN
        RAISE EXCEPTION 'La descripción no puede superar 5000 caracteres';
    END IF;

    v_priority := LOWER(BTRIM(COALESCE(p_priority, 'normal')));

    IF v_priority NOT IN ('low', 'normal', 'high', 'urgent') THEN
        RAISE EXCEPTION 'Prioridad no válida';
    END IF;

    IF p_milestone_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1
            FROM public.project_milestones pm
            WHERE pm.id = p_milestone_id
              AND pm.project_id = p_project_id
        ) THEN
            RAISE EXCEPTION
                'El hito no existe o no pertenece al proyecto';
        END IF;
    END IF;

    -- La asignación real solo puede hacerla Dirección.
    -- El Developer ya no puede asignarse ni asignar a otro worker.
    IF p_assigned_to_worker_id IS NOT NULL THEN
        IF NOT public.current_worker_is_direction() THEN
            RAISE EXCEPTION
                'Solo Dirección puede asignar directamente una tarea a un trabajador';
        END IF;

        PERFORM public.validate_project_task_assignee(
            p_assigned_to_worker_id
        );
    END IF;

    -- La recomendación es solo una sugerencia para Dirección.
    -- Debe corresponder a un worker activo.
    IF p_recommended_worker_id IS NOT NULL THEN
        PERFORM public.validate_project_task_assignee(
            p_recommended_worker_id
        );
    END IF;

    INSERT INTO public.project_tasks (
        project_id,
        milestone_id,
        title,
        description,
        created_by_worker_id,
        assigned_to_worker_id,
        recommended_worker_id,
        status,
        progress,
        priority,
        due_at
    )
    VALUES (
        p_project_id,
        p_milestone_id,
        v_title,
        v_description,
        v_worker_id,
        p_assigned_to_worker_id,
        p_recommended_worker_id,
        'to_do',
        0,
        v_priority,
        p_due_at
    )
    RETURNING *
    INTO v_task;

    PERFORM public.record_project_task_update(
        v_task.id,
        'created',
        NULL,
        NULL,
        v_task.status,
        v_task.progress,
        NULL
    );

    RETURN v_task;
END;
$$;


ALTER FUNCTION "public"."create_project_task"("p_project_id" "uuid", "p_title" "text", "p_description" "text", "p_milestone_id" "uuid", "p_assigned_to_worker_id" "uuid", "p_recommended_worker_id" "uuid", "p_priority" "text", "p_due_at" timestamp with time zone) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."project_updates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "titulo" "text" NOT NULL,
    "contenido" "text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "project_updates_contenido_check" CHECK ((("length"("btrim"("contenido")) > 0) AND ("length"("contenido") <= 5000))),
    CONSTRAINT "project_updates_titulo_check" CHECK ((("length"("btrim"("titulo")) > 0) AND ("length"("titulo") <= 200)))
);


ALTER TABLE "public"."project_updates" OWNER TO "postgres";


COMMENT ON TABLE "public"."project_updates" IS 'Actualizaciones editoriales de proyectos publicadas deliberadamente para el cliente. No sustituye activity_log, que continúa siendo el registro general de actividad de Modira.';



COMMENT ON COLUMN "public"."project_updates"."project_id" IS 'Proyecto al que pertenece la actualización. El cliente accede a las actualizaciones mediante projects.user_id.';



COMMENT ON COLUMN "public"."project_updates"."titulo" IS 'Título breve de la actualización que se mostrará en Últimas novedades del Área Cliente.';



COMMENT ON COLUMN "public"."project_updates"."contenido" IS 'Contenido descriptivo de la actualización visible para el cliente.';



COMMENT ON COLUMN "public"."project_updates"."created_by" IS 'Usuario trabajador que creó la actualización.';



CREATE OR REPLACE FUNCTION "public"."create_project_update"("p_project_id" "uuid", "p_titulo" "text", "p_contenido" "text") RETURNS "public"."project_updates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'project_updates.create'
    );

    RETURN public.create_project_update__legacy_113(
        p_project_id,
        p_titulo,
        p_contenido
    );

END;
$$;


ALTER FUNCTION "public"."create_project_update"("p_project_id" "uuid", "p_titulo" "text", "p_contenido" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project_update__legacy_113"("p_project_id" "uuid", "p_titulo" "text", "p_contenido" "text") RETURNS "public"."project_updates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

    v_update public.project_updates;

BEGIN

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- WORKER ACTIVO
    -- --------------------------------------------------------

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    -- --------------------------------------------------------
    -- PROJECT ID
    -- --------------------------------------------------------

    IF p_project_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto es obligatorio';
    END IF;


    -- --------------------------------------------------------
    -- TÍTULO
    -- --------------------------------------------------------

    IF p_titulo IS NULL
       OR LENGTH(BTRIM(p_titulo)) = 0
       OR LENGTH(p_titulo) > 200
    THEN
        RAISE EXCEPTION
            'El título de la novedad no es válido';
    END IF;


    -- --------------------------------------------------------
    -- CONTENIDO
    -- --------------------------------------------------------

    IF p_contenido IS NULL
       OR LENGTH(BTRIM(p_contenido)) = 0
       OR LENGTH(p_contenido) > 5000
    THEN
        RAISE EXCEPTION
            'El contenido de la novedad no es válido';
    END IF;


    -- --------------------------------------------------------
    -- COMPROBAR PROYECTO
    -- --------------------------------------------------------

    IF NOT EXISTS (
        SELECT 1
        FROM public.projects
        WHERE id = p_project_id
    ) THEN
        RAISE EXCEPTION
            'El proyecto indicado no existe';
    END IF;


    -- --------------------------------------------------------
    -- CREAR NOVEDAD
    -- --------------------------------------------------------

    INSERT INTO public.project_updates (
        project_id,
        titulo,
        contenido,
        created_by
    )
    VALUES (
        p_project_id,
        BTRIM(p_titulo),
        BTRIM(p_contenido),
        auth.uid()
    )
    RETURNING *
    INTO v_update;


    -- --------------------------------------------------------
    -- NOTIFICAR AL CLIENTE
    --
    -- El destinatario se obtiene internamente a partir de:
    --
    -- project_id
    --     ↓
    -- projects.user_id
    --
    -- El worker nunca proporciona el user_id del destinatario.
    -- --------------------------------------------------------

    PERFORM public.emit_project_client_notification(
        p_project_id,
        'project_update',
        v_update.titulo,
        'Hay una nueva actualización en tu proyecto.',
        jsonb_build_object(
            'project_update_id', v_update.id,
            'event', 'project_update_created'
        )
    );


    RETURN v_update;

END;
$$;


ALTER FUNCTION "public"."create_project_update__legacy_113"("p_project_id" "uuid", "p_titulo" "text", "p_contenido" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_project_update__legacy_113"("p_project_id" "uuid", "p_titulo" "text", "p_contenido" "text") IS 'Crea una actualización visible para el cliente y genera una notificación asociada al proyecto. Solo puede ejecutarla un trabajador activo.';



CREATE OR REPLACE FUNCTION "public"."create_quotation_by_worker"("p_company_id" "uuid", "p_project_id" "uuid", "p_titulo" "text", "p_descripcion_detallada" "text", "p_servicios_incluidos" "jsonb", "p_iva_porcentaje" numeric, "p_irpf_aplicado" boolean, "p_irpf_porcentaje" numeric, "p_estado" "text", "p_fecha_emision" timestamp with time zone, "p_fecha_validez" timestamp with time zone, "p_notas" "text") RETURNS "public"."quotations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_quotation public.quotations;
    v_project public.projects%ROWTYPE;

    v_title TEXT;
    v_description TEXT;
    v_notes TEXT;
    v_state TEXT;

    v_iva NUMERIC(5,2);
    v_irpf NUMERIC(5,2);
    v_irpf_applied BOOLEAN;

    v_subtotal NUMERIC(12,2);
    v_iva_importe NUMERIC(12,2);
    v_irpf_importe NUMERIC(12,2);
    v_total NUMERIC(12,2);

    v_service JSONB;
    v_service_description TEXT;
    v_quantity NUMERIC;
    v_price NUMERIC;

    v_fecha_emision TIMESTAMPTZ;
    v_fecha_validez TIMESTAMPTZ;
    -- --------------------------------------------------------
    -- Fiscal issuer snapshot
    -- --------------------------------------------------------
    v_issuer_legal_name TEXT;
    v_issuer_tax_id TEXT;
    v_issuer_address TEXT;
    v_issuer_postal_code TEXT;
    v_issuer_city TEXT;
    v_issuer_province TEXT;
    v_issuer_country TEXT;

    -- --------------------------------------------------------
    -- Fiscal customer snapshot
    -- --------------------------------------------------------
    v_customer_legal_name TEXT;
    v_customer_tax_id TEXT;
    v_customer_address TEXT;
    v_customer_postal_code TEXT;
    v_customer_city TEXT;
    v_customer_province TEXT;
    v_customer_country TEXT;
    v_customer_contact_name TEXT;

BEGIN

    PERFORM public.require_current_worker_permission(
        'quotations.create'
    );

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Acceso denegado';
    END IF;

    IF p_company_id IS NULL THEN
        RAISE EXCEPTION
            'La empresa es obligatoria';
    END IF;

    IF p_project_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto es obligatorio';
    END IF;

    SELECT *
    INTO v_project
    FROM public.projects
    WHERE id = p_project_id
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El proyecto seleccionado no existe';
    END IF;

    IF v_project.company_id IS NULL
       OR v_project.company_id <> p_company_id
    THEN
        RAISE EXCEPTION
            'El proyecto no pertenece a la empresa seleccionada';
    END IF;

    IF v_project.user_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto no tiene un usuario propietario válido';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM auth.users u
        WHERE u.id = v_project.user_id
    ) THEN
        RAISE EXCEPTION
            'El propietario del proyecto no existe';
    END IF;

    IF v_project.client_id IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
            FROM public.clients c
            WHERE c.id = v_project.client_id
              AND c.company_id = v_project.company_id
       )
    THEN
        RAISE EXCEPTION
            'El cliente del proyecto no pertenece a la empresa';
    END IF;


    -- ========================================================
    -- FISCAL SNAPSHOT
    -- ========================================================
    --
    -- El presupuesto conserva una fotografía de los datos
    -- fiscales del emisor y del cliente usados para su documento.
    -- El cliente del proyecto puede ser NULL y, en ese caso,
    -- el snapshot del cliente permanece NULL.
    --
    -- ========================================================

    SELECT
        COALESCE(
            NULLIF(TRIM(c.legal_name), ''),
            NULLIF(TRIM(c.company_name), '')
        ),
        NULLIF(TRIM(c.cif_vat), ''),
        NULLIF(TRIM(c.address), ''),
        NULLIF(TRIM(c.postal_code), ''),
        NULLIF(TRIM(c.city), ''),
        NULLIF(TRIM(c.province), ''),
        COALESCE(
            NULLIF(TRIM(c.country), ''),
            'ES'
        )
    INTO
        v_issuer_legal_name,
        v_issuer_tax_id,
        v_issuer_address,
        v_issuer_postal_code,
        v_issuer_city,
        v_issuer_province,
        v_issuer_country
    FROM public.companies c
    WHERE c.id = v_project.company_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La empresa del proyecto no existe';
    END IF;

    IF v_project.client_id IS NOT NULL THEN

        SELECT
            COALESCE(
                NULLIF(TRIM(c.empresa), ''),
                NULLIF(TRIM(c.nombre), '')
            ),
            NULLIF(TRIM(c.cif_vat), ''),
            NULLIF(TRIM(c.direccion), ''),
            NULLIF(TRIM(c.codigo_postal), ''),
            NULLIF(TRIM(c.ciudad), ''),
            NULLIF(TRIM(c.provincia), ''),
            COALESCE(
                NULLIF(TRIM(c.pais), ''),
                'ES'
            ),
            NULLIF(TRIM(c.nombre), '')
        INTO
            v_customer_legal_name,
            v_customer_tax_id,
            v_customer_address,
            v_customer_postal_code,
            v_customer_city,
            v_customer_province,
            v_customer_country,
            v_customer_contact_name
        FROM public.clients c
        WHERE c.id = v_project.client_id
          AND c.company_id = v_project.company_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'El cliente del proyecto no existe o no pertenece a la empresa seleccionada';
        END IF;

    END IF;

    v_title := NULLIF(BTRIM(p_titulo), '');

    IF v_title IS NULL THEN
        RAISE EXCEPTION
            'El título del presupuesto es obligatorio';
    END IF;

    IF LENGTH(v_title) > 300 THEN
        RAISE EXCEPTION
            'El título no puede superar 300 caracteres';
    END IF;

    v_description :=
        NULLIF(
            BTRIM(
                COALESCE(
                    p_descripcion_detallada,
                    ''
                )
            ),
            ''
        );

    IF v_description IS NOT NULL
       AND LENGTH(v_description) > 10000
    THEN
        RAISE EXCEPTION
            'La descripción del presupuesto no puede superar 10000 caracteres';
    END IF;

    v_notes :=
        NULLIF(
            BTRIM(
                COALESCE(
                    p_notas,
                    ''
                )
            ),
            ''
        );

    IF v_notes IS NOT NULL
       AND LENGTH(v_notes) > 10000
    THEN
        RAISE EXCEPTION
            'Las notas del presupuesto no pueden superar 10000 caracteres';
    END IF;

    v_state :=
        INITCAP(
            LOWER(
                BTRIM(
                    COALESCE(
                        p_estado,
                        'Pendiente'
                    )
                )
            )
        );

    IF v_state NOT IN (
        'Pendiente',
        'Aceptado',
        'Rechazado'
    ) THEN
        RAISE EXCEPTION
            'Estado de presupuesto no válido';
    END IF;

    v_iva :=
        ROUND(
            COALESCE(
                p_iva_porcentaje,
                0
            ),
            2
        );

    IF v_iva < 0 OR v_iva > 100 THEN
        RAISE EXCEPTION
            'El porcentaje de IVA debe estar entre 0 y 100';
    END IF;

    v_irpf_applied :=
        COALESCE(
            p_irpf_aplicado,
            FALSE
        );

    v_irpf :=
        ROUND(
            COALESCE(
                p_irpf_porcentaje,
                0
            ),
            2
        );

    IF NOT v_irpf_applied THEN

        IF v_irpf <> 0 THEN
            RAISE EXCEPTION
                'Si el IRPF no se aplica, el porcentaje debe ser 0';
        END IF;

        v_irpf := 0;

    ELSE

        IF v_irpf <= 0 OR v_irpf > 100 THEN
            RAISE EXCEPTION
                'El porcentaje de IRPF debe ser mayor que 0 y menor o igual que 100';
        END IF;

    END IF;

    IF p_servicios_incluidos IS NULL
       OR jsonb_typeof(p_servicios_incluidos) <> 'array'
    THEN
        RAISE EXCEPTION
            'Los servicios incluidos deben ser un array JSON';
    END IF;

    IF jsonb_array_length(p_servicios_incluidos) = 0 THEN
        RAISE EXCEPTION
            'Debe existir al menos un servicio';
    END IF;

    IF jsonb_array_length(p_servicios_incluidos) > 100 THEN
        RAISE EXCEPTION
            'El presupuesto no puede contener más de 100 servicios';
    END IF;

    v_subtotal := 0;

    FOR v_service IN
        SELECT value
        FROM jsonb_array_elements(
            p_servicios_incluidos
        )
    LOOP

        IF jsonb_typeof(v_service) <> 'object' THEN
            RAISE EXCEPTION
                'Cada servicio debe ser un objeto JSON';
        END IF;

        v_service_description :=
            NULLIF(
                BTRIM(
                    COALESCE(
                        v_service->>'descripcion',
                        ''
                    )
                ),
                ''
            );

        IF v_service_description IS NULL THEN
            RAISE EXCEPTION
                'Todos los servicios deben tener una descripción';
        END IF;

        IF LENGTH(v_service_description) > 2000 THEN
            RAISE EXCEPTION
                'La descripción de un servicio no puede superar 2000 caracteres';
        END IF;

        IF NOT (v_service ? 'cantidad')
           OR NOT (v_service ? 'precio')
        THEN
            RAISE EXCEPTION
                'Cada servicio debe contener cantidad y precio';
        END IF;

        BEGIN
            v_quantity :=
                (v_service->>'cantidad')::NUMERIC;

            v_price :=
                (v_service->>'precio')::NUMERIC;

        EXCEPTION
            WHEN invalid_text_representation
              OR numeric_value_out_of_range
        THEN
            RAISE EXCEPTION
                'Cantidad o precio de servicio no válidos';
        END;

        IF v_quantity IS NULL
           OR v_quantity <= 0
           OR v_quantity > 1000000
        THEN
            RAISE EXCEPTION
                'La cantidad de un servicio debe ser mayor que 0';
        END IF;

        IF v_price IS NULL
           OR v_price < 0
           OR v_price > 100000000
        THEN
            RAISE EXCEPTION
                'El precio de un servicio no puede ser negativo';
        END IF;

        v_subtotal :=
            v_subtotal
            + ROUND(
                v_quantity * v_price,
                2
            );

        IF v_subtotal > 1000000000 THEN
            RAISE EXCEPTION
                'El importe total del presupuesto supera el límite permitido';
        END IF;

    END LOOP;

    v_subtotal :=
        ROUND(
            v_subtotal,
            2
        );

    v_iva_importe :=
        ROUND(
            v_subtotal * (v_iva / 100),
            2
        );

    IF v_irpf_applied THEN
        v_irpf_importe :=
            ROUND(
                v_subtotal * (v_irpf / 100),
                2
            );
    ELSE
        v_irpf_importe := 0;
    END IF;

    v_total :=
        ROUND(
            v_subtotal
            + v_iva_importe
            - v_irpf_importe,
            2
        );

    IF v_total < 0 THEN
        RAISE EXCEPTION
            'El total del presupuesto no puede ser negativo';
    END IF;

    v_fecha_emision :=
        COALESCE(
            p_fecha_emision,
            CURRENT_TIMESTAMP
        );

    v_fecha_validez :=
        p_fecha_validez;

    INSERT INTO public.quotations (
        company_id,
        user_id,
        project_id,
        client_id,
        titulo,
        descripcion_detallada,
        servicios_incluidos,
        precio_base,
        iva_porcentaje,
        precio_total,
        irpf_aplicado,
        irpf_porcentaje,
        irpf_importe,
        estado,
        fecha_emision,
        fecha_validez,
        notas,

        issuer_legal_name,
        issuer_tax_id,
        issuer_address,
        issuer_postal_code,
        issuer_city,
        issuer_province,
        issuer_country,

        customer_legal_name,
        customer_tax_id,
        customer_address,
        customer_postal_code,
        customer_city,
        customer_province,
        customer_country,
        customer_contact_name
    )
    VALUES (
        v_project.company_id,
        v_project.user_id,
        v_project.id,
        v_project.client_id,
        v_title,
        v_description,
        p_servicios_incluidos,
        v_subtotal,
        v_iva,
        v_total,
        v_irpf_applied,
        v_irpf,
        v_irpf_importe,
        v_state,
        v_fecha_emision,
        v_fecha_validez,
        v_notes,

        v_issuer_legal_name,
        v_issuer_tax_id,
        v_issuer_address,
        v_issuer_postal_code,
        v_issuer_city,
        v_issuer_province,
        v_issuer_country,

        v_customer_legal_name,
        v_customer_tax_id,
        v_customer_address,
        v_customer_postal_code,
        v_customer_city,
        v_customer_province,
        v_customer_country,
        v_customer_contact_name
    )
    RETURNING *
    INTO v_quotation;

    RETURN v_quotation;

EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION
            'No se pudo generar el presupuesto por un conflicto de unicidad';
END;
$$;


ALTER FUNCTION "public"."create_quotation_by_worker"("p_company_id" "uuid", "p_project_id" "uuid", "p_titulo" "text", "p_descripcion_detallada" "text", "p_servicios_incluidos" "jsonb", "p_iva_porcentaje" numeric, "p_irpf_aplicado" boolean, "p_irpf_porcentaje" numeric, "p_estado" "text", "p_fecha_emision" timestamp with time zone, "p_fecha_validez" timestamp with time zone, "p_notas" "text") OWNER TO "postgres";


