CREATE TABLE IF NOT EXISTS "public"."recurring_expense_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "description" "text" NOT NULL,
    "expense_type" "text" NOT NULL,
    "category_id" "uuid",
    "supplier_id" "uuid",
    "project_id" "uuid",
    "currency" character varying(3) DEFAULT 'EUR'::character varying NOT NULL,
    "frequency" "text" NOT NULL,
    "start_date" "date" NOT NULL,
    "end_date" "date",
    "day_of_month" smallint,
    "subtotal" numeric(14,2) NOT NULL,
    "total_tax" numeric(14,2) DEFAULT 0 NOT NULL,
    "total_withholding" numeric(14,2) DEFAULT 0 NOT NULL,
    "total_amount" numeric(14,2) NOT NULL,
    "tax_config" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "approval_status" "text" DEFAULT 'approved'::"text" NOT NULL,
    "lifecycle_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "created_by" "uuid" NOT NULL,
    "updated_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "recurring_expense_templates_approval_status_check" CHECK (("approval_status" = ANY (ARRAY['pending_review'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "recurring_expense_templates_check" CHECK ((("end_date" IS NULL) OR ("end_date" >= "start_date"))),
    CONSTRAINT "recurring_expense_templates_check1" CHECK (("total_amount" = GREATEST("round"((("subtotal" + "total_tax") - "total_withholding"), 2), (0)::numeric))),
    CONSTRAINT "recurring_expense_templates_currency_check" CHECK ((("currency")::"text" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "recurring_expense_templates_day_of_month_check" CHECK ((("day_of_month" >= 1) AND ("day_of_month" <= 31))),
    CONSTRAINT "recurring_expense_templates_description_check" CHECK ((("length"("btrim"("description")) >= 1) AND ("length"("btrim"("description")) <= 5000))),
    CONSTRAINT "recurring_expense_templates_expense_type_check" CHECK (("expense_type" = ANY (ARRAY['supplier_invoice'::"text", 'employee_expense'::"text", 'travel'::"text", 'meals'::"text", 'corporate_card'::"text", 'subscription'::"text", 'tax'::"text", 'other'::"text"]))),
    CONSTRAINT "recurring_expense_templates_frequency_check" CHECK (("frequency" = ANY (ARRAY['weekly'::"text", 'monthly'::"text", 'quarterly'::"text", 'yearly'::"text"]))),
    CONSTRAINT "recurring_expense_templates_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['active'::"text", 'paused'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "recurring_expense_templates_subtotal_check" CHECK (("subtotal" >= (0)::numeric)),
    CONSTRAINT "recurring_expense_templates_tax_config_check" CHECK (("jsonb_typeof"("tax_config") = 'array'::"text")),
    CONSTRAINT "recurring_expense_templates_total_amount_check" CHECK (("total_amount" >= (0)::numeric)),
    CONSTRAINT "recurring_expense_templates_total_tax_check" CHECK (("total_tax" >= (0)::numeric)),
    CONSTRAINT "recurring_expense_templates_total_withholding_check" CHECK (("total_withholding" >= (0)::numeric))
);


ALTER TABLE "public"."recurring_expense_templates" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_recurring_expense_template"("p_description" "text", "p_expense_type" "text", "p_category_id" "uuid", "p_supplier_id" "uuid", "p_project_id" "uuid", "p_currency" "text", "p_frequency" "text", "p_start_date" "date", "p_end_date" "date", "p_day_of_month" smallint, "p_subtotal" numeric, "p_total_tax" numeric, "p_total_withholding" numeric, "p_tax_config" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."recurring_expense_templates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_template public.recurring_expense_templates;
  v_total numeric(14,2);
  v_approval_status text;
BEGIN
  PERFORM public.require_expense_permission('expenses.recurring.create');
  PERFORM public.consume_expense_worker_rate_limit('expenses:recurring_create');

  IF p_description IS NULL OR length(btrim(p_description)) NOT BETWEEN 1 AND 5000 THEN
    RAISE EXCEPTION 'La descripción debe tener entre 1 y 5000 caracteres';
  END IF;
  IF p_frequency NOT IN ('weekly','monthly','quarterly','yearly') THEN
    RAISE EXCEPTION 'Periodicidad no válida';
  END IF;
  IF p_start_date IS NULL OR (p_end_date IS NOT NULL AND p_end_date < p_start_date) THEN
    RAISE EXCEPTION 'El intervalo de fechas no es válido';
  END IF;
  IF p_subtotal IS NULL OR p_subtotal < 0 OR COALESCE(p_total_tax,0) < 0 OR COALESCE(p_total_withholding,0) < 0 THEN
    RAISE EXCEPTION 'Los importes no pueden ser negativos';
  END IF;
  IF COALESCE(p_currency, 'EUR') !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'La moneda debe ser un código ISO de tres letras en mayúsculas';
  END IF;
  IF p_frequency IN ('monthly','quarterly','yearly') AND p_day_of_month IS NOT NULL
     AND p_day_of_month NOT BETWEEN 1 AND 31 THEN
    RAISE EXCEPTION 'El día del mes debe estar entre 1 y 31';
  END IF;
  IF p_tax_config IS NOT NULL AND jsonb_typeof(p_tax_config) <> 'array' THEN
    RAISE EXCEPTION 'La configuración de impuestos debe ser una lista JSON';
  END IF;

  v_total := GREATEST(ROUND(COALESCE(p_subtotal,0) + COALESCE(p_total_tax,0) - COALESCE(p_total_withholding,0), 2), 0);
  v_approval_status := CASE WHEN public.expense_requires_approval(v_total, p_category_id) THEN 'pending_review' ELSE 'approved' END;

  INSERT INTO public.recurring_expense_templates (
    description, expense_type, category_id, supplier_id, project_id, currency,
    frequency, start_date, end_date, day_of_month, subtotal, total_tax,
    total_withholding, total_amount, tax_config, approval_status,
    created_by, updated_by
  ) VALUES (
    btrim(p_description), p_expense_type, p_category_id, p_supplier_id, p_project_id,
    COALESCE(p_currency, 'EUR'), p_frequency, p_start_date, p_end_date, p_day_of_month,
    ROUND(p_subtotal,2), ROUND(COALESCE(p_total_tax,0),2), ROUND(COALESCE(p_total_withholding,0),2),
    v_total, COALESCE(p_tax_config,'[]'::jsonb), v_approval_status, auth.uid(), auth.uid()
  ) RETURNING * INTO v_template;

  RETURN v_template;
END;
$_$;


ALTER FUNCTION "public"."create_recurring_expense_template"("p_description" "text", "p_expense_type" "text", "p_category_id" "uuid", "p_supplier_id" "uuid", "p_project_id" "uuid", "p_currency" "text", "p_frequency" "text", "p_start_date" "date", "p_end_date" "date", "p_day_of_month" smallint, "p_subtotal" numeric, "p_total_tax" numeric, "p_total_withholding" numeric, "p_tax_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_worker_custom_role"("p_code" "text", "p_name" "text", "p_description" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_code text;
    v_name text;
    v_role_id uuid;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required'
            USING ERRCODE = '42501';
    END IF;

    IF NOT public.current_user_can_manage_worker_roles() THEN
        RAISE EXCEPTION 'Insufficient permissions to create worker roles'
            USING ERRCODE = '42501';
    END IF;

    v_code := LOWER(BTRIM(COALESCE(p_code, '')));
    v_name := BTRIM(COALESCE(p_name, ''));

    IF v_name = '' THEN
        RAISE EXCEPTION 'Role name is required'
            USING ERRCODE = '22023';
    END IF;

    IF v_code !~ '^[a-z][a-z0-9_]{0,49}$' THEN
        RAISE EXCEPTION
            'Invalid role code. Use lowercase letters, numbers and underscores, starting with a letter.'
            USING ERRCODE = '22023';
    END IF;

    IF v_code IN ('direction', 'commercial', 'accounting', 'developer', 'support') THEN
        RAISE EXCEPTION 'This role code is reserved for a system role'
            USING ERRCODE = '42501';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.worker_roles r
        WHERE LOWER(r.code) = v_code
    ) THEN
        RAISE EXCEPTION 'A role with this code already exists'
            USING ERRCODE = '23505';
    END IF;

    INSERT INTO public.worker_roles (
        code,
        name,
        description,
        is_system_role,
        is_active
    )
    VALUES (
        v_code,
        v_name,
        NULLIF(BTRIM(COALESCE(p_description, '')), ''),
        FALSE,
        TRUE
    )
    RETURNING id INTO v_role_id;

    RETURN v_role_id;
END;
$_$;


ALTER FUNCTION "public"."create_worker_custom_role"("p_code" "text", "p_name" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_project_task_worker_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_worker_id UUID;
BEGIN

    IF auth.uid() IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT w.id
    INTO v_worker_id
    FROM public.workers w
    WHERE w.auth_user_id = auth.uid()
      AND w.is_active = TRUE
    LIMIT 1;

    RETURN v_worker_id;

END;
$$;


