CREATE OR REPLACE FUNCTION "public"."current_worker_has_all_permissions"("p_permission_codes" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

    WITH requested AS (
        SELECT DISTINCT
            lower(btrim(value)) AS permission_code
        FROM unnest(
            COALESCE(
                p_permission_codes,
                ARRAY[]::TEXT[]
            )
        ) AS value
        WHERE btrim(value) <> ''
    ),

    requested_count AS (
        SELECT COUNT(*)::BIGINT AS total
        FROM requested
    ),

    granted AS (
        SELECT DISTINCT
            wp.code
        FROM public.worker_role_assignments wra

        INNER JOIN public.worker_roles wr
            ON wr.id = wra.role_id

        INNER JOIN public.worker_role_permissions wrp
            ON wrp.role_id = wr.id

        INNER JOIN public.worker_permissions wp
            ON wp.id = wrp.permission_id

        INNER JOIN requested r
            ON r.permission_code = wp.code

        WHERE wra.worker_auth_user_id = auth.uid()

          AND wr.is_active = TRUE
    )

    SELECT
        CASE
            WHEN auth.uid() IS NULL THEN FALSE

            WHEN p_permission_codes IS NULL THEN FALSE

            WHEN cardinality(p_permission_codes) = 0 THEN FALSE

            WHEN NOT public.current_user_is_worker() THEN FALSE

            ELSE (
                SELECT COUNT(*)::BIGINT
                FROM granted
            )
            =
            (
                SELECT total
                FROM requested_count
            )
        END;

$$;


ALTER FUNCTION "public"."current_worker_has_all_permissions"("p_permission_codes" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."current_worker_has_all_permissions"("p_permission_codes" "text"[]) IS 'MODIRA RBAC: comprueba si el worker autenticado posee todos los permisos indicados.';



CREATE OR REPLACE FUNCTION "public"."current_worker_has_any_permission"("p_permission_codes" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

    SELECT
        CASE
            WHEN auth.uid() IS NULL THEN FALSE

            WHEN p_permission_codes IS NULL THEN FALSE

            WHEN cardinality(p_permission_codes) = 0 THEN FALSE

            WHEN NOT public.current_user_is_worker() THEN FALSE

            ELSE EXISTS (
                SELECT 1
                FROM public.worker_role_assignments wra

                INNER JOIN public.worker_roles wr
                    ON wr.id = wra.role_id

                INNER JOIN public.worker_role_permissions wrp
                    ON wrp.role_id = wr.id

                INNER JOIN public.worker_permissions wp
                    ON wp.id = wrp.permission_id

                INNER JOIN (
                    SELECT DISTINCT
                        lower(btrim(value)) AS permission_code
                    FROM unnest(p_permission_codes) AS value
                    WHERE btrim(value) <> ''
                ) requested
                    ON requested.permission_code = wp.code

                WHERE wra.worker_auth_user_id = auth.uid()

                  AND wr.is_active = TRUE
            )
        END;

$$;


ALTER FUNCTION "public"."current_worker_has_any_permission"("p_permission_codes" "text"[]) OWNER TO "postgres";


