CREATE OR REPLACE FUNCTION "public"."current_worker_is_direction"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_is_direction BOOLEAN;
BEGIN

    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN FALSE;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM public.get_worker_roles(v_user_id) r
        WHERE r.role_code = 'direction'
          AND r.is_active = TRUE
    )
    INTO v_is_direction;

    RETURN COALESCE(v_is_direction, FALSE);

END;
$$;


