CREATE OR REPLACE FUNCTION "public"."delete_expense"("p_expense_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_status TEXT;

  v_document_count INTEGER;

  v_payment_count INTEGER;

  v_allocation_count INTEGER;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.delete'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:delete'
  );


  SELECT status
  INTO v_status

  FROM public.expenses

  WHERE id = p_expense_id

  FOR UPDATE;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El gasto % no existe',
      p_expense_id;

  END IF;


  IF v_status <> 'draft' THEN

    RAISE EXCEPTION
      'Solo se pueden eliminar gastos en estado draft';

  END IF;


  SELECT COUNT(*)
  INTO v_document_count

  FROM public.expense_documents

  WHERE expense_id = p_expense_id;


  SELECT COUNT(*)
  INTO v_payment_count

  FROM public.expense_payments

  WHERE expense_id = p_expense_id;


  SELECT COUNT(*)
  INTO v_allocation_count

  FROM public.expense_allocations

  WHERE expense_id = p_expense_id;


  IF v_document_count > 0 THEN

    RAISE EXCEPTION
      'No se puede eliminar un gasto que tiene documentos';

  END IF;


  IF v_payment_count > 0 THEN

    RAISE EXCEPTION
      'No se puede eliminar un gasto que tiene pagos';

  END IF;


  IF v_allocation_count > 0 THEN

    RAISE EXCEPTION
      'No se puede eliminar un gasto que tiene asignaciones';

  END IF;


  DELETE FROM public.expenses

  WHERE id = p_expense_id;


  RETURN TRUE;

END;
$$;


ALTER FUNCTION "public"."delete_expense"("p_expense_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_expense"("p_expense_id" "uuid") IS 'Deletes a draft internal Modira expense when no dependent accounting records exist.';



CREATE OR REPLACE FUNCTION "public"."delete_expense_allocation"("p_allocation_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_expense_id UUID;

  v_status TEXT;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.allocate'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:allocate_delete'
  );


  SELECT
    ea.expense_id,
    e.status

  INTO
    v_expense_id,
    v_status

  FROM public.expense_allocations ea

  JOIN public.expenses e
    ON e.id = ea.expense_id

  WHERE ea.id = p_allocation_id

  FOR UPDATE OF ea, e;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'La asignación % no existe',
      p_allocation_id;

  END IF;


  IF v_status IN (
    'paid',
    'cancelled'
  ) THEN

    RAISE EXCEPTION
      'No se puede modificar la asignación de un gasto en estado %',
      v_status;

  END IF;


  DELETE FROM public.expense_allocations

  WHERE id = p_allocation_id;


  RETURN TRUE;

END;
$$;


ALTER FUNCTION "public"."delete_expense_allocation"("p_allocation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_expense_document"("p_document_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_storage_path TEXT;

  v_expense_id UUID;

  v_status TEXT;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.documents'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:document_delete'
  );


  SELECT
    ed.storage_path,
    ed.expense_id,
    e.status

  INTO
    v_storage_path,
    v_expense_id,
    v_status

  FROM public.expense_documents ed

  JOIN public.expenses e
    ON e.id = ed.expense_id

  WHERE ed.id = p_document_id

  FOR UPDATE OF ed;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El documento % no existe',
      p_document_id;

  END IF;


  IF v_status IN (
    'paid',
    'cancelled'
  ) THEN

    RAISE EXCEPTION
      'No se puede eliminar documentación de un gasto en estado %',
      v_status;

  END IF;


  DELETE FROM public.expense_documents

  WHERE id = p_document_id;


  RETURN v_storage_path;

END;
$$;


ALTER FUNCTION "public"."delete_expense_document"("p_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_expense_tax_line"("p_tax_line_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_expense_id UUID;

  v_status TEXT;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.update'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:tax_delete'
  );


  SELECT
    etl.expense_id,
