    v_status

  FROM public.expense_tax_lines etl

  JOIN public.expenses e
    ON e.id = etl.expense_id

  WHERE etl.id = p_tax_line_id

  FOR UPDATE OF e;


  IF NOT FOUND THEN

    RAISE EXCEPTION
