CREATE OR REPLACE FUNCTION "public"."delete_internal_task"("p_task_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."internal_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.internal_tasks;
    v_worker_id UUID;
    v_old_status TEXT;
    v_old_progress INTEGER;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.delete'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:delete:' || auth.uid()::TEXT,
        30,
        3600
    );


    IF NOT public.internal_task_current_worker_is_direction() THEN
        RAISE EXCEPTION
            'Solo Dirección puede anular una tarea';
    END IF;


    IF NULLIF(BTRIM(p_reason), '') IS NULL THEN
        RAISE EXCEPTION
            'Debes indicar el motivo de la anulación';
    END IF;


    v_worker_id := public.internal_task_current_worker_id();


    SELECT *
    INTO v_task
    FROM public.internal_tasks
    WHERE id = p_task_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tarea no existe';
    END IF;


    IF v_task.status = 'cancelled' THEN
        RAISE EXCEPTION
            'La tarea ya está anulada';
    END IF;


    v_old_status := v_task.status;
    v_old_progress := v_task.progress;


    UPDATE public.internal_tasks
    SET
        status = 'cancelled',
        cancelled_at = CURRENT_TIMESTAMP,
        cancelled_by_worker_id = v_worker_id,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_task_id
    RETURNING *
    INTO v_task;


    PERFORM public.internal_task_record_update(
        p_task_id,
        v_worker_id,
        'cancelled',
        v_old_status,
        v_old_progress,
        'cancelled',
        v_task.progress,
        BTRIM(p_reason)
    );


    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."delete_internal_task"("p_task_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_internal_task"("p_task_id" "uuid", "p_reason" "text") IS 'Direction-only logical task deletion. The task is cancelled instead of physically deleted so the complete audit history remains available.';



CREATE OR REPLACE FUNCTION "public"."delete_invoice_by_worker"("p_invoice_id" "uuid") RETURNS "public"."invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_invoice public.invoices;
BEGIN

    PERFORM public.require_current_worker_permission(
        'invoices.delete'
    );

    SELECT *
    INTO v_invoice
    FROM public.invoices
    WHERE id = p_invoice_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Factura no encontrada';
    END IF;

    IF v_invoice.document_path IS NOT NULL
       AND TRIM(v_invoice.document_path) <> ''
    THEN

        DELETE FROM storage.objects
        WHERE bucket_id = 'invoices'
          AND name = v_invoice.document_path;

    ELSE

        DELETE FROM storage.objects
        WHERE bucket_id = 'invoices'
          AND name = v_invoice.numero_factura || '.pdf';

    END IF;

    DELETE FROM public.invoices
    WHERE id = p_invoice_id
    RETURNING *
    INTO v_invoice;

    RETURN v_invoice;

END;
$$;


ALTER FUNCTION "public"."delete_invoice_by_worker"("p_invoice_id" "uuid") OWNER TO "postgres";


