CREATE OR REPLACE FUNCTION "public"."direction_set_internal_task_state"("p_task_id" "uuid", "p_status" "text", "p_progress" integer, "p_comment" "text" DEFAULT NULL::"text") RETURNS "public"."internal_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.internal_tasks;
    v_worker_id UUID;
    v_old_status TEXT;
    v_old_progress INTEGER;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.update'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:direction_state:' || auth.uid()::TEXT,
        120,
        3600
    );


    IF NOT public.internal_task_current_worker_is_direction() THEN
        RAISE EXCEPTION
            'Solo Dirección puede cambiar manualmente el estado de una tarea';
    END IF;


    IF p_status NOT IN (
        'to_do',
        'in_progress',
        'pending_review',
        'completed',
        'cancelled'
    ) THEN
        RAISE EXCEPTION
            'Estado no válido';
    END IF;


    IF p_progress IS NULL
       OR p_progress < 0
       OR p_progress > 100
    THEN
        RAISE EXCEPTION
            'El progreso debe estar entre 0 y 100';
    END IF;


    IF p_status = 'pending_review'
       AND p_progress <> 100
    THEN
        RAISE EXCEPTION
            'Una tarea pendiente de revisión debe estar al 100%%';
    END IF;


    IF p_status = 'completed'
       AND p_progress <> 100
    THEN
        RAISE EXCEPTION
            'Una tarea completada debe estar al 100%%';
    END IF;


    v_worker_id := public.internal_task_current_worker_id();


    SELECT *
    INTO v_task
    FROM public.internal_tasks
    WHERE id = p_task_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tarea no existe';
    END IF;


    v_old_status := v_task.status;
    v_old_progress := v_task.progress;


    UPDATE public.internal_tasks
    SET
        status = p_status,
        progress = p_progress,

        started_at = CASE
            WHEN p_status = 'in_progress'
            THEN COALESCE(started_at, CURRENT_TIMESTAMP)
            ELSE started_at
        END,

        submitted_for_review_at = CASE
            WHEN p_status = 'pending_review'
            THEN COALESCE(submitted_for_review_at, CURRENT_TIMESTAMP)
            WHEN p_status IN ('to_do', 'in_progress')
            THEN NULL
            ELSE submitted_for_review_at
        END,

        completed_at = CASE
            WHEN p_status = 'completed'
            THEN COALESCE(completed_at, CURRENT_TIMESTAMP)
            WHEN p_status <> 'completed'
            THEN NULL
            ELSE completed_at
        END,

        completed_by_worker_id = CASE
            WHEN p_status = 'completed'
            THEN v_worker_id
            WHEN p_status <> 'completed'
            THEN NULL
            ELSE completed_by_worker_id
        END,

        cancelled_at = CASE
            WHEN p_status = 'cancelled'
            THEN COALESCE(cancelled_at, CURRENT_TIMESTAMP)
            WHEN p_status <> 'cancelled'
            THEN NULL
            ELSE cancelled_at
        END,

        cancelled_by_worker_id = CASE
            WHEN p_status = 'cancelled'
            THEN v_worker_id
            WHEN p_status <> 'cancelled'
            THEN NULL
            ELSE cancelled_by_worker_id
        END,

        updated_at = CURRENT_TIMESTAMP

    WHERE id = p_task_id

    RETURNING *
    INTO v_task;


    PERFORM public.internal_task_record_update(
        p_task_id,
        v_worker_id,
        'direction_state_change',
        v_old_status,
        v_old_progress,
        v_task.status,
        v_task.progress,
        p_comment
    );


    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."direction_set_internal_task_state"("p_task_id" "uuid", "p_status" "text", "p_progress" integer, "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."direction_set_project_task_state"("p_task_id" "uuid", "p_status" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "public"."project_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.project_tasks;
    v_old_status TEXT;
    v_old_progress INTEGER;
    v_comment TEXT;
BEGIN

    IF public.current_project_task_worker_id() IS NULL THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.update'
    );

    IF NOT public.current_worker_is_direction() THEN
        RAISE EXCEPTION
            'Solo Dirección puede intervenir directamente sobre el estado';
    END IF;

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:direction_state:' || auth.uid()::TEXT,
        120,
        3600
    );

    IF p_status IS NULL THEN
        RAISE EXCEPTION
            'El estado es obligatorio';
    END IF;

    IF LOWER(BTRIM(p_status)) NOT IN (
        'to_do',
        'in_progress',
        'cancelled'
    ) THEN
        RAISE EXCEPTION
            'Estado no permitido para intervención de Dirección';
    END IF;

    v_comment := NULLIF(BTRIM(p_comment), '');

    IF v_comment IS NOT NULL
       AND LENGTH(v_comment) > 5000
    THEN
        RAISE EXCEPTION
            'El comentario no puede superar 5000 caracteres';
    END IF;

    SELECT *
    INTO v_task
    FROM public.project_tasks
    WHERE id = p_task_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Tarea no encontrada';
    END IF;

    v_old_status := v_task.status;
    v_old_progress := v_task.progress;

    UPDATE public.project_tasks
    SET
        status = LOWER(BTRIM(p_status)),
        cancelled_at = CASE
            WHEN LOWER(BTRIM(p_status)) = 'cancelled'
                THEN CURRENT_TIMESTAMP
            ELSE NULL
        END,
        cancelled_by_worker_id = CASE
            WHEN LOWER(BTRIM(p_status)) = 'cancelled'
                THEN public.current_project_task_worker_id()
            ELSE NULL
        END
    WHERE id = v_task.id
    RETURNING *
    INTO v_task;

    PERFORM public.record_project_task_update(
        v_task.id,
        CASE
            WHEN v_task.status = 'cancelled'
                THEN 'cancelled'
            ELSE 'direction_state_change'
        END,
        v_old_status,
        v_old_progress,
        v_task.status,
        v_task.progress,
        v_comment
    );

    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."direction_set_project_task_state"("p_task_id" "uuid", "p_status" "text", "p_comment" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."quotation_workflow_drafts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "project_id" "uuid" NOT NULL,
    "quotation_id" "uuid",
    "created_by" "uuid" NOT NULL,
    "draft_kind" "text" NOT NULL,
    "draft_status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "content" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "based_on_version_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "published_at" timestamp with time zone,
    "published_version_id" "uuid",
    CONSTRAINT "quotation_workflow_drafts_content_check" CHECK (("jsonb_typeof"("content") = 'object'::"text")),
    CONSTRAINT "quotation_workflow_drafts_content_size_check" CHECK (("pg_column_size"("content") <= 262144)),
    CONSTRAINT "quotation_workflow_drafts_draft_kind_check" CHECK (("draft_kind" = ANY (ARRAY['initial'::"text", 'correction'::"text", 'requested_change'::"text"]))),
    CONSTRAINT "quotation_workflow_drafts_draft_status_check" CHECK (("draft_status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'discarded'::"text"])))
);


ALTER TABLE "public"."quotation_workflow_drafts" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discard_quotation_workflow_draft"("p_draft_id" "uuid") RETURNS "public"."quotation_workflow_drafts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_draft public.quotation_workflow_drafts%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.current_user_is_worker() THEN
    RAISE EXCEPTION 'Acceso denegado: se requiere un trabajador autenticado';
  END IF;

  SELECT * INTO v_draft
  FROM public.quotation_workflow_drafts
  WHERE id = p_draft_id
  FOR UPDATE;
  IF NOT FOUND OR v_draft.draft_status <> 'draft' THEN
    RAISE EXCEPTION 'El borrador no existe o ya no se puede descartar';
  END IF;

  IF v_draft.quotation_id IS NULL THEN
    PERFORM public.require_current_worker_permission('quotations.create');
  ELSE
    PERFORM public.require_current_worker_permission('quotations.update');
  END IF;

  PERFORM public.enforce_security_rate_limit(
    'quotation_draft:discard:' || auth.uid()::text, 20, 3600
  );

  UPDATE public.quotation_workflow_drafts
  SET draft_status = 'discarded', updated_at = now()
  WHERE id = p_draft_id
  RETURNING * INTO v_draft;

  RETURN v_draft;
END;
$$;


ALTER FUNCTION "public"."discard_quotation_workflow_draft"("p_draft_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."emit_maintenance_custom_proposal_notification"("p_proposal_id" "uuid", "p_titulo" "text", "p_mensaje" "text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."notifications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$

DECLARE
    v_proposal public.maintenance_custom_proposals;
    v_notification public.notifications;

BEGIN

    SELECT *
    INTO v_proposal
    FROM public.maintenance_custom_proposals
    WHERE id = p_proposal_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La propuesta personalizada no existe';
    END IF;

    IF v_proposal.user_id IS NULL THEN
        RAISE EXCEPTION
            'La propuesta no tiene usuario cliente';
    END IF;

    IF p_titulo IS NULL
       OR LENGTH(BTRIM(p_titulo)) = 0
       OR LENGTH(p_titulo) > 200
    THEN
        RAISE EXCEPTION
            'El título de la notificación no es válido';
    END IF;

    IF p_mensaje IS NULL
       OR LENGTH(BTRIM(p_mensaje)) = 0
       OR LENGTH(p_mensaje) > 2000
    THEN
        RAISE EXCEPTION
            'El mensaje de la notificación no es válido';
    END IF;

    IF p_metadata IS NOT NULL
       AND pg_column_size(p_metadata) > 8192
    THEN
        RAISE EXCEPTION
            'La metadata de la notificación supera 8 KiB';
    END IF;

    INSERT INTO public.notifications (
        user_id,
        project_id,
        tipo,
        titulo,
        mensaje,
        metadata
    )
    VALUES (
        v_proposal.user_id,
        NULL,
        'maintenance_proposal',
        BTRIM(p_titulo),
        BTRIM(p_mensaje),
        p_metadata
    )
    RETURNING *
    INTO v_notification;

    RETURN v_notification;

END;
$$;


ALTER FUNCTION "public"."emit_maintenance_custom_proposal_notification"("p_proposal_id" "uuid", "p_titulo" "text", "p_mensaje" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."emit_project_client_notification"("p_project_id" "uuid", "p_tipo" "text", "p_titulo" "text", "p_mensaje" "text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."notifications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

    v_client_user_id UUID;

    v_notification public.notifications;

BEGIN

    -- --------------------------------------------------------
    -- VALIDAR PROYECTO
    -- --------------------------------------------------------

    IF p_project_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto es obligatorio';
    END IF;


    SELECT p.user_id
    INTO v_client_user_id
    FROM public.projects p
    WHERE p.id = p_project_id;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El proyecto indicado no existe';
    END IF;


    -- --------------------------------------------------------
    -- VALIDAR USUARIO DEL PROYECTO
    -- --------------------------------------------------------

    IF v_client_user_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto no tiene un usuario cliente asociado';
    END IF;


    -- --------------------------------------------------------
    -- VALIDAR TIPO
    -- --------------------------------------------------------

    IF p_tipo IS NULL
       OR p_tipo NOT IN (
            'milestone_completed',
            'information_requested',
            'project_update',
            'document_available',
            'quotation',
            'invoice',
            'project_change_request',
            'system'
       )
    THEN
        RAISE EXCEPTION
            'Tipo de notificación no válido';
    END IF;


    -- --------------------------------------------------------
    -- VALIDAR TÍTULO
    -- --------------------------------------------------------

    IF p_titulo IS NULL
       OR LENGTH(BTRIM(p_titulo)) = 0
       OR LENGTH(p_titulo) > 200
    THEN
        RAISE EXCEPTION
            'El título de la notificación no es válido';
    END IF;


    -- --------------------------------------------------------
    -- VALIDAR MENSAJE
    -- --------------------------------------------------------

    IF p_mensaje IS NULL
       OR LENGTH(BTRIM(p_mensaje)) = 0
       OR LENGTH(p_mensaje) > 2000
    THEN
        RAISE EXCEPTION
            'El mensaje de la notificación no es válido';
    END IF;


    -- --------------------------------------------------------
    -- INSERTAR
    -- --------------------------------------------------------

    INSERT INTO public.notifications (
        user_id,
        project_id,
        tipo,
        titulo,
        mensaje,
        metadata
    )
    VALUES (
        v_client_user_id,
        p_project_id,
        p_tipo,
        BTRIM(p_titulo),
        BTRIM(p_mensaje),
        p_metadata
    )
    RETURNING *
    INTO v_notification;


    RETURN v_notification;

END;
$$;


ALTER FUNCTION "public"."emit_project_client_notification"("p_project_id" "uuid", "p_tipo" "text", "p_titulo" "text", "p_mensaje" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_custom_maintenance_proposal_creation_rate_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_limit INTEGER;
    v_count INTEGER;
BEGIN

    SELECT max_creations_24h
    INTO v_limit
    FROM public.maintenance_custom_proposal_security_limits();

    SELECT COUNT(*)
    INTO v_count
    FROM public.maintenance_custom_proposals
    WHERE company_id = NEW.company_id
      AND created_at >= CURRENT_TIMESTAMP - INTERVAL '24 hours';

    IF v_count >= v_limit THEN
        RAISE EXCEPTION
            'Se ha alcanzado el límite de % propuestas creadas en 24 horas para esta empresa. Inténtalo de nuevo más tarde.',
            v_limit;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_custom_maintenance_proposal_creation_rate_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_custom_maintenance_proposal_submission_rate_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_limit INTEGER;
    v_count INTEGER;
BEGIN

    IF NEW.status = 'submitted'
       AND OLD.status IS DISTINCT FROM 'submitted'
    THEN

        SELECT max_submissions_24h
        INTO v_limit
        FROM public.maintenance_custom_proposal_security_limits();

        SELECT COUNT(*)
        INTO v_count
        FROM public.maintenance_custom_proposals
        WHERE company_id = NEW.company_id
          AND submitted_at IS NOT NULL
          AND submitted_at >= CURRENT_TIMESTAMP - INTERVAL '24 hours';

        IF v_count >= v_limit THEN
            RAISE EXCEPTION
                'Se ha alcanzado el límite de % propuestas enviadas en 24 horas para esta empresa. Inténtalo de nuevo más tarde.',
                v_limit;
        END IF;

    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_custom_maintenance_proposal_submission_rate_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_security_rate_limit"("p_rate_key" "text", "p_limit" integer, "p_window_seconds" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    v_now TIMESTAMPTZ := clock_timestamp();
    v_window_start TIMESTAMPTZ;
    v_request_count INTEGER;
BEGIN

    IF p_rate_key IS NULL
       OR length(p_rate_key) = 0
       OR length(p_rate_key) > 300
    THEN
        RAISE EXCEPTION 'Invalid rate limit key';
    END IF;


    IF p_limit IS NULL
       OR p_limit < 1
       OR p_limit > 1000
    THEN
        RAISE EXCEPTION 'Invalid rate limit';
    END IF;


    IF p_window_seconds IS NULL
       OR p_window_seconds < 1
       OR p_window_seconds > 86400
    THEN
        RAISE EXCEPTION 'Invalid rate limit window';
    END IF;


    PERFORM pg_advisory_xact_lock(
        hashtextextended(p_rate_key, 0)
    );


    SELECT
        window_started_at,
        request_count
    INTO
        v_window_start,
        v_request_count
    FROM public.security_rate_limits
    WHERE rate_key = p_rate_key
    FOR UPDATE;


    IF NOT FOUND THEN

        INSERT INTO public.security_rate_limits (
            rate_key,
            window_started_at,
            request_count,
            updated_at
        )
        VALUES (
            p_rate_key,
            v_now,
            1,
            v_now
        );

        RETURN;
    END IF;


    IF v_now >=
       v_window_start
       + make_interval(secs => p_window_seconds)
    THEN

        UPDATE public.security_rate_limits
        SET
            window_started_at = v_now,
            request_count = 1,
            updated_at = v_now
        WHERE rate_key = p_rate_key;

        RETURN;
    END IF;


    IF v_request_count >= p_limit THEN

        RAISE EXCEPTION 'Rate limit exceeded'
            USING ERRCODE = 'P0001';

    END IF;


    UPDATE public.security_rate_limits
    SET
        request_count = request_count + 1,
        updated_at = v_now
    WHERE rate_key = p_rate_key;

END;
$$;


ALTER FUNCTION "public"."enforce_security_rate_limit"("p_rate_key" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_worker_write_rate_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_operation_key TEXT;
    v_limit INTEGER;
    v_allowed BOOLEAN;
BEGIN

    IF auth.uid() IS NULL
       OR NOT public.current_user_is_worker()
    THEN
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        ELSE
            RETURN NEW;
        END IF;
    END IF;


    -- --------------------------------------------------------
    -- SOLO operaciones con escritura de worker confirmada
    -- en el esquema actual.
    --
    -- Límite = operaciones por 10 minutos por worker.
    -- --------------------------------------------------------

    CASE TG_TABLE_NAME

        WHEN 'project_milestones' THEN
            v_operation_key := 'project_milestones.write';
            v_limit := 60;

        WHEN 'project_updates' THEN
            v_operation_key := 'project_updates.write';
            v_limit := 40;

        WHEN 'invoices' THEN
            v_operation_key := 'invoices.write';
            v_limit := 40;

        WHEN 'project_documents' THEN
            v_operation_key := 'project_documents.write';
            v_limit := 30;

        WHEN 'support_tickets' THEN
            v_operation_key := 'support_tickets.write';
            v_limit := 60;

        WHEN 'automation_runs' THEN
            v_operation_key := 'automation_runs.write';
            v_limit := 40;

        WHEN 'quotations' THEN
            v_operation_key := 'quotations.write';
            v_limit := 60;

        WHEN 'maintenance_contracts' THEN
            v_operation_key := 'maintenance_contracts.write';
            v_limit := 30;

        ELSE
            -- No imponer límites a tablas no verificadas.
            IF TG_OP = 'DELETE' THEN
                RETURN OLD;
            ELSE
                RETURN NEW;
            END IF;
    END CASE;


    v_allowed :=
        public.consume_worker_write_rate_limit(
            v_operation_key,
            v_limit,
            600
        );

    IF NOT v_allowed THEN
        RAISE EXCEPTION
            'Demasiadas operaciones. Inténtalo de nuevo más tarde.';
    END IF;


    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;


ALTER FUNCTION "public"."enforce_worker_write_rate_limit"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_worker_write_rate_limit"() IS 'Trigger interno de rate limiting para escrituras de workers. No limita SELECT ni operaciones de clientes.';



CREATE OR REPLACE FUNCTION "public"."expense_requires_approval"("p_amount" numeric, "p_category_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_requires boolean;
BEGIN
  SELECT r.requires_approval AND COALESCE(p_amount, 0) >= r.minimum_amount
    INTO v_requires
  FROM public.expense_approval_rules r
  WHERE r.is_active
    AND (r.category_id = p_category_id OR r.category_id IS NULL)
  ORDER BY (r.category_id IS NOT NULL) DESC
  LIMIT 1;

  RETURN COALESCE(v_requires, false);
END;
$$;


ALTER FUNCTION "public"."expense_requires_approval"("p_amount" numeric, "p_category_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_ai_quota"("p_reservation_id" "uuid", "p_actual_input_tokens" integer, "p_actual_output_tokens" integer, "p_actual_cost_cents" numeric, "p_success" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$

DECLARE

    r public.ai_usage_reservations;

    c public.ai_quota_config;

    v_now TIMESTAMPTZ := clock_timestamp();

BEGIN

    -- ========================================================
    -- VALIDACIÓN
    -- ========================================================

    IF p_actual_input_tokens < 0
       OR p_actual_output_tokens < 0
       OR p_actual_cost_cents < 0
    THEN

        RAISE EXCEPTION
            'Invalid AI usage';

    END IF;


    -- ========================================================
    -- CONFIGURACIÓN
    -- ========================================================

    SELECT *
    INTO c

    FROM public.ai_quota_config

    WHERE config_key = 'modira-ai';


    -- ========================================================
    -- RESERVA
    -- ========================================================

    SELECT *
    INTO r

    FROM public.ai_usage_reservations

    WHERE id = p_reservation_id

    FOR UPDATE;


    IF NOT FOUND
       OR r.status <> 'reserved'
    THEN

        RETURN FALSE;

    END IF;


    -- ========================================================
    -- RESERVA EXPIRADA
    -- ========================================================
    --
    -- La Edge Function no puede consumir una reserva cuyo TTL
    -- ya haya terminado.
    --

    IF r.expires_at <= v_now
    THEN

        /*
         * Utilizar los mismos locks que las funciones de
         * reserva/cleanup.
         */

        IF r.scope_key LIKE 'anon-ip:%'
        THEN

            PERFORM pg_advisory_xact_lock(
                hashtextextended(
                    r.scope_key,
                    19020
                )
            );


            UPDATE public.ai_anonymous_quota_periods

            SET

                reserved_requests =
                    GREATEST(
                        0,
                        reserved_requests - 1
                    ),

                reserved_input_tokens =
                    GREATEST(
                        0,
                        reserved_input_tokens
                        - r.estimated_input_tokens
                    ),

                reserved_output_tokens =
                    GREATEST(
                        0,
                        reserved_output_tokens
                        - r.estimated_output_tokens
                    ),

                reserved_cost_cents =
                    GREATEST(
                        0,
                        reserved_cost_cents
                        - r.estimated_cost_cents
                    ),

                updated_at = v_now

            WHERE identity_key = r.scope_key

              AND period_started_at <= r.expires_at

              AND period_ends_at > r.expires_at;


        ELSE

            PERFORM pg_advisory_xact_lock(
                hashtextextended(
                    r.scope_key,
                    19019
                )
            );


            UPDATE public.ai_usage_periods

            SET

                reserved_requests =
                    GREATEST(
                        0,
                        reserved_requests - 1
                    ),

                reserved_input_tokens =
                    GREATEST(
                        0,
                        reserved_input_tokens
                        - r.estimated_input_tokens
                    ),

                reserved_output_tokens =
                    GREATEST(
                        0,
                        reserved_output_tokens
                        - r.estimated_output_tokens
                    ),

                reserved_cost_cents =
                    GREATEST(
                        0,
                        reserved_cost_cents
                        - r.estimated_cost_cents
                    ),

                updated_at = v_now

            WHERE scope_key = r.scope_key

              AND period_started_at <= r.expires_at

              AND period_ends_at > r.expires_at;


            IF r.company_id IS NOT NULL
            THEN

                PERFORM pg_advisory_xact_lock(
                    hashtextextended(
                        'company:' || r.company_id::TEXT,
                        19019
                    )
                );


                UPDATE public.ai_usage_periods

                SET

                    reserved_requests =
                        GREATEST(
                            0,
                            reserved_requests - 1
                        ),

                    reserved_input_tokens =
                        GREATEST(
                            0,
                            reserved_input_tokens
                            - r.estimated_input_tokens
                        ),

                    reserved_output_tokens =
                        GREATEST(
                            0,
                            reserved_output_tokens
                            - r.estimated_output_tokens
                        ),

                    reserved_cost_cents =
                        GREATEST(
                            0,
                            reserved_cost_cents
                            - r.estimated_cost_cents
                        ),

                    updated_at = v_now

                WHERE scope_key =
                    'company:' || r.company_id::TEXT

                  AND period_started_at <= r.expires_at

                  AND period_ends_at > r.expires_at;

            END IF;

        END IF;


        UPDATE public.ai_usage_reservations

        SET

            status = 'expired',

            finalized_at = v_now

        WHERE id = r.id

          AND status = 'reserved';


        RETURN FALSE;

    END IF;


    -- ========================================================
    -- CUOTA ANÓNIMA
    -- ========================================================

    IF r.scope_key LIKE 'anon-ip:%'
    THEN

        PERFORM pg_advisory_xact_lock(
            hashtextextended(
                r.scope_key,
                19020
            )
        );


        UPDATE public.ai_anonymous_quota_periods

        SET

            reserved_requests =
                GREATEST(
                    0,
                    reserved_requests - 1
                ),

            reserved_input_tokens =
                GREATEST(
                    0,
                    reserved_input_tokens
                    - r.estimated_input_tokens
                ),

            reserved_output_tokens =
                GREATEST(
                    0,
                    reserved_output_tokens
                    - r.estimated_output_tokens
                ),

            reserved_cost_cents =
                GREATEST(
                    0,
                    reserved_cost_cents
                    - r.estimated_cost_cents
                ),

            request_count =
                request_count
                + CASE
                    WHEN p_success THEN 1
                    ELSE 0
                  END,

            input_tokens =
                input_tokens
                + CASE
                    WHEN p_success
                    THEN p_actual_input_tokens
                    ELSE 0
                  END,

            output_tokens =
                output_tokens
                + CASE
                    WHEN p_success
                    THEN p_actual_output_tokens
                    ELSE 0
                  END,

            cost_cents =
                cost_cents
                + CASE
                    WHEN p_success
                    THEN p_actual_cost_cents
                    ELSE 0
                  END,

            updated_at = v_now

        WHERE identity_key = r.scope_key;


    ELSE

        -- ====================================================
        -- CUOTA AUTENTICADA
        -- ====================================================

        PERFORM pg_advisory_xact_lock(
            hashtextextended(
                r.scope_key,
                19019
            )
        );


        UPDATE public.ai_usage_periods

        SET

            reserved_requests =
                GREATEST(
                    0,
                    reserved_requests - 1
                ),

            reserved_input_tokens =
                GREATEST(
                    0,
                    reserved_input_tokens
                    - r.estimated_input_tokens
                ),

            reserved_output_tokens =
                GREATEST(
                    0,
                    reserved_output_tokens
                    - r.estimated_output_tokens
                ),

            reserved_cost_cents =
                GREATEST(
                    0,
                    reserved_cost_cents
                    - r.estimated_cost_cents
                ),

            request_count =
                request_count
                + CASE
                    WHEN p_success THEN 1
                    ELSE 0
                  END,

            input_tokens =
                input_tokens
                + CASE
                    WHEN p_success
                    THEN p_actual_input_tokens
                    ELSE 0
                  END,

            output_tokens =
                output_tokens
                + CASE
                    WHEN p_success
                    THEN p_actual_output_tokens
                    ELSE 0
                  END,

            cost_cents =
                cost_cents
                + CASE
                    WHEN p_success
                    THEN p_actual_cost_cents
                    ELSE 0
                  END,

            updated_at = v_now

        WHERE scope_key = r.scope_key;


        -- ====================================================
        -- CUOTA EMPRESA
        -- ====================================================

        IF r.company_id IS NOT NULL
        THEN

            PERFORM pg_advisory_xact_lock(
                hashtextextended(
                    'company:' || r.company_id::TEXT,
                    19019
                )
            );


            UPDATE public.ai_usage_periods

            SET

                reserved_requests =
                    GREATEST(
                        0,
                        reserved_requests - 1
                    ),

                reserved_input_tokens =
                    GREATEST(
                        0,
                        reserved_input_tokens
                        - r.estimated_input_tokens
                    ),

                reserved_output_tokens =
                    GREATEST(
                        0,
                        reserved_output_tokens
                        - r.estimated_output_tokens
                    ),

                reserved_cost_cents =
                    GREATEST(
                        0,
                        reserved_cost_cents
                        - r.estimated_cost_cents
                    ),

                request_count =
                    request_count
                    + CASE
                        WHEN p_success THEN 1
                        ELSE 0
                      END,

                input_tokens =
                    input_tokens
                    + CASE
                        WHEN p_success
                        THEN p_actual_input_tokens
                        ELSE 0
                      END,

                output_tokens =
                    output_tokens
                    + CASE
                        WHEN p_success
                        THEN p_actual_output_tokens
                        ELSE 0
                      END,

                cost_cents =
                    cost_cents
                    + CASE
                        WHEN p_success
                        THEN p_actual_cost_cents
                        ELSE 0
                      END,

                updated_at = v_now

            WHERE scope_key =
                'company:' || r.company_id::TEXT;

        END IF;

    END IF;


    -- ========================================================
    -- ESTADO FINAL
    -- ========================================================

    UPDATE public.ai_usage_reservations

    SET

        status =
            CASE
                WHEN p_success
                THEN 'consumed'
                ELSE 'released'
            END,

        actual_input_tokens =
            p_actual_input_tokens,

        actual_output_tokens =
            p_actual_output_tokens,

        actual_cost_cents =
            p_actual_cost_cents,

        finalized_at = v_now

    WHERE id = p_reservation_id

      AND status = 'reserved';


    RETURN TRUE;

END;

$$;


ALTER FUNCTION "public"."finalize_ai_quota"("p_reservation_id" "uuid", "p_actual_input_tokens" integer, "p_actual_output_tokens" integer, "p_actual_cost_cents" numeric, "p_success" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_invoice_backend_document"("p_invoice_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") RETURNS "public"."invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$

DECLARE
    v_invoice public.invoices;
    v_hash TEXT;
    v_expected_path TEXT;

BEGIN

    -- ========================================================
    -- 1. VALIDAR IDENTIFICADOR
    -- ========================================================

    IF p_invoice_id IS NULL THEN
        RAISE EXCEPTION
            'La factura es obligatoria';
    END IF;


    -- ========================================================
    -- 2. VALIDAR RUTA
    -- ========================================================

    IF p_document_path IS NULL
       OR TRIM(p_document_path) = ''
    THEN

        RAISE EXCEPTION
            'La ruta del documento es obligatoria';

    END IF;


    -- ========================================================
    -- 3. OBTENER FACTURA
    -- ========================================================

    SELECT *
    INTO v_invoice
    FROM public.invoices
    WHERE id = p_invoice_id
    FOR UPDATE;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'La factura no existe';

    END IF;


    -- ========================================================
    -- 4. RUTA OFICIAL ESPERADA
    -- ========================================================
    --
    -- Se mantiene la convención que ya utiliza 057:
    --
    --     numero_factura.pdf
    --
    -- Esto mantiene compatibilidad con el Storage actual y
    -- con invoice_document_storage_is_locked().
    --
    -- ========================================================

    v_expected_path :=
        v_invoice.numero_factura
        || '.pdf';


    IF TRIM(p_document_path) <> v_expected_path THEN

        RAISE EXCEPTION
            'La ruta del documento no coincide con la factura';

    END IF;


    -- ========================================================
    -- 5. VALIDAR EXTENSIÓN
    -- ========================================================

    IF LOWER(TRIM(p_document_path)) NOT LIKE '%.pdf' THEN

        RAISE EXCEPTION
            'El documento debe ser un PDF';

    END IF;


    -- ========================================================
    -- 6. COMPROBAR EXISTENCIA REAL EN STORAGE
    -- ========================================================
    --
    -- La Edge Function debe haber generado previamente el
    -- archivo en el bucket privado "invoices".
    --
    -- ========================================================

    IF NOT EXISTS (
        SELECT 1
        FROM storage.objects
        WHERE bucket_id = 'invoices'
          AND name = TRIM(p_document_path)
    ) THEN

        RAISE EXCEPTION
            'El PDF no existe en el bucket de facturas';

    END IF;


    -- ========================================================
    -- 7. VALIDAR SHA-256
    -- ========================================================

    v_hash := LOWER(
        TRIM(
            COALESCE(
                p_document_sha256,
                ''
            )
        )
    );


    IF v_hash = '' THEN

        RAISE EXCEPTION
            'El SHA-256 del documento es obligatorio';

    END IF;


    IF v_hash !~ '^[0-9a-f]{64}$' THEN

        RAISE EXCEPTION
            'El SHA-256 del documento no es válido';

    END IF;


    -- ========================================================
    -- 8. NO PERMITIR CAMBIAR DOCUMENTO DESPUÉS DE ACEPTACIÓN
    -- ========================================================

    IF EXISTS (
        SELECT 1
        FROM public.invoice_document_acknowledgements a
        WHERE a.invoice_id = v_invoice.id
    ) THEN

        RAISE EXCEPTION
            'El documento de esta factura ya ha sido aceptado y no puede modificarse';

    END IF;


    -- ========================================================
    -- 9. IDEMPOTENCIA
    -- ========================================================
    --
    -- Si la Edge Function reintenta exactamente el mismo
    -- documento + hash, devolvemos la factura sin modificarla.
    --
    -- Esto es importante para evitar duplicaciones en reintentos.
    --
    -- ========================================================

    IF v_invoice.document_path = TRIM(p_document_path)
       AND LOWER(
            COALESCE(v_invoice.document_sha256, '')
           ) = v_hash
    THEN

        RETURN v_invoice;

    END IF;


    -- ========================================================
    -- 10. NO SOBRESCRIBIR UN DOCUMENTO DIFERENTE
    -- ========================================================
    --
    -- Si ya existe otro PDF/hash asociado y no coincide con el
    -- nuevo documento, se rechaza.
    --
    -- La generación automática deberá ser idempotente.
    --
    -- ========================================================

    IF v_invoice.document_path IS NOT NULL
       AND TRIM(v_invoice.document_path) <> ''
       AND v_invoice.document_path IS DISTINCT FROM
           TRIM(p_document_path)
    THEN

        RAISE EXCEPTION
            'La factura ya tiene asociado otro documento';

    END IF;


    IF v_invoice.document_sha256 IS NOT NULL
       AND LOWER(TRIM(v_invoice.document_sha256)) IS DISTINCT FROM
           v_hash
    THEN

        RAISE EXCEPTION
            'La factura ya tiene asociado otro SHA-256';

    END IF;


    -- ========================================================
    -- 11. GUARDAR DOCUMENTO + HASH
    -- ========================================================

    UPDATE public.invoices
    SET
        document_path = TRIM(p_document_path),
        document_sha256 = v_hash,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = v_invoice.id
    RETURNING *
    INTO v_invoice;


    IF v_invoice.id IS NULL THEN

        RAISE EXCEPTION
            'No se ha podido finalizar el documento de la factura';

    END IF;


    RETURN v_invoice;

END;
$_$;


ALTER FUNCTION "public"."finalize_invoice_backend_document"("p_invoice_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_invoice_backend_document"("p_invoice_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") IS 'Registra de forma idempotente el PDF oficial generado server-side para una factura y su SHA-256. Exclusivo para service_role.';



CREATE OR REPLACE FUNCTION "public"."finalize_maintenance_invoice_backend_document"("p_invoice_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") RETURNS "public"."maintenance_invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$

DECLARE
    v_invoice public.maintenance_invoices;
    v_path TEXT;
    v_hash TEXT;

    v_object_exists BOOLEAN;
    v_object_mime TEXT;
    v_object_size BIGINT;

    v_expected_prefix TEXT;

BEGIN

    -- ========================================================
    -- 1. VALIDAR INVOICE ID
    -- ========================================================

    IF p_invoice_id IS NULL THEN
        RAISE EXCEPTION
            'La factura de mantenimiento es obligatoria';
    END IF;


    -- ========================================================
    -- 2. NORMALIZAR RUTA
    -- ========================================================

    v_path := BTRIM(COALESCE(p_document_path, ''));

    IF v_path = '' THEN
        RAISE EXCEPTION
            'La ruta del documento es obligatoria';
    END IF;


    -- ========================================================
    -- 3. NORMALIZAR SHA-256
    -- ========================================================

    v_hash := LOWER(
        BTRIM(
            COALESCE(p_document_sha256, '')
        )
    );

    IF v_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION
            'La huella digital del documento no es un SHA-256 válido';
    END IF;


    -- ========================================================
    -- 4. OBTENER Y BLOQUEAR FACTURA
    -- ========================================================

    SELECT *
    INTO v_invoice
    FROM public.maintenance_invoices
    WHERE id = p_invoice_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La factura de mantenimiento no existe';
    END IF;


    -- ========================================================
    -- 5. VALIDAR RUTA
    -- ========================================================
    --
    -- Todas las facturas automáticas utilizan:
    --
    --   <invoice_uuid>/<archivo>.pdf
    --
    -- Esto evita que el backend pueda asociar accidentalmente
    -- un documento perteneciente a otra factura.
    -- ========================================================

    v_expected_prefix := v_invoice.id::TEXT || '/';

    IF LEFT(v_path, LENGTH(v_expected_prefix))
       <> v_expected_prefix
    THEN
        RAISE EXCEPTION
            'La ruta del documento no pertenece a la factura';
    END IF;


    IF v_path = v_expected_prefix THEN
        RAISE EXCEPTION
            'La ruta del documento no contiene un nombre de archivo válido';
    END IF;


    IF v_path LIKE '%..%' THEN
        RAISE EXCEPTION
            'La ruta del documento contiene una secuencia no permitida';
    END IF;


    IF LEFT(v_path, 1) = '/' THEN
        RAISE EXCEPTION
            'La ruta del documento no puede comenzar por /';
    END IF;


    IF RIGHT(LOWER(v_path), 4) <> '.pdf' THEN
        RAISE EXCEPTION
            'El documento de una factura de mantenimiento debe ser un PDF';
    END IF;


    -- No permitimos subcarpetas adicionales.
    IF ARRAY_LENGTH(string_to_array(v_path, '/'), 1) <> 2 THEN
        RAISE EXCEPTION
            'La ruta del documento de la factura no es válida';
    END IF;


    -- ========================================================
    -- 6. DOCUMENTO YA ASOCIADO
    -- ========================================================
    --
    -- Una factura emitida no puede cambiar de documento.
    --
    -- Si el mismo proceso vuelve a ejecutarse con exactamente
    -- el mismo documento y hash, devolvemos la factura.
    --
    -- Esto hace que el proceso sea idempotente.
    -- ========================================================

    IF v_invoice.document_path IS NOT NULL THEN

        IF v_invoice.document_path <> v_path THEN
            RAISE EXCEPTION
                'La factura ya tiene un documento asociado diferente; no se permite sustituirlo';
        END IF;


        IF v_invoice.document_sha256 IS NOT NULL
           AND LOWER(v_invoice.document_sha256) <> v_hash
        THEN
            RAISE EXCEPTION
                'La factura ya tiene una huella SHA-256 diferente; no se permite sustituirla';
        END IF;

    END IF;


    -- ========================================================
    -- 7. COMPROBAR OBJETO FÍSICO EN STORAGE
    -- ========================================================

    SELECT
        TRUE,
        COALESCE(
            NULLIF(o.metadata ->> 'mimetype', ''),
            NULLIF(o.metadata ->> 'mimeType', '')
        ),
        CASE
            WHEN COALESCE(o.metadata ->> 'size', '') ~ '^[0-9]+$'
            THEN (o.metadata ->> 'size')::BIGINT
            ELSE NULL
        END
    INTO
        v_object_exists,
        v_object_mime,
        v_object_size
    FROM storage.objects o
    WHERE o.bucket_id = 'maintenance-invoices'
      AND o.name = v_path
    LIMIT 1;


    IF NOT COALESCE(v_object_exists, FALSE) THEN
        RAISE EXCEPTION
            'El documento no existe físicamente en el bucket maintenance-invoices';
    END IF;


    -- ========================================================
    -- 8. VALIDAR MIME
    -- ========================================================

    IF v_object_mime IS NOT NULL
       AND LOWER(BTRIM(v_object_mime)) <> 'application/pdf'
    THEN
        RAISE EXCEPTION
            'El documento almacenado no es un PDF válido';
    END IF;


    -- ========================================================
    -- 9. VALIDAR TAMAÑO
    -- ========================================================
    --
    -- Máximo 20 MiB.
    -- ========================================================

    IF v_object_size IS NOT NULL THEN

        IF v_object_size <= 0 THEN
            RAISE EXCEPTION
                'El PDF de la factura está vacío';
        END IF;


        IF v_object_size > 20 * 1024 * 1024 THEN
            RAISE EXCEPTION
                'El PDF de la factura supera el límite de 20 MiB';
        END IF;

    END IF;


    -- ========================================================
    -- 10. ASOCIAR DOCUMENTO + HASH
    -- ========================================================

    UPDATE public.maintenance_invoices
    SET
        document_path = v_path,
        document_mime_type = 'application/pdf',
        document_file_size = v_object_size,
        document_sha256 = v_hash,
        document_uploaded_at = COALESCE(
            document_uploaded_at,
            CURRENT_TIMESTAMP
        ),
        document_uploaded_by = NULL,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = v_invoice.id
    RETURNING *
    INTO v_invoice;


    -- ========================================================
    -- 11. DEVOLVER FACTURA ACTUALIZADA
    -- ========================================================

    RETURN v_invoice;

END;
$_$;


ALTER FUNCTION "public"."finalize_maintenance_invoice_backend_document"("p_invoice_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_maintenance_invoice_backend_document"("p_invoice_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") IS 'Asocia de forma segura el PDF de Modira y su SHA-256 a una maintenance_invoice desde el backend service_role. Valida pertenencia de la ruta, existencia física en Storage, PDF, tamaño e idempotencia. No modifica el estado de la factura ni sustituye las RPC existentes de workers.';



CREATE OR REPLACE FUNCTION "public"."finalize_quotation_backend_document"("p_quotation_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") RETURNS "public"."quotations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_quotation public.quotations;
    v_hash TEXT;
    v_expected_path TEXT;
BEGIN

    IF p_quotation_id IS NULL THEN
        RAISE EXCEPTION 'El presupuesto es obligatorio';
    END IF;

    IF p_document_path IS NULL OR TRIM(p_document_path) = '' THEN
        RAISE EXCEPTION 'La ruta del documento es obligatoria';
    END IF;

    SELECT *
    INTO v_quotation
    FROM public.quotations
    WHERE id = p_quotation_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El presupuesto no existe';
    END IF;

    v_expected_path :=
        v_quotation.company_id::TEXT
        || '/'
        || v_quotation.numero_presupuesto
        || '.pdf';

    IF TRIM(p_document_path) <> v_expected_path THEN
        RAISE EXCEPTION 'La ruta del documento no coincide con el presupuesto';
    END IF;

    IF LOWER(TRIM(p_document_path)) NOT LIKE '%.pdf' THEN
        RAISE EXCEPTION 'El documento debe ser un PDF';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM storage.objects
        WHERE bucket_id = 'quotations'
          AND name = TRIM(p_document_path)
    ) THEN
        RAISE EXCEPTION 'El PDF no existe en el bucket de presupuestos';
    END IF;

    v_hash := LOWER(TRIM(COALESCE(p_document_sha256, '')));

    IF v_hash = '' THEN
        RAISE EXCEPTION 'El SHA-256 del documento es obligatorio';
    END IF;

    IF v_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'El SHA-256 del documento no es válido';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.quotation_document_acknowledgements a
        WHERE a.quotation_id = v_quotation.id
    ) THEN
        RAISE EXCEPTION
            'El documento de este presupuesto ya ha sido aceptado y no puede modificarse';
    END IF;

    IF v_quotation.document_path = TRIM(p_document_path)
       AND LOWER(COALESCE(v_quotation.document_sha256, '')) = v_hash
    THEN
        RETURN v_quotation;
    END IF;

    IF v_quotation.document_path IS NOT NULL
       AND TRIM(v_quotation.document_path) <> ''
       AND v_quotation.document_path IS DISTINCT FROM TRIM(p_document_path)
    THEN
        RAISE EXCEPTION 'El presupuesto ya tiene asociado otro documento';
    END IF;

    IF v_quotation.document_sha256 IS NOT NULL
       AND LOWER(TRIM(v_quotation.document_sha256)) IS DISTINCT FROM v_hash
    THEN
        RAISE EXCEPTION 'El presupuesto ya tiene asociado otro SHA-256';
    END IF;

    UPDATE public.quotations
    SET
        document_path = TRIM(p_document_path),
        document_sha256 = v_hash,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = v_quotation.id
    RETURNING *
    INTO v_quotation;

    IF v_quotation.id IS NULL THEN
        RAISE EXCEPTION 'No se ha podido finalizar el documento del presupuesto';
    END IF;

    RETURN v_quotation;
END;
$_$;


ALTER FUNCTION "public"."finalize_quotation_backend_document"("p_quotation_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_quotation_backend_document"("p_quotation_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") IS 'Registra de forma idempotente el PDF oficial generado server-side para un presupuesto y su SHA-256. Exclusivo para service_role.';



CREATE OR REPLACE FUNCTION "public"."generate_invoice_number"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_year TEXT := TO_CHAR(CURRENT_DATE, 'YY');
    v_random TEXT;
    v_invoice_number TEXT;
BEGIN

    LOOP

        SELECT string_agg(
            substr(
                'ABCDEFGHJKLMNPQRSTUVWXYZ23456789',
                floor(random() * 32 + 1)::INTEGER,
                1
            ),
            ''
        )
        INTO v_random
        FROM generate_series(1, 6);


        v_invoice_number :=
            'MODIRA-' || v_year || '-' || v_random;


        EXIT WHEN NOT EXISTS (
            SELECT 1
            FROM public.invoices
            WHERE numero_factura = v_invoice_number
        );

    END LOOP;


    RETURN v_invoice_number;

END;
$$;


ALTER FUNCTION "public"."generate_invoice_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_recurring_expense_forecasts"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_template public.recurring_expense_templates;
  v_occurrence date;
  v_next date;
  v_month date;
  v_day integer;
  v_inserted integer := 0;
  v_count integer;
BEGIN
  FOR v_template IN
    SELECT * FROM public.recurring_expense_templates
    WHERE lifecycle_status = 'active'
      AND approval_status = 'approved'
      AND start_date <= CURRENT_DATE
      AND (end_date IS NULL OR end_date >= start_date)
  LOOP
    v_occurrence := v_template.start_date;

    WHILE v_occurrence <= CURRENT_DATE
      AND (v_template.end_date IS NULL OR v_occurrence <= v_template.end_date)
    LOOP
      INSERT INTO public.recurring_expense_forecasts (
        recurring_template_id, occurrence_date, description, currency,
        subtotal, total_tax, total_withholding, total_amount,
        category_id, supplier_id, project_id, tax_config
      ) VALUES (
        v_template.id, v_occurrence, v_template.description, v_template.currency,
        v_template.subtotal, v_template.total_tax, v_template.total_withholding,
        v_template.total_amount, v_template.category_id, v_template.supplier_id,
        v_template.project_id, v_template.tax_config
      ) ON CONFLICT (recurring_template_id, occurrence_date) DO NOTHING;

      GET DIAGNOSTICS v_count = ROW_COUNT;
      v_inserted := v_inserted + v_count;

      IF v_template.frequency = 'weekly' THEN
        v_next := v_occurrence + 7;
      ELSE
        v_month := (date_trunc('month', v_occurrence)::date +
          CASE v_template.frequency WHEN 'quarterly' THEN INTERVAL '3 months' WHEN 'yearly' THEN INTERVAL '12 months' ELSE INTERVAL '1 month' END)::date;
        v_day := COALESCE(v_template.day_of_month, EXTRACT(DAY FROM v_template.start_date)::integer);
        v_next := v_month + (LEAST(v_day, EXTRACT(DAY FROM (v_month + INTERVAL '1 month - 1 day'))::integer) - 1);
      END IF;

      IF v_next <= v_occurrence THEN
        RAISE EXCEPTION 'No se pudo avanzar la fecha de recurrencia para %', v_template.id;
      END IF;
      v_occurrence := v_next;
    END LOOP;
  END LOOP;

  RETURN v_inserted;
END;
$$;


ALTER FUNCTION "public"."generate_recurring_expense_forecasts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ai_worker_conversation_usage"("p_conversation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    v_result JSONB;
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo de MODIRA';
    END IF;


    IF NOT public.current_worker_has_permission(
        'ai.read'
    ) THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere el permiso ai.read';
    END IF;


    IF p_conversation_id IS NULL THEN
        RAISE EXCEPTION
            'conversation_id is required';
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM public.ai_conversations c
        WHERE c.id = p_conversation_id
    ) THEN
        RAISE EXCEPTION
            'AI conversation not found';
    END IF;


    SELECT jsonb_build_object(

        'summary', jsonb_build_object(

            'request_count', (
                SELECT count(*)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
                  AND r.status = 'consumed'
            ),

            'input_tokens', (
                SELECT COALESCE(sum(r.actual_input_tokens), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
                  AND r.status = 'consumed'
            ),

            'output_tokens', (
                SELECT COALESCE(sum(r.actual_output_tokens), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
                  AND r.status = 'consumed'
            ),

            'total_tokens', (
                SELECT COALESCE(sum(
                    COALESCE(r.actual_input_tokens, 0)
                    + COALESCE(r.actual_output_tokens, 0)
                ), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
                  AND r.status = 'consumed'
            ),

            'actual_cost_cents', (
                SELECT COALESCE(sum(r.actual_cost_cents), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
                  AND r.status = 'consumed'
            ),

            'estimated_input_tokens', (
                SELECT COALESCE(sum(r.estimated_input_tokens), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
            ),

            'estimated_output_tokens', (
                SELECT COALESCE(sum(r.estimated_output_tokens), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
            ),

            'estimated_total_tokens', (
                SELECT COALESCE(sum(
                    r.estimated_input_tokens
                    + r.estimated_output_tokens
                ), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
            ),

            'estimated_cost_cents', (
                SELECT COALESCE(sum(r.estimated_cost_cents), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
            ),

            'reserved_input_tokens', (
                SELECT COALESCE(sum(r.estimated_input_tokens), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
                  AND r.status = 'reserved'
            ),

            'reserved_output_tokens', (
                SELECT COALESCE(sum(r.estimated_output_tokens), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
                  AND r.status = 'reserved'
            ),

            'reserved_total_tokens', (
                SELECT COALESCE(sum(
                    r.estimated_input_tokens
                    + r.estimated_output_tokens
                ), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
                  AND r.status = 'reserved'
            ),

            'reserved_cost_cents', (
                SELECT COALESCE(sum(r.estimated_cost_cents), 0)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
                  AND r.status = 'reserved'
            ),

            'has_usage_data', (
                SELECT count(*) > 0
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id = p_conversation_id
            )
        ),

        'events', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', r.id,
                    'user_id', r.user_id,
                    'company_id', r.company_id,
                    'scope_key', r.scope_key,
                    'conversation_id', r.conversation_id,
                    'model', r.model,
                    'estimated_input_tokens', r.estimated_input_tokens,
                    'estimated_output_tokens', r.estimated_output_tokens,
                    'estimated_total_tokens',
                        r.estimated_input_tokens + r.estimated_output_tokens,
                    'estimated_cost_cents', r.estimated_cost_cents,
                    'actual_input_tokens', r.actual_input_tokens,
                    'actual_output_tokens', r.actual_output_tokens,
                    'actual_total_tokens',
                        COALESCE(r.actual_input_tokens, 0)
                        + COALESCE(r.actual_output_tokens, 0),
                    'actual_cost_cents', r.actual_cost_cents,
                    'status', r.status,
                    'expires_at', r.expires_at,
                    'created_at', r.created_at,
                    'finalized_at', r.finalized_at
                )
                ORDER BY r.created_at ASC
            )
            FROM public.ai_usage_reservations r
            WHERE r.conversation_id = p_conversation_id
        ), '[]'::jsonb)

    )
    INTO v_result;

    RETURN v_result;

END;
$$;


ALTER FUNCTION "public"."get_ai_worker_conversation_usage"("p_conversation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ai_worker_conversation_usage"("p_conversation_id" "uuid") IS 'Read-only AI usage projection for one conversation, available only to active Modira workers.';



CREATE OR REPLACE FUNCTION "public"."get_ai_worker_panel_data"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    v_result JSONB;
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo de MODIRA';
    END IF;


    IF NOT public.current_worker_has_permission(
        'ai.read'
    ) THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere el permiso ai.read';
    END IF;


    SELECT jsonb_build_object(

        'config', COALESCE((
            SELECT to_jsonb(c)
            FROM public.ai_quota_config c
            WHERE c.config_key = 'modira-ai'
        ), '{}'::jsonb),

        'authenticated_usage', COALESCE((
            SELECT jsonb_agg(
                to_jsonb(u)
                ORDER BY u.period_ends_at DESC
            )
            FROM public.ai_usage_periods u
        ), '[]'::jsonb),

        'anonymous_usage', COALESCE((
            SELECT jsonb_agg(
                to_jsonb(a)
                ORDER BY a.period_ends_at DESC
            )
            FROM public.ai_anonymous_quota_periods a
        ), '[]'::jsonb),

        'reservations', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', r.id,
                    'user_id', r.user_id,
                    'company_id', r.company_id,
                    'scope_key', r.scope_key,
                    'conversation_id', r.conversation_id,
                    'model', r.model,
                    'estimated_input_tokens', r.estimated_input_tokens,
                    'estimated_output_tokens', r.estimated_output_tokens,
                    'estimated_total_tokens',
                        r.estimated_input_tokens + r.estimated_output_tokens,
                    'estimated_cost_cents', r.estimated_cost_cents,
                    'actual_input_tokens', r.actual_input_tokens,
                    'actual_output_tokens', r.actual_output_tokens,
                    'actual_total_tokens',
                        COALESCE(r.actual_input_tokens, 0)
                        + COALESCE(r.actual_output_tokens, 0),
                    'actual_cost_cents', r.actual_cost_cents,
                    'status', r.status,
                    'expires_at', r.expires_at,
                    'created_at', r.created_at,
                    'finalized_at', r.finalized_at
                )
                ORDER BY r.created_at DESC
            )
            FROM public.ai_usage_reservations r
        ), '[]'::jsonb),

        'rate_limits', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'key_masked',
                        CASE
                            WHEN length(r.rate_key) <= 10
                                THEN '••••••••'
                            ELSE left(r.rate_key, 4)
                                 || '••••••••'
                                 || right(r.rate_key, 4)
                        END,
                    'window_started_at', r.window_started_at,
                    'request_count', r.request_count,
                    'created_at', r.created_at,
                    'updated_at', r.updated_at
                )
                ORDER BY r.updated_at DESC
            )
            FROM public.ai_rate_limits r
        ), '[]'::jsonb),

        'summary', jsonb_build_object(

            'conversation_linked_reservations', (
                SELECT count(*)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id IS NOT NULL
            ),

            'unlinked_reservations', (
                SELECT count(*)
                FROM public.ai_usage_reservations r
                WHERE r.conversation_id IS NULL
            ),

            'reservation_count', (
                SELECT count(*)
                FROM public.ai_usage_reservations
            ),

            'active_reservations', (
                SELECT count(*)
                FROM public.ai_usage_reservations r
                WHERE r.status = 'reserved'
            ),

            'consumed_reservations', (
                SELECT count(*)
                FROM public.ai_usage_reservations r
                WHERE r.status = 'consumed'
            ),

            'released_reservations', (
                SELECT count(*)
                FROM public.ai_usage_reservations r
                WHERE r.status = 'released'
            ),

            'expired_reservations', (
                SELECT count(*)
                FROM public.ai_usage_reservations r
                WHERE r.status = 'expired'
            ),

            'total_actual_input_tokens', (
                SELECT COALESCE(sum(r.actual_input_tokens), 0)
                FROM public.ai_usage_reservations r
                WHERE r.status = 'consumed'
            ),

            'total_actual_output_tokens', (
                SELECT COALESCE(sum(r.actual_output_tokens), 0)
                FROM public.ai_usage_reservations r
                WHERE r.status = 'consumed'
            ),

            'total_actual_cost_cents', (
                SELECT COALESCE(sum(r.actual_cost_cents), 0)
                FROM public.ai_usage_reservations r
                WHERE r.status = 'consumed'
            )
        )

    )
    INTO v_result;

    RETURN v_result;

END;
$$;


