CREATE OR REPLACE FUNCTION "public"."get_company_effective_iva"("p_company_id" "uuid") RETURNS TABLE("iva_aplicado" boolean, "iva_porcentaje" numeric, "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE

    v_user_company_id UUID;

BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado.';
    END IF;


    IF NOT public.current_user_is_worker() THEN

        IF NOT public.current_user_is_active() THEN
            RAISE EXCEPTION
                'El usuario no está activo.';
        END IF;


        v_user_company_id :=
            public.current_user_company_id();


        IF v_user_company_id IS DISTINCT FROM p_company_id THEN
            RAISE EXCEPTION
                'No tienes acceso a la configuración fiscal de esta empresa.';
        END IF;

    END IF;


    -- --------------------------------------------------------
    -- APROBADO
    -- --------------------------------------------------------

    IF EXISTS (
        SELECT 1
        FROM public.companies c
        WHERE c.id = p_company_id
          AND c.iva_aprobado_at IS NOT NULL
    ) THEN

        RETURN QUERY
        SELECT
            c.iva_aprobado_aplicado,
            c.iva_aprobado_porcentaje,
            'approved'::TEXT
        FROM public.companies c
        WHERE c.id = p_company_id;

        RETURN;

    END IF;


    -- --------------------------------------------------------
    -- RECOMENDADO
    -- --------------------------------------------------------

    IF EXISTS (
        SELECT 1
        FROM public.companies c
        WHERE c.id = p_company_id
    ) THEN

        RETURN QUERY
        SELECT
            COALESCE(
                c.iva_recomendado_aplicado,
                TRUE
            ),

            CASE
                WHEN COALESCE(
                    c.iva_recomendado_aplicado,
                    TRUE
                )
                THEN COALESCE(
                    c.iva_recomendado_porcentaje,
                    21
                )
                ELSE 0
            END::NUMERIC(5,2),

            'recommended'::TEXT

        FROM public.companies c
        WHERE c.id = p_company_id;

        RETURN;

    END IF;


    -- --------------------------------------------------------
    -- DEFAULT
    -- --------------------------------------------------------

    RETURN QUERY
    SELECT
        TRUE,
        21::NUMERIC(5,2),
        'default'::TEXT;

END;
$$;


