CREATE OR REPLACE FUNCTION "public"."get_current_registration_status"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_status TEXT;
BEGIN
    IF auth.uid() IS NULL THEN
