CREATE OR REPLACE FUNCTION "public"."get_direction_worker_profiles"() RETURNS TABLE("worker_id" "uuid", "auth_user_id" "uuid", "name" "text", "email" "text", "status" "text", "is_active" boolean, "roles" "jsonb", "assigned_tasks_count" bigint, "completed_tasks_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado';
    END IF;

    IF NOT public.current_worker_has_permission('system.workers.read') THEN
        RAISE EXCEPTION 'Acceso denegado: se requiere system.workers.read';
    END IF;

    RETURN QUERY
    SELECT
        w.id,
        w.auth_user_id,
        COALESCE(NULLIF(BTRIM(p.nombre), ''), 'Sin nombre')::TEXT,
        p.email::TEXT,
        p.status::TEXT,
        w.is_active,
        COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'code', wr.code,
                    'name', wr.name
                )
                ORDER BY wr.name
            )
            FROM public.worker_role_assignments wra
            JOIN public.worker_roles wr
              ON wr.id = wra.role_id
            WHERE wra.worker_auth_user_id = w.auth_user_id
              AND wr.is_active = TRUE
        ), '[]'::JSONB),
        COALESCE((
            SELECT COUNT(*)
            FROM public.internal_tasks t
            WHERE t.assigned_to_worker_id = w.id
              AND COALESCE(t.status, '') <> 'cancelled'
        ), 0)::BIGINT,
        COALESCE((
            SELECT COUNT(*)
            FROM public.internal_tasks t
            WHERE t.assigned_to_worker_id = w.id
              AND t.status = 'completed'
        ), 0)::BIGINT
    FROM public.workers w
    JOIN public.profiles p
      ON p.id = w.auth_user_id
    WHERE w.is_active = TRUE
    ORDER BY COALESCE(NULLIF(BTRIM(p.nombre), ''), 'Sin nombre');
END;
$$;


ALTER FUNCTION "public"."get_direction_worker_profiles"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_direction_worker_tasks"("p_worker_id" "uuid", "p_filter" "text" DEFAULT 'assigned'::"text") RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "status" "text", "priority" "text", "due_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_filter TEXT := LOWER(BTRIM(COALESCE(p_filter, 'assigned')));
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado';
    END IF;

    IF NOT public.current_worker_has_permission('system.workers.read') THEN
        RAISE EXCEPTION 'Acceso denegado: se requiere system.workers.read';
    END IF;

    IF p_worker_id IS NULL THEN
        RAISE EXCEPTION 'worker_id es obligatorio';
    END IF;

    IF v_filter NOT IN ('assigned', 'completed') THEN
        RAISE EXCEPTION 'Filtro de tareas no válido';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.workers w
        WHERE w.id = p_worker_id
          AND w.is_active = TRUE
    ) THEN
        RAISE EXCEPTION 'Trabajador no encontrado o inactivo';
    END IF;

    RETURN QUERY
    SELECT
        t.id,
        t.title::TEXT,
        t.description::TEXT,
        t.status::TEXT,
        t.priority::TEXT,
        t.due_at,
        t.created_at,
        t.updated_at
    FROM public.internal_tasks t
    WHERE t.assigned_to_worker_id = p_worker_id
      AND (
          (v_filter = 'assigned' AND COALESCE(t.status, '') <> 'cancelled')
          OR
          (v_filter = 'completed' AND t.status = 'completed')
      )
    ORDER BY
        CASE WHEN t.status = 'completed' THEN 1 ELSE 0 END,
        t.due_at NULLS LAST,
        t.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_direction_worker_tasks"("p_worker_id" "uuid", "p_filter" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_expense_allocated_amount"("p_expense_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_allocated NUMERIC(14,2);

BEGIN

  IF p_expense_id IS NULL THEN

    RAISE EXCEPTION
      'get_expense_allocated_amount: expense_id es obligatorio';

  END IF;


  SELECT
    ROUND(
      COALESCE(
        SUM(amount),
        0
      ),
      2
    )

  INTO
    v_allocated

  FROM public.expense_allocations

  WHERE expense_id = p_expense_id;


  RETURN COALESCE(v_allocated, 0);

END;
$$;


