CREATE OR REPLACE FUNCTION "public"."get_expense_unallocated_amount"("p_expense_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_total NUMERIC(14,2);

  v_allocated NUMERIC(14,2);

BEGIN

  IF p_expense_id IS NULL THEN

    RAISE EXCEPTION
      'get_expense_unallocated_amount: expense_id es obligatorio';

  END IF;


  SELECT
    ROUND(
      COALESCE(total_amount, 0),
      2
    )

  INTO
    v_total

  FROM public.expenses

  WHERE id = p_expense_id;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El gasto % no existe',
      p_expense_id;

  END IF;


  v_allocated :=
    public.get_expense_allocated_amount(
      p_expense_id
    );


  RETURN ROUND(
    GREATEST(
      v_total - v_allocated,
      0
    ),
    2
  );

END;
$$;


ALTER FUNCTION "public"."get_expense_unallocated_amount"("p_expense_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_internal_task"("p_task_id" "uuid") RETURNS "public"."internal_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.internal_tasks;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.read'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:get:' || auth.uid()::TEXT,
        300,
        600
    );


    IF NOT public.internal_task_can_current_worker_view(p_task_id) THEN
        RAISE EXCEPTION
            'No tienes acceso a esta tarea';
    END IF;


    SELECT *
    INTO v_task
    FROM public.internal_tasks
    WHERE id = p_task_id;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tarea no existe';
    END IF;


    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."get_internal_task"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_internal_task_history"("p_task_id" "uuid", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS SETOF "public"."internal_task_updates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.read'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:history:' || auth.uid()::TEXT,
        300,
        600
    );


    IF p_limit IS NULL
       OR p_limit < 1
       OR p_limit > 200
    THEN
        RAISE EXCEPTION
            'El límite debe estar entre 1 y 200';
    END IF;


    IF p_offset IS NULL
       OR p_offset < 0
    THEN
        RAISE EXCEPTION
            'El offset no puede ser negativo';
    END IF;


    IF NOT public.internal_task_can_current_worker_view(p_task_id) THEN
        RAISE EXCEPTION
            'No tienes acceso al historial de esta tarea';
    END IF;


    RETURN QUERY
    SELECT u.*
    FROM public.internal_task_updates u
    WHERE u.task_id = p_task_id
    ORDER BY u.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;

END;
$$;


ALTER FUNCTION "public"."get_internal_task_history"("p_task_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_internal_task_visibility"("p_task_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_result JSONB;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.read'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:visibility_read:' || auth.uid()::TEXT,
        300,
        600
    );


    IF NOT public.internal_task_can_current_worker_view(p_task_id) THEN
        RAISE EXCEPTION
            'No tienes acceso a esta tarea';
    END IF;


    SELECT jsonb_build_object(
        'workers',
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'worker_id', a.worker_id,
                        'display_name', w.display_name,
                        'created_at', a.created_at
                    )
                    ORDER BY w.display_name
                )
                FROM public.internal_task_user_access a
                JOIN public.workers w
                  ON w.id = a.worker_id
                WHERE a.task_id = p_task_id
            ),
            '[]'::JSONB
        ),

        'roles',
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'role_id', a.role_id,
                        'code', wr.code,
                        'name', wr.name,
                        'created_at', a.created_at
                    )
                    ORDER BY wr.name
                )
                FROM public.internal_task_role_access a
                JOIN public.worker_roles wr
                  ON wr.id = a.role_id
                WHERE a.task_id = p_task_id
            ),
            '[]'::JSONB
        )
    )
    INTO v_result;


    RETURN v_result;

END;
$$;


ALTER FUNCTION "public"."get_internal_task_visibility"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_internal_tasks"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS SETOF "public"."internal_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_worker_id UUID;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.read'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:read:' || auth.uid()::TEXT,
        300,
        600
    );


    IF p_limit IS NULL
       OR p_limit < 1
       OR p_limit > 100
    THEN
        RAISE EXCEPTION
            'El límite debe estar entre 1 y 100';
    END IF;


    IF p_offset IS NULL
       OR p_offset < 0
    THEN
        RAISE EXCEPTION
            'El offset no puede ser negativo';
    END IF;


    IF p_status IS NOT NULL
       AND p_status NOT IN (
           'to_do',
           'in_progress',
           'pending_review',
           'completed',
           'cancelled'
       )
    THEN
        RAISE EXCEPTION
            'Estado no válido';
    END IF;


    v_worker_id := public.internal_task_current_worker_id();


    RETURN QUERY
    SELECT t.*
    FROM public.internal_tasks t
    WHERE (
        public.internal_task_current_worker_is_direction()
        OR t.assigned_to_worker_id = v_worker_id
        OR EXISTS (
            SELECT 1
            FROM public.internal_task_user_access a
            WHERE a.task_id = t.id
              AND a.worker_id = v_worker_id
        )
        OR EXISTS (
            SELECT 1
            FROM public.internal_task_role_access tra
            JOIN public.worker_role_assignments wra
              ON wra.role_id = tra.role_id
            JOIN public.worker_roles wr
              ON wr.id = tra.role_id
            WHERE tra.task_id = t.id
              AND wra.worker_auth_user_id = auth.uid()
              AND wr.is_active = TRUE
        )
    )
    AND (
        p_status IS NULL
        OR t.status = p_status
    )
    ORDER BY
        CASE t.priority
            WHEN 'urgent' THEN 1
            WHEN 'high' THEN 2
            WHEN 'normal' THEN 3
            WHEN 'low' THEN 4
            ELSE 5
        END,
        t.due_at NULLS LAST,
        t.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;

END;
$$;


ALTER FUNCTION "public"."get_internal_tasks"("p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_internal_tasks"("p_status" "text", "p_limit" integer, "p_offset" integer) IS 'Returns internal tasks visible to the current active worker. Reads are rate limited.';



CREATE OR REPLACE FUNCTION "public"."get_project_task"("p_task_id" "uuid") RETURNS "public"."project_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.project_tasks;
    v_worker_id UUID;
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.read'
    );

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:get:' || auth.uid()::TEXT,
        180,
        600
    );

    v_worker_id := public.current_project_task_worker_id();

    SELECT pt.*
    INTO v_task
    FROM public.project_tasks pt
    WHERE pt.id = p_task_id
      AND (
          public.current_worker_is_direction()
          OR pt.created_by_worker_id = v_worker_id
          OR pt.assigned_to_worker_id = v_worker_id
          OR EXISTS (
              SELECT 1
              FROM public.project_task_visibility v
              WHERE v.task_id = pt.id
                AND (
                    v.worker_id = v_worker_id
                    OR EXISTS (
                        SELECT 1
                        FROM public.worker_role_assignments wra
                        WHERE wra.worker_auth_user_id = auth.uid()
                          AND wra.role_id = v.role_id
                    )
                )
          )
      );

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Tarea no encontrada o no tienes acceso a ella';
    END IF;

    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."get_project_task"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_task_history"("p_task_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS SETOF "public"."project_task_updates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_limit INTEGER;
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Debes iniciar sesión';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.read'
    );

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:history:' || auth.uid()::TEXT,
        120,
        600
    );

    IF NOT EXISTS (
        SELECT 1
        FROM public.project_tasks
        WHERE id = p_task_id
    ) THEN
        RAISE EXCEPTION
            'Tarea no encontrada';
    END IF;

    v_limit := LEAST(
        GREATEST(COALESCE(p_limit, 100), 1),
        200
    );

    RETURN QUERY
    SELECT ptu.*
    FROM public.project_task_updates ptu
    WHERE ptu.task_id = p_task_id
    ORDER BY ptu.created_at DESC
    LIMIT v_limit;

END;
$$;


ALTER FUNCTION "public"."get_project_task_history"("p_task_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_task_visibility"("p_task_id" "uuid") RETURNS TABLE("worker_id" "uuid", "worker_name" "text", "role_id" "uuid", "role_code" "text", "role_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.read'
    );

    IF p_task_id IS NULL THEN
        RAISE EXCEPTION 'La tarea es obligatoria';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.project_tasks pt
        WHERE pt.id = p_task_id
          AND (
              public.current_worker_is_direction()
              OR pt.created_by_worker_id = public.current_project_task_worker_id()
              OR pt.assigned_to_worker_id = public.current_project_task_worker_id()
              OR EXISTS (
                  SELECT 1
                  FROM public.project_task_visibility v
                  WHERE v.task_id = pt.id
                    AND (
                        v.worker_id = public.current_project_task_worker_id()
                        OR EXISTS (
                            SELECT 1
                            FROM public.worker_role_assignments wra
                            WHERE wra.worker_auth_user_id = auth.uid()
                              AND wra.role_id = v.role_id
                        )
                    )
              )
          )
    ) THEN
        RAISE EXCEPTION 'No tienes acceso a esta tarea';
    END IF;

    RETURN QUERY
    SELECT
        v.worker_id,
        w.display_name,
        v.role_id,
        wr.code,
        wr.name
    FROM public.project_task_visibility v
    LEFT JOIN public.workers w
        ON w.id = v.worker_id
    LEFT JOIN public.worker_roles wr
        ON wr.id = v.role_id
    WHERE v.task_id = p_task_id
    ORDER BY
        CASE WHEN v.worker_id IS NOT NULL THEN 1 ELSE 2 END,
        COALESCE(w.display_name, wr.name);

END;
$$;


ALTER FUNCTION "public"."get_project_task_visibility"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_tasks"("p_project_id" "uuid" DEFAULT NULL::"uuid", "p_milestone_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT NULL::"text", "p_priority" "text" DEFAULT NULL::"text", "p_assigned_to_worker_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 100) RETURNS SETOF "public"."project_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_limit INTEGER;
    v_worker_id UUID;
    v_is_direction BOOLEAN;
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.read'
    );

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:read:' || auth.uid()::TEXT,
        120,
        600
    );

    v_worker_id := public.current_project_task_worker_id();
    v_is_direction := public.current_worker_is_direction();

    IF v_worker_id IS NULL THEN
        RAISE EXCEPTION
            'No se ha podido identificar al trabajador actual';
    END IF;

    v_limit := LEAST(
        GREATEST(COALESCE(p_limit, 100), 1),
        200
    );

    IF p_project_id IS NOT NULL
       AND NOT public.project_task_project_exists(p_project_id)
    THEN
        RAISE EXCEPTION 'El proyecto no existe';
    END IF;

    RETURN QUERY
    SELECT pt.*
    FROM public.project_tasks pt
    WHERE (p_project_id IS NULL OR pt.project_id = p_project_id)
      AND (
          p_milestone_id IS NULL
          OR pt.milestone_id = p_milestone_id
      )
      AND (
          p_status IS NULL
          OR pt.status = LOWER(BTRIM(p_status))
      )
      AND (
          p_priority IS NULL
          OR pt.priority = LOWER(BTRIM(p_priority))
      )
      AND (
          p_assigned_to_worker_id IS NULL
          OR pt.assigned_to_worker_id = p_assigned_to_worker_id
      )
      AND (
          v_is_direction
          OR pt.created_by_worker_id = v_worker_id
          OR pt.assigned_to_worker_id = v_worker_id
          OR EXISTS (
              SELECT 1
              FROM public.project_task_visibility v
              WHERE v.task_id = pt.id
                AND (
                    v.worker_id = v_worker_id
                    OR EXISTS (
                        SELECT 1
                        FROM public.worker_role_assignments wra
                        WHERE wra.worker_auth_user_id = auth.uid()
                          AND wra.role_id = v.role_id
                    )
                )
          )
      )
    ORDER BY
        CASE pt.priority
            WHEN 'urgent' THEN 1
            WHEN 'high' THEN 2
            WHEN 'normal' THEN 3
            WHEN 'low' THEN 4
            ELSE 5
        END,
        pt.due_at NULLS LAST,
        pt.created_at DESC
    LIMIT v_limit;

END;
$$;


ALTER FUNCTION "public"."get_project_tasks"("p_project_id" "uuid", "p_milestone_id" "uuid", "p_status" "text", "p_priority" "text", "p_assigned_to_worker_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_task_worker_options"() RETURNS TABLE("id" "uuid", "display_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    -- Debe existir una sesión autenticada
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión.';
    END IF;

    -- Debe ser un trabajador activo de Modira
    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION 'El usuario actual no corresponde a un trabajador activo de Modira.';
    END IF;

    -- Debe tener explícitamente task_workers.read
    IF NOT public.current_worker_has_permission('task_workers.read') THEN
        RAISE EXCEPTION 'No tienes permiso para consultar trabajadores.';
    END IF;

    RETURN QUERY
    SELECT
        w.id,
        w.display_name
    FROM public.workers w
    WHERE w.is_active = TRUE
    ORDER BY w.display_name;

END;
$$;


ALTER FUNCTION "public"."get_task_worker_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_worker_permission_catalog"() RETURNS TABLE("permission_id" "uuid", "permission_code" "text", "resource" "text", "action" "text", "permission_description" "text", "role_count" bigint, "role_codes" "text"[], "role_names" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required'
            USING ERRCODE = '42501';
    END IF;

    IF NOT (
        public.current_user_can_manage_worker_roles()
        OR (
            public.current_user_is_worker()
            AND (
                public.current_worker_has_permission('system.roles.read')
                OR public.current_worker_has_permission('system.roles.manage')
            )
        )
    ) THEN
        RAISE EXCEPTION 'Insufficient permissions to read worker permissions'
            USING ERRCODE = '42501';
    END IF;

    RETURN QUERY
    SELECT
        p.id,
        p.code,
        p.resource,
        p.action,
        p.description,
        (
            SELECT COUNT(DISTINCT r2.id)
            FROM public.worker_role_permissions wrp2
            JOIN public.worker_roles r2
              ON r2.id = wrp2.role_id
            WHERE wrp2.permission_id = p.id
              AND r2.is_active = TRUE
        ) AS role_count,
        COALESCE((
            SELECT ARRAY_AGG(DISTINCT r3.code ORDER BY r3.code)
            FROM public.worker_role_permissions wrp3
            JOIN public.worker_roles r3
              ON r3.id = wrp3.role_id
            WHERE wrp3.permission_id = p.id
              AND r3.is_active = TRUE
        ), ARRAY[]::text[]) AS role_codes,
        COALESCE((
            SELECT ARRAY_AGG(DISTINCT r4.name ORDER BY r4.name)
            FROM public.worker_role_permissions wrp4
            JOIN public.worker_roles r4
              ON r4.id = wrp4.role_id
            WHERE wrp4.permission_id = p.id
              AND r4.is_active = TRUE
        ), ARRAY[]::text[]) AS role_names
    FROM public.worker_permissions p
    ORDER BY p.resource, p.action, p.code;
END;
$$;


ALTER FUNCTION "public"."get_worker_permission_catalog"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_worker_project_change_requests"() RETURNS TABLE("id" "uuid", "project_id" "uuid", "project_nombre" "text", "user_id" "uuid", "cliente_nombre" "text", "cliente_email" "text", "company_id" "uuid", "client_id" "uuid", "description" "text", "status" "text", "reviewed_by" "uuid", "reviewed_at" timestamp with time zone, "review_notes" "text", "accepted_at" timestamp with time zone, "completed_by" "uuid", "completed_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "change_requests_enabled" boolean, "change_requests_deadline" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
BEGIN

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    IF NOT public.current_worker_has_permission(
        'projects.read'
    ) THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere el permiso projects.read';
    END IF;


    RETURN QUERY

    SELECT
        r.id,
        r.project_id,
        p.nombre AS project_nombre,
        r.user_id,
        COALESCE(
            pr.nombre,
            'Sin nombre'
        ) AS cliente_nombre,
        u.email::TEXT AS cliente_email,
        r.company_id,
        r.client_id,
        r.description,
        r.status,
        r.reviewed_by,
        r.reviewed_at,
        r.review_notes,
        r.accepted_at,
        r.completed_by,
        r.completed_at,
        r.created_at,
        r.updated_at,
        p.change_requests_enabled,
        p.change_requests_deadline

    FROM public.project_change_requests r

    INNER JOIN public.projects p
        ON p.id = r.project_id

    LEFT JOIN public.profiles pr
        ON pr.id = r.user_id

    LEFT JOIN auth.users u
        ON u.id = r.user_id

    ORDER BY
        CASE
            WHEN r.status = 'pending'
                THEN 1
            WHEN r.status = 'in_review'
                THEN 2
            WHEN r.status = 'accepted'
                THEN 3
            WHEN r.status = 'completed'
                THEN 4
            WHEN r.status = 'rejected'
                THEN 5
            ELSE 6
        END,
        r.created_at DESC;

END;
$$;


ALTER FUNCTION "public"."get_worker_project_change_requests"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_worker_projects"() RETURNS TABLE("id" "uuid", "nombre" "text", "descripcion" "text", "estado" "text", "fecha_inicio" timestamp with time zone, "fecha_fin" timestamp with time zone, "company_id" "uuid", "user_id" "uuid", "created_at" timestamp with time zone, "cliente_nombre" "text", "cliente_email" "text", "empresa_nombre" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
BEGIN

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere rol de trabajador activo';
    END IF;


    IF NOT public.current_worker_has_permission(
        'projects.read'
    ) THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere el permiso projects.read';
    END IF;


    RETURN QUERY

    SELECT
        p.id,
        p.nombre,
        p.descripcion,
        p.estado,
        p.fecha_inicio,
        p.fecha_fin,
        p.company_id,
        p.user_id,
        p.created_at,
        COALESCE(
            pr.nombre,
            'Sin nombre'
        ) AS cliente_nombre,
        u.email::TEXT AS cliente_email,
        c.company_name AS empresa_nombre

    FROM public.projects p

    LEFT JOIN public.profiles pr
        ON p.user_id = pr.id

    LEFT JOIN public.companies c
        ON p.company_id = c.id

    LEFT JOIN auth.users u
        ON p.user_id = u.id

    ORDER BY p.created_at DESC;

END;
$$;


ALTER FUNCTION "public"."get_worker_projects"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_worker_role_catalog"() RETURNS TABLE("role_id" "uuid", "role_code" "text", "role_name" "text", "role_description" "text", "is_system_role" boolean, "is_active" boolean, "worker_count" bigint, "permission_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required'
            USING ERRCODE = '42501';
    END IF;

    IF NOT (
        public.current_user_can_manage_worker_roles()
        OR (
            public.current_user_is_worker()
            AND (
                public.current_worker_has_permission('system.roles.read')
                OR public.current_worker_has_permission('system.roles.manage')
            )
        )
    ) THEN
        RAISE EXCEPTION 'Insufficient permissions to read worker roles'
            USING ERRCODE = '42501';
    END IF;

    RETURN QUERY
    SELECT
        r.id,
        r.code,
        r.name,
        r.description,
        r.is_system_role,
        r.is_active,
        (
            SELECT COUNT(DISTINCT wra.worker_auth_user_id)
            FROM public.worker_role_assignments wra
            JOIN public.workers w
              ON w.auth_user_id = wra.worker_auth_user_id
            WHERE wra.role_id = r.id
        ) AS worker_count,
        (
            SELECT COUNT(DISTINCT wrp.permission_id)
            FROM public.worker_role_permissions wrp
            WHERE wrp.role_id = r.id
        ) AS permission_count
    FROM public.worker_roles r
    ORDER BY r.is_system_role DESC, r.name ASC;
END;
$$;


ALTER FUNCTION "public"."get_worker_role_catalog"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_worker_roles"("p_worker_auth_user_id" "uuid") RETURNS TABLE("role_id" "uuid", "role_code" "text", "role_name" "text", "role_description" "text", "is_system_role" boolean, "is_active" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Authentication required'
            USING ERRCODE = '42501';
    END IF;


    IF p_worker_auth_user_id IS NULL THEN
        RAISE EXCEPTION
            'Worker auth user id is required'
            USING ERRCODE = '22023';
    END IF;


    -- Un worker puede consultar sus propios roles.
    -- Para consultar los de otro worker se necesita
    -- capacidad administrativa.
    IF p_worker_auth_user_id <> auth.uid()
       AND NOT public.current_user_can_manage_worker_roles() THEN

        RAISE EXCEPTION
            'Insufficient permissions to view worker roles'
            USING ERRCODE = '42501';

    END IF;


    RETURN QUERY
    SELECT
        r.id,
        r.code,
        r.name,
        r.description,
        r.is_system_role,
        r.is_active
    FROM public.worker_role_assignments wra
    JOIN public.worker_roles r
        ON r.id = wra.role_id
    WHERE wra.worker_auth_user_id = p_worker_auth_user_id
    ORDER BY r.name;

END;
$$;


ALTER FUNCTION "public"."get_worker_roles"("p_worker_auth_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_worker_roles"("p_worker_auth_user_id" "uuid") IS 'Consulta los roles RBAC asignados a un worker.';



CREATE OR REPLACE FUNCTION "public"."guard_maintenance_custom_proposal_acceptance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$

BEGIN

    IF NEW.status = 'accepted'
       AND OLD.status IS DISTINCT FROM 'accepted'
    THEN

        IF OLD.status <> 'quoted' THEN
            RAISE EXCEPTION
                'Solo una propuesta cotizada puede pasar a aceptada';
        END IF;

        IF NEW.accepted_by IS NULL
           OR NEW.accepted_by IS DISTINCT FROM NEW.user_id
        THEN
            RAISE EXCEPTION
                'La aceptación debe pertenecer al usuario cliente de la propuesta';
        END IF;

        IF NEW.current_document_id IS NULL THEN
            RAISE EXCEPTION
                'La propuesta no tiene un PDF publicado';
        END IF;

        IF NEW.quoted_valid_until IS NOT NULL
           AND NEW.quoted_valid_until < CURRENT_DATE
        THEN
            RAISE EXCEPTION
                'La propuesta ha caducado';
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM public.maintenance_custom_proposal_documents d
            WHERE d.id = NEW.current_document_id
              AND d.proposal_id = NEW.id
              AND d.published_at IS NOT NULL
              AND EXISTS (
                  SELECT 1
                  FROM public.maintenance_custom_proposal_document_acknowledgements a
                  WHERE a.proposal_id = NEW.id
                    AND a.document_id = d.id
                    AND a.user_id = NEW.user_id
                    AND LOWER(a.document_sha256)
                        = LOWER(d.document_sha256)
              )
        )
        THEN
            RAISE EXCEPTION
                'Antes de aceptar la propuesta debes confirmar que has leído el PDF publicado';
        END IF;

    END IF;

    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."guard_maintenance_custom_proposal_acceptance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_maintenance_invoice_fiscal_data"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_company public.companies;
    v_original public.maintenance_invoices;
BEGIN

    -- Los borradores pueden existir incompletos.
    -- La validación fiscal se realiza al emitirlos.
    IF COALESCE(NEW.estado, 'borrador') = 'borrador' THEN
        RETURN NEW;
    END IF;


    -- --------------------------------------------------------
    -- Validar empresa
    -- --------------------------------------------------------

    IF NEW.company_id IS NULL THEN
        RAISE EXCEPTION
            'No se puede emitir una factura de mantenimiento sin empresa';
    END IF;

    SELECT *
    INTO v_company
    FROM public.companies
    WHERE id = NEW.company_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No se puede emitir una factura de mantenimiento: la empresa no existe';
    END IF;


    -- --------------------------------------------------------
    -- CASO A: FACTURA RECTIFICATIVA
    -- --------------------------------------------------------

    IF NEW.rectifies_invoice_id IS NOT NULL THEN

        SELECT *
        INTO v_original
        FROM public.maintenance_invoices
        WHERE id = NEW.rectifies_invoice_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'No existe la factura de mantenimiento que se desea rectificar';
        END IF;

        IF v_original.id = NEW.id THEN
            RAISE EXCEPTION
                'Una factura no puede rectificarse a sí misma';
        END IF;

        IF v_original.company_id IS DISTINCT FROM NEW.company_id THEN
            RAISE EXCEPTION
                'La rectificativa y la factura original deben pertenecer a la misma empresa';
        END IF;


        -- ....................................................
        -- Opción A: snapshot fiscal de la factura original
        -- ....................................................

        IF NEW.rectification_customer_data_source = 'original_invoice' THEN

            NEW.customer_legal_name := v_original.customer_legal_name;
            NEW.customer_tax_id := v_original.customer_tax_id;
            NEW.customer_address := v_original.customer_address;
            NEW.customer_postal_code := v_original.customer_postal_code;
            NEW.customer_city := v_original.customer_city;
            NEW.customer_province := v_original.customer_province;
            NEW.customer_country := v_original.customer_country;


        -- ....................................................
        -- Opción B: datos fiscales actuales de la empresa
        -- ....................................................

        ELSIF NEW.rectification_customer_data_source = 'current_company' THEN

            IF NULLIF(BTRIM(v_company.legal_name), '') IS NULL
               AND NULLIF(BTRIM(v_company.company_name), '') IS NULL
            THEN
                RAISE EXCEPTION
                    'No se puede emitir la rectificativa: falta la razón social';
            END IF;

            IF NULLIF(BTRIM(v_company.cif_vat), '') IS NULL THEN
                RAISE EXCEPTION
                    'No se puede emitir la rectificativa: falta el NIF/CIF/VAT';
            END IF;

            IF NULLIF(BTRIM(v_company.address), '') IS NULL THEN
                RAISE EXCEPTION
                    'No se puede emitir la rectificativa: falta la dirección fiscal';
            END IF;

            IF NULLIF(BTRIM(v_company.postal_code), '') IS NULL THEN
                RAISE EXCEPTION
                    'No se puede emitir la rectificativa: falta el código postal';
            END IF;

            IF NULLIF(BTRIM(v_company.city), '') IS NULL THEN
                RAISE EXCEPTION
                    'No se puede emitir la rectificativa: falta la ciudad';
            END IF;

            IF NULLIF(BTRIM(v_company.country), '') IS NULL THEN
                RAISE EXCEPTION
                    'No se puede emitir la rectificativa: falta el país';
            END IF;

            NEW.customer_legal_name :=
                COALESCE(
                    NULLIF(BTRIM(v_company.legal_name), ''),
                    NULLIF(BTRIM(v_company.company_name), '')
                );

            NEW.customer_tax_id :=
                NULLIF(BTRIM(v_company.cif_vat), '');

            NEW.customer_address :=
                NULLIF(BTRIM(v_company.address), '');

            NEW.customer_postal_code :=
                NULLIF(BTRIM(v_company.postal_code), '');

            NEW.customer_city :=
                NULLIF(BTRIM(v_company.city), '');

            NEW.customer_province :=
                NULLIF(BTRIM(v_company.province), '');

            NEW.customer_country :=
                UPPER(NULLIF(BTRIM(v_company.country), ''));

        ELSE
            RAISE EXCEPTION
                'La rectificativa debe indicar de dónde proceden sus datos fiscales';
        END IF;


    -- --------------------------------------------------------
    -- CASO B: FACTURA ORDINARIA
    -- --------------------------------------------------------

    ELSE

        IF NULLIF(BTRIM(v_company.legal_name), '') IS NULL
           AND NULLIF(BTRIM(v_company.company_name), '') IS NULL
        THEN
            RAISE EXCEPTION
                'No se puede emitir la factura: falta la razón social';
        END IF;

        IF NULLIF(BTRIM(v_company.cif_vat), '') IS NULL THEN
            RAISE EXCEPTION
                'No se puede emitir la factura: falta el NIF/CIF/VAT';
        END IF;

        IF NULLIF(BTRIM(v_company.address), '') IS NULL THEN
            RAISE EXCEPTION
                'No se puede emitir la factura: falta la dirección fiscal';
        END IF;

        IF NULLIF(BTRIM(v_company.postal_code), '') IS NULL THEN
            RAISE EXCEPTION
                'No se puede emitir la factura: falta el código postal';
        END IF;

        IF NULLIF(BTRIM(v_company.city), '') IS NULL THEN
            RAISE EXCEPTION
                'No se puede emitir la factura: falta la ciudad';
        END IF;

        IF NULLIF(BTRIM(v_company.country), '') IS NULL THEN
            RAISE EXCEPTION
                'No se puede emitir la factura: falta el país';
        END IF;

        NEW.customer_legal_name :=
            COALESCE(
                NULLIF(BTRIM(v_company.legal_name), ''),
                NULLIF(BTRIM(v_company.company_name), '')
            );

        NEW.customer_tax_id :=
            NULLIF(BTRIM(v_company.cif_vat), '');

        NEW.customer_address :=
            NULLIF(BTRIM(v_company.address), '');

        NEW.customer_postal_code :=
            NULLIF(BTRIM(v_company.postal_code), '');

        NEW.customer_city :=
            NULLIF(BTRIM(v_company.city), '');

        NEW.customer_province :=
            NULLIF(BTRIM(v_company.province), '');

        NEW.customer_country :=
            UPPER(NULLIF(BTRIM(v_company.country), ''));

    END IF;


    -- --------------------------------------------------------
    -- Validación final del snapshot fiscal
    -- --------------------------------------------------------

    IF NULLIF(BTRIM(NEW.customer_legal_name), '') IS NULL
       OR NULLIF(BTRIM(NEW.customer_tax_id), '') IS NULL
       OR NULLIF(BTRIM(NEW.customer_address), '') IS NULL
       OR NULLIF(BTRIM(NEW.customer_postal_code), '') IS NULL
       OR NULLIF(BTRIM(NEW.customer_city), '') IS NULL
       OR NULLIF(BTRIM(NEW.customer_country), '') IS NULL
    THEN
        RAISE EXCEPTION
            'No se puede emitir la factura: los datos fiscales del destinatario están incompletos';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_maintenance_invoice_fiscal_data"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guard_maintenance_invoice_fiscal_data"() IS 'Impide emitir facturas de mantenimiento sin datos fiscales mínimos completos y toma un snapshot fiscal de companies en customer_*.';



CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_empresa TEXT;
    v_company_id UUID;
    v_company_code TEXT;
BEGIN
    v_empresa :=
        NULLIF(
            TRIM(
                COALESCE(
                    NEW.raw_user_meta_data->>'empresa',
                    ''
                )
            ),
            ''
        );

    IF v_empresa IS NOT NULL THEN
        v_company_code :=
            'CLI-' ||
            UPPER(
                REPLACE(
                    gen_random_uuid()::TEXT,
                    '-',
                    ''
                )
            );

        INSERT INTO public.companies (
            company_code,
            company_name,
            legal_name,
            created_by
        )
        VALUES (
            v_company_code,
            LEFT(v_empresa, 200),
            LEFT(v_empresa, 200),
            NEW.id
        )
        RETURNING id
        INTO v_company_id;
    END IF;

    INSERT INTO public.profiles (
        id,
        nombre,
        empresa,
        company_id,
        rol,
        email,
        status
    )
    VALUES (
        NEW.id,
        COALESCE(
            NULLIF(
                TRIM(
                    NEW.raw_user_meta_data->>'nombre'
                ),
                ''
            ),
            NULLIF(
                TRIM(
                    NEW.raw_user_meta_data->>'name'
                ),
                ''
            ),
            NEW.email,
            'Usuario'
        ),
        v_empresa,
        v_company_id,
        'user',
        NEW.email,
        'pending_legal'
    )
    ON CONFLICT (id)
    DO UPDATE
    SET
        nombre = EXCLUDED.nombre,
        empresa = EXCLUDED.empresa,
        company_id = EXCLUDED.company_id,
        email = EXCLUDED.email;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_current_legal_action"("p_document_type" "text", "p_action_type" "text", "p_context" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN FALSE;
    END IF;

    RETURN EXISTS (
        SELECT 1
        FROM public.legal_acceptances la
        JOIN public.legal_documents ld
          ON ld.id = la.document_id
        WHERE la.user_id = auth.uid()
          AND ld.document_type = p_document_type
          AND ld.is_current = TRUE
          AND la.action_type = p_action_type
          AND (
              p_context IS NULL
              OR la.context = p_context
          )
          AND la.document_hash = ld.content_hash
          AND la.accepted_at >= ld.effective_from
          AND (
              ld.effective_until IS NULL
              OR la.accepted_at < ld.effective_until
          )
        ORDER BY la.accepted_at DESC
        LIMIT 1
    );
END;
$$;


ALTER FUNCTION "public"."has_current_legal_action"("p_document_type" "text", "p_action_type" "text", "p_context" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."internal_task_can_current_worker_view"("p_task_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_worker_id UUID;
BEGIN

    IF auth.uid() IS NULL THEN
        RETURN FALSE;
    END IF;


    IF NOT public.current_user_is_worker() THEN
        RETURN FALSE;
    END IF;


    v_worker_id := public.internal_task_current_worker_id();


    IF v_worker_id IS NULL THEN
        RETURN FALSE;
    END IF;


    IF public.internal_task_current_worker_is_direction() THEN
        RETURN TRUE;
    END IF;


    IF EXISTS (
        SELECT 1
        FROM public.internal_tasks t
        WHERE t.id = p_task_id
          AND t.assigned_to_worker_id = v_worker_id
    ) THEN
        RETURN TRUE;
    END IF;


    IF EXISTS (
        SELECT 1
        FROM public.internal_task_user_access a
        WHERE a.task_id = p_task_id
          AND a.worker_id = v_worker_id
    ) THEN
        RETURN TRUE;
    END IF;


    IF EXISTS (
        SELECT 1
        FROM public.internal_task_role_access tra
        JOIN public.worker_role_assignments wra
          ON wra.role_id = tra.role_id
        JOIN public.worker_roles wr
          ON wr.id = tra.role_id
        WHERE tra.task_id = p_task_id
          AND wra.worker_auth_user_id = auth.uid()
          AND wr.is_active = TRUE
    ) THEN
        RETURN TRUE;
    END IF;


    RETURN FALSE;

END;
$$;


ALTER FUNCTION "public"."internal_task_can_current_worker_view"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."internal_task_current_worker_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_worker_id UUID;
BEGIN

    IF auth.uid() IS NULL THEN
        RETURN NULL;
    END IF;


    SELECT w.id
    INTO v_worker_id
    FROM public.workers w
    WHERE w.auth_user_id = auth.uid()
      AND w.is_active = TRUE
    LIMIT 1;


    RETURN v_worker_id;

END;
$$;


