CREATE OR REPLACE FUNCTION "public"."link_ai_usage_reservation_context"("p_reservation_id" "uuid", "p_conversation_id" "uuid", "p_model" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    v_updated INTEGER;
BEGIN
    IF p_reservation_id IS NULL THEN
        RAISE EXCEPTION 'reservation_id is required';
    END IF;

    IF p_conversation_id IS NULL THEN
        RAISE EXCEPTION 'conversation_id is required';
    END IF;

    IF p_model IS NOT NULL
       AND (
            length(btrim(p_model)) = 0
            OR length(p_model) > 100
       )
    THEN
        RAISE EXCEPTION 'Invalid AI model';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.ai_conversations c
        WHERE c.id = p_conversation_id
    ) THEN
        RAISE EXCEPTION 'AI conversation not found';
    END IF;

    UPDATE public.ai_usage_reservations r
    SET
        conversation_id = p_conversation_id,
        model = CASE
            WHEN p_model IS NULL THEN r.model
            ELSE btrim(p_model)
        END
    WHERE r.id = p_reservation_id
      AND r.status = 'reserved';

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    IF v_updated <> 1 THEN
        RAISE EXCEPTION
            'AI reservation not found or is no longer reserved';
    END IF;

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."link_ai_usage_reservation_context"("p_reservation_id" "uuid", "p_conversation_id" "uuid", "p_model" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."link_ai_usage_reservation_context"("p_reservation_id" "uuid", "p_conversation_id" "uuid", "p_model" "text") IS 'Internal service-role RPC used by modira-ai to associate a quota reservation with its conversation and model.';



CREATE TABLE IF NOT EXISTS "public"."recurring_expense_forecasts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "recurring_template_id" "uuid" NOT NULL,
    "occurrence_date" "date" NOT NULL,
    "description" "text" NOT NULL,
    "currency" character varying(3) NOT NULL,
    "subtotal" numeric(14,2) NOT NULL,
    "total_tax" numeric(14,2) NOT NULL,
    "total_withholding" numeric(14,2) NOT NULL,
    "total_amount" numeric(14,2) NOT NULL,
    "category_id" "uuid",
    "supplier_id" "uuid",
    "project_id" "uuid",
    "tax_config" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "linked_expense_id" "uuid",
    "generated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "recurring_expense_forecasts_check" CHECK (("total_amount" = GREATEST("round"((("subtotal" + "total_tax") - "total_withholding"), 2), (0)::numeric))),
    CONSTRAINT "recurring_expense_forecasts_check1" CHECK (((("status" = 'converted'::"text") AND ("linked_expense_id" IS NOT NULL)) OR (("status" <> 'converted'::"text") AND ("linked_expense_id" IS NULL)))),
    CONSTRAINT "recurring_expense_forecasts_currency_check" CHECK ((("currency")::"text" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "recurring_expense_forecasts_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'converted'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "recurring_expense_forecasts_subtotal_check" CHECK (("subtotal" >= (0)::numeric)),
    CONSTRAINT "recurring_expense_forecasts_tax_config_check" CHECK (("jsonb_typeof"("tax_config") = 'array'::"text")),
    CONSTRAINT "recurring_expense_forecasts_total_amount_check" CHECK (("total_amount" >= (0)::numeric)),
    CONSTRAINT "recurring_expense_forecasts_total_tax_check" CHECK (("total_tax" >= (0)::numeric)),
    CONSTRAINT "recurring_expense_forecasts_total_withholding_check" CHECK (("total_withholding" >= (0)::numeric))
);


ALTER TABLE "public"."recurring_expense_forecasts" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_expense_forecast_to_expense"("p_forecast_id" "uuid", "p_expense_id" "uuid") RETURNS "public"."recurring_expense_forecasts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_forecast public.recurring_expense_forecasts;
  v_expense public.expenses;
BEGIN
  PERFORM public.require_expense_permission('expenses.update');
  PERFORM public.consume_expense_worker_rate_limit('expenses:forecast_link');

  SELECT * INTO v_forecast FROM public.recurring_expense_forecasts WHERE id = p_forecast_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'La previsión no existe'; END IF;
  IF v_forecast.status <> 'pending' THEN RAISE EXCEPTION 'La previsión ya no está pendiente'; END IF;

  SELECT * INTO v_expense FROM public.expenses WHERE id = p_expense_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'El gasto real no existe'; END IF;
  IF v_expense.status = 'cancelled' THEN RAISE EXCEPTION 'No se puede vincular un gasto cancelado'; END IF;
  IF v_expense.currency <> v_forecast.currency THEN RAISE EXCEPTION 'La moneda del gasto y la previsión no coincide'; END IF;

  UPDATE public.recurring_expense_forecasts
  SET status = 'converted', linked_expense_id = p_expense_id
  WHERE id = p_forecast_id
  RETURNING * INTO v_forecast;

  RETURN v_forecast;
END;
$$;


ALTER FUNCTION "public"."link_expense_forecast_to_expense"("p_forecast_id" "uuid", "p_expense_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."activity_log" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid",
    "company_id" "uuid",
    "action" "text" NOT NULL,
    "resource_type" "text" NOT NULL,
    "resource_id" "uuid",
    "description" "text",
    "metadata" "jsonb",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "activity_log_action_check" CHECK (("length"(TRIM(BOTH FROM "action")) > 0)),
    CONSTRAINT "activity_log_action_length_hardening_check" CHECK ((("action" IS NULL) OR ("length"("action") <= 100))),
    CONSTRAINT "activity_log_description_length_hardening_check" CHECK ((("description" IS NULL) OR ("length"("description") <= 2000))),
    CONSTRAINT "activity_log_metadata_size_hardening_check" CHECK ((("metadata" IS NULL) OR ("pg_column_size"("metadata") <= 51200))),
    CONSTRAINT "activity_log_resource_type_check" CHECK (("length"(TRIM(BOTH FROM "resource_type")) > 0)),
    CONSTRAINT "activity_log_resource_type_length_hardening_check" CHECK ((("resource_type" IS NULL) OR ("length"("resource_type") <= 100)))
);


ALTER TABLE "public"."activity_log" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_activity"("p_action" "text", "p_resource_type" "text", "p_resource_id" "uuid" DEFAULT NULL::"uuid", "p_description" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."activity_log"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_company_id UUID;
    v_activity public.activity_log;
BEGIN
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado';
    END IF;

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION 'Acceso denegado: la cuenta está bloqueada';
    END IF;

    IF public.current_user_is_worker() THEN
        v_company_id := NULL;
    ELSE
        v_company_id := public.current_user_company_id();
    END IF;

    IF p_action IS NULL OR TRIM(p_action) = '' THEN
        RAISE EXCEPTION 'La acción es obligatoria';
    END IF;

    IF p_resource_type IS NULL OR TRIM(p_resource_type) = '' THEN
        RAISE EXCEPTION 'El tipo de recurso es obligatorio';
    END IF;

    INSERT INTO public.activity_log (
        user_id,
        company_id,
        action,
        resource_type,
        resource_id,
        description,
        metadata
    )
    VALUES (
        v_user_id,
        v_company_id,
        TRIM(p_action),
        TRIM(p_resource_type),
        p_resource_id,
        p_description,
        p_metadata
    )
    RETURNING * INTO v_activity;

    RETURN v_activity;
END;
$$;


ALTER FUNCTION "public"."log_activity"("p_action" "text", "p_resource_type" "text", "p_resource_id" "uuid", "p_description" "text", "p_metadata" "jsonb") OWNER TO "postgres";


