CREATE OR REPLACE FUNCTION "public"."mark_all_notifications_read"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

    v_updated_count INTEGER;

BEGIN

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- CUENTA ACTIVA
    -- --------------------------------------------------------

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION
            'Acceso denegado: la cuenta está bloqueada';
    END IF;


    -- --------------------------------------------------------
    -- ACTUALIZAR SOLO LAS PROPIAS
    -- --------------------------------------------------------

    UPDATE public.notifications
    SET read_at = CURRENT_TIMESTAMP
    WHERE user_id = auth.uid()
      AND read_at IS NULL;


    GET DIAGNOSTICS
        v_updated_count = ROW_COUNT;


    RETURN v_updated_count;

END;
$$;


ALTER FUNCTION "public"."mark_all_notifications_read"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_all_notifications_read"() IS 'Marca como leídas todas las notificaciones no leídas del usuario autenticado y activo.';



CREATE OR REPLACE FUNCTION "public"."mark_notification_read"("p_notification_id" "uuid") RETURNS "public"."notifications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

    v_notification public.notifications;

BEGIN

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- CUENTA ACTIVA
    -- --------------------------------------------------------

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION
            'Acceso denegado: la cuenta está bloqueada';
    END IF;


    -- --------------------------------------------------------
    -- NOTIFICACIÓN PROPIA
    -- --------------------------------------------------------

    SELECT *
    INTO v_notification
    FROM public.notifications
    WHERE id = p_notification_id
      AND user_id = auth.uid()
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Notificación no encontrada';
    END IF;


    -- --------------------------------------------------------
    -- MARCAR COMO LEÍDA
    --
    -- Si ya estaba leída, conservamos el timestamp original.
    -- --------------------------------------------------------

    IF v_notification.read_at IS NULL THEN

        UPDATE public.notifications
        SET read_at = CURRENT_TIMESTAMP
        WHERE id = p_notification_id
        RETURNING *
        INTO v_notification;

    END IF;


    RETURN v_notification;

END;
$$;


ALTER FUNCTION "public"."mark_notification_read"("p_notification_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_notification_read"("p_notification_id" "uuid") IS 'Marca como leída una notificación perteneciente al usuario autenticado y activo.';



CREATE OR REPLACE FUNCTION "public"."notify_client_when_milestone_completed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    -- --------------------------------------------------------
    -- SOLO CUANDO SE PRODUCE LA TRANSICIÓN A COMPLETADO
    -- --------------------------------------------------------

    IF NEW.estado = 'completado'
       AND (
            TG_OP = 'INSERT'
            OR OLD.estado IS DISTINCT FROM 'completado'
       )
    THEN

        PERFORM public.emit_project_client_notification(
            NEW.project_id,
            'milestone_completed',
            'Hito completado',
            'El hito "' ||
            LEFT(BTRIM(NEW.nombre), 180) ||
            '" ha sido completado.',
            jsonb_build_object(
                'milestone_id', NEW.id,
                'event', 'milestone_completed'
            )
        );

    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."notify_client_when_milestone_completed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."observed_request_ip"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_headers JSONB := '{}'::JSONB;
BEGIN
    BEGIN
        v_headers := COALESCE(
            NULLIF(
                current_setting('request.headers', TRUE),
                ''
            )::JSONB,
            '{}'::JSONB
        );
    EXCEPTION WHEN OTHERS THEN
        v_headers := '{}'::JSONB;
    END;

    RETURN COALESCE(
        NULLIF(
            TRIM(v_headers->>'cf-connecting-ip'),
            ''
        ),
        NULLIF(
            TRIM(v_headers->>'x-real-ip'),
            ''
        ),
        NULLIF(
            TRIM(
                SPLIT_PART(
                    COALESCE(v_headers->>'x-forwarded-for', ''),
                    ',',
                    1
                )
            ),
            ''
        )
    );
END;
$$;


ALTER FUNCTION "public"."observed_request_ip"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."observed_request_user_agent"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_headers JSONB := '{}'::JSONB;
BEGIN
    BEGIN
        v_headers := COALESCE(
            NULLIF(
                current_setting('request.headers', TRUE),
                ''
            )::JSONB,
            '{}'::JSONB
        );
    EXCEPTION WHEN OTHERS THEN
        v_headers := '{}'::JSONB;
    END;

    RETURN NULLIF(
        LEFT(
            TRIM(
                COALESCE(
                    v_headers->>'user-agent',
                    ''
                )
            ),
            2000
        ),
        ''
    );
END;
$$;


ALTER FUNCTION "public"."observed_request_user_agent"() OWNER TO "postgres";


