CREATE OR REPLACE FUNCTION "public"."process_due_expense_payments"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_payment_id uuid;
  v_processed integer := 0;
BEGIN
  FOR v_payment_id IN
    SELECT ep.id
    FROM public.expense_payments ep
    JOIN public.expenses e ON e.id = ep.expense_id
    WHERE ep.status = 'pending'
      AND ep.payment_date <= CURRENT_TIMESTAMP
      AND e.status IN ('pending_payment', 'partially_paid')
    ORDER BY ep.payment_date, ep.created_at
    LIMIT 500
    FOR UPDATE OF ep SKIP LOCKED
  LOOP
    BEGIN
      UPDATE public.expense_payments
      SET status = 'succeeded',
          updated_at = CURRENT_TIMESTAMP
      WHERE id = v_payment_id
        AND status = 'pending';

      IF FOUND THEN
        v_processed := v_processed + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING
        'No se ha podido procesar automáticamente el pago %: %',
        v_payment_id, SQLERRM;
    END;
  END LOOP;

  RETURN v_processed;
END;
$$;


ALTER FUNCTION "public"."process_due_expense_payments"() OWNER TO "postgres";


