CREATE OR REPLACE FUNCTION "public"."protect_budget_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN

    IF auth.uid() IS NULL THEN
        RETURN NEW;
    END IF;

    IF public.current_user_is_worker() THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN

        IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
            RAISE EXCEPTION
                'No se puede modificar el propietario del presupuesto';
        END IF;

        IF NEW.company_id IS DISTINCT FROM OLD.company_id THEN
            RAISE EXCEPTION
                'No se puede modificar la empresa del presupuesto';
        END IF;

    END IF;

    RETURN NEW;

END;
$$;


