CREATE OR REPLACE FUNCTION "public"."protect_invoice_paid_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

BEGIN

    -- ========================================================
    -- 1. NO HAY CAMBIO DE ESTADO
    -- ========================================================

    IF NEW.estado IS NOT DISTINCT FROM OLD.estado THEN
        RETURN NEW;
    END IF;


    -- ========================================================
    -- 2. UNA FACTURA YA PAGADA NO PUEDE RETROCEDER
    -- ========================================================

    IF LOWER(
        TRIM(
            COALESCE(OLD.estado, '')
        )
    ) = 'pagada'
    AND LOWER(
        TRIM(
            COALESCE(NEW.estado, '')
        )
    ) <> 'pagada'
    THEN

        RAISE EXCEPTION
            'Una factura pagada no puede volver a otro estado';

    END IF;


    -- ========================================================
    -- 3. PARA ENTRAR EN PAGADA DEBE EXISTIR UN PAGO EXITOSO
    -- ========================================================

    IF LOWER(
        TRIM(
            COALESCE(NEW.estado, '')
        )
    ) = 'pagada'
    AND LOWER(
        TRIM(
            COALESCE(OLD.estado, '')
        )
    ) <> 'pagada'
    THEN

        IF NOT EXISTS (
            SELECT 1
            FROM public.payments p
            WHERE p.invoice_id = NEW.id
              AND p.status = 'succeeded'
        ) THEN

            RAISE EXCEPTION
                'Una factura solo puede marcarse como pagada cuando existe un pago confirmado';

        END IF;

    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."protect_invoice_paid_status"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."protect_invoice_paid_status"() IS 'Protege el estado pagada de invoices: exige un payment succeeded para entrar en pagada y bloquea cualquier retroceso desde pagada. Compatible con register_stripe_invoice_payment().';



