CREATE OR REPLACE FUNCTION "public"."protect_quotation_direct_acceptance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_ack_count INTEGER;
BEGIN

    -- --------------------------------------------------------
    -- Solo nos interesa una transición hacia Aceptado.
    -- --------------------------------------------------------

    IF LOWER(TRIM(COALESCE(NEW.estado, ''))) <> 'aceptado' THEN
        RETURN NEW;
    END IF;


    -- --------------------------------------------------------
    -- Crear Aceptado directamente desde INSERT tampoco está
    -- permitido.
    -- --------------------------------------------------------

    IF TG_OP = 'INSERT' THEN

        RAISE EXCEPTION
            'Un presupuesto no puede crearse directamente como Aceptado; debe pasar por el proceso de aceptación contractual';

    END IF;


    -- --------------------------------------------------------
    -- Pendiente -> Aceptado requiere acknowledgement del PDF.
    -- --------------------------------------------------------

    IF LOWER(TRIM(COALESCE(OLD.estado, ''))) = 'pendiente' THEN

        SELECT COUNT(*)
        INTO v_ack_count
        FROM public.quotation_document_acknowledgements a
        WHERE a.quotation_id = NEW.id
          AND a.document_path = NEW.document_path
          AND LOWER(TRIM(a.document_sha256))
              = LOWER(TRIM(NEW.document_sha256));


        IF v_ack_count = 0 THEN
            RAISE EXCEPTION
                'No se puede aceptar el presupuesto sin una aceptación previa del PDF actualmente asociado';
        END IF;

    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."protect_quotation_direct_acceptance"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."protect_quotation_direct_acceptance"() IS 'Impide crear o modificar directamente un presupuesto a Aceptado sin acknowledgement previo del PDF actualmente asociado. La aceptación contractual continúa realizándose mediante respond_to_quotation().';



CREATE OR REPLACE FUNCTION "public"."protect_quotation_official_version_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.quotation_id IS DISTINCT FROM NEW.quotation_id
     OR OLD.version_major IS DISTINCT FROM NEW.version_major
     OR OLD.version_minor IS DISTINCT FROM NEW.version_minor
     OR OLD.version_label IS DISTINCT FROM NEW.version_label
     OR OLD.content_snapshot IS DISTINCT FROM NEW.content_snapshot
     OR OLD.published_by IS DISTINCT FROM NEW.published_by
     OR OLD.published_at IS DISTINCT FROM NEW.published_at THEN
    RAISE EXCEPTION 'El contenido y la identidad de una versión oficial son inmutables';
  END IF;

  IF OLD.document_path IS NOT NULL
     AND (OLD.document_path IS DISTINCT FROM NEW.document_path
       OR OLD.document_sha256 IS DISTINCT FROM NEW.document_sha256) THEN
    RAISE EXCEPTION 'El PDF y el hash de una versión oficial publicada son inmutables';
  END IF;

  IF OLD.client_response IS NOT NULL
     AND (OLD.client_response IS DISTINCT FROM NEW.client_response
       OR OLD.responded_by IS DISTINCT FROM NEW.responded_by
       OR OLD.responded_at IS DISTINCT FROM NEW.responded_at) THEN
    RAISE EXCEPTION 'La respuesta del cliente sobre una versión oficial es inmutable';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."protect_quotation_official_version_immutability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_quotation_project_owner_response"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_project_owner UUID;

BEGIN

    -- --------------------------------------------------------
    -- Solo nos interesa responder un presupuesto.
    -- --------------------------------------------------------

    IF LOWER(TRIM(COALESCE(OLD.estado, ''))) <> 'pendiente'
       OR LOWER(TRIM(COALESCE(NEW.estado, ''))) NOT IN (
            'aceptado',
            'rechazado'
       )
    THEN
        RETURN NEW;
    END IF;


    -- --------------------------------------------------------
    -- Los workers mantienen su autorización existente.
    -- --------------------------------------------------------

    IF public.current_user_is_worker() THEN
        RETURN NEW;
    END IF;


    -- --------------------------------------------------------
    -- Usuario autenticado.
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- Obtener propietario actual del proyecto.
    -- --------------------------------------------------------

    SELECT p.user_id
    INTO v_project_owner
    FROM public.projects p
    WHERE p.id = NEW.project_id;


    IF v_project_owner IS NULL THEN
        RAISE EXCEPTION
            'El presupuesto no tiene un propietario de proyecto válido';
    END IF;


    -- --------------------------------------------------------
    -- SOLO EL PROPIETARIO DEL PROYECTO
    -- --------------------------------------------------------

    IF v_project_owner IS DISTINCT FROM auth.uid() THEN

        RAISE EXCEPTION
            'Solo el propietario del proyecto puede responder a este presupuesto';

    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."protect_quotation_project_owner_response"() OWNER TO "postgres";


