CREATE OR REPLACE FUNCTION "public"."publish_legal_document_version"("p_document_type" "text", "p_version" "text", "p_title" "text", "p_content" "text", "p_effective_from" timestamp with time zone DEFAULT "now"()) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_document_id UUID;
    v_now TIMESTAMPTZ := clock_timestamp();
    v_content_hash TEXT;
BEGIN
    -- Solo se versionan estos dos tipos desde esta RPC.
    IF p_document_type IS NULL
       OR p_document_type NOT IN (
           'maintenance_contract_terms',
           'maintenance_specific_conditions'
       )
    THEN
        RAISE EXCEPTION
            'Tipo de documento no permitido: %',
            p_document_type;
    END IF;

    IF p_version IS NULL OR BTRIM(p_version) = '' THEN
        RAISE EXCEPTION 'La versión del documento es obligatoria';
    END IF;

    IF p_title IS NULL OR BTRIM(p_title) = '' THEN
        RAISE EXCEPTION 'El título del documento es obligatorio';
    END IF;

    IF p_content IS NULL OR BTRIM(p_content) = '' THEN
        RAISE EXCEPTION 'El contenido del documento es obligatorio';
    END IF;

    IF p_effective_from IS NULL THEN
        RAISE EXCEPTION 'La fecha de entrada en vigor es obligatoria';
    END IF;

    -- Esta implementación publica inmediatamente. Aceptar una fecha futura
    -- y desactivar ya la versión anterior dejaría el checkout sin términos
    -- vigentes hasta que llegase esa fecha.
    IF p_effective_from > v_now THEN
        RAISE EXCEPTION
            'La publicación debe entrar en vigor ahora o en una fecha pasada. No se admiten fechas futuras en esta versión de la función.';
    END IF;

    -- Evita que dos publicaciones del mismo tipo se pisen entre sí.
    PERFORM pg_advisory_xact_lock(
        hashtextextended('legal-document-publish:' || p_document_type, 0)
    );

    -- No se permite reutilizar el identificador de versión dentro del tipo.
    IF EXISTS (
        SELECT 1
        FROM public.legal_documents ld
        WHERE ld.document_type = p_document_type
          AND ld.version = p_version
    ) THEN
        RAISE EXCEPTION
            'La versión % ya existe para el documento %',
            p_version,
            p_document_type;
    END IF;

    -- SHA-256 del contenido exacto guardado, codificado en UTF-8.
    v_content_hash := encode(
        extensions.digest(convert_to(p_content, 'UTF8'), 'sha256'),
        'hex'
    );

    -- Cierra la versión que estaba vigente sin alterar su contenido/hash.
    UPDATE public.legal_documents
       SET is_current = FALSE,
           effective_until = CASE
               WHEN effective_until IS NULL
                    OR effective_until > p_effective_from
               THEN p_effective_from
               ELSE effective_until
           END
     WHERE document_type = p_document_type
       AND is_current = TRUE;

    INSERT INTO public.legal_documents (
        document_type,
        version,
        title,
        content,
        content_hash,
        effective_from,
        effective_until,
        is_current
    )
    VALUES (
        p_document_type,
        BTRIM(p_version),
        BTRIM(p_title),
        p_content,
        v_content_hash,
        p_effective_from,
        NULL,
        TRUE
    )
    RETURNING id INTO v_document_id;

    RETURN v_document_id;
END;
$$;


ALTER FUNCTION "public"."publish_legal_document_version"("p_document_type" "text", "p_version" "text", "p_title" "text", "p_content" "text", "p_effective_from" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_quotation_workflow_draft"("p_draft_id" "uuid", "p_publish_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_draft public.quotation_workflow_drafts%ROWTYPE;
  v_project public.projects%ROWTYPE;
  v_quotation public.quotations%ROWTYPE;
  v_state public.quotation_workflow_state%ROWTYPE;
  v_latest public.quotation_official_versions%ROWTYPE;
  v_version public.quotation_official_versions%ROWTYPE;
  v_content jsonb;
  v_major integer;
  v_minor integer;
  v_label text;
  v_permission text;
  v_fecha_validez timestamptz;
  v_fecha_emision timestamptz;
BEGIN
  IF auth.uid() IS NULL OR NOT public.current_user_is_worker() THEN
    RAISE EXCEPTION 'Acceso denegado: se requiere un trabajador autenticado';
  END IF;
  IF p_publish_mode IS NULL OR p_publish_mode NOT IN ('initial', 'correction', 'requested_change') THEN
    RAISE EXCEPTION 'Modo de publicación no válido';
  END IF;

  SELECT * INTO v_draft
  FROM public.quotation_workflow_drafts
  WHERE id = p_draft_id
  FOR UPDATE;
  IF NOT FOUND OR v_draft.draft_status <> 'draft' THEN
    RAISE EXCEPTION 'El borrador no existe o ya ha sido publicado';
  END IF;
  IF v_draft.draft_kind <> p_publish_mode THEN
    RAISE EXCEPTION 'El modo de publicación no coincide con el tipo de borrador';
  END IF;

  v_permission := CASE WHEN p_publish_mode = 'initial' THEN 'quotations.create' ELSE 'quotations.update' END;
  PERFORM public.require_current_worker_permission(v_permission);
  PERFORM public.enforce_security_rate_limit(
    'quotation_workflow:publish:' || auth.uid()::text, 12, 3600
  );

  v_content := public.validate_quotation_workflow_content(v_draft.content);
  SELECT * INTO v_project FROM public.projects WHERE id = v_draft.project_id FOR SHARE;
  IF NOT FOUND OR v_project.company_id IS DISTINCT FROM v_draft.company_id THEN
    RAISE EXCEPTION 'El proyecto del borrador ya no es válido';
  END IF;

  IF NULLIF(btrim(v_content->>'titulo'), '') IS NULL THEN
    RAISE EXCEPTION 'El título es obligatorio para publicar';
  END IF;
  IF jsonb_typeof(v_content->'servicios_incluidos') <> 'array'
     OR jsonb_array_length(v_content->'servicios_incluidos') = 0 THEN
    RAISE EXCEPTION 'Debe existir al menos un servicio para publicar';
  END IF;

  IF v_content->'fecha_validez' IS NULL OR v_content->'fecha_validez' = 'null'::jsonb THEN
    v_fecha_validez := NULL;
  ELSE
    v_fecha_validez := (v_content->>'fecha_validez')::timestamptz;
  END IF;

  IF p_publish_mode = 'initial' THEN
    IF v_draft.quotation_id IS NOT NULL THEN
      RAISE EXCEPTION 'Un borrador inicial no puede estar vinculado a un presupuesto existente';
    END IF;

    v_quotation := public.create_quotation_by_worker(
      v_draft.company_id,
      v_draft.project_id,
      v_content->>'titulo',
      NULLIF(v_content->>'descripcion_detallada', ''),
      v_content->'servicios_incluidos',
      (v_content->>'iva_porcentaje')::numeric,
      (v_content->>'irpf_aplicado')::boolean,
      (v_content->>'irpf_porcentaje')::numeric,
      'Pendiente',
      now(),
      v_fecha_validez,
      NULLIF(v_content->>'notas', '')
    );

    v_major := 1;
    v_minor := 0;
  ELSE
    IF v_draft.quotation_id IS NULL THEN
      RAISE EXCEPTION 'El borrador no está vinculado a un presupuesto';
    END IF;

    SELECT * INTO v_quotation
    FROM public.quotations
    WHERE id = v_draft.quotation_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Presupuesto no encontrado';
    END IF;
    IF v_quotation.estado <> 'Pendiente' THEN
      RAISE EXCEPTION 'Solo se puede publicar una versión de un presupuesto pendiente';
    END IF;

    SELECT * INTO v_state
    FROM public.quotation_workflow_state
    WHERE quotation_id = v_quotation.id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'El presupuesto no dispone de estado de flujo';
    END IF;

    SELECT * INTO v_latest
    FROM public.quotation_official_versions
    WHERE id = v_state.current_version_id AND quotation_id = v_quotation.id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'No se encuentra la versión oficial actual';
    END IF;

    IF p_publish_mode = 'correction' AND v_state.workflow_status <> 'presented' THEN
      RAISE EXCEPTION 'Una corrección solo puede publicarse mientras se espera la respuesta del cliente';
    ELSIF p_publish_mode = 'requested_change' AND v_state.workflow_status <> 'in_review' THEN
      RAISE EXCEPTION 'Solo se puede publicar una nueva versión si hay una solicitud de cambio pendiente';
    END IF;

    v_fecha_emision := v_quotation.fecha_emision;
    v_quotation := public.update_quotation_by_worker(
      v_quotation.id,
      v_draft.project_id,
      v_content->>'titulo',
      NULLIF(v_content->>'descripcion_detallada', ''),
      v_content->'servicios_incluidos',
      (v_content->>'iva_porcentaje')::numeric,
      (v_content->>'irpf_aplicado')::boolean,
      (v_content->>'irpf_porcentaje')::numeric,
      'Pendiente',
      v_fecha_emision,
      v_fecha_validez,
      NULLIF(v_content->>'notas', '')
    );

    IF p_publish_mode = 'requested_change' THEN
      v_major := v_latest.version_major + 1;
      v_minor := 0;
    ELSE
      v_major := v_latest.version_major;
      v_minor := v_latest.version_minor + 1;
    END IF;
  END IF;

  v_label := 'V' || v_major::text || CASE WHEN v_minor > 0 THEN '.' || v_minor::text ELSE '' END;

  UPDATE public.quotation_official_versions
  SET is_current = false
  WHERE quotation_id = v_quotation.id AND is_current = true;

  INSERT INTO public.quotation_official_versions (
    quotation_id, version_major, version_minor, version_label,
    content_snapshot, is_current, published_by, published_at
  )
  VALUES (
    v_quotation.id, v_major, v_minor, v_label,
    to_jsonb(v_quotation), true, auth.uid(), now()
  )
  RETURNING * INTO v_version;

  INSERT INTO public.quotation_workflow_state (
    quotation_id, current_version_id, workflow_status, updated_at, updated_by
  )
  VALUES (v_quotation.id, v_version.id, 'presented', now(), auth.uid())
  ON CONFLICT (quotation_id) DO UPDATE
    SET current_version_id = EXCLUDED.current_version_id,
        workflow_status = 'presented',
        updated_at = now(),
        updated_by = auth.uid();

  IF p_publish_mode = 'requested_change' THEN
    UPDATE public.quotation_change_requests
    SET request_status = 'resolved',
        resolved_at = now(),
        resolved_by = auth.uid(),
        resolved_version_id = v_version.id
    WHERE quotation_id = v_quotation.id AND request_status = 'open';
  END IF;

  UPDATE public.quotation_workflow_drafts
  SET quotation_id = v_quotation.id,
      draft_status = 'published',
      published_at = now(),
      published_version_id = v_version.id,
      updated_at = now()
  WHERE id = v_draft.id;

  RETURN jsonb_build_object(
    'quotation_id', v_quotation.id,
    'numero_presupuesto', v_quotation.numero_presupuesto,
    'version_id', v_version.id,
    'version_label', v_label,
    'workflow_status', 'presented',
    'quotation', to_jsonb(v_quotation)
  );
END;
$$;


ALTER FUNCTION "public"."publish_quotation_workflow_draft"("p_draft_id" "uuid", "p_publish_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rate_limit_company_change_request"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_rate_key TEXT;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF public.current_user_is_worker() THEN
    RETURN NEW;
  END IF;

  IF NEW.current_company_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_rate_key :=
    'company_change:' || NEW.current_company_id::TEXT;

  PERFORM public.enforce_security_rate_limit(
    v_rate_key,
    3,
    86400
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."rate_limit_company_change_request"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rate_limit_company_iva_change_request"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_user_id UUID;
    v_is_worker BOOLEAN;

BEGIN

    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN NEW;
    END IF;


    v_is_worker := public.current_user_is_worker();


    -- --------------------------------------------------------
    -- CLIENTE CREA SOLICITUD
    -- --------------------------------------------------------

    IF TG_OP = 'INSERT'
       AND NOT v_is_worker
    THEN

        PERFORM public.enforce_security_rate_limit(
            'company_iva_change_request:client:' || v_user_id::TEXT,
            3,
            86400
        );

        RETURN NEW;

    END IF;


    -- --------------------------------------------------------
    -- WORKER RESUELVE SOLICITUD
    -- --------------------------------------------------------

    IF TG_OP = 'UPDATE'
       AND v_is_worker
    THEN

        PERFORM public.enforce_security_rate_limit(
            'company_iva_change_request:worker:' || v_user_id::TEXT,
            60,
            3600
        );

        RETURN NEW;

    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."rate_limit_company_iva_change_request"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rate_limit_company_worker_notes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_rate_key TEXT;
BEGIN
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN NEW;
    END IF;

    IF NOT public.current_user_is_worker() THEN
        RETURN NEW;
    END IF;

    IF NEW.worker_notes IS NOT DISTINCT FROM OLD.worker_notes THEN
        RETURN NEW;
    END IF;

    v_rate_key :=
        'companies:worker_notes:update:' || v_user_id::TEXT;

    PERFORM public.enforce_security_rate_limit(
        v_rate_key,
        10,
        3600
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."rate_limit_company_worker_notes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rate_limit_maintenance_iva_change_request"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_user_id UUID;
