CREATE OR REPLACE FUNCTION "public"."rate_limit_profile_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_rate_key TEXT;
BEGIN

  v_user_id := auth.uid();


  -- ----------------------------------------------------------
  -- Sin sesión autenticada:
  -- no aplicar este límite.
  --
  -- La autorización/RLS existente continúa siendo la encargada
  -- de impedir actualizaciones no autorizadas.
  -- ----------------------------------------------------------

  IF v_user_id IS NULL THEN
    RETURN NEW;
  END IF;


  -- ----------------------------------------------------------
  -- Los workers utilizan sus propios mecanismos internos.
  -- No consumir el rate limit de clientes.
  -- ----------------------------------------------------------

  IF public.current_user_is_worker() THEN
    RETURN NEW;
  END IF;


  -- ----------------------------------------------------------
  -- Solo contar cambios reales de los campos que el cliente
  -- puede modificar.
  --
  -- Un UPDATE que envíe el mismo nombre/teléfono no consume
  -- una operación.
  -- ----------------------------------------------------------

  IF NEW.nombre IS NOT DISTINCT FROM OLD.nombre
     AND NEW.telefono IS NOT DISTINCT FROM OLD.telefono
  THEN
    RETURN NEW;
  END IF;


  -- ----------------------------------------------------------
  -- 7 cambios por usuario cada 1 hora.
  -- ----------------------------------------------------------

  v_rate_key :=
    'profiles:update:' || v_user_id::TEXT;

  PERFORM public.enforce_security_rate_limit(
    v_rate_key,
    7,
    3600
  );


  RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."rate_limit_profile_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rate_limit_quotation_workflow_field_changes"("p_user_id" "uuid", "p_old_content" "jsonb", "p_new_content" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_field text;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  -- Límite general: 60 guardados por usuario/hora (se consume por operación).
  PERFORM public.enforce_security_rate_limit(
    'quotation_draft:save:' || p_user_id::text, 60, 3600
  );

  -- Cada campo editable dispone de su propio límite: 30 cambios por usuario/hora.
  -- Solo consume el límite de un campo si su valor cambia realmente.
  FOREACH v_field IN ARRAY ARRAY[
    'titulo', 'descripcion_detallada', 'servicios_incluidos',
    'iva_porcentaje', 'irpf_aplicado', 'irpf_porcentaje',
    'fecha_validez', 'notas'
  ]
  LOOP
    IF (p_old_content->v_field) IS DISTINCT FROM (p_new_content->v_field) THEN
      PERFORM public.enforce_security_rate_limit(
        'quotation_draft:field:' || v_field || ':' || p_user_id::text,
        30,
        3600
      );
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rate_limit_quotation_workflow_field_changes"("p_user_id" "uuid", "p_old_content" "jsonb", "p_new_content" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reassign_project_task"("p_task_id" "uuid", "p_assigned_to_worker_id" "uuid") RETURNS "public"."project_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.project_tasks;
    v_old_worker_id UUID;
BEGIN

    IF public.current_project_task_worker_id() IS NULL THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.update'
    );

    IF NOT public.current_worker_is_direction() THEN
        RAISE EXCEPTION
            'Solo Dirección puede reasignar tareas';
    END IF;

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:reassign:' || auth.uid()::TEXT,
        120,
        3600
    );

    PERFORM public.validate_project_task_assignee(
        p_assigned_to_worker_id
    );

    SELECT *
    INTO v_task
    FROM public.project_tasks
    WHERE id = p_task_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Tarea no encontrada';
    END IF;

    v_old_worker_id := v_task.assigned_to_worker_id;

    UPDATE public.project_tasks
    SET
        assigned_to_worker_id = p_assigned_to_worker_id
    WHERE id = v_task.id
    RETURNING *
    INTO v_task;

    PERFORM public.record_project_task_update(
        v_task.id,
        'reassigned',
        v_task.status,
        v_task.progress,
        v_task.status,
        v_task.progress,
        NULL
    );

    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."reassign_project_task"("p_task_id" "uuid", "p_assigned_to_worker_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_expense_totals"("p_expense_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_subtotal NUMERIC(14,2);

  v_total_tax NUMERIC(14,2);

  v_total_withholding NUMERIC(14,2);

  v_total_amount NUMERIC(14,2);

BEGIN

  IF p_expense_id IS NULL THEN
    RAISE EXCEPTION
      'recalculate_expense_totals: expense_id es obligatorio';
  END IF;


  SELECT
    ROUND(COALESCE(subtotal, 0), 2)
  INTO
    v_subtotal
  FROM public.expenses
  WHERE id = p_expense_id;


  IF NOT FOUND THEN
    RAISE EXCEPTION
      'recalculate_expense_totals: el gasto % no existe',
      p_expense_id;
  END IF;


  SELECT
    ROUND(
      COALESCE(
        SUM(
          CASE
            WHEN tax_type IN ('vat', 'other')
              THEN tax_amount
            ELSE 0
          END
        ),
        0
      ),
      2
    ),

    ROUND(
      COALESCE(
        SUM(
          CASE
            WHEN tax_type = 'withholding'
              THEN tax_amount
            ELSE 0
          END
        ),
        0
      ),
      2
    )

  INTO
    v_total_tax,
    v_total_withholding

  FROM public.expense_tax_lines

  WHERE expense_id = p_expense_id;


  v_total_amount :=
    ROUND(
      GREATEST(
        v_subtotal
        + v_total_tax
        - v_total_withholding,
        0
      ),
      2
    );


  UPDATE public.expenses

  SET
    total_tax = v_total_tax,
    total_withholding = v_total_withholding,
    total_amount = v_total_amount,
    updated_at = CURRENT_TIMESTAMP

  WHERE id = p_expense_id;

END;
$$;


ALTER FUNCTION "public"."recalculate_expense_totals"("p_expense_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_cookie_consent"("p_analytics" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_policy_version CONSTANT TEXT := '2026-09';
    v_consent_id UUID;
BEGIN

    -- --------------------------------------------------------
    -- VALIDACIÓN DE ENTRADA
    -- --------------------------------------------------------
    --
    -- La decisión debe ser explícitamente TRUE o FALSE.
    -- NULL no representa una decisión válida.
    --
    -- --------------------------------------------------------

    IF p_analytics IS NULL THEN
        RAISE EXCEPTION
            'Decisión de cookies no válida.';
    END IF;


    -- --------------------------------------------------------
    -- REGISTRAR DECISIÓN
    -- --------------------------------------------------------
    --
    -- PostgreSQL genera:
    -- - UUID del registro
    -- - fecha/hora del servidor
    --
    -- La versión procede de la propia función.
    --
    -- --------------------------------------------------------

    INSERT INTO public.cookie_consents (
        analytics,
        policy_version
    )
    VALUES (
        p_analytics,
        v_policy_version
    )
    RETURNING id
    INTO v_consent_id;


    RETURN v_consent_id;

END;
$$;


ALTER FUNCTION "public"."record_cookie_consent"("p_analytics" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_cookie_consent"("p_analytics" boolean) IS 'Registra una decisión de consentimiento de cookies. La versión de la Política de Cookies y la fecha del registro se determinan en el servidor.';



CREATE TABLE IF NOT EXISTS "public"."invoice_document_acknowledgements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "invoice_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "document_path" "text" NOT NULL,
    "document_sha256" "text" NOT NULL,
    "acknowledgement_text_version" "text" NOT NULL,
    "accepted_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "invoice_ack_document_path_not_empty" CHECK (("length"(TRIM(BOTH FROM "document_path")) > 0)),
    CONSTRAINT "invoice_ack_document_sha256_format" CHECK (("document_sha256" ~ '^[0-9a-fA-F]{64}$'::"text")),
    CONSTRAINT "invoice_ack_text_version_not_empty" CHECK (("length"(TRIM(BOTH FROM "acknowledgement_text_version")) > 0))
);


ALTER TABLE "public"."invoice_document_acknowledgements" OWNER TO "postgres";


COMMENT ON TABLE "public"."invoice_document_acknowledgements" IS 'Registro de aceptación del documento PDF asociado a una factura antes de iniciar el pago.';



COMMENT ON COLUMN "public"."invoice_document_acknowledgements"."document_sha256" IS 'SHA-256 exacto del PDF que el usuario aceptó.';



COMMENT ON COLUMN "public"."invoice_document_acknowledgements"."acknowledgement_text_version" IS 'Versión del texto mostrado al usuario en el momento de la aceptación.';



COMMENT ON COLUMN "public"."invoice_document_acknowledgements"."accepted_at" IS 'Fecha y hora de la aceptación del documento.';



CREATE OR REPLACE FUNCTION "public"."record_invoice_document_acknowledgement"("p_invoice_id" "uuid") RETURNS "public"."invoice_document_acknowledgements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$

DECLARE
    v_user_id UUID;
    v_invoice public.invoices;
    v_acknowledgement public.invoice_document_acknowledgements;

    -- --------------------------------------------------------
    -- Debe coincidir con el texto/versionado utilizado en
    -- frontend y create-checkout-session.
    -- --------------------------------------------------------
    v_acknowledgement_text_version TEXT :=
        'invoice_document_acknowledgement_v1';

BEGIN

    -- ========================================================
    -- 1. USUARIO AUTENTICADO
    -- ========================================================

    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION
            'Debes iniciar sesión para aceptar el documento de la factura';
    END IF;


    -- ========================================================
    -- 2. LOS WORKERS NO UTILIZAN ESTA RPC
    -- ========================================================
    --
    -- Esta función registra una aceptación realizada por el
    -- cliente propietario de la factura.
    --
    -- La gestión de documentos por workers utiliza las RPC
    -- específicas de workers.
    -- ========================================================

    IF public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Los trabajadores no pueden registrar una aceptación de cliente';
    END IF;


    -- ========================================================
    -- 3. INVOICE ID OBLIGATORIO
    -- ========================================================

    IF p_invoice_id IS NULL THEN
        RAISE EXCEPTION
            'La factura es obligatoria';
    END IF;


    -- ========================================================
    -- 4. OBTENER FACTURA DEL USUARIO
    -- ========================================================
    --
    -- IMPORTANTE:
    --
    -- No utilizamos el document_path ni el hash enviados por
    -- el navegador.
    --
    -- Se obtiene la factura directamente desde la BD y se exige:
    --
    --     invoices.id = p_invoice_id
    --     invoices.user_id = auth.uid()
    --
    -- La función es SECURITY DEFINER, por lo que esta comprobación
    -- debe hacerse explícitamente.
    -- ========================================================

    SELECT *
    INTO v_invoice
    FROM public.invoices
    WHERE id = p_invoice_id
      AND user_id = v_user_id;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La factura no existe o no tienes acceso a ella';
    END IF;


    -- ========================================================
    -- 5. COMPROBAR ESTADO DE LA FACTURA
    -- ========================================================
    --
    -- Se mantiene el mismo criterio utilizado por
    -- create-checkout-session:
    --
    --   pendiente → aceptable
    --   vencida   → aceptable
    --
    --   pagada    → no tiene sentido aceptar para iniciar pago
    --   cancelada → no puede pagarse
    --
    -- Si en el futuro se añaden estados pagables, deberán
    -- añadirse explícitamente aquí y en create-checkout-session.
    -- ========================================================

    IF LOWER(TRIM(COALESCE(v_invoice.estado, ''))) NOT IN (
        'pendiente',
        'vencida'
    ) THEN

        RAISE EXCEPTION
            'Esta factura no se encuentra en un estado que permita iniciar el pago';

    END IF;


    -- ========================================================
    -- 6. PDF OBLIGATORIO
    -- ========================================================
    --
    -- No se permite registrar una aceptación si la factura no
    -- tiene documento asociado.
    -- ========================================================

    IF v_invoice.document_path IS NULL
       OR TRIM(v_invoice.document_path) = ''
    THEN

        RAISE EXCEPTION
            'La factura no tiene un documento PDF asociado';

    END IF;


    -- ========================================================
    -- 7. SHA-256 OBLIGATORIO
    -- ========================================================
    --
    -- El hash debe haber sido calculado previamente por el flujo
    -- server-side de set-invoice-document-hash.
    --
    -- El cliente nunca puede proporcionar este valor.
    -- ========================================================

    IF v_invoice.document_sha256 IS NULL
       OR TRIM(v_invoice.document_sha256) = ''
       OR LOWER(TRIM(v_invoice.document_sha256))
          !~ '^[0-9a-f]{64}$'
    THEN

        RAISE EXCEPTION
            'El documento de la factura todavía no está validado';

    END IF;


    -- ========================================================
    -- 8. REGISTRAR ACEPTACIÓN
    -- ========================================================
    --
    -- Todos los datos sensibles se obtienen del servidor:
    --
    -- user_id
    -- invoice_id
    -- document_path
    -- document_sha256
    -- acknowledgement_text_version
    -- accepted_at
    --
    -- El cliente únicamente proporciona invoice_id.
    -- ========================================================

    INSERT INTO public.invoice_document_acknowledgements (
        invoice_id,
        user_id,
        document_path,
        document_sha256,
        acknowledgement_text_version,
        accepted_at
    )
    VALUES (
        v_invoice.id,
        v_user_id,
        TRIM(v_invoice.document_path),
        LOWER(TRIM(v_invoice.document_sha256)),
        v_acknowledgement_text_version,
        CURRENT_TIMESTAMP
    )
    ON CONFLICT (
        invoice_id,
        user_id,
        document_sha256,
        acknowledgement_text_version
    )
    DO UPDATE
    SET
        document_path = EXCLUDED.document_path,
        accepted_at = EXCLUDED.accepted_at
    RETURNING *
    INTO v_acknowledgement;


    -- ========================================================
    -- 9. COMPROBACIÓN FINAL
    -- ========================================================

    IF v_acknowledgement.id IS NULL THEN
        RAISE EXCEPTION
            'No se ha podido registrar la aceptación del documento';
    END IF;


    RETURN v_acknowledgement;

END;
$_$;


ALTER FUNCTION "public"."record_invoice_document_acknowledgement"("p_invoice_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_invoice_document_acknowledgement"("p_invoice_id" "uuid") IS 'Registra la aceptación de un cliente del PDF actualmente asociado a una factura. El documento y su SHA-256 se obtienen exclusivamente desde invoices; el cliente solo proporciona invoice_id.';



CREATE TABLE IF NOT EXISTS "public"."maintenance_custom_proposal_document_acknowledgements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "proposal_id" "uuid" NOT NULL,
    "document_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "company_id" "uuid" NOT NULL,
    "document_path" "text" NOT NULL,
    "document_sha256" "text" NOT NULL,
    "acknowledgement_text_version" "text" NOT NULL,
    "accepted_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "maintenance_custom_proposal_ack_path_check" CHECK ((("length"("btrim"("document_path")) > 0) AND ("length"("document_path") <= 500))),
    CONSTRAINT "maintenance_custom_proposal_ack_sha256_check" CHECK (("document_sha256" ~ '^[0-9a-fA-F]{64}$'::"text")),
    CONSTRAINT "maintenance_custom_proposal_ack_version_check" CHECK ((("length"("btrim"("acknowledgement_text_version")) > 0) AND ("length"("acknowledgement_text_version") <= 100)))
);


ALTER TABLE "public"."maintenance_custom_proposal_document_acknowledgements" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_maintenance_custom_proposal_document_acknowledgement"("p_proposal_id" "uuid") RETURNS "public"."maintenance_custom_proposal_document_acknowledgements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$

DECLARE
    v_user_id UUID;
    v_proposal public.maintenance_custom_proposals;
    v_document
        public.maintenance_custom_proposal_documents;
    v_ack
        public.maintenance_custom_proposal_document_acknowledgements;

    v_text_version TEXT :=
        'maintenance_custom_proposal_document_acknowledgement_v1';

BEGIN

    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION
            'Debes iniciar sesión';
    END IF;

    IF public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Los trabajadores no pueden registrar el acknowledgement del cliente';
    END IF;

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION
            'El usuario no está activo';
    END IF;

    SELECT *
    INTO v_proposal
    FROM public.maintenance_custom_proposals
    WHERE id = p_proposal_id
      AND user_id = v_user_id
      AND company_id = public.current_user_company_id()
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La propuesta no existe o no tienes acceso a ella';
    END IF;

    IF v_proposal.status <> 'quoted' THEN
        RAISE EXCEPTION
            'La propuesta todavía no está disponible para aceptación';
    END IF;

    PERFORM public.enforce_security_rate_limit(
        'maintenance_proposal_acknowledgement:' || auth.uid()::TEXT || ':' || p_proposal_id::TEXT,
        10,
        86400
    );



    IF v_proposal.current_document_id IS NULL THEN
        RAISE EXCEPTION
            'La propuesta no tiene un PDF publicado';
    END IF;

    SELECT *
    INTO v_document
    FROM public.maintenance_custom_proposal_documents
    WHERE id = v_proposal.current_document_id
      AND proposal_id = v_proposal.id
      AND published_at IS NOT NULL
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El PDF publicado de la propuesta no está disponible';
    END IF;

    INSERT INTO public.maintenance_custom_proposal_document_acknowledgements (
        proposal_id,
        document_id,
        user_id,
        company_id,
        document_path,
        document_sha256,
        acknowledgement_text_version,
        accepted_at
    )
    VALUES (
        v_proposal.id,
        v_document.id,
        v_user_id,
        v_proposal.company_id,
        v_document.document_path,
        LOWER(v_document.document_sha256),
        v_text_version,
        CURRENT_TIMESTAMP
    )
    ON CONFLICT (
        proposal_id,
        user_id,
        document_id,
        acknowledgement_text_version
    )
    DO UPDATE
    SET
        document_path = EXCLUDED.document_path,
        document_sha256 = EXCLUDED.document_sha256,
        accepted_at = EXCLUDED.accepted_at
    RETURNING *
    INTO v_ack;


    INSERT INTO public.maintenance_custom_proposal_events (
        proposal_id,
        actor_id,
        actor_type,
        event_type,
        notes,
        metadata
    )
    VALUES (
        v_proposal.id,
        v_user_id,
        'client',
        'document_acknowledged',
        'El cliente ha confirmado que ha leído/revisado el PDF publicado.',
        jsonb_build_object(
            'document_id', v_document.id,
            'document_version', v_document.version,
            'document_sha256', v_document.document_sha256,
            'acknowledgement_text_version', v_text_version
        )
    );


    RETURN v_ack;

END;
$$;


ALTER FUNCTION "public"."record_maintenance_custom_proposal_document_acknowledgement"("p_proposal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_maintenance_custom_proposal_status_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$

DECLARE
    v_actor_id UUID;
    v_actor_type TEXT;
    v_event_type TEXT;
    v_notes TEXT;
BEGIN

    v_actor_id := auth.uid();

    IF v_actor_id IS NULL THEN
        v_actor_type := 'system';
    ELSIF public.current_user_is_worker() THEN
        v_actor_type := 'worker';
    ELSE
        v_actor_type := 'client';
    END IF;

    IF TG_OP = 'INSERT' THEN

        v_event_type := 'created';

        INSERT INTO public.maintenance_custom_proposal_events (
            proposal_id,
            actor_id,
            actor_type,
            event_type,
            old_status,
            new_status
        )
        VALUES (
            NEW.id,
            v_actor_id,
            v_actor_type,
            v_event_type,
            NULL,
            NEW.status
        );

        RETURN NEW;

    END IF;


    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RETURN NEW;
    END IF;


    v_event_type :=
        CASE NEW.status
            WHEN 'submitted'
                THEN 'submitted'
            WHEN 'in_review'
                THEN 'review_started'
            WHEN 'clarification_requested'
                THEN 'clarification_requested'
            WHEN 'quoted'
                THEN 'quoted'
            WHEN 'rejected'
                THEN 'rejected'
            WHEN 'accepted'
                THEN 'accepted'
            WHEN 'expired'
                THEN 'expired'
            WHEN 'cancelled'
                THEN 'cancelled'
            ELSE NULL
        END;

    IF v_event_type IS NULL THEN
        RETURN NEW;
    END IF;


    v_notes :=
        CASE NEW.status
            WHEN 'rejected'
                THEN NEW.rejection_reason
            WHEN 'clarification_requested'
                THEN NEW.clarification_message
            ELSE NULL
        END;


    INSERT INTO public.maintenance_custom_proposal_events (
        proposal_id,
        actor_id,
        actor_type,
        event_type,
        old_status,
        new_status,
        notes,
        metadata
    )
    VALUES (
        NEW.id,
        v_actor_id,
        v_actor_type,
        v_event_type,
        OLD.status,
        NEW.status,
        v_notes,
        CASE
            WHEN NEW.status = 'quoted'
            THEN jsonb_build_object(
                'response_version',
                NEW.response_version,
                'quoted_monthly_price',
                NEW.quoted_monthly_price,
                'quoted_currency',
                NEW.quoted_currency,
                'quoted_valid_until',
                NEW.quoted_valid_until,
                'current_document_id',
                NEW.current_document_id
            )
            ELSE NULL
        END
    );


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."record_maintenance_custom_proposal_status_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_maintenance_legal_acceptances"("p_user_id" "uuid", "p_company_id" "uuid", "p_checkout_attempt_id" "uuid", "p_checkout_session_id" "text", "p_plan_id" "uuid", "p_expected_general_version" "text", "p_expected_specific_version" "text", "p_proposal_id" "uuid" DEFAULT NULL::"uuid", "p_general_accepted" boolean DEFAULT false, "p_specific_accepted" boolean DEFAULT false, "p_ip" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_profile_company_id UUID;
    v_profile_status TEXT;

    v_general_id UUID;
    v_general_version TEXT;
    v_general_hash TEXT;

    v_specific_id UUID;
    v_specific_version TEXT;
    v_specific_hash TEXT;

    v_existing_count INTEGER;
    v_existing_general_count INTEGER;
    v_existing_specific_count INTEGER;
    v_existing_general_version TEXT;
    v_existing_specific_version TEXT;
    v_existing_general_id UUID;
    v_existing_specific_id UUID;
    v_existing_general_hash TEXT;
    v_existing_specific_hash TEXT;

    v_now TIMESTAMPTZ;
    v_ip TEXT;
    v_user_agent TEXT;
BEGIN
    -- Validación de los datos obligatorios del checkout.
    IF p_user_id IS NULL
       OR p_company_id IS NULL
       OR p_checkout_attempt_id IS NULL
       OR NULLIF(BTRIM(p_checkout_session_id), '') IS NULL
       OR p_plan_id IS NULL
    THEN
        RAISE EXCEPTION 'Faltan datos obligatorios del checkout de mantenimiento';
    END IF;

    IF NULLIF(BTRIM(p_expected_general_version), '') IS NULL THEN
        RAISE EXCEPTION 'Falta la versión esperada de las condiciones generales';
    END IF;

    IF NULLIF(BTRIM(p_expected_specific_version), '') IS NULL THEN
        RAISE EXCEPTION 'Falta la versión esperada de las condiciones particulares';
    END IF;

    IF p_general_accepted IS NOT TRUE THEN
        RAISE EXCEPTION 'Debes aceptar las condiciones generales de mantenimiento';
    END IF;

    IF p_specific_accepted IS NOT TRUE THEN
        RAISE EXCEPTION 'Debes aceptar las condiciones particulares de mantenimiento';
    END IF;

    -- Un mismo intento se procesa de forma serializada.
    PERFORM pg_advisory_xact_lock(
        hashtextextended('maintenance-legal-checkout:' || p_checkout_attempt_id::TEXT, 0)
    );

    -- Compartir los mismos bloqueos por tipo que la RPC de publicación.
    -- Así una publicación no puede cambiar un documento entre la lectura
    -- de las versiones vigentes y la inserción de las aceptaciones.
    PERFORM pg_advisory_xact_lock(
        hashtextextended('legal-document-publish:maintenance_contract_terms', 0)
    );
    PERFORM pg_advisory_xact_lock(
        hashtextextended('legal-document-publish:maintenance_specific_conditions', 0)
    );

    -- Tomar la hora después de adquirir los bloqueos.
    v_now := clock_timestamp();

    -- Idempotencia: un reintento solo puede recuperar las dos evidencias
    -- del mismo intento/sesión y con las mismas versiones esperadas.
    SELECT COUNT(*)
      INTO v_existing_count
      FROM public.legal_acceptances la
     WHERE la.context = 'maintenance_checkout'
       AND la.metadata ->> 'maintenance_checkout_attempt_id' = p_checkout_attempt_id::TEXT;

    IF v_existing_count > 0 THEN
        IF v_existing_count <> 2 THEN
            RAISE EXCEPTION 'El intento de checkout ya tiene un registro legal incompleto o inconsistente';
        END IF;

        IF EXISTS (
            SELECT 1
              FROM public.legal_acceptances la
             WHERE la.context = 'maintenance_checkout'
               AND la.metadata ->> 'maintenance_checkout_attempt_id' = p_checkout_attempt_id::TEXT
               AND (
                   la.metadata ->> 'stripe_checkout_session_id' IS DISTINCT FROM p_checkout_session_id
                   OR la.user_id IS DISTINCT FROM p_user_id
                   OR la.company_id IS DISTINCT FROM p_company_id
                   OR la.metadata ->> 'plan_id' IS DISTINCT FROM p_plan_id::TEXT
                   OR la.metadata ->> 'document_version' IS NULL
               )
        ) THEN
            RAISE EXCEPTION 'El intento de checkout ya tiene un registro legal inconsistente';
        END IF;

        SELECT COUNT(*),
               (ARRAY_AGG(la.document_id) FILTER (
                   WHERE la.metadata ->> 'document_type' = 'maintenance_contract_terms'
               ))[1],
               MAX(la.metadata ->> 'document_version') FILTER (
                   WHERE la.metadata ->> 'document_type' = 'maintenance_contract_terms'
               ),
               MAX(la.document_hash) FILTER (
                   WHERE la.metadata ->> 'document_type' = 'maintenance_contract_terms'
               )
          INTO v_existing_general_count,
               v_existing_general_id,
               v_existing_general_version,
               v_existing_general_hash
          FROM public.legal_acceptances la
         WHERE la.context = 'maintenance_checkout'
           AND la.metadata ->> 'maintenance_checkout_attempt_id' = p_checkout_attempt_id::TEXT
           AND la.metadata ->> 'document_type' = 'maintenance_contract_terms';

        SELECT COUNT(*),
               (ARRAY_AGG(la.document_id) FILTER (
                   WHERE la.metadata ->> 'document_type' = 'maintenance_specific_conditions'
               ))[1],
               MAX(la.metadata ->> 'document_version') FILTER (
                   WHERE la.metadata ->> 'document_type' = 'maintenance_specific_conditions'
               ),
               MAX(la.document_hash) FILTER (
                   WHERE la.metadata ->> 'document_type' = 'maintenance_specific_conditions'
               )
          INTO v_existing_specific_count,
               v_existing_specific_id,
               v_existing_specific_version,
               v_existing_specific_hash
          FROM public.legal_acceptances la
         WHERE la.context = 'maintenance_checkout'
           AND la.metadata ->> 'maintenance_checkout_attempt_id' = p_checkout_attempt_id::TEXT
           AND la.metadata ->> 'document_type' = 'maintenance_specific_conditions';

        IF v_existing_general_count <> 1 OR v_existing_specific_count <> 1 THEN
            RAISE EXCEPTION 'El intento de checkout no contiene exactamente una aceptación por cada documento legal';
        END IF;

        IF v_existing_general_version IS DISTINCT FROM p_expected_general_version
           OR v_existing_specific_version IS DISTINCT FROM p_expected_specific_version
        THEN
            RAISE EXCEPTION 'Las versiones aceptadas no coinciden con las versiones esperadas para este checkout';
        END IF;

        RETURN jsonb_build_object(
            'ok', TRUE,
            'already_recorded', TRUE,
            'checkout_attempt_id', p_checkout_attempt_id,
            'stripe_checkout_session_id', p_checkout_session_id,
            'general_terms', jsonb_build_object(
                'document_id', v_existing_general_id,
                'version', v_existing_general_version,
                'content_hash', v_existing_general_hash
            ),
            'specific_conditions', jsonb_build_object(
                'document_id', v_existing_specific_id,
                'version', v_existing_specific_version,
                'content_hash', v_existing_specific_hash
            )
        );
    END IF;

    -- La persona debe seguir activa y pertenecer a la empresa indicada.
    SELECT p.company_id, p.status
      INTO v_profile_company_id, v_profile_status
      FROM public.profiles p
     WHERE p.id = p_user_id;

    IF NOT FOUND
       OR v_profile_status IS DISTINCT FROM 'active'
       OR v_profile_company_id IS DISTINCT FROM p_company_id
    THEN
        RAISE EXCEPTION 'El usuario no está activo o no pertenece a la empresa del checkout';
    END IF;

    -- Leer las condiciones generales vigentes.
    SELECT ld.id, ld.version, ld.content_hash
      INTO v_general_id, v_general_version, v_general_hash
      FROM public.legal_documents ld
     WHERE ld.document_type = 'maintenance_contract_terms'
       AND ld.is_current = TRUE
       AND ld.effective_from <= v_now
       AND (ld.effective_until IS NULL OR ld.effective_until > v_now)
     ORDER BY ld.effective_from DESC, ld.created_at DESC
     LIMIT 1;

    IF v_general_id IS NULL THEN
        RAISE EXCEPTION 'No existen condiciones generales de mantenimiento vigentes';
    END IF;

    -- Leer las condiciones particulares vigentes.
    SELECT ld.id, ld.version, ld.content_hash
      INTO v_specific_id, v_specific_version, v_specific_hash
      FROM public.legal_documents ld
     WHERE ld.document_type = 'maintenance_specific_conditions'
       AND ld.is_current = TRUE
       AND ld.effective_from <= v_now
       AND (ld.effective_until IS NULL OR ld.effective_until > v_now)
     ORDER BY ld.effective_from DESC, ld.created_at DESC
     LIMIT 1;

    IF v_specific_id IS NULL THEN
        RAISE EXCEPTION 'No existen condiciones particulares de mantenimiento vigentes';
    END IF;

    -- La comprobación sucede antes de crear ninguna evidencia.
    IF v_general_version IS DISTINCT FROM p_expected_general_version THEN
        RAISE EXCEPTION 'Las condiciones generales han cambiado. Recarga y acepta la versión vigente antes de contratar';
    END IF;

    IF v_specific_version IS DISTINCT FROM p_expected_specific_version THEN
        RAISE EXCEPTION 'Las condiciones particulares han cambiado. Recarga y acepta la versión vigente antes de contratar';
    END IF;

    -- Validar hashes, incluidos valores NULL, antes de guardar evidencia.
    IF v_general_hash IS NULL
       OR v_specific_hash IS NULL
       OR v_general_hash !~ '^[0-9a-f]{64}$'
       OR v_specific_hash !~ '^[0-9a-f]{64}$'
    THEN
        RAISE EXCEPTION 'El hash de uno de los documentos legales no es válido';
    END IF;

    v_ip := LEFT(NULLIF(BTRIM(p_ip), ''), 200);
    v_user_agent := LEFT(NULLIF(BTRIM(p_user_agent), ''), 2000);

    -- Las dos inserciones son atómicas: si alguna falla, ninguna queda guardada.
    INSERT INTO public.legal_acceptances (
        user_id, company_id, document_id, action_type, accepted_at,
        ip, user_agent, context, source, document_hash, metadata
    ) VALUES (
        p_user_id, p_company_id, v_general_id, 'accepted', v_now,
        v_ip, v_user_agent, 'maintenance_checkout', 'maintenance_checkout',
        v_general_hash,
        jsonb_build_object(
            'maintenance_checkout_attempt_id', p_checkout_attempt_id,
            'stripe_checkout_session_id', p_checkout_session_id,
            'plan_id', p_plan_id,
            'proposal_id', p_proposal_id,
            'document_type', 'maintenance_contract_terms',
            'document_version', v_general_version
        )
    );

    INSERT INTO public.legal_acceptances (
        user_id, company_id, document_id, action_type, accepted_at,
        ip, user_agent, context, source, document_hash, metadata
    ) VALUES (
        p_user_id, p_company_id, v_specific_id, 'accepted', v_now,
        v_ip, v_user_agent, 'maintenance_checkout', 'maintenance_checkout',
        v_specific_hash,
        jsonb_build_object(
            'maintenance_checkout_attempt_id', p_checkout_attempt_id,
            'stripe_checkout_session_id', p_checkout_session_id,
            'plan_id', p_plan_id,
            'proposal_id', p_proposal_id,
            'document_type', 'maintenance_specific_conditions',
            'document_version', v_specific_version
        )
    );

    RETURN jsonb_build_object(
        'ok', TRUE,
        'already_recorded', FALSE,
        'checkout_attempt_id', p_checkout_attempt_id,
        'stripe_checkout_session_id', p_checkout_session_id,
        'general_terms', jsonb_build_object(
            'document_id', v_general_id,
            'version', v_general_version,
            'content_hash', v_general_hash
        ),
        'specific_conditions', jsonb_build_object(
            'document_id', v_specific_id,
            'version', v_specific_version,
            'content_hash', v_specific_hash
        )
    );
END;
$_$;


ALTER FUNCTION "public"."record_maintenance_legal_acceptances"("p_user_id" "uuid", "p_company_id" "uuid", "p_checkout_attempt_id" "uuid", "p_checkout_session_id" "text", "p_plan_id" "uuid", "p_expected_general_version" "text", "p_expected_specific_version" "text", "p_proposal_id" "uuid", "p_general_accepted" boolean, "p_specific_accepted" boolean, "p_ip" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_project_task_update"("p_task_id" "uuid", "p_action" "text", "p_old_status" "text" DEFAULT NULL::"text", "p_old_progress" integer DEFAULT NULL::integer, "p_new_status" "text" DEFAULT NULL::"text", "p_new_progress" integer DEFAULT NULL::integer, "p_comment" "text" DEFAULT NULL::"text") RETURNS "public"."project_task_updates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_worker_id UUID;
    v_update public.project_task_updates;
    v_comment TEXT;
BEGIN

    v_worker_id := public.current_project_task_worker_id();

    IF v_worker_id IS NULL THEN
        RAISE EXCEPTION
            'Se requiere un trabajador activo';
    END IF;

    IF p_task_id IS NULL THEN
        RAISE EXCEPTION
            'La tarea es obligatoria';
    END IF;

    IF p_action IS NULL
       OR BTRIM(p_action) = ''
    THEN
        RAISE EXCEPTION
            'La acción es obligatoria';
    END IF;

    IF LENGTH(BTRIM(p_action)) > 100 THEN
        RAISE EXCEPTION
            'La acción no puede superar 100 caracteres';
    END IF;

    v_comment := NULLIF(BTRIM(p_comment), '');

    IF v_comment IS NOT NULL
       AND LENGTH(v_comment) > 5000
    THEN
        RAISE EXCEPTION
            'El comentario no puede superar 5000 caracteres';
    END IF;

    INSERT INTO public.project_task_updates (
        task_id,
        actor_worker_id,
        action,
        old_status,
        old_progress,
        new_status,
        new_progress,
        comment
    )
    VALUES (
        p_task_id,
        v_worker_id,
        BTRIM(p_action),
        p_old_status,
        p_old_progress,
        p_new_status,
        p_new_progress,
        v_comment
    )
    RETURNING *
    INTO v_update;

    RETURN v_update;

END;
$$;


ALTER FUNCTION "public"."record_project_task_update"("p_task_id" "uuid", "p_action" "text", "p_old_status" "text", "p_old_progress" integer, "p_new_status" "text", "p_new_progress" integer, "p_comment" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."quotation_document_acknowledgements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "quotation_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "company_id" "uuid" NOT NULL,
    "document_path" "text" NOT NULL,
    "document_sha256" "text" NOT NULL,
    "acknowledgement_text_version" "text" NOT NULL,
    "accepted_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "quotation_document_ack_document_sha256_check" CHECK (("document_sha256" ~ '^[0-9a-fA-F]{64}$'::"text")),
    CONSTRAINT "quotation_document_ack_path_check" CHECK ((TRIM(BOTH FROM "document_path") <> ''::"text")),
    CONSTRAINT "quotation_document_ack_version_check" CHECK ((TRIM(BOTH FROM "acknowledgement_text_version") <> ''::"text"))
);


ALTER TABLE "public"."quotation_document_acknowledgements" OWNER TO "postgres";


COMMENT ON TABLE "public"."quotation_document_acknowledgements" IS 'Registro de la aceptación previa del PDF de un presupuesto por parte del cliente. No sustituye quotation_acceptances, que conserva la aceptación contractual definitiva.';



CREATE OR REPLACE FUNCTION "public"."record_quotation_document_acknowledgement"("p_quotation_id" "uuid") RETURNS "public"."quotation_document_acknowledgements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$

DECLARE
    v_user_id UUID;
    v_quotation public.quotations;
    v_acknowledgement public.quotation_document_acknowledgements;
    v_acknowledgement_text_version TEXT :=
        'quotation_document_acknowledgement_v1';

BEGIN

    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    IF public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Los trabajadores no pueden registrar la aceptación documental de un cliente';
    END IF;


    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION
            'Acceso denegado: la cuenta no está activa';
    END IF;


    -- ========================================================
    -- OBTENER PRESUPUESTO
    -- ========================================================

    SELECT *
    INTO v_quotation
    FROM public.quotations
    WHERE id = p_quotation_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Presupuesto no encontrado';
    END IF;


    -- ========================================================
    -- COMPROBAR QUE EL USUARIO ES EL CLIENTE DEL PRESUPUESTO
    -- ========================================================
    --
    -- La empresa del presupuesto pertenece a la empresa que
    -- gestiona el proyecto.
    --
    -- El cliente se identifica mediante:
    --
    -- quotations.client_id
    --        ↓
    -- clients.profile_id
    --        ↓
    -- auth.uid()
    --
    -- ========================================================

    IF v_quotation.client_id IS NULL
       OR NOT EXISTS (
            SELECT 1
            FROM public.clients c
            WHERE c.id = v_quotation.client_id
              AND c.profile_id = v_user_id
       )
    THEN
        RAISE EXCEPTION
            'Acceso denegado al presupuesto';
    END IF;


    -- ========================================================
    -- SOLO PRESUPUESTOS PENDIENTES
    -- ========================================================

    IF LOWER(TRIM(v_quotation.estado)) <> 'pendiente' THEN
        RAISE EXCEPTION
            'Solo se puede registrar la aceptación documental de un presupuesto pendiente';
    END IF;


    -- ========================================================
    -- COMPROBAR PDF
    -- ========================================================

    IF v_quotation.document_path IS NULL
       OR TRIM(v_quotation.document_path) = ''
    THEN
        RAISE EXCEPTION
            'Este presupuesto no tiene un PDF asociado';
    END IF;


    IF v_quotation.document_sha256 IS NULL
       OR TRIM(v_quotation.document_sha256) = ''
    THEN
        RAISE EXCEPTION
            'El PDF del presupuesto todavía no está preparado para su aceptación';
    END IF;


    IF LOWER(TRIM(v_quotation.document_sha256))
       !~ '^[0-9a-f]{64}$'
    THEN
        RAISE EXCEPTION
            'El hash del PDF del presupuesto no es válido';
    END IF;


    -- ========================================================
    -- REGISTRAR ACKNOWLEDGEMENT
    -- ========================================================

    INSERT INTO public.quotation_document_acknowledgements (
        quotation_id,
        user_id,
        company_id,
        document_path,
        document_sha256,
        acknowledgement_text_version,
        accepted_at
    )
    VALUES (
        v_quotation.id,
        v_user_id,
        v_quotation.company_id,
        TRIM(v_quotation.document_path),
        LOWER(TRIM(v_quotation.document_sha256)),
        v_acknowledgement_text_version,
        CURRENT_TIMESTAMP
    )
    ON CONFLICT (
        quotation_id,
        user_id,
        document_sha256,
        acknowledgement_text_version
    )
    DO UPDATE
    SET
        document_path = EXCLUDED.document_path,
        accepted_at = EXCLUDED.accepted_at
    RETURNING *
    INTO v_acknowledgement;


    IF v_acknowledgement.id IS NULL THEN
        RAISE EXCEPTION
            'No se ha podido registrar la aceptación del documento';
    END IF;


    RETURN v_acknowledgement;

END;
$_$;


ALTER FUNCTION "public"."record_quotation_document_acknowledgement"("p_quotation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_quotation_document_acknowledgement"("p_quotation_id" "uuid") IS 'Registra que el cliente ha aceptado documentalmente el PDF actualmente asociado a un presupuesto. El documento, empresa, usuario y SHA-256 se obtienen desde backend/BD y no son elegibles por el frontend.';



CREATE OR REPLACE FUNCTION "public"."refresh_expense_allocation_percentages"("p_expense_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_total NUMERIC(14,2);

BEGIN

  SELECT
    ROUND(
      COALESCE(total_amount, 0),
      2
    )

  INTO
    v_total

  FROM public.expenses

  WHERE id = p_expense_id;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El gasto % no existe',
      p_expense_id;

  END IF;


  IF v_total <= 0 THEN

    UPDATE public.expense_allocations

    SET
      percentage = 0,
      updated_at = CURRENT_TIMESTAMP

    WHERE expense_id = p_expense_id;


  ELSE

    UPDATE public.expense_allocations

    SET
      percentage =
        ROUND(
          (
            amount
            / v_total
          ) * 100,
          4
        ),
      updated_at = CURRENT_TIMESTAMP

    WHERE expense_id = p_expense_id;

  END IF;

END;
$$;


ALTER FUNCTION "public"."refresh_expense_allocation_percentages"("p_expense_id" "uuid") OWNER TO "postgres";


