    CONSTRAINT "maintenance_contracts_billing_failure_count_check" CHECK (("billing_failure_count" >= 0)),
    CONSTRAINT "maintenance_contracts_cancel_dates_check" CHECK ((("cancel_effective_at" IS NULL) OR ("cancel_requested_at" IS NOT NULL))),
    CONSTRAINT "maintenance_contracts_company_required_check" CHECK (("company_id" IS NOT NULL)),
    CONSTRAINT "maintenance_contracts_dates_check" CHECK ((("fecha_fin" IS NULL) OR ("fecha_fin" >= "fecha_inicio"))),
    CONSTRAINT "maintenance_contracts_descripcion_length_check" CHECK ((("descripcion" IS NULL) OR ("length"("descripcion") <= 5000))),
    CONSTRAINT "maintenance_contracts_estado_check" CHECK (("estado" = ANY (ARRAY['activo'::"text", 'pausado'::"text", 'cancelado'::"text", 'finalizado'::"text"]))),
    CONSTRAINT "maintenance_contracts_estado_length_check" CHECK ((("estado" IS NULL) OR ("length"("estado") <= 20))),
    CONSTRAINT "maintenance_contracts_iva_porcentaje_check" CHECK ((("iva_porcentaje" >= (0)::numeric) AND ("iva_porcentaje" <= (100)::numeric))),
    CONSTRAINT "maintenance_contracts_iva_source_check" CHECK (("iva_source" = ANY (ARRAY['company_default'::"text", 'worker'::"text", 'client_request'::"text"]))),
    CONSTRAINT "maintenance_contracts_nombre_plan_length_check" CHECK ((("nombre_plan" IS NULL) OR ("length"("nombre_plan") <= 200))),
    CONSTRAINT "maintenance_contracts_pending_change_check" CHECK ((("pending_change_effective_at" IS NULL) OR ("pending_plan_id" IS NOT NULL))),
