    CONSTRAINT "maintenance_contracts_scope_snapshot_check" CHECK ((("scope_snapshot" IS NULL) OR ("jsonb_typeof"("scope_snapshot") = 'object'::"text"))),
    CONSTRAINT "maintenance_contracts_stripe_subscription_check" CHECK ((("stripe_subscription_id" IS NULL) OR ("length"(TRIM(BOTH FROM "stripe_subscription_id")) > 0)))
);


ALTER TABLE "public"."maintenance_contracts" OWNER TO "postgres";


COMMENT ON TABLE "public"."maintenance_contracts" IS 'Contrato concreto de mantenimiento de una empresa. Contiene snapshots comerciales, ciclo de renovación, cancelación y referencias Stripe.';



COMMENT ON COLUMN "public"."maintenance_contracts"."cancel_effective_at" IS 'Fecha efectiva de finalización. Una cancelación dentro del plazo evita el siguiente cobro; una cancelación fuera de plazo termina al final del periodo que resulte cobrado.';



COMMENT ON COLUMN "public"."maintenance_contracts"."stripe_checkout_session_id" IS 'Checkout Session de Stripe que originó la contratación del mantenimiento. Evidencia técnica del proceso de contratación.';



COMMENT ON COLUMN "public"."maintenance_contracts"."contracted_at" IS 'Momento en que Modira registra la contratación completada mediante Stripe Checkout.';



COMMENT ON COLUMN "public"."maintenance_contracts"."terms_version" IS 'Versión de los términos/condiciones aceptados durante la contratación.';



COMMENT ON COLUMN "public"."maintenance_contracts"."billing_failure_count" IS 'Número de fallos consecutivos de cobro Stripe registrados por Modira. Se reinicia cuando una factura de mantenimiento se paga correctamente.';



COMMENT ON COLUMN "public"."maintenance_contracts"."last_payment_failed_at" IS 'Momento del último intento de cobro fallido de la suscripción Stripe.';



COMMENT ON COLUMN "public"."maintenance_contracts"."billing_blocked_at" IS 'Momento en que Modira alcanzó el umbral de 3 fallos consecutivos y bloqueó la recaudación automática mediante Stripe.';



COMMENT ON COLUMN "public"."maintenance_contracts"."billing_block_reason" IS 'Motivo del bloqueo de facturación. Los bloqueos por impago usan el prefijo payment_failed; los bloqueos fiscales se gestionan mediante pause_collection y el flujo fiscal existente.';



COMMENT ON COLUMN "public"."maintenance_contracts"."iva_aplicado" IS 'IVA aplicado al contrato de mantenimiento. Se conserva como snapshot contractual.';



COMMENT ON COLUMN "public"."maintenance_contracts"."iva_porcentaje" IS 'Porcentaje de IVA del contrato de mantenimiento. No se recalcula automáticamente cuando cambia la recomendación de la empresa.';



COMMENT ON COLUMN "public"."maintenance_contracts"."iva_source" IS 'Origen del IVA del contrato: company_default, worker o client_request.';



COMMENT ON COLUMN "public"."maintenance_contracts"."specific_conditions_version" IS 'Versión de las condiciones particulares de mantenimiento aceptadas para este contrato.';



CREATE OR REPLACE FUNCTION "public"."register_maintenance_billing_failure"("p_subscription_id" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."maintenance_contracts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_contract public.maintenance_contracts;
  v_count INTEGER;
  v_reason TEXT;
BEGIN
  IF p_subscription_id IS NULL OR BTRIM(p_subscription_id) = '' THEN
    RAISE EXCEPTION 'subscription_id obligatorio';
  END IF;

  v_reason := LEFT(
    COALESCE(NULLIF(BTRIM(p_reason), ''), 'Stripe ha rechazado o no ha podido completar el cobro.'),
    1000
  );

  SELECT *
  INTO v_contract
  FROM public.maintenance_contracts
  WHERE stripe_subscription_id = p_subscription_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'No existe un contrato de mantenimiento para la suscripción %',
      p_subscription_id;
  END IF;

  v_count := COALESCE(v_contract.billing_failure_count, 0) + 1;

  UPDATE public.maintenance_contracts
  SET
    billing_failure_count = v_count,
    last_payment_failed_at = CURRENT_TIMESTAMP,
    billing_blocked_at = CASE
      WHEN v_count >= 3
        THEN COALESCE(v_contract.billing_blocked_at, CURRENT_TIMESTAMP)
      ELSE v_contract.billing_blocked_at
    END,
    billing_block_reason = CASE
      WHEN v_count >= 3
        THEN COALESCE(
          NULLIF(v_contract.billing_block_reason, ''),
          'payment_failed: ' || v_reason
        )
      ELSE v_contract.billing_block_reason
    END,
    updated_at = CURRENT_TIMESTAMP
  WHERE id = v_contract.id
  RETURNING *
  INTO v_contract;

  RETURN v_contract;
END;
$$;


ALTER FUNCTION "public"."register_maintenance_billing_failure"("p_subscription_id" "text", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."payments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "invoice_id" "uuid",
    "quotation_id" "uuid",
    "stripe_invoice_id" character varying(255),
    "stripe_payment_intent_id" character varying(255),
    "amount" integer NOT NULL,
    "currency" character varying(3) DEFAULT 'EUR'::character varying NOT NULL,
    "status" character varying(50) NOT NULL,
    "description" "text",
    "paid_at" timestamp with time zone,
    "due_date" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "stripe_checkout_session_id" character varying(255),
    "maintenance_invoice_id" "uuid",
    CONSTRAINT "payments_amount_check" CHECK (("amount" >= 0)),
    CONSTRAINT "payments_invoice_source_check" CHECK ((NOT (("invoice_id" IS NOT NULL) AND ("maintenance_invoice_id" IS NOT NULL)))),
    CONSTRAINT "payments_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['failed'::character varying, 'canceled'::character varying, 'succeeded'::character varying])::"text"[])))
);


ALTER TABLE "public"."payments" OWNER TO "postgres";


COMMENT ON COLUMN "public"."payments"."stripe_payment_intent_id" IS 'Identificador del PaymentIntent de Stripe asociado al pago.';



COMMENT ON COLUMN "public"."payments"."stripe_checkout_session_id" IS 'Identificador de la Checkout Session de Stripe utilizada para este intento de pago.';



CREATE OR REPLACE FUNCTION "public"."register_stripe_invoice_payment"("p_invoice_id" "uuid", "p_checkout_session_id" "text", "p_payment_intent_id" "text", "p_amount" integer, "p_currency" character varying, "p_status" character varying, "p_paid_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_description" "text" DEFAULT NULL::"text") RETURNS "public"."payments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_invoice public.invoices;
    v_payment public.payments;
    v_expected_amount INTEGER;

BEGIN

    -- ========================================================
    -- 1. FACTURA
    -- ========================================================

    SELECT *
    INTO v_invoice
    FROM public.invoices
    WHERE id = p_invoice_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Factura no encontrada';
    END IF;


    -- ========================================================
    -- 2. IMPORTE ESPERADO
    -- ========================================================

    v_expected_amount :=
        ROUND(
            v_invoice.importe_a_pagar * 100
        )::INTEGER;


    -- ========================================================
    -- 3. COMPROBAR IMPORTE
    -- ========================================================

    IF p_amount <> v_expected_amount THEN
        RAISE EXCEPTION
            'El importe del pago no coincide con la factura';
    END IF;


    -- ========================================================
    -- 4. COMPROBAR MONEDA
    -- ========================================================

    IF UPPER(COALESCE(p_currency, '')) <>
       UPPER(COALESCE(
           (
               SELECT c.currency
               FROM public.companies c
               WHERE c.id = v_invoice.company_id
           ),
           'EUR'
       ))
    THEN
        RAISE EXCEPTION
            'La moneda del pago no coincide con la moneda de la empresa';
    END IF;


    -- ========================================================
    -- 5. PAYMENT INTENT EXISTENTE
    --
    -- Idempotencia + transición de estado.
    --
    -- Si el mismo PaymentIntent ya existe:
    --
    --   succeeded
    --       -> no se modifica.
    --
    --   failed/canceled -> succeeded
    --       -> se actualiza.
    --
    --   cualquier otra combinación
    --       -> se mantiene el registro existente.
    --
    -- Nunca permitimos degradar:
    --
    --   succeeded -> failed
    --   succeeded -> canceled
    --
    -- ========================================================

    IF p_payment_intent_id IS NOT NULL THEN

        SELECT *
        INTO v_payment
        FROM public.payments
        WHERE stripe_payment_intent_id = p_payment_intent_id
        LIMIT 1
        FOR UPDATE;

        IF FOUND THEN

            -- ------------------------------------------------
            -- El PaymentIntent no puede cambiar de factura.
            -- ------------------------------------------------

            IF v_payment.invoice_id IS DISTINCT FROM v_invoice.id THEN
                RAISE EXCEPTION
                    'El PaymentIntent ya está asociado a otra factura';
            END IF;


            -- ------------------------------------------------
            -- Ya está exitoso.
            -- Nunca lo degradamos.
            -- ------------------------------------------------

            IF v_payment.status = 'succeeded' THEN
                RETURN v_payment;
            END IF;


            -- ------------------------------------------------
            -- TRANSICIÓN VÁLIDA:
            --
            -- failed/canceled -> succeeded
            -- ------------------------------------------------

            IF p_status = 'succeeded'
               AND v_payment.status IN (
                   'failed',
                   'canceled'
               )
            THEN

                -- --------------------------------------------
                -- Si la factura ya fue pagada mediante otro
                -- PaymentIntent, no permitimos otro succeeded.
                -- --------------------------------------------

                IF LOWER(
                    COALESCE(v_invoice.estado, '')
                ) = 'pagada'
                THEN
                    RAISE EXCEPTION
                        'La factura ya está pagada';
                END IF;


                -- --------------------------------------------
                -- Actualizar el Payment existente.
                -- --------------------------------------------

                UPDATE public.payments
                SET
                    status = 'succeeded',
                    paid_at = COALESCE(
                        p_paid_at,
                        CURRENT_TIMESTAMP
                    ),
                    description = COALESCE(
                        p_description,
                        v_payment.description
                    ),
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = v_payment.id
                RETURNING *
                INTO v_payment;


                -- --------------------------------------------
                -- Marcar factura como pagada.
                -- --------------------------------------------

                UPDATE public.invoices
                SET
                    estado = 'pagada',
                    fecha_pago = COALESCE(
                        p_paid_at,
                        CURRENT_TIMESTAMP
                    ),
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = v_invoice.id;


                RETURN v_payment;

            END IF;


            -- ------------------------------------------------
            -- No cambiar estados sin una transición válida.
            -- ------------------------------------------------

            RETURN v_payment;

        END IF;

    END IF;


    -- ========================================================
    -- 6. CHECKOUT SESSION EXISTENTE
    -- ========================================================

    IF p_checkout_session_id IS NOT NULL THEN

        SELECT *
        INTO v_payment
        FROM public.payments
        WHERE stripe_checkout_session_id =
              p_checkout_session_id
        LIMIT 1
        FOR UPDATE;

        IF FOUND THEN

            -- ------------------------------------------------
            -- La Checkout Session tampoco puede cambiar
            -- de factura.
            -- ------------------------------------------------

            IF v_payment.invoice_id IS DISTINCT FROM v_invoice.id THEN
                RAISE EXCEPTION
                    'La Checkout Session ya está asociada a otra factura';
            END IF;

            RETURN v_payment;

        END IF;

    END IF;


    -- ========================================================
    -- 7. FACTURA YA PAGADA
    -- ========================================================

    IF LOWER(COALESCE(v_invoice.estado, '')) = 'pagada'
       AND p_status = 'succeeded'
    THEN
        RAISE EXCEPTION
            'La factura ya está pagada';
    END IF;


    -- ========================================================
    -- 8. REGISTRAR NUEVO PAYMENT
    -- ========================================================

    INSERT INTO public.payments (
        company_id,
        user_id,
        invoice_id,
        stripe_checkout_session_id,
        stripe_payment_intent_id,
        amount,
        currency,
        status,
        description,
        paid_at
    )
    VALUES (
        v_invoice.company_id,
        v_invoice.user_id,
        v_invoice.id,
        p_checkout_session_id,
        p_payment_intent_id,
        p_amount,
        UPPER(p_currency),
        p_status,
        p_description,
        CASE
            WHEN p_status = 'succeeded'
            THEN COALESCE(
                p_paid_at,
                CURRENT_TIMESTAMP
            )
            ELSE NULL
        END
    )
    RETURNING *
    INTO v_payment;


    -- ========================================================
    -- 9. MARCAR FACTURA COMO PAGADA
    -- ========================================================

    IF p_status = 'succeeded' THEN

        UPDATE public.invoices
        SET
            estado = 'pagada',
            fecha_pago = COALESCE(
                p_paid_at,
                CURRENT_TIMESTAMP
            ),
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_invoice.id;

    END IF;


    RETURN v_payment;

END;

$$;


ALTER FUNCTION "public"."register_stripe_invoice_payment"("p_invoice_id" "uuid", "p_checkout_session_id" "text", "p_payment_intent_id" "text", "p_amount" integer, "p_currency" character varying, "p_status" character varying, "p_paid_at" timestamp with time zone, "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_expense"("p_expense_id" "uuid") RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_expense public.expenses;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.approve'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:reject'
  );


  SELECT *
  INTO v_expense

  FROM public.expenses

  WHERE id = p_expense_id

  FOR UPDATE;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El gasto % no existe',
      p_expense_id;

  END IF;


  IF v_expense.status <> 'pending_review' THEN

    RAISE EXCEPTION
      'Solo se pueden rechazar gastos en estado pending_review';

  END IF;


  UPDATE public.expenses

  SET
    status = 'rejected',
    updated_by = auth.uid(),
    updated_at = CURRENT_TIMESTAMP

  WHERE id = p_expense_id

  RETURNING *
  INTO v_expense;


  RETURN v_expense;

END;
$$;


ALTER FUNCTION "public"."reject_expense"("p_expense_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_maintenance_contract_project_change"("p_request_id" "uuid", "p_reason" "text") RETURNS "public"."maintenance_contract_project_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'maintenance.update'
    );

    RETURN public.reject_maintenance_contract_project_change__legacy_113(
        p_request_id,
        p_reason
    );

END;
$$;


ALTER FUNCTION "public"."reject_maintenance_contract_project_change"("p_request_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_maintenance_contract_project_change__legacy_113"("p_request_id" "uuid", "p_reason" "text") RETURNS "public"."maintenance_contract_project_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_worker_id UUID := auth.uid();
  v_request public.maintenance_contract_project_change_requests;
BEGIN
  IF v_worker_id IS NULL THEN
    RAISE EXCEPTION 'Debes iniciar sesión';
  END IF;

  IF NOT public.current_user_is_worker() THEN
    RAISE EXCEPTION 'Se requiere un trabajador activo';
  END IF;

  IF NULLIF(BTRIM(p_reason), '') IS NULL THEN
    RAISE EXCEPTION 'Debes indicar el motivo del rechazo';
  END IF;

  SELECT *
  INTO v_request
  FROM public.maintenance_contract_project_change_requests
  WHERE id = p_request_id
    AND status = 'pending'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'La solicitud no existe o ya ha sido revisada';
  END IF;

  UPDATE public.maintenance_contract_project_change_requests
  SET
    status = 'rejected',
    reviewed_at = CURRENT_TIMESTAMP,
    reviewed_by = v_worker_id,
    rejection_reason = LEFT(BTRIM(p_reason), 2000),
    updated_at = CURRENT_TIMESTAMP
  WHERE id = v_request.id
  RETURNING *
  INTO v_request;

  RETURN v_request;
END;
$$;


ALTER FUNCTION "public"."reject_maintenance_contract_project_change__legacy_113"("p_request_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_project_ownership_transfer"("p_transfer_id" "uuid") RETURNS "public"."project_ownership_transfers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_transfer public.project_ownership_transfers;

BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado';
    END IF;

    SELECT *
    INTO v_transfer
    FROM public.project_ownership_transfers
    WHERE id = p_transfer_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transferencia no encontrada';
    END IF;

    IF v_transfer.requested_new_owner_id IS DISTINCT FROM auth.uid() THEN
        RAISE EXCEPTION
            'Solo el nuevo propietario puede rechazar la transferencia';
    END IF;

    IF v_transfer.status <> 'pending_acceptance' THEN
        RAISE EXCEPTION
            'La transferencia no está pendiente de aceptación';
    END IF;

    UPDATE public.project_ownership_transfers
    SET
        status = 'rejected',
        accepted_by = auth.uid(),
        accepted_at = CURRENT_TIMESTAMP,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_transfer_id
    RETURNING *
    INTO v_transfer;

    RETURN v_transfer;

END;
$$;


ALTER FUNCTION "public"."reject_project_ownership_transfer"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_worker_role"("p_worker_auth_user_id" "uuid", "p_role_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_role_id UUID;
    v_normalized_role TEXT;
BEGIN

    -- --------------------------------------------------------
    -- Autenticación
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Authentication required'
            USING ERRCODE = '42501';
    END IF;


    -- --------------------------------------------------------
    -- Autorización
    -- --------------------------------------------------------

    IF NOT public.current_user_can_manage_worker_roles() THEN
        RAISE EXCEPTION
            'Insufficient permissions to manage worker roles'
            USING ERRCODE = '42501';
    END IF;


    -- --------------------------------------------------------
    -- Validaciones
    -- --------------------------------------------------------

    IF p_worker_auth_user_id IS NULL THEN
        RAISE EXCEPTION
            'Worker auth user id is required'
            USING ERRCODE = '22023';
    END IF;


    v_normalized_role := LOWER(BTRIM(p_role_code));


    IF v_normalized_role = '' THEN
        RAISE EXCEPTION
            'Role code is required'
            USING ERRCODE = '22023';
    END IF;


    SELECT r.id
    INTO v_role_id
    FROM public.worker_roles r
    WHERE r.code = v_normalized_role;


    IF v_role_id IS NULL THEN
        RAISE EXCEPTION
            'Role does not exist: %',
            v_normalized_role
            USING ERRCODE = '22023';
    END IF;


    -- --------------------------------------------------------
    -- Evitar que un worker se quite a sí mismo su último rol
    -- de administración RBAC.
    --
    -- Esto evita un bloqueo accidental de la administración
    -- desde una cuenta worker.
    -- --------------------------------------------------------

    IF p_worker_auth_user_id = auth.uid()
       AND v_normalized_role = 'direction'
       AND public.current_user_is_worker()
       AND NOT public.current_user_is_admin() THEN

        IF (
            SELECT COUNT(*)
            FROM public.worker_role_assignments wra
            JOIN public.worker_roles wr
                ON wr.id = wra.role_id
            WHERE wra.worker_auth_user_id = auth.uid()
              AND wr.is_active = TRUE
              AND wr.code = 'direction'
        ) <= 1 THEN

            RAISE EXCEPTION
                'A worker cannot remove its last Direction role'
                USING ERRCODE = '42501';

        END IF;

    END IF;


    -- --------------------------------------------------------
    -- Eliminación de relación
    -- --------------------------------------------------------

    DELETE FROM public.worker_role_assignments
    WHERE worker_auth_user_id = p_worker_auth_user_id
      AND role_id = v_role_id;


    RETURN TRUE;

END;
$$;


ALTER FUNCTION "public"."remove_worker_role"("p_worker_auth_user_id" "uuid", "p_role_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_worker_role"("p_worker_auth_user_id" "uuid", "p_role_code" "text") IS 'Elimina una asignación RBAC concreta de un worker.';



CREATE OR REPLACE FUNCTION "public"."replace_worker_custom_role_permissions"("p_role_code" "text", "p_permission_codes" "text"[]) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_role_id uuid;
    v_requested_codes text[];
    v_valid_count bigint;
    v_requested_count bigint;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required'
            USING ERRCODE = '42501';
    END IF;

    IF NOT public.current_user_can_manage_worker_roles() THEN
        RAISE EXCEPTION 'Insufficient permissions to manage role permissions'
            USING ERRCODE = '42501';
    END IF;

    SELECT r.id
    INTO v_role_id
    FROM public.worker_roles r
    WHERE r.code = LOWER(BTRIM(COALESCE(p_role_code, '')))
      AND r.is_active = TRUE
      AND r.is_system_role = FALSE;

    IF v_role_id IS NULL THEN
        RAISE EXCEPTION 'Custom role not found or inactive'
            USING ERRCODE = '22023';
    END IF;

    SELECT COALESCE(
        ARRAY_AGG(DISTINCT LOWER(BTRIM(x.code))),
        ARRAY[]::text[]
    )
    INTO v_requested_codes
    FROM UNNEST(COALESCE(p_permission_codes, ARRAY[]::text[])) AS x(code)
    WHERE BTRIM(COALESCE(x.code, '')) <> '';

    SELECT CARDINALITY(v_requested_codes)::bigint
    INTO v_requested_count;

    SELECT COUNT(DISTINCT p.id)::bigint
    INTO v_valid_count
    FROM public.worker_permissions p
    WHERE p.code = ANY(v_requested_codes);

    IF v_valid_count <> v_requested_count THEN
        RAISE EXCEPTION 'One or more permission codes do not exist'
            USING ERRCODE = '22023';
    END IF;

    DELETE FROM public.worker_role_permissions wrp
    WHERE wrp.role_id = v_role_id;

    INSERT INTO public.worker_role_permissions (role_id, permission_id)
    SELECT v_role_id, p.id
    FROM public.worker_permissions p
    WHERE p.code = ANY(v_requested_codes);

    UPDATE public.worker_roles
    SET updated_at = CURRENT_TIMESTAMP
    WHERE id = v_role_id;

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."replace_worker_custom_role_permissions"("p_role_code" "text", "p_permission_codes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_worker_roles"("p_worker_auth_user_id" "uuid", "p_role_codes" "text"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_worker_exists BOOLEAN;
    v_requested_roles TEXT[];
    v_role_count INTEGER;
    v_existing_direction_count INTEGER;
BEGIN

    -- --------------------------------------------------------
    -- Autenticación
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Authentication required'
            USING ERRCODE = '42501';
    END IF;


    -- --------------------------------------------------------
    -- Autorización
    -- --------------------------------------------------------

    IF NOT public.current_user_can_manage_worker_roles() THEN
        RAISE EXCEPTION
            'Insufficient permissions to manage worker roles'
            USING ERRCODE = '42501';
    END IF;


    -- --------------------------------------------------------
    -- Validar worker
    -- --------------------------------------------------------

    IF p_worker_auth_user_id IS NULL THEN
        RAISE EXCEPTION
            'Worker auth user id is required'
            USING ERRCODE = '22023';
    END IF;


    SELECT EXISTS (
        SELECT 1
        FROM public.workers w
        WHERE w.auth_user_id = p_worker_auth_user_id
    )
    INTO v_worker_exists;


    IF NOT v_worker_exists THEN
        RAISE EXCEPTION
            'Worker does not exist'
            USING ERRCODE = '22023';
    END IF;


    -- --------------------------------------------------------
    -- Normalizar roles recibidos
    -- --------------------------------------------------------

    SELECT COALESCE(
        ARRAY_AGG(DISTINCT LOWER(BTRIM(role_code))),
        ARRAY[]::TEXT[]
    )
    INTO v_requested_roles
    FROM UNNEST(
        COALESCE(p_role_codes, ARRAY[]::TEXT[])
    ) AS role_code
    WHERE BTRIM(role_code) <> '';


    -- --------------------------------------------------------
    -- Verificar que todos los roles solicitados existen
    -- y están activos.
    -- --------------------------------------------------------

    IF EXISTS (
        SELECT 1
        FROM UNNEST(v_requested_roles) AS requested(code)
        WHERE NOT EXISTS (
            SELECT 1
            FROM public.worker_roles r
            WHERE r.code = requested.code
              AND r.is_active = TRUE
        )
    ) THEN

        RAISE EXCEPTION
            'One or more requested roles do not exist or are inactive'
            USING ERRCODE = '22023';

    END IF;


    -- --------------------------------------------------------
    -- Protección contra autoeliminación del último rol
    -- de Dirección.
    -- --------------------------------------------------------

    IF p_worker_auth_user_id = auth.uid()
       AND public.current_user_is_worker()
       AND NOT public.current_user_is_admin() THEN

        SELECT COUNT(*)
        INTO v_existing_direction_count
        FROM public.worker_role_assignments wra
        JOIN public.worker_roles r
            ON r.id = wra.role_id
        WHERE wra.worker_auth_user_id = auth.uid()
          AND r.code = 'direction'
          AND r.is_active = TRUE;


        IF v_existing_direction_count > 0
           AND NOT ('direction' = ANY(v_requested_roles)) THEN

            RAISE EXCEPTION
                'A worker cannot remove its last Direction role'
                USING ERRCODE = '42501';

        END IF;

    END IF;


    -- --------------------------------------------------------
    -- Sustituir conjunto de roles
    -- --------------------------------------------------------

    DELETE FROM public.worker_role_assignments
    WHERE worker_auth_user_id = p_worker_auth_user_id;


    INSERT INTO public.worker_role_assignments (
        worker_auth_user_id,
        role_id
    )
    SELECT
        p_worker_auth_user_id,
        r.id
    FROM public.worker_roles r
    WHERE r.code = ANY(v_requested_roles)
      AND r.is_active = TRUE
    ON CONFLICT (
        worker_auth_user_id,
        role_id
    )
    DO NOTHING;


    -- --------------------------------------------------------
    -- Número final de roles
    -- --------------------------------------------------------

    SELECT COUNT(*)
    INTO v_role_count
    FROM public.worker_role_assignments wra
    WHERE wra.worker_auth_user_id = p_worker_auth_user_id;


    RETURN v_role_count;

END;
$$;


ALTER FUNCTION "public"."replace_worker_roles"("p_worker_auth_user_id" "uuid", "p_role_codes" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."replace_worker_roles"("p_worker_auth_user_id" "uuid", "p_role_codes" "text"[]) IS 'Reemplaza el conjunto completo de roles RBAC de un worker.';



CREATE TABLE IF NOT EXISTS "public"."account_deletion_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "requested_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "rejection_reason" "text",
    CONSTRAINT "account_deletion_requests_rejection_reason_check" CHECK ((("rejection_reason" IS NULL) OR ("length"(TRIM(BOTH FROM "rejection_reason")) <= 1000))),
    CONSTRAINT "account_deletion_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'blocked'::"text", 'completed'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."account_deletion_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."account_deletion_requests" IS 'Solicitudes de eliminación de cuentas de clientes. El cliente
solicita mediante RPC y un trabajador activo de MODIRA puede
aprobar o rechazar la solicitud.';



COMMENT ON COLUMN "public"."account_deletion_requests"."status" IS 'Estado de la solicitud: pending=pendiente, approved=aprobada por worker, rejected=rechazada por worker, blocked=bloqueada por reglas de negocio, completed=eliminación completada, failed=fallo técnico durante la eliminación.';



CREATE OR REPLACE FUNCTION "public"."request_account_deletion"() RETURNS "public"."account_deletion_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$

DECLARE
    v_request public.account_deletion_requests;

BEGIN

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- CUENTA ACTIVA
    -- --------------------------------------------------------

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION
            'La cuenta no está activa';
    END IF;


    -- --------------------------------------------------------
    -- SOLO CLIENTES
    -- --------------------------------------------------------

    IF public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Los trabajadores no pueden utilizar esta solicitud';
    END IF;


    -- --------------------------------------------------------
    -- ASEGURAR QUE EXISTE EL PERFIL
    -- --------------------------------------------------------

    IF NOT EXISTS (
        SELECT 1
        FROM public.profiles
        WHERE id = auth.uid()
    ) THEN
        RAISE EXCEPTION
            'Perfil de usuario no encontrado';
    END IF;


    -- --------------------------------------------------------
    -- NO PERMITIR SOLICITUD DUPLICADA
    -- --------------------------------------------------------

    IF EXISTS (
        SELECT 1
        FROM public.account_deletion_requests
        WHERE user_id = auth.uid()
          AND status = 'pending'
    ) THEN
        RAISE EXCEPTION
            'Ya existe una solicitud de eliminación pendiente';
    END IF;


    -- --------------------------------------------------------
    -- CREAR SOLICITUD
    -- --------------------------------------------------------

    INSERT INTO public.account_deletion_requests (
        user_id,
        status
    )
    VALUES (
        auth.uid(),
        'pending'
    )
    RETURNING *
    INTO v_request;


    RETURN v_request;

END;

$$;


ALTER FUNCTION "public"."request_account_deletion"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_account_deletion"() IS 'Permite a un cliente activo solicitar la eliminación de su propia cuenta.';



CREATE OR REPLACE FUNCTION "public"."request_company_change"("p_requested_company_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN public.request_company_change_with_projects(
    p_requested_company_name,
    FALSE
  );
END;
$$;


ALTER FUNCTION "public"."request_company_change"("p_requested_company_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_company_change"("p_requested_company_name" "text") IS 'Solicita el cambio de empresa del usuario autenticado.';



CREATE OR REPLACE FUNCTION "public"."request_company_change_with_projects"("p_requested_company_name" "text", "p_requested_legal_name" "text", "p_requested_cif_vat" "text", "p_requested_billing_email" "text", "p_requested_address" "text", "p_requested_postal_code" "text", "p_requested_city" "text", "p_requested_province" "text", "p_requested_country" "text", "p_reason" "text", "p_apply_to_active_projects" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$

DECLARE
    v_user_id UUID;
    v_current_company_id UUID;
    v_requested_company_id UUID;
    v_request_id UUID;

    v_requested_company_name TEXT;
    v_legal_name TEXT;
    v_cif_vat TEXT;
    v_billing_email TEXT;
    v_address TEXT;
    v_postal_code TEXT;
    v_city TEXT;
    v_province TEXT;
    v_country TEXT;
    v_reason TEXT;

    v_apply_to_active_projects BOOLEAN := COALESCE(
        p_apply_to_active_projects,
        FALSE
    );

BEGIN

    -- ========================================================
    -- 1. AUTENTICACIÓN
    -- ========================================================

    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION
            'Debes iniciar sesión para solicitar un cambio de empresa.';
    END IF;


    -- ========================================================
    -- 2. LOS WORKERS NO UTILIZAN ESTE FLUJO
    -- ========================================================

    IF public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Las cuentas de trabajadores no pueden solicitar cambio de empresa.';
    END IF;


    -- ========================================================
    -- 3. COMPROBAR PERFIL ACTIVO
    -- ========================================================

    SELECT p.company_id
    INTO v_current_company_id
    FROM public.profiles p
    WHERE p.id = v_user_id
      AND p.status = 'active'
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No se encontró un perfil activo para el usuario.';
    END IF;


    -- ========================================================
    -- 4. NORMALIZAR DATOS
    -- ========================================================

    v_requested_company_name :=
        NULLIF(BTRIM(p_requested_company_name), '');

    v_legal_name :=
        NULLIF(BTRIM(p_requested_legal_name), '');

    v_cif_vat :=
        UPPER(NULLIF(BTRIM(p_requested_cif_vat), ''));

    v_billing_email :=
        LOWER(NULLIF(BTRIM(p_requested_billing_email), ''));

    v_address :=
        NULLIF(BTRIM(p_requested_address), '');

    v_postal_code :=
        NULLIF(BTRIM(p_requested_postal_code), '');

    v_city :=
        NULLIF(BTRIM(p_requested_city), '');

    v_province :=
        NULLIF(BTRIM(p_requested_province), '');

    v_country :=
        UPPER(NULLIF(BTRIM(p_requested_country), ''));

    v_reason :=
        NULLIF(BTRIM(p_reason), '');


    -- ========================================================
    -- 5. VALIDACIONES
    -- ========================================================

    IF v_requested_company_name IS NULL THEN
        RAISE EXCEPTION
            'El nombre de empresa es obligatorio.';
    END IF;

    IF LENGTH(v_requested_company_name) > 200 THEN
        RAISE EXCEPTION
            'El nombre de empresa no puede superar 200 caracteres.';
    END IF;

    IF v_legal_name IS NULL THEN
        RAISE EXCEPTION
            'La razón social es obligatoria.';
    END IF;

    IF LENGTH(v_legal_name) > 300 THEN
        RAISE EXCEPTION
            'La razón social no puede superar 300 caracteres.';
    END IF;

    IF v_cif_vat IS NULL THEN
        RAISE EXCEPTION
            'El NIF/CIF/VAT es obligatorio.';
    END IF;

    IF LENGTH(v_cif_vat) > 100 THEN
        RAISE EXCEPTION
            'El NIF/CIF/VAT no puede superar 100 caracteres.';
    END IF;

    IF v_address IS NULL THEN
        RAISE EXCEPTION
            'La dirección fiscal es obligatoria.';
    END IF;

    IF LENGTH(v_address) > 500 THEN
        RAISE EXCEPTION
            'La dirección fiscal no puede superar 500 caracteres.';
    END IF;

    IF v_postal_code IS NULL THEN
        RAISE EXCEPTION
            'El código postal es obligatorio.';
    END IF;

    IF LENGTH(v_postal_code) > 30 THEN
        RAISE EXCEPTION
            'El código postal no puede superar 30 caracteres.';
    END IF;

    IF v_city IS NULL THEN
        RAISE EXCEPTION
            'La ciudad es obligatoria.';
    END IF;

    IF LENGTH(v_city) > 200 THEN
        RAISE EXCEPTION
            'La ciudad no puede superar 200 caracteres.';
    END IF;

    IF v_country IS NULL
       OR v_country !~ '^[A-Z]{2}$'
    THEN
        RAISE EXCEPTION
            'El país debe indicarse mediante un código ISO de dos letras.';
    END IF;

    IF v_billing_email IS NOT NULL
       AND LENGTH(v_billing_email) > 320
    THEN
        RAISE EXCEPTION
            'El email de facturación no puede superar 320 caracteres.';
    END IF;

    IF v_reason IS NOT NULL
       AND LENGTH(v_reason) > 1000
    THEN
        RAISE EXCEPTION
            'El motivo no puede superar 1000 caracteres.';
    END IF;


    -- ========================================================
    -- 6. COMPROBAR QUE NO SEA LA MISMA EMPRESA
    -- ========================================================

    IF EXISTS (
        SELECT 1
        FROM public.companies c
        WHERE c.id = v_current_company_id
          AND LOWER(BTRIM(c.company_name))
              = LOWER(v_requested_company_name)
    ) THEN
        RAISE EXCEPTION
            'La empresa solicitada coincide con la empresa actual.';
    END IF;


    -- ========================================================
    -- 7. BUSCAR EMPRESA DESTINO SI YA EXISTE
    -- ========================================================

    SELECT c.id
    INTO v_requested_company_id
    FROM public.companies c
    WHERE c.is_active = TRUE
      AND LOWER(BTRIM(c.company_name))
          = LOWER(v_requested_company_name)
    ORDER BY c.created_at
    LIMIT 1;


    -- ========================================================
    -- 8. UNA SOLA SOLICITUD PENDIENTE
    -- ========================================================

    IF EXISTS (
        SELECT 1
        FROM public.company_change_requests r
        WHERE r.user_id = v_user_id
          AND r.status = 'pending'
    ) THEN
        RAISE EXCEPTION
            'Ya tienes una solicitud de cambio de empresa pendiente.';
    END IF;


    -- ========================================================
    -- 9. CREAR SOLICITUD
    -- ========================================================
    --
    -- IMPORTANTE:
    -- v_apply_to_active_projects conserva exactamente la decisión
    -- del cliente.
    --
    -- NO se comprueba aquí si existen proyectos trasladables.
    -- Esa comprobación se hace en la aprobación para evitar que
    -- la solicitud cambie de significado entre creación y revisión.
    -- ========================================================

    INSERT INTO public.company_change_requests (
        user_id,
        current_company_id,
        requested_company_id,
        requested_company_name,

        requested_legal_name,
        requested_cif_vat,
        requested_billing_email,
        requested_address,
        requested_postal_code,
        requested_city,
        requested_province,
        requested_country,

        reason,
        apply_to_active_projects,
        status
    )
    VALUES (
        v_user_id,
        v_current_company_id,
        v_requested_company_id,
        v_requested_company_name,

        v_legal_name,
        v_cif_vat,
        v_billing_email,
        v_address,
        v_postal_code,
        v_city,
        v_province,
        v_country,

        v_reason,
        v_apply_to_active_projects,
        'pending'
    )
    RETURNING id
    INTO v_request_id;


    RETURN v_request_id;

END;
$_$;


ALTER FUNCTION "public"."request_company_change_with_projects"("p_requested_company_name" "text", "p_requested_legal_name" "text", "p_requested_cif_vat" "text", "p_requested_billing_email" "text", "p_requested_address" "text", "p_requested_postal_code" "text", "p_requested_city" "text", "p_requested_province" "text", "p_requested_country" "text", "p_reason" "text", "p_apply_to_active_projects" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_company_iva_change"("p_requested_iva_aplicado" boolean, "p_requested_iva_porcentaje" numeric, "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE

    v_user_id UUID;
    v_company_id UUID;
    v_request_id UUID;
    v_percentage NUMERIC(5,2);
    v_reason TEXT;

BEGIN

    v_user_id := auth.uid();


    IF v_user_id IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado.';
    END IF;


    IF public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Los trabajadores no pueden crear solicitudes de IVA de cliente.';
    END IF;


    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION
            'El usuario no está activo.';
    END IF;


    v_company_id :=
        public.current_user_company_id();


    IF v_company_id IS NULL THEN
        RAISE EXCEPTION
            'El usuario no está asociado a una empresa.';
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM public.companies c
        WHERE c.id = v_company_id
          AND c.is_active = TRUE
    ) THEN
        RAISE EXCEPTION
            'La empresa no existe o está inactiva.';
    END IF;


    -- --------------------------------------------------------
    -- IVA
    -- --------------------------------------------------------

    IF p_requested_iva_aplicado IS NULL THEN
        RAISE EXCEPTION
            'Debes indicar si el IVA se aplica.';
    END IF;


    IF p_requested_iva_aplicado = FALSE THEN

        v_percentage := 0;

    ELSE

        IF p_requested_iva_porcentaje IS NULL THEN
            RAISE EXCEPTION
                'Debes indicar el porcentaje de IVA.';
        END IF;


        v_percentage :=
            ROUND(p_requested_iva_porcentaje, 2);


        IF v_percentage < 0
           OR v_percentage > 100
        THEN
            RAISE EXCEPTION
                'El porcentaje de IVA debe estar entre 0 y 100.';
        END IF;

    END IF;


    -- --------------------------------------------------------
    -- JUSTIFICACIÓN
    -- --------------------------------------------------------

    v_reason :=
        NULLIF(
            BTRIM(COALESCE(p_reason, '')),
            ''
        );


    IF v_reason IS NULL THEN
        RAISE EXCEPTION
            'Debes indicar el motivo de la solicitud.';
    END IF;


    IF char_length(v_reason) > 2000 THEN
        RAISE EXCEPTION
            'El motivo no puede superar 2000 caracteres.';
    END IF;


    IF pg_column_size(v_reason) > 16384 THEN
        RAISE EXCEPTION
            'El motivo supera el tamaño máximo permitido.';
    END IF;


    -- --------------------------------------------------------
    -- SOLICITUD ACTIVA
    -- --------------------------------------------------------

    IF EXISTS (
        SELECT 1
        FROM public.company_iva_change_requests r
        WHERE r.company_id = v_company_id
          AND r.status IN ('pending', 'in_review')
    ) THEN

        RAISE EXCEPTION
            'Ya existe una solicitud de IVA pendiente para esta empresa.';

    END IF;


    -- --------------------------------------------------------
    -- INSERT
    -- El trigger aplica rate limit al cliente.
    -- --------------------------------------------------------

    INSERT INTO public.company_iva_change_requests (
        company_id,
        user_id,
        requested_iva_aplicado,
        requested_iva_porcentaje,
        reason,
        status
    )
    VALUES (
        v_company_id,
        v_user_id,
        p_requested_iva_aplicado,
        v_percentage,
        v_reason,
        'pending'
    )
    RETURNING id
    INTO v_request_id;


    RETURN v_request_id;

END;
$$;


ALTER FUNCTION "public"."request_company_iva_change"("p_requested_iva_aplicado" boolean, "p_requested_iva_porcentaje" numeric, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_maintenance_contract_project_change"("p_contract_id" "uuid", "p_requested_project_id" "uuid") RETURNS "public"."maintenance_contract_project_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_company_id UUID;
  v_contract public.maintenance_contracts;
  v_current_project_id UUID;
  v_request public.maintenance_contract_project_change_requests;
  v_limit JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Debes iniciar sesión';
  END IF;

  IF public.current_user_is_worker() THEN
    RAISE EXCEPTION 'Los trabajadores no utilizan esta vía';
  END IF;

  IF NOT public.current_user_is_active() THEN
    RAISE EXCEPTION 'El usuario no está activo';
  END IF;

  v_company_id := public.current_user_company_id();

  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'El usuario no pertenece a ninguna empresa';
  END IF;

  SELECT *
  INTO v_contract
  FROM public.maintenance_contracts
  WHERE id = p_contract_id
    AND company_id = v_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'El contrato de mantenimiento no existe o no pertenece a tu empresa';
  END IF;

  IF NOT public.is_live_maintenance_contract_status(v_contract.estado) THEN
    RAISE EXCEPTION 'El mantenimiento no está activo o pausado';
  END IF;

  SELECT mcp.project_id
  INTO v_current_project_id
  FROM public.maintenance_contract_projects mcp
  WHERE mcp.maintenance_contract_id = v_contract.id
  ORDER BY mcp.created_at DESC
  LIMIT 1;

  IF v_current_project_id IS NULL THEN
    RAISE EXCEPTION 'El contrato no tiene un proyecto asociado';
  END IF;

  IF p_requested_project_id IS NULL THEN
    RAISE EXCEPTION 'Debes seleccionar un proyecto';
  END IF;

  IF p_requested_project_id = v_current_project_id THEN
    RAISE EXCEPTION 'El proyecto seleccionado ya es el proyecto actual';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.maintenance_contract_project_change_requests
    WHERE maintenance_contract_id = v_contract.id
      AND status = 'pending'
  ) THEN
    RAISE EXCEPTION 'Ya existe una solicitud de cambio de proyecto pendiente para este mantenimiento';
  END IF;

  IF v_contract.pending_project_id IS NOT NULL THEN
    RAISE EXCEPTION 'Ya existe un cambio de proyecto programado para este mantenimiento';
  END IF;

  -- El proyecto nuevo debe pertenecer a la empresa y estar disponible.
  PERFORM 1
  FROM public.projects p
  WHERE p.id = p_requested_project_id
    AND p.company_id = v_company_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'El proyecto seleccionado no existe o no pertenece a tu empresa';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.maintenance_contract_projects mcp
    JOIN public.maintenance_contracts other_mc
      ON other_mc.id = mcp.maintenance_contract_id
    WHERE mcp.project_id = p_requested_project_id
      AND other_mc.id <> v_contract.id
      AND public.is_live_maintenance_contract_status(other_mc.estado)
  ) THEN
    RAISE EXCEPTION 'El proyecto seleccionado ya tiene un mantenimiento activo o pausado';
  END IF;

  v_limit := public.consume_maintenance_change_rate_limit(
    v_company_id,
    'maintenance_project_change',
    1,
    604800
  );

  IF COALESCE((v_limit ->> 'allowed')::BOOLEAN, FALSE) = FALSE THEN
    RAISE EXCEPTION
      'Has alcanzado el límite de solicitudes de cambio de proyecto. Inténtalo de nuevo cuando finalice el periodo de espera.';
  END IF;

  INSERT INTO public.maintenance_contract_project_change_requests (
    maintenance_contract_id,
    company_id,
    requested_by,
    current_project_id,
    requested_project_id,
    status
  )
  VALUES (
    v_contract.id,
    v_company_id,
    v_user_id,
    v_current_project_id,
    p_requested_project_id,
    'pending'
  )
  RETURNING *
  INTO v_request;

  RETURN v_request;
END;
$$;


ALTER FUNCTION "public"."request_maintenance_contract_project_change"("p_contract_id" "uuid", "p_requested_project_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."maintenance_iva_change_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "maintenance_contract_id" "uuid",
    "requested_iva_aplicado" boolean DEFAULT true NOT NULL,
    "requested_iva_porcentaje" numeric(5,2) NOT NULL,
    "message" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "worker_notes" "text",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "maintenance_iva_change_requests_iva_check" CHECK (((("requested_iva_aplicado" = true) AND ("requested_iva_porcentaje" >= (0)::numeric) AND ("requested_iva_porcentaje" <= (100)::numeric)) OR (("requested_iva_aplicado" = false) AND ("requested_iva_porcentaje" = (0)::numeric)))),
    CONSTRAINT "maintenance_iva_change_requests_message_length_check" CHECK ((("message" IS NULL) OR (("char_length"("message") <= 2000) AND ("pg_column_size"("message") <= 16384)))),
    CONSTRAINT "maintenance_iva_change_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'in_review'::"text", 'approved'::"text", 'rejected'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "maintenance_iva_change_requests_worker_notes_length_check" CHECK ((("worker_notes" IS NULL) OR (("char_length"("worker_notes") <= 2000) AND ("pg_column_size"("worker_notes") <= 16384)))),
    CONSTRAINT "maintenance_iva_request_message_check" CHECK ((("length"("btrim"("message")) >= 1) AND ("length"("btrim"("message")) <= 2000))),
    CONSTRAINT "maintenance_iva_request_percentage_check" CHECK ((("requested_iva_porcentaje" >= (0)::numeric) AND ("requested_iva_porcentaje" <= (100)::numeric))),
    CONSTRAINT "maintenance_iva_request_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'in_review'::"text", 'approved'::"text", 'rejected'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."maintenance_iva_change_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."maintenance_iva_change_requests" IS 'Solicitudes de cambio del tratamiento de IVA específico de mantenimiento. Este sistema es independiente del IVA general de la empresa, de presupuestos y de facturas normales.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."id" IS 'Identificador único de la solicitud de cambio de IVA de mantenimiento.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."company_id" IS 'Empresa a la que pertenece la solicitud de IVA de mantenimiento.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."user_id" IS 'Usuario cliente que presentó la solicitud de cambio de IVA de mantenimiento.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."maintenance_contract_id" IS 'Contrato de mantenimiento al que se refiere la solicitud cuando existe. Puede ser NULL cuando el cliente solicita el tratamiento de IVA antes de tener un contrato de mantenimiento.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."requested_iva_aplicado" IS 'Indica si el cliente solicita aplicar IVA al tratamiento fiscal del mantenimiento.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."requested_iva_porcentaje" IS 'Porcentaje de IVA de mantenimiento solicitado por el cliente. Debe estar entre 0 y 100 cuando el IVA está aplicado y debe ser 0 cuando no está aplicado.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."message" IS 'Mensaje o justificación aportada por el cliente para solicitar el tratamiento de IVA de mantenimiento. Máximo 2.000 caracteres y 16 KiB.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."status" IS 'Estado de la solicitud de IVA de mantenimiento: pending, in_review, approved, rejected o cancelled.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."reviewed_by" IS 'Usuario de Auth del worker que resolvió la solicitud de IVA de mantenimiento.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."reviewed_at" IS 'Fecha y hora en que el worker resolvió la solicitud de IVA de mantenimiento.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."worker_notes" IS 'Notas internas introducidas por el worker al revisar o resolver la solicitud. Máximo 2.000 caracteres y 16 KiB.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."created_at" IS 'Fecha y hora de creación de la solicitud de IVA de mantenimiento.';



COMMENT ON COLUMN "public"."maintenance_iva_change_requests"."updated_at" IS 'Fecha y hora de la última modificación de la solicitud de IVA de mantenimiento.';



CREATE OR REPLACE FUNCTION "public"."request_maintenance_iva_change"("p_requested_iva_aplicado" boolean, "p_requested_iva_porcentaje" numeric, "p_message" "text", "p_maintenance_contract_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."maintenance_iva_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_company_id UUID;
    v_request public.maintenance_iva_change_requests;
    v_contract public.maintenance_contracts;
BEGIN

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION
            'La cuenta no está activa';
    END IF;


    IF public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Los trabajadores no pueden crear solicitudes de cliente';
    END IF;


    -- --------------------------------------------------------
    -- EMPRESA
    -- --------------------------------------------------------

    v_company_id :=
        public.current_user_company_id();


    IF v_company_id IS NULL THEN
        RAISE EXCEPTION
            'El usuario no tiene una empresa asociada';
    END IF;


    -- --------------------------------------------------------
    -- IVA
    -- --------------------------------------------------------

    IF p_requested_iva_porcentaje IS NULL
       OR p_requested_iva_porcentaje < 0
       OR p_requested_iva_porcentaje > 100
    THEN
        RAISE EXCEPTION
            'El porcentaje de IVA solicitado debe estar entre 0 y 100';
    END IF;


    IF p_message IS NULL
       OR LENGTH(BTRIM(p_message)) = 0
    THEN
        RAISE EXCEPTION
            'Debes indicar el motivo de la solicitud';
    END IF;


    IF LENGTH(BTRIM(p_message)) > 2000 THEN
        RAISE EXCEPTION
            'El mensaje no puede superar 2000 caracteres';
    END IF;


    -- --------------------------------------------------------
    -- CONTRATO OPCIONAL
    -- --------------------------------------------------------

    IF p_maintenance_contract_id IS NOT NULL THEN

        SELECT *
        INTO v_contract
        FROM public.maintenance_contracts
        WHERE id = p_maintenance_contract_id
          AND company_id = v_company_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'El contrato de mantenimiento no pertenece a tu empresa';
        END IF;

    END IF;


    -- --------------------------------------------------------
    -- EVITAR DUPLICADOS
    -- --------------------------------------------------------

    IF EXISTS (
        SELECT 1
        FROM public.maintenance_iva_change_requests
        WHERE company_id = v_company_id
          AND status IN ('pending', 'in_review')
    ) THEN
        RAISE EXCEPTION
            'Ya existe una solicitud de cambio de IVA pendiente para esta empresa';
    END IF;


    -- --------------------------------------------------------
    -- CREAR SOLICITUD
    -- --------------------------------------------------------

    INSERT INTO public.maintenance_iva_change_requests (
        company_id,
        user_id,
        maintenance_contract_id,
        requested_iva_aplicado,
        requested_iva_porcentaje,
        message,
        status
    )
    VALUES (
        v_company_id,
        auth.uid(),
        p_maintenance_contract_id,
        COALESCE(p_requested_iva_aplicado, TRUE),
        ROUND(p_requested_iva_porcentaje, 2),
        BTRIM(p_message),
        'pending'
    )
    RETURNING *
    INTO v_request;


    RETURN v_request;

END;
$$;


ALTER FUNCTION "public"."request_maintenance_iva_change"("p_requested_iva_aplicado" boolean, "p_requested_iva_porcentaje" numeric, "p_message" "text", "p_maintenance_contract_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."project_change_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "company_id" "uuid",
    "client_id" "uuid",
    "description" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_notes" "text",
    "accepted_at" timestamp with time zone,
    "completed_by" "uuid",
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "project_change_requests_description_check" CHECK ((("length"("btrim"("description")) > 0) AND ("length"("description") <= 5000))),
    CONSTRAINT "project_change_requests_description_length_check" CHECK ((("description" IS NULL) OR ("length"("description") <= 5000))),
    CONSTRAINT "project_change_requests_review_notes_check" CHECK ((("review_notes" IS NULL) OR ("length"("review_notes") <= 5000))),
    CONSTRAINT "project_change_requests_review_notes_length_check" CHECK ((("review_notes" IS NULL) OR ("length"("review_notes") <= 5000))),
    CONSTRAINT "project_change_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'in_review'::"text", 'accepted'::"text", 'rejected'::"text", 'completed'::"text"])))
);


ALTER TABLE "public"."project_change_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_project_change"("p_project_id" "uuid", "p_description" "text") RETURNS "public"."project_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_project public.projects;
    v_request public.project_change_requests;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado';
    END IF;

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION 'Acceso denegado: la cuenta está bloqueada';
    END IF;

    IF public.current_user_is_worker() THEN
        RAISE EXCEPTION 'Los trabajadores no pueden crear solicitudes de cambio de cliente';
    END IF;

    IF p_project_id IS NULL THEN
        RAISE EXCEPTION 'El proyecto es obligatorio';
    END IF;

    IF p_description IS NULL OR btrim(p_description) = '' THEN
        RAISE EXCEPTION 'La descripción del cambio es obligatoria';
    END IF;

    IF length(p_description) > 5000 THEN
        RAISE EXCEPTION 'La descripción del cambio no puede superar 5000 caracteres';
    END IF;

    SELECT *
    INTO v_project
    FROM public.projects
    WHERE id = p_project_id
      AND user_id = auth.uid()
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El proyecto no existe o no pertenece al usuario autenticado';
    END IF;

    IF v_project.change_requests_enabled IS NOT TRUE THEN
        RAISE EXCEPTION 'Las solicitudes de cambio no están habilitadas para este proyecto';
    END IF;

    IF v_project.change_requests_deadline IS NULL THEN
        RAISE EXCEPTION 'El proyecto no tiene una fecha límite de solicitudes configurada';
    END IF;

    IF CURRENT_TIMESTAMP > v_project.change_requests_deadline THEN
        RAISE EXCEPTION 'El periodo para solicitar cambios ha finalizado';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.project_change_requests r
        WHERE r.project_id = v_project.id
          AND r.status IN ('pending', 'in_review', 'accepted')
    ) THEN
        RAISE EXCEPTION 'Este proyecto ya tiene una solicitud de cambio en curso';
    END IF;

    INSERT INTO public.project_change_requests (
        project_id,
        user_id,
        company_id,
        client_id,
        description,
        status
    )
    VALUES (
        v_project.id,
        auth.uid(),
        v_project.company_id,
        v_project.client_id,
        btrim(p_description),
        'pending'
    )
    RETURNING * INTO v_request;

    INSERT INTO public.activity_log (
        user_id,
        company_id,
        action,
        resource_type,
        resource_id,
        description,
        metadata
    )
    VALUES (
        auth.uid(),
        v_project.company_id,
        'project.change_request_created',
        'project_change_request',
        v_request.id,
        'El cliente ha solicitado un cambio en el proyecto',
        jsonb_build_object(
            'project_id', v_project.id,
            'description', v_request.description
        )
    );

    RETURN v_request;
END;
$$;


ALTER FUNCTION "public"."request_project_change"("p_project_id" "uuid", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_project_ownership_transfer"("p_project_id" "uuid", "p_new_owner_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."project_ownership_transfers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$

DECLARE
    v_project public.projects;
    v_new_owner public.profiles;
    v_transfer public.project_ownership_transfers;
    v_snapshot JSONB;
    v_hash TEXT;

BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado';
    END IF;

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION 'La cuenta no está activa';
    END IF;


    SELECT *
    INTO v_project
    FROM public.projects
    WHERE id = p_project_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Proyecto no encontrado';
    END IF;


    -- Solo el propietario actual puede solicitar la transferencia.

    IF v_project.user_id IS DISTINCT FROM auth.uid() THEN
        RAISE EXCEPTION
            'Solo el propietario actual puede solicitar la transferencia';
    END IF;


    IF p_new_owner_id IS NULL THEN
        RAISE EXCEPTION 'El nuevo propietario es obligatorio';
    END IF;


    IF p_new_owner_id = auth.uid() THEN
        RAISE EXCEPTION
            'El nuevo propietario debe ser diferente al propietario actual';
    END IF;


    SELECT *
    INTO v_new_owner
    FROM public.profiles
    WHERE id = p_new_owner_id
      AND status = 'active'
      AND company_id = v_project.company_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El nuevo propietario debe ser un usuario activo de la misma empresa';
    END IF;


    IF EXISTS (
        SELECT 1
        FROM public.project_ownership_transfers t
        WHERE t.project_id = v_project.id
          AND t.status IN (
              'pending_approval',
              'pending_acceptance'
          )
    ) THEN
        RAISE EXCEPTION
            'Ya existe una transferencia pendiente para este proyecto';
    END IF;


    v_snapshot := jsonb_build_object(
        'project_id', v_project.id,
        'company_id', v_project.company_id,
        'previous_owner_id', v_project.user_id,
        'new_owner_id', p_new_owner_id,
        'project_state', v_project.state,
        'project_client_id', v_project.client_id,
        'created_at', v_project.created_at,
        'captured_at', CURRENT_TIMESTAMP
    );

    v_hash := encode(
        extensions.digest(
            v_snapshot::text,
            'sha256'
        ),
        'hex'
    );


    INSERT INTO public.project_ownership_transfers (
        project_id,
        company_id,
        previous_owner_id,
        requested_new_owner_id,
        requested_by,
        reason,
        status,
        project_snapshot,
        project_snapshot_hash,
        acknowledgement_text_version
    )
    VALUES (
        v_project.id,
        v_project.company_id,
        v_project.user_id,
        p_new_owner_id,
        auth.uid(),
        p_reason,
        'pending_approval',
        v_snapshot,
        v_hash,
        'project_ownership_transfer_v1'
    )
    RETURNING *
    INTO v_transfer;


    RETURN v_transfer;

END;
$$;


ALTER FUNCTION "public"."request_project_ownership_transfer"("p_project_id" "uuid", "p_new_owner_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."quotation_change_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "quotation_id" "uuid" NOT NULL,
    "official_version_id" "uuid" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "request_text" "text" NOT NULL,
    "request_status" "text" DEFAULT 'open'::"text" NOT NULL,
    "requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "resolved_by" "uuid",
    "resolved_version_id" "uuid",
    CONSTRAINT "quotation_change_requests_request_status_check" CHECK (("request_status" = ANY (ARRAY['open'::"text", 'resolved'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "quotation_change_requests_request_text_check" CHECK ((("length"("btrim"("request_text")) >= 1) AND ("length"("btrim"("request_text")) <= 5000))),
    CONSTRAINT "quotation_change_requests_resolution_check" CHECK (((("request_status" = 'open'::"text") AND ("resolved_at" IS NULL) AND ("resolved_by" IS NULL) AND ("resolved_version_id" IS NULL)) OR (("request_status" <> 'open'::"text") AND ("resolved_at" IS NOT NULL) AND ("resolved_by" IS NOT NULL))))
);


ALTER TABLE "public"."quotation_change_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_quotation_changes"("p_quotation_id" "uuid", "p_request_text" "text") RETURNS "public"."quotation_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_quotation public.quotations%ROWTYPE;
  v_state public.quotation_workflow_state%ROWTYPE;
  v_version public.quotation_official_versions%ROWTYPE;
  v_request public.quotation_change_requests%ROWTYPE;
  v_text text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Usuario no autenticado'; END IF;
  IF public.current_user_is_worker() THEN RAISE EXCEPTION 'Solo el cliente puede solicitar cambios'; END IF;
  IF NOT public.current_user_is_active() THEN RAISE EXCEPTION 'La cuenta no está activa'; END IF;

  v_text := btrim(COALESCE(p_request_text, ''));
  IF length(v_text) < 1 OR length(v_text) > 5000 THEN
    RAISE EXCEPTION 'Explica los cambios solicitados (máximo 5000 caracteres)';
  END IF;

  PERFORM public.enforce_security_rate_limit(
    'quotation_change_request:user:' || auth.uid()::text, 5, 3600
  );
  PERFORM public.enforce_security_rate_limit(
    'quotation_change_request:quotation:' || COALESCE(p_quotation_id::text, 'null') || ':' || auth.uid()::text,
    3,
    86400
  );

  SELECT * INTO v_quotation
  FROM public.quotations
  WHERE id = p_quotation_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Presupuesto no encontrado'; END IF;

  IF NOT (
    v_quotation.user_id = auth.uid()
    OR EXISTS (
      SELECT 1 FROM public.clients c
      WHERE c.id = v_quotation.client_id AND c.profile_id = auth.uid()
    )
  ) THEN
    RAISE EXCEPTION 'No tienes acceso a este presupuesto';
  END IF;

  SELECT * INTO v_state
  FROM public.quotation_workflow_state
  WHERE quotation_id = p_quotation_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Este presupuesto todavía no utiliza el nuevo flujo'; END IF;
  IF v_state.workflow_status <> 'presented' THEN
    RAISE EXCEPTION 'Solo se pueden solicitar cambios a una versión pendiente de respuesta';
  END IF;
  IF v_quotation.estado <> 'Pendiente' THEN
    RAISE EXCEPTION 'El presupuesto ya no admite solicitudes de cambio';
  END IF;

  SELECT * INTO v_version
  FROM public.quotation_official_versions
  WHERE id = v_state.current_version_id AND quotation_id = p_quotation_id AND is_current = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'No se encuentra la versión oficial actual'; END IF;
  IF v_version.document_path IS NULL OR v_version.document_sha256 IS NULL
     OR v_quotation.document_path IS DISTINCT FROM v_version.document_path
     OR lower(COALESCE(v_quotation.document_sha256, '')) IS DISTINCT FROM lower(COALESCE(v_version.document_sha256, '')) THEN
    RAISE EXCEPTION 'El PDF de la versión oficial no está generado o no coincide con su huella digital';
  END IF;

  INSERT INTO public.quotation_change_requests (
    quotation_id, official_version_id, requested_by, request_text
  ) VALUES (
    p_quotation_id, v_version.id, auth.uid(), v_text
  ) RETURNING * INTO v_request;

  UPDATE public.quotation_workflow_state
  SET workflow_status = 'in_review', updated_at = now(), updated_by = auth.uid()
  WHERE quotation_id = p_quotation_id;

  -- Si ya había una corrección interna en curso, conservar su contenido pero
  -- convertirla en el borrador que atenderá formalmente esta solicitud (V2, V3...).
  UPDATE public.quotation_workflow_drafts
  SET draft_kind = 'requested_change', updated_at = now()
  WHERE quotation_id = p_quotation_id
    AND draft_status = 'draft'
    AND draft_kind = 'correction';

  -- Notificar al trabajador que publicó la versión vigente.
  INSERT INTO public.notifications (user_id, project_id, tipo, titulo, mensaje, metadata)
  VALUES (
    v_version.published_by,
    v_quotation.project_id,
    'quotation',
    'Solicitud de cambios en presupuesto',
    'El cliente ha solicitado cambios en el presupuesto ' || COALESCE(v_quotation.numero_presupuesto, '') || '.',
    jsonb_build_object(
      'event', 'quotation_change_requested',
      'quotation_id', v_quotation.id,
      'version_id', v_version.id,
      'version_label', v_version.version_label,
      'change_request_id', v_request.id
    )
  );

  RETURN v_request;
END;
$$;


ALTER FUNCTION "public"."request_quotation_changes"("p_quotation_id" "uuid", "p_request_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_current_worker_permission"("p_permission" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Acceso denegado: usuario no autenticado';
    END IF;

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;

    IF NOT public.current_worker_has_permission(p_permission) THEN
        RAISE EXCEPTION
            'Acceso denegado: falta el permiso %',
            p_permission;
    END IF;

END;
$$;


ALTER FUNCTION "public"."require_current_worker_permission"("p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_expense_permission"("p_permission" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION
      'Usuario no autenticado';
  END IF;


  IF NOT public.current_user_is_worker() THEN
    RAISE EXCEPTION
      'Solo los trabajadores pueden gestionar gastos internos';
  END IF;


  IF NOT public.current_user_is_active() THEN
    RAISE EXCEPTION
      'El trabajador no está activo';
  END IF;


  IF p_permission IS NULL
     OR BTRIM(p_permission) = '' THEN
    RAISE EXCEPTION
      'Permiso requerido no especificado';
  END IF;


  IF NOT public.current_worker_has_permission(p_permission) THEN
    RAISE EXCEPTION
      'No tienes permiso para realizar esta operación';
  END IF;

END;
$$;


ALTER FUNCTION "public"."require_expense_permission"("p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_maintenance_invoice_document"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- La Edge Function puede crear primero la factura local a partir del
  -- webhook de Stripe y el worker adjuntar después el documento de Modira.
  -- Por eso no exigimos el PDF durante el INSERT inicial.
  --
  -- Sí lo exigimos cuando una factura que estaba en borrador pasa a un
  -- estado emitido/operativo.
  IF TG_OP = 'UPDATE'
     AND OLD.estado = 'borrador'
     AND NEW.estado <> 'borrador'
     AND NEW.document_path IS NULL
     AND NEW.electronic_document_storage_path IS NULL
  THEN
    RAISE EXCEPTION
      'La factura de mantenimiento debe tener un documento asociado antes de emitirse';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."require_maintenance_invoice_document"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_ai_anonymous_quota"("p_identity_key" "text", "p_estimated_input_tokens" integer, "p_estimated_output_tokens" integer, "p_estimated_cost_cents" numeric) RETURNS TABLE("allowed" boolean, "reservation_id" "uuid", "retry_after_seconds" integer, "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$

DECLARE

    c public.ai_quota_config;

    v_now TIMESTAMPTZ := clock_timestamp();

    v_period_end TIMESTAMPTZ;

    v_row public.ai_anonymous_quota_periods;

    v_count BIGINT;

    v_reservation UUID;

BEGIN

    -- ========================================================
    -- VALIDACIÓN
    -- ========================================================

    IF p_identity_key IS NULL
       OR p_identity_key NOT LIKE 'anon-ip:%'
       OR LENGTH(p_identity_key) > 200
       OR p_estimated_input_tokens < 0
       OR p_estimated_output_tokens < 0
       OR p_estimated_cost_cents < 0
    THEN

        RAISE EXCEPTION
            'Invalid anonymous AI quota parameters';

    END IF;


    -- ========================================================
    -- CONFIGURACIÓN
    -- ========================================================

    SELECT *
    INTO c

    FROM public.ai_quota_config

    WHERE config_key = 'modira-ai'

    FOR SHARE;


    IF NOT FOUND
       OR NOT c.enabled
    THEN

        RETURN QUERY
        SELECT
            FALSE,
            NULL::UUID,
            3600,
            'disabled';

        RETURN;

    END IF;


    v_period_end :=
        v_now
        + make_interval(
            secs => c.anonymous_period_seconds
        );


    -- ========================================================
    -- LOCK POR IDENTIDAD ANÓNIMA
    -- ========================================================

    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            p_identity_key,
            19020
        )
    );


    -- ========================================================
    -- CREAR / RENOVAR PERIODO
    -- ========================================================

    INSERT INTO public.ai_anonymous_quota_periods (
        identity_key,
        period_started_at,
        period_ends_at
    )

    VALUES (
        p_identity_key,
        v_now,
        v_period_end
    )

    ON CONFLICT (identity_key)
    DO UPDATE
    SET

        period_started_at =
            CASE
                WHEN ai_anonymous_quota_periods.period_ends_at <= v_now
                THEN v_now
                ELSE ai_anonymous_quota_periods.period_started_at
            END,

        period_ends_at =
            CASE
                WHEN ai_anonymous_quota_periods.period_ends_at <= v_now
                THEN v_period_end
                ELSE ai_anonymous_quota_periods.period_ends_at
            END,

        request_count =
            CASE
                WHEN ai_anonymous_quota_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_anonymous_quota_periods.request_count
            END,

        input_tokens =
            CASE
                WHEN ai_anonymous_quota_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_anonymous_quota_periods.input_tokens
            END,

        output_tokens =
            CASE
                WHEN ai_anonymous_quota_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_anonymous_quota_periods.output_tokens
            END,

        cost_cents =
            CASE
                WHEN ai_anonymous_quota_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_anonymous_quota_periods.cost_cents
            END,

        reserved_requests =
            CASE
                WHEN ai_anonymous_quota_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_anonymous_quota_periods.reserved_requests
            END,

        reserved_input_tokens =
            CASE
                WHEN ai_anonymous_quota_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_anonymous_quota_periods.reserved_input_tokens
            END,

        reserved_output_tokens =
            CASE
                WHEN ai_anonymous_quota_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_anonymous_quota_periods.reserved_output_tokens
            END,

        reserved_cost_cents =
            CASE
                WHEN ai_anonymous_quota_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_anonymous_quota_periods.reserved_cost_cents
            END,

        updated_at = v_now

    RETURNING *
    INTO v_row;


    -- ========================================================
    -- LÍMITE REQUESTS
    -- ========================================================

    v_count :=
        v_row.request_count
        + v_row.reserved_requests;


    IF v_count >= c.anonymous_request_limit
    THEN

        RETURN QUERY
        SELECT
            FALSE,
            NULL::UUID,

            GREATEST(
                1,
                CEIL(
                    EXTRACT(
                        EPOCH FROM
                        (
                            v_row.period_ends_at
                            - v_now
                        )
                    )
                )::INTEGER
            ),

            'anonymous_request_limit';

        RETURN;

    END IF;


    -- ========================================================
    -- LÍMITE ECONÓMICO OPCIONAL
    -- ========================================================

    IF c.anonymous_budget_cents IS NOT NULL
       AND
       (
           v_row.cost_cents
           + v_row.reserved_cost_cents
           + p_estimated_cost_cents
       ) > c.anonymous_budget_cents
    THEN

        RETURN QUERY
        SELECT
            FALSE,
            NULL::UUID,

            GREATEST(
                1,
                CEIL(
                    EXTRACT(
                        EPOCH FROM
                        (
                            v_row.period_ends_at
                            - v_now
                        )
                    )
                )::INTEGER
            ),

            'budget_limit';

        RETURN;

    END IF;


    -- ========================================================
    -- RESERVA
    -- ========================================================

    v_reservation :=
        gen_random_uuid();


    INSERT INTO public.ai_usage_reservations (
        id,
        user_id,
        company_id,
        scope_key,
        estimated_input_tokens,
        estimated_output_tokens,
        estimated_cost_cents,
        expires_at
    )

    VALUES (
        v_reservation,
        NULL,
        NULL,
        p_identity_key,
        p_estimated_input_tokens,
        p_estimated_output_tokens,
        p_estimated_cost_cents,
        v_now + INTERVAL '2 minutes'
    );


    UPDATE public.ai_anonymous_quota_periods

    SET

        reserved_requests =
            reserved_requests + 1,

        reserved_input_tokens =
            reserved_input_tokens
            + p_estimated_input_tokens,

        reserved_output_tokens =
            reserved_output_tokens
            + p_estimated_output_tokens,

        reserved_cost_cents =
            reserved_cost_cents
            + p_estimated_cost_cents,

        updated_at = v_now

    WHERE identity_key = p_identity_key;


    RETURN QUERY
    SELECT
        TRUE,
        v_reservation,
        0,
        'allowed';

END;

$$;


ALTER FUNCTION "public"."reserve_ai_anonymous_quota"("p_identity_key" "text", "p_estimated_input_tokens" integer, "p_estimated_output_tokens" integer, "p_estimated_cost_cents" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_ai_quota_for_user"("p_user_id" "uuid", "p_company_id" "uuid", "p_estimated_input_tokens" integer, "p_estimated_output_tokens" integer, "p_estimated_cost_cents" numeric) RETURNS TABLE("allowed" boolean, "reservation_id" "uuid", "retry_after_seconds" integer, "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$

DECLARE

    v_config public.ai_quota_config;

    v_profile public.profiles;

    v_now TIMESTAMPTZ := clock_timestamp();

    v_period_end TIMESTAMPTZ;

    v_user_key TEXT;

    v_company_key TEXT;

    v_user public.ai_usage_periods;

    v_company public.ai_usage_periods;

    v_reservation UUID;

    v_user_count BIGINT;

    v_company_count BIGINT;

BEGIN

    -- ========================================================
    -- VALIDACIÓN
    -- ========================================================

    IF p_user_id IS NULL
       OR p_estimated_input_tokens < 0
       OR p_estimated_output_tokens < 0
       OR p_estimated_cost_cents < 0
    THEN

        RAISE EXCEPTION
            'Invalid AI quota parameters';

    END IF;


    -- ========================================================
    -- CONFIGURACIÓN
    -- ========================================================

    SELECT *
    INTO v_config

    FROM public.ai_quota_config

    WHERE config_key = 'modira-ai'

    FOR SHARE;


    IF NOT FOUND
       OR NOT v_config.enabled
    THEN

        RETURN QUERY
        SELECT
            FALSE,
            NULL::UUID,
            3600,
            'disabled';

        RETURN;

    END IF;


    -- ========================================================
    -- PERFIL ACTIVO
    -- ========================================================

    SELECT *
    INTO v_profile

    FROM public.profiles

    WHERE id = p_user_id;


    IF NOT FOUND
       OR v_profile.status <> 'active'
    THEN

        RETURN QUERY
        SELECT
            FALSE,
            NULL::UUID,
            3600,
            'inactive';

        RETURN;

    END IF;


    -- ========================================================
    -- EMPRESA
    -- ========================================================
    --
    -- El company_id utilizado por la Edge Function debe
    -- coincidir con el profile real.
    --

    IF v_profile.company_id IS DISTINCT FROM p_company_id
    THEN

        RAISE EXCEPTION
            'Invalid AI company identity';

    END IF;


    -- ========================================================
    -- PERIODO
    -- ========================================================

    v_period_end :=
        v_now
        + make_interval(
            secs => v_config.period_seconds
        );


    v_user_key :=
        'user:' || p_user_id::TEXT;


    -- ========================================================
    -- LOCK POR USUARIO
    -- ========================================================

    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            v_user_key,
            19019
        )
    );


    -- ========================================================
    -- CREAR / RENOVAR PERIODO
    -- ========================================================

    INSERT INTO public.ai_usage_periods (
        scope_key,
        user_id,
        company_id,
        period_started_at,
        period_ends_at
    )

    VALUES (
        v_user_key,
        p_user_id,
        p_company_id,
        v_now,
        v_period_end
    )

    ON CONFLICT (scope_key)
    DO UPDATE
    SET

        period_started_at =
            CASE
                WHEN ai_usage_periods.period_ends_at <= v_now
                THEN v_now
                ELSE ai_usage_periods.period_started_at
            END,

        period_ends_at =
            CASE
                WHEN ai_usage_periods.period_ends_at <= v_now
                THEN v_period_end
                ELSE ai_usage_periods.period_ends_at
            END,

        request_count =
            CASE
                WHEN ai_usage_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_usage_periods.request_count
            END,

        input_tokens =
            CASE
                WHEN ai_usage_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_usage_periods.input_tokens
            END,

        output_tokens =
            CASE
                WHEN ai_usage_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_usage_periods.output_tokens
            END,

        cost_cents =
            CASE
                WHEN ai_usage_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_usage_periods.cost_cents
            END,

        reserved_requests =
            CASE
                WHEN ai_usage_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_usage_periods.reserved_requests
            END,

        reserved_input_tokens =
            CASE
                WHEN ai_usage_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_usage_periods.reserved_input_tokens
            END,

        reserved_output_tokens =
            CASE
                WHEN ai_usage_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_usage_periods.reserved_output_tokens
            END,

        reserved_cost_cents =
            CASE
                WHEN ai_usage_periods.period_ends_at <= v_now
                THEN 0
                ELSE ai_usage_periods.reserved_cost_cents
            END,

        updated_at = v_now

    RETURNING *
    INTO v_user;


    -- ========================================================
    -- LÍMITE DE REQUESTS
    -- ========================================================

    v_user_count :=
        v_user.request_count
        + v_user.reserved_requests;


    IF v_user_count >= v_config.user_request_limit
    THEN

        RETURN QUERY
        SELECT
            FALSE,
            NULL::UUID,

            GREATEST(
                1,
                CEIL(
                    EXTRACT(
                        EPOCH FROM
                        (
                            v_user.period_ends_at
                            - v_now
                        )
                    )
                )::INTEGER
            ),

            'user_request_limit';

        RETURN;

    END IF;


    -- ========================================================
    -- LÍMITE ECONÓMICO OPCIONAL
    -- ========================================================

    IF v_config.budget_cents IS NOT NULL
       AND
       (
           v_user.cost_cents
           + v_user.reserved_cost_cents
           + p_estimated_cost_cents
       ) > v_config.budget_cents
    THEN

        RETURN QUERY
        SELECT
            FALSE,
            NULL::UUID,

            GREATEST(
                1,
                CEIL(
                    EXTRACT(
                        EPOCH FROM
                        (
                            v_user.period_ends_at
                            - v_now
                        )
                    )
                )::INTEGER
            ),

            'budget_limit';

        RETURN;

    END IF;


    -- ========================================================
    -- CUOTA POR EMPRESA OPCIONAL
    -- ========================================================

    IF p_company_id IS NOT NULL
       AND v_config.company_request_limit IS NOT NULL
    THEN

        v_company_key :=
            'company:' || p_company_id::TEXT;


        PERFORM pg_advisory_xact_lock(
            hashtextextended(
                v_company_key,
                19019
            )
        );


        INSERT INTO public.ai_usage_periods (
            scope_key,
            user_id,
            company_id,
            period_started_at,
            period_ends_at
        )

        VALUES (
            v_company_key,
            p_user_id,
            p_company_id,
            v_now,
            v_period_end
        )

        ON CONFLICT (scope_key)
        DO UPDATE
        SET

            period_started_at =
                CASE
                    WHEN ai_usage_periods.period_ends_at <= v_now
                    THEN v_now
                    ELSE ai_usage_periods.period_started_at
                END,

            period_ends_at =
                CASE
                    WHEN ai_usage_periods.period_ends_at <= v_now
                    THEN v_period_end
                    ELSE ai_usage_periods.period_ends_at
                END,

            request_count =
                CASE
                    WHEN ai_usage_periods.period_ends_at <= v_now
                    THEN 0
                    ELSE ai_usage_periods.request_count
                END,

            reserved_requests =
                CASE
                    WHEN ai_usage_periods.period_ends_at <= v_now
                    THEN 0
                    ELSE ai_usage_periods.reserved_requests
                END,

            input_tokens =
                CASE
                    WHEN ai_usage_periods.period_ends_at <= v_now
                    THEN 0
                    ELSE ai_usage_periods.input_tokens
                END,

            output_tokens =
                CASE
                    WHEN ai_usage_periods.period_ends_at <= v_now
                    THEN 0
                    ELSE ai_usage_periods.output_tokens
                END,

            cost_cents =
                CASE
                    WHEN ai_usage_periods.period_ends_at <= v_now
                    THEN 0
                    ELSE ai_usage_periods.cost_cents
                END,

            reserved_input_tokens =
                CASE
                    WHEN ai_usage_periods.period_ends_at <= v_now
                    THEN 0
                    ELSE ai_usage_periods.reserved_input_tokens
                END,

            reserved_output_tokens =
                CASE
                    WHEN ai_usage_periods.period_ends_at <= v_now
                    THEN 0
                    ELSE ai_usage_periods.reserved_output_tokens
                END,

            reserved_cost_cents =
                CASE
                    WHEN ai_usage_periods.period_ends_at <= v_now
                    THEN 0
                    ELSE ai_usage_periods.reserved_cost_cents
                END,

            updated_at = v_now

        RETURNING *
        INTO v_company;


        v_company_count :=
            v_company.request_count
            + v_company.reserved_requests;


        IF v_company_count
           >= v_config.company_request_limit
        THEN

            RETURN QUERY
            SELECT
                FALSE,
                NULL::UUID,

                GREATEST(
                    1,
                    CEIL(
                        EXTRACT(
                            EPOCH FROM
                            (
                                v_company.period_ends_at
                                - v_now
                            )
                        )
                    )::INTEGER
                ),

                'company_request_limit';

            RETURN;

        END IF;

    END IF;


    -- ========================================================
    -- CREAR RESERVA
    -- ========================================================

    v_reservation :=
        gen_random_uuid();


    INSERT INTO public.ai_usage_reservations (
        id,
        user_id,
        company_id,
        scope_key,
        estimated_input_tokens,
        estimated_output_tokens,
        estimated_cost_cents,
        expires_at
    )

    VALUES (
        v_reservation,
        p_user_id,
        p_company_id,
        v_user_key,
        p_estimated_input_tokens,
        p_estimated_output_tokens,
        p_estimated_cost_cents,
        v_now + INTERVAL '2 minutes'
    );


    UPDATE public.ai_usage_periods

    SET

        reserved_requests =
            reserved_requests + 1,

        reserved_input_tokens =
            reserved_input_tokens
            + p_estimated_input_tokens,

        reserved_output_tokens =
            reserved_output_tokens
            + p_estimated_output_tokens,

        reserved_cost_cents =
            reserved_cost_cents
            + p_estimated_cost_cents,

        updated_at = v_now

    WHERE scope_key = v_user_key;


    IF p_company_id IS NOT NULL
       AND v_config.company_request_limit IS NOT NULL
    THEN

        UPDATE public.ai_usage_periods

        SET

            reserved_requests =
                reserved_requests + 1,

            reserved_input_tokens =
                reserved_input_tokens
                + p_estimated_input_tokens,

            reserved_output_tokens =
                reserved_output_tokens
                + p_estimated_output_tokens,

            reserved_cost_cents =
                reserved_cost_cents
                + p_estimated_cost_cents,

            updated_at = v_now

        WHERE scope_key =
            v_company_key;

    END IF;


    RETURN QUERY
    SELECT
        TRUE,
        v_reservation,
        0,
        'allowed';

END;

$$;


ALTER FUNCTION "public"."reserve_ai_quota_for_user"("p_user_id" "uuid", "p_company_id" "uuid", "p_estimated_input_tokens" integer, "p_estimated_output_tokens" integer, "p_estimated_cost_cents" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_maintenance_billing_failures"("p_subscription_id" "text") RETURNS "public"."maintenance_contracts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_contract public.maintenance_contracts;
BEGIN
  IF p_subscription_id IS NULL OR BTRIM(p_subscription_id) = '' THEN
    RAISE EXCEPTION 'subscription_id obligatorio';
  END IF;

  SELECT *
  INTO v_contract
  FROM public.maintenance_contracts
  WHERE stripe_subscription_id = p_subscription_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'No existe un contrato de mantenimiento para la suscripción %',
      p_subscription_id;
  END IF;

  UPDATE public.maintenance_contracts
  SET
    billing_failure_count = 0,
    last_payment_failed_at = NULL,
    billing_blocked_at = NULL,
    billing_block_reason = NULL,
    updated_at = CURRENT_TIMESTAMP
  WHERE id = v_contract.id
  RETURNING *
  INTO v_contract;

  RETURN v_contract;
END;
$$;


ALTER FUNCTION "public"."reset_maintenance_billing_failures"("p_subscription_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_account_deletion"("p_request_id" "uuid", "p_decision" "text", "p_rejection_reason" "text" DEFAULT NULL::"text") RETURNS "public"."account_deletion_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$

DECLARE
    v_request public.account_deletion_requests;
    v_target_profile public.profiles;

BEGIN

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- SOLO WORKER ACTIVO
    -- --------------------------------------------------------

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    -- --------------------------------------------------------
    -- VALIDAR DECISIÓN
    -- --------------------------------------------------------

    IF p_decision NOT IN (
        'approved',
        'rejected'
    ) THEN
        RAISE EXCEPTION
            'Decisión no válida';
    END IF;


    -- --------------------------------------------------------
    -- VALIDAR MOTIVO DE RECHAZO
    -- --------------------------------------------------------

    IF p_decision = 'rejected'
       AND p_rejection_reason IS NOT NULL
       AND LENGTH(TRIM(p_rejection_reason)) > 1000
    THEN
        RAISE EXCEPTION
            'El motivo de rechazo no puede superar los 1000 caracteres';
    END IF;


    -- --------------------------------------------------------
    -- OBTENER SOLICITUD
    -- --------------------------------------------------------

    SELECT *
    INTO v_request
    FROM public.account_deletion_requests
    WHERE id = p_request_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Solicitud de eliminación no encontrada';
    END IF;


    -- --------------------------------------------------------
    -- SOLO SE PUEDE RESOLVER UNA SOLICITUD PENDIENTE
    -- --------------------------------------------------------

    IF v_request.status <> 'pending' THEN
        RAISE EXCEPTION
            'La solicitud ya ha sido resuelta';
    END IF;


    -- --------------------------------------------------------
    -- EL USUARIO OBJETIVO DEBE EXISTIR
    -- --------------------------------------------------------

    IF v_request.user_id IS NULL THEN
        RAISE EXCEPTION
            'La solicitud no tiene un usuario asociado';
    END IF;


    -- --------------------------------------------------------
    -- OBTENER PERFIL
    -- --------------------------------------------------------

    SELECT *
    INTO v_target_profile
    FROM public.profiles
    WHERE id = v_request.user_id;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Perfil del usuario solicitado no encontrado';
    END IF;


    -- --------------------------------------------------------
    -- SOLO CUENTAS DE CLIENTE
    --
    -- Un worker no puede utilizar esta solicitud para borrar
    -- otra cuenta worker.
    -- --------------------------------------------------------

    IF v_target_profile.rol <> 'user' THEN
        RAISE EXCEPTION
            'La solicitud no corresponde a una cuenta de cliente';
    END IF;


    IF EXISTS (
        SELECT 1
        FROM public.workers
        WHERE auth_user_id = v_request.user_id
    ) THEN
        RAISE EXCEPTION
            'No se puede eliminar una cuenta de trabajador mediante esta solicitud';
    END IF;


    -- ========================================================
    -- RECHAZAR
    -- ========================================================

    IF p_decision = 'rejected' THEN

        UPDATE public.account_deletion_requests
        SET
            status = 'rejected',
            reviewed_at = CURRENT_TIMESTAMP,
            reviewed_by = auth.uid(),
            rejection_reason =
                NULLIF(BTRIM(p_rejection_reason), '')
        WHERE id = p_request_id
        RETURNING *
        INTO v_request;

        RETURN v_request;

    END IF;


    -- ========================================================
    -- APROBAR
    -- ========================================================

    UPDATE public.account_deletion_requests
    SET
        status = 'approved',
        reviewed_at = CURRENT_TIMESTAMP,
        reviewed_by = auth.uid(),
        rejection_reason = NULL
    WHERE id = p_request_id
    RETURNING *
    INTO v_request;


    -- --------------------------------------------------------
    -- REVOCAR SESIONES
    -- --------------------------------------------------------

    DELETE FROM auth.sessions
    WHERE user_id = v_request.user_id;


    -- --------------------------------------------------------
    -- ELIMINAR CUENTA DE AUTH
    --
    -- Las FK existentes determinan qué datos relacionados
    -- hacen CASCADE y cuáles hacen SET NULL.
    -- --------------------------------------------------------

    DELETE FROM auth.users
    WHERE id = v_request.user_id;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No se pudo eliminar la cuenta de Auth';
    END IF;


    RETURN v_request;

END;

$$;


ALTER FUNCTION "public"."resolve_account_deletion"("p_request_id" "uuid", "p_decision" "text", "p_rejection_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_account_deletion"("p_request_id" "uuid", "p_decision" "text", "p_rejection_reason" "text") IS 'Permite a un trabajador activo aprobar o rechazar una solicitud
de eliminación. Una aprobación elimina la cuenta correspondiente
de auth.users y revoca previamente sus sesiones.';



CREATE OR REPLACE FUNCTION "public"."resolve_company_change_request"("p_request_id" "uuid", "p_action" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'companies.update'
    );

    RETURN public.resolve_company_change_request__legacy_113(
        p_request_id,
        p_action
    );

END;
$$;


ALTER FUNCTION "public"."resolve_company_change_request"("p_request_id" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_company_change_request__legacy_113"("p_request_id" "uuid", "p_action" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE

    v_request public.company_change_requests%ROWTYPE;

    v_target_company_id UUID;
    v_target_company_name TEXT;
    v_company_code TEXT;

    v_moved_projects INTEGER := 0;

BEGIN

    -- ========================================================
    -- 1. AUTENTICACIÓN
    -- ========================================================

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado.';
    END IF;


    -- ========================================================
    -- 2. SOLO WORKERS ACTIVOS
    -- ========================================================

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'No tienes permisos para gestionar solicitudes de cambio de empresa.';
    END IF;


    -- ========================================================
    -- 3. VALIDAR PARÁMETROS
    -- ========================================================

    IF p_request_id IS NULL THEN
        RAISE EXCEPTION
            'La solicitud es obligatoria.';
    END IF;

    IF p_action NOT IN ('approved', 'rejected') THEN
        RAISE EXCEPTION
            'La acción debe ser approved o rejected.';
    END IF;


    -- ========================================================
    -- 4. OBTENER Y BLOQUEAR SOLICITUD
    -- ========================================================

    SELECT *
    INTO v_request
    FROM public.company_change_requests
    WHERE id = p_request_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La solicitud indicada no existe.';
    END IF;

    IF v_request.status <> 'pending' THEN
        RAISE EXCEPTION
            'La solicitud ya ha sido gestionada.';
    END IF;


    -- ========================================================
    -- 5. RECHAZO
    -- ========================================================

    IF p_action = 'rejected' THEN

        UPDATE public.company_change_requests
        SET
            status = 'rejected',
            reviewed_by = (
                SELECT w.id
                FROM public.workers w
                WHERE w.auth_user_id = auth.uid()
                LIMIT 1
            ),
            reviewed_at = CURRENT_TIMESTAMP,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = p_request_id;

        RETURN TRUE;

    END IF;


    -- ========================================================
    -- 6. DETERMINAR EMPRESA DESTINO
    -- ========================================================

    v_target_company_id :=
        v_request.requested_company_id;

    v_target_company_name :=
        NULLIF(
            TRIM(v_request.requested_company_name),
            ''
        );


    -- ========================================================
    -- 7. SI YA EXISTE COMPANY_ID,
    --    COMPROBAR QUE SIGUE ACTIVA
    -- ========================================================

    IF v_target_company_id IS NOT NULL THEN

        SELECT c.company_name
        INTO v_target_company_name
        FROM public.companies c
        WHERE c.id = v_target_company_id
          AND c.is_active = TRUE;

        IF v_target_company_name IS NULL THEN
            v_target_company_id := NULL;
        END IF;

    END IF;


    -- ========================================================
    -- 8. SI NO TENEMOS COMPANY_ID,
    --    BUSCAR POR NOMBRE
    -- ========================================================

    IF v_target_company_id IS NULL
       AND v_target_company_name IS NOT NULL
    THEN

        SELECT c.id
        INTO v_target_company_id
        FROM public.companies c
        WHERE c.is_active = TRUE
          AND LOWER(TRIM(c.company_name)) =
              LOWER(v_target_company_name)
        ORDER BY c.created_at ASC
        LIMIT 1;

    END IF;


    -- ========================================================
    -- 9. SI NO EXISTE, CREAR EMPRESA
    -- ========================================================

    IF v_target_company_id IS NULL THEN

        IF v_target_company_name IS NULL THEN
            RAISE EXCEPTION
                'La solicitud no contiene un nombre de empresa válido.';
        END IF;

        v_company_code :=
            'CLI-' ||
            UPPER(
                REPLACE(
                    gen_random_uuid()::TEXT,
                    '-',
                    ''
                )
            );

        INSERT INTO public.companies (
            company_code,
            company_name,
            legal_name,
            created_by,
            is_active
        )
        VALUES (
            v_company_code,
            v_target_company_name,
            v_target_company_name,
            auth.uid(),
            TRUE
        )
        RETURNING id
        INTO v_target_company_id;

    END IF;


    -- ========================================================
    -- 10. CONFIRMAR EMPRESA DESTINO
    -- ========================================================

    SELECT c.company_name
    INTO v_target_company_name
    FROM public.companies c
    WHERE c.id = v_target_company_id
      AND c.is_active = TRUE;

    IF v_target_company_name IS NULL THEN
        RAISE EXCEPTION
            'La empresa solicitada no existe o está inactiva.';
    END IF;


    -- ========================================================
    -- 11. ACTUALIZAR PERFIL
    -- ========================================================

    UPDATE public.profiles
    SET
        company_id = v_target_company_id,
        empresa = v_target_company_name,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = v_request.user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El perfil del usuario asociado a la solicitud no existe.';
    END IF;


    -- ========================================================
    -- 12. TRASLADAR PROYECTOS SI EL CLIENTE LO SOLICITÓ
    -- ========================================================
    --
    -- NO se filtra por company_id = current_company_id.
    --
    -- projects.company_id representa la empresa asociada al
    -- proyecto y puede ser histórica.
    --
    -- Solo se mueven proyectos que:
    --   1. pertenecen al usuario;
    --   2. están Pendiente, Activo o Pausado;
    --   3. NO tienen ninguna factura normal asociada.
    --
    -- La comprobación de factura se hace justo al aprobar.
    -- ========================================================

    IF COALESCE(
        v_request.apply_to_active_projects,
        FALSE
    ) THEN

        UPDATE public.projects p
        SET
            company_id = v_target_company_id,
            updated_at = CURRENT_TIMESTAMP
        WHERE p.user_id = v_request.user_id
          AND p.estado IN (
              'Pendiente',
              'Activo',
              'Pausado'
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.invoices i
              WHERE i.project_id = p.id
          );

        GET DIAGNOSTICS v_moved_projects = ROW_COUNT;

    END IF;


    -- ========================================================
    -- 13. MARCAR SOLICITUD COMO APROBADA
    -- ========================================================

    UPDATE public.company_change_requests
    SET
        requested_company_id = v_target_company_id,
        requested_company_name = v_target_company_name,
        status = 'approved',
        reviewed_by = (
            SELECT w.id
            FROM public.workers w
            WHERE w.auth_user_id = auth.uid()
            LIMIT 1
        ),
        reviewed_at = CURRENT_TIMESTAMP,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_request_id;


    -- ========================================================
    -- 14. REGISTRO DE ACTIVIDAD
    -- ========================================================

    PERFORM public.log_activity(
        'company_change_approved',
        'company_change_request',
        v_request.id,
        CASE
            WHEN COALESCE(
                v_request.apply_to_active_projects,
                FALSE
            )
            THEN
                'El trabajador ha aprobado el cambio de empresa y se han trasladado los proyectos Pendiente, Activo y Pausado sin factura normal asociada.'
            ELSE
                'El trabajador ha aprobado el cambio de empresa sin trasladar los proyectos.'
        END,
        jsonb_build_object(
            'user_id',
            v_request.user_id,

            'previous_company_id',
            v_request.current_company_id,

            'new_company_id',
            v_target_company_id,

            'apply_to_active_projects',
            COALESCE(
                v_request.apply_to_active_projects,
                FALSE
            ),

            'moved_projects_count',
            v_moved_projects
        )
    );


    -- ========================================================
    -- 15. ÉXITO
    -- ========================================================

    RETURN TRUE;

END;
$$;


ALTER FUNCTION "public"."resolve_company_change_request__legacy_113"("p_request_id" "uuid", "p_action" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_company_change_request__legacy_113"("p_request_id" "uuid", "p_action" "text") IS 'Permite a un worker resolver una solicitud de cambio de empresa. Si fue solicitada, traslada únicamente los proyectos del usuario en estado Pendiente, Activo o Pausado y pertenecientes a la empresa actual registrada en la solicitud.';



CREATE OR REPLACE FUNCTION "public"."resolve_company_iva_change_request"("p_request_id" "uuid", "p_action" "text", "p_worker_notes" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_request public.company_iva_change_requests%ROWTYPE;
    v_user_id UUID := auth.uid();
    v_action TEXT := LOWER(TRIM(COALESCE(p_action, '')));
    v_notes TEXT := NULLIF(BTRIM(COALESCE(p_worker_notes, '')), '');

BEGIN

    -- ========================================================
    -- 1. AUTENTICACIÓN
    -- ========================================================

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado.';
    END IF;


    -- ========================================================
    -- 2. AUTORIZACIÓN RBAC
    -- ========================================================

    PERFORM public.require_current_worker_permission(
        'companies.update'
    );


    -- ========================================================
    -- 3. VALIDAR ACCIÓN
    -- ========================================================

    IF v_action NOT IN ('approved', 'rejected') THEN
        RAISE EXCEPTION
            'La acción debe ser approved o rejected.';
    END IF;


    -- ========================================================
    -- 4. VALIDAR NOTAS
    -- ========================================================

    IF v_notes IS NOT NULL
       AND (
            LENGTH(v_notes) > 2000
            OR pg_column_size(v_notes) > 16384
       )
    THEN
        RAISE EXCEPTION
            'Las notas de revisión no pueden superar los 2000 caracteres.';
    END IF;


    -- ========================================================
    -- 5. BLOQUEAR LA SOLICITUD
    -- ========================================================

    SELECT *
    INTO v_request
    FROM public.company_iva_change_requests
    WHERE id = p_request_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La solicitud de cambio de IVA no existe.';
    END IF;


    -- ========================================================
    -- 6. SOLO SE PUEDE RESOLVER UNA SOLICITUD ACTIVA
    -- ========================================================

    IF v_request.status NOT IN ('pending', 'in_review') THEN
        RAISE EXCEPTION
            'La solicitud de cambio de IVA ya ha sido resuelta.';
    END IF;


    -- ========================================================
    -- 7. APROBACIÓN
    -- ========================================================

    IF v_action = 'approved' THEN

        UPDATE public.companies
        SET
            iva_aprobado_aplicado =
                v_request.requested_iva_aplicado,

            iva_aprobado_porcentaje =
                CASE
                    WHEN v_request.requested_iva_aplicado
                    THEN v_request.requested_iva_porcentaje
                    ELSE 0
                END,

            iva_aprobado_por =
                v_user_id,

            iva_aprobado_at =
                CURRENT_TIMESTAMP,

            updated_at =
                CURRENT_TIMESTAMP

        WHERE id = v_request.company_id;


        IF NOT FOUND THEN
            RAISE EXCEPTION
                'La empresa asociada a la solicitud no existe.';
        END IF;

    END IF;


    -- ========================================================
    -- 8. ACTUALIZAR SOLICITUD
    -- ========================================================

    UPDATE public.company_iva_change_requests
    SET
        status =
            v_action,

        reviewed_by =
            v_user_id,

        reviewed_at =
            CURRENT_TIMESTAMP,

        worker_notes =
            v_notes,

        updated_at =
            CURRENT_TIMESTAMP

    WHERE id = v_request.id;


    RETURN TRUE;

END;
$$;


ALTER FUNCTION "public"."resolve_company_iva_change_request"("p_request_id" "uuid", "p_action" "text", "p_worker_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_maintenance_iva_change_request"("p_request_id" "uuid", "p_action" "text", "p_worker_notes" "text" DEFAULT NULL::"text") RETURNS "public"."maintenance_iva_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_request public.maintenance_iva_change_requests;
    v_action TEXT;
BEGIN

    PERFORM public.require_current_worker_permission(
        'maintenance.update'
    );

    v_action :=
        LOWER(
            BTRIM(
                COALESCE(
                    p_action,
                    ''
                )
            )
        );

    IF v_action NOT IN (
        'in_review',
        'approved',
        'rejected'
    ) THEN
        RAISE EXCEPTION
            'Acción no válida';
    END IF;

    SELECT *
    INTO v_request
    FROM public.maintenance_iva_change_requests
    WHERE id = p_request_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Solicitud de cambio de IVA no encontrada';
    END IF;

    IF v_request.status IN (
        'approved',
        'rejected',
        'cancelled'
    ) THEN
        RAISE EXCEPTION
            'La solicitud ya está cerrada';
    END IF;

    IF v_action = 'in_review' THEN

        UPDATE public.maintenance_iva_change_requests
        SET
            status = 'in_review',
            reviewed_by = auth.uid(),
            reviewed_at = CURRENT_TIMESTAMP,
            worker_notes =
                NULLIF(
                    BTRIM(p_worker_notes),
                    ''
                ),
            updated_at = CURRENT_TIMESTAMP
        WHERE id = p_request_id
        RETURNING *
        INTO v_request;

        RETURN v_request;

    END IF;

    IF v_action = 'rejected' THEN

        UPDATE public.maintenance_iva_change_requests
        SET
            status = 'rejected',
            reviewed_by = auth.uid(),
            reviewed_at = CURRENT_TIMESTAMP,
            worker_notes =
                NULLIF(
                    BTRIM(p_worker_notes),
                    ''
                ),
            updated_at = CURRENT_TIMESTAMP
        WHERE id = p_request_id
        RETURNING *
        INTO v_request;

        RETURN v_request;

    END IF;

    IF v_action = 'approved' THEN

        UPDATE public.companies
        SET
            iva_recomendado_aplicado =
                v_request.requested_iva_aplicado,
            iva_recomendado_porcentaje =
                v_request.requested_iva_porcentaje,
            iva_recomendado_updated_by =
                auth.uid(),
            iva_recomendado_updated_at =
                CURRENT_TIMESTAMP,
            updated_at =
                CURRENT_TIMESTAMP
        WHERE id = v_request.company_id;

        IF v_request.maintenance_contract_id IS NOT NULL THEN

            UPDATE public.maintenance_contracts
            SET
                iva_aplicado =
                    v_request.requested_iva_aplicado,
                iva_porcentaje =
                    v_request.requested_iva_porcentaje,
                iva_source =
                    'client_request',
                iva_configured_by =
                    auth.uid(),
                iva_configured_at =
                    CURRENT_TIMESTAMP,
                updated_at =
                    CURRENT_TIMESTAMP
            WHERE id =
                v_request.maintenance_contract_id
              AND company_id =
                v_request.company_id;

        END IF;

        UPDATE public.maintenance_iva_change_requests
        SET
            status = 'approved',
            reviewed_by = auth.uid(),
            reviewed_at = CURRENT_TIMESTAMP,
            worker_notes =
                NULLIF(
                    BTRIM(p_worker_notes),
                    ''
                ),
            updated_at = CURRENT_TIMESTAMP
        WHERE id = p_request_id
        RETURNING *
        INTO v_request;

        RETURN v_request;

    END IF;

    RAISE EXCEPTION
        'No se pudo resolver la solicitud';

END;
$$;


ALTER FUNCTION "public"."resolve_maintenance_iva_change_request"("p_request_id" "uuid", "p_action" "text", "p_worker_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_project_change_request"("p_request_id" "uuid", "p_action" "text", "p_review_notes" "text" DEFAULT NULL::"text") RETURNS "public"."project_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

    v_request public.project_change_requests;

    v_worker_id UUID;

    v_project public.projects;

    v_new_status TEXT;

BEGIN
    PERFORM public.require_current_worker_permission('projects.update');

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN

        RAISE EXCEPTION
            'Usuario no autenticado';

    END IF;


    -- --------------------------------------------------------
    -- WORKER
    -- --------------------------------------------------------

    IF NOT public.current_user_is_worker() THEN

        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';

    END IF;


    -- --------------------------------------------------------
    -- REQUEST ID
    -- --------------------------------------------------------

    IF p_request_id IS NULL THEN

        RAISE EXCEPTION
            'La solicitud es obligatoria';

    END IF;


    -- --------------------------------------------------------
    -- ACTION
    -- --------------------------------------------------------

    IF p_action NOT IN (
        'in_review',
        'accepted',
        'rejected',
        'completed'
    ) THEN

        RAISE EXCEPTION
            'Acción no válida. Debe ser in_review, accepted, rejected o completed';

    END IF;


    -- --------------------------------------------------------
    -- REVIEW NOTES
    -- --------------------------------------------------------

    IF p_review_notes IS NOT NULL
       AND length(p_review_notes) > 5000
    THEN

        RAISE EXCEPTION
            'Las notas no pueden superar 5000 caracteres';

    END IF;


    -- --------------------------------------------------------
    -- WORKER ID
    -- --------------------------------------------------------

    SELECT w.id
    INTO v_worker_id
    FROM public.workers w
    WHERE
        w.auth_user_id = auth.uid()
        AND w.is_active = TRUE
    LIMIT 1;


    IF v_worker_id IS NULL THEN

        RAISE EXCEPTION
            'No se ha encontrado un trabajador activo asociado al usuario';

    END IF;


    -- --------------------------------------------------------
    -- OBTENER SOLICITUD
    -- --------------------------------------------------------

    SELECT *
    INTO v_request
    FROM public.project_change_requests
    WHERE id = p_request_id
    FOR UPDATE;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'La solicitud indicada no existe';

    END IF;


    -- --------------------------------------------------------
    -- OBTENER PROYECTO
    -- --------------------------------------------------------

    SELECT *
    INTO v_project
    FROM public.projects
    WHERE id = v_request.project_id;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'El proyecto asociado a la solicitud no existe';

    END IF;


    -- --------------------------------------------------------
    -- NO MODIFICAR SOLICITUDES FINALES
    -- --------------------------------------------------------

    IF v_request.status IN (
        'completed',
        'rejected'
    ) THEN

        RAISE EXCEPTION
            'La solicitud ya está cerrada y no puede modificarse';

    END IF;


    -- ========================================================
    -- ACCIÓN: IN_REVIEW
    -- ========================================================

    IF p_action = 'in_review' THEN

        IF v_request.status <> 'pending' THEN

            RAISE EXCEPTION
                'Solo una solicitud pendiente puede pasar a revisión';

        END IF;


        v_new_status := 'in_review';


        UPDATE public.project_change_requests

        SET
            status = v_new_status,

            reviewed_by = v_worker_id,

            reviewed_at = COALESCE(
                reviewed_at,
                CURRENT_TIMESTAMP
            ),

            review_notes = COALESCE(
                NULLIF(btrim(p_review_notes), ''),
                review_notes
            ),

            updated_at = CURRENT_TIMESTAMP

        WHERE id = p_request_id

        RETURNING *
        INTO v_request;


        INSERT INTO public.activity_log (
            user_id,
            company_id,
            action,
            resource_type,
            resource_id,
            description,
            metadata
        )
        VALUES (
            auth.uid(),
            v_project.company_id,
            'project.change_request_in_review',
            'project_change_request',
            v_request.id,
            'Solicitud de cambio puesta en revisión',
            jsonb_build_object(
                'project_id', v_project.id,
                'worker_id', v_worker_id
            )
        );


        RETURN v_request;

    END IF;


    -- ========================================================
    -- ACCIÓN: ACCEPTED
    -- ========================================================

    IF p_action = 'accepted' THEN

        IF v_request.status NOT IN (
            'pending',
            'in_review'
        ) THEN

            RAISE EXCEPTION
                'Solo una solicitud pendiente o en revisión puede aceptarse';

        END IF;


        v_new_status := 'accepted';


        UPDATE public.project_change_requests

        SET
            status = v_new_status,

            reviewed_by = v_worker_id,

            reviewed_at = COALESCE(
                reviewed_at,
                CURRENT_TIMESTAMP
            ),

            accepted_at = CURRENT_TIMESTAMP,

            review_notes = COALESCE(
                NULLIF(btrim(p_review_notes), ''),
                review_notes
            ),

            updated_at = CURRENT_TIMESTAMP

        WHERE id = p_request_id

        RETURNING *
        INTO v_request;


        INSERT INTO public.activity_log (
            user_id,
            company_id,
            action,
            resource_type,
            resource_id,
            description,
            metadata
        )
        VALUES (
            auth.uid(),
            v_project.company_id,
            'project.change_request_accepted',
            'project_change_request',
            v_request.id,
            'Solicitud de cambio aceptada por un trabajador',
            jsonb_build_object(
                'project_id', v_project.id,
                'worker_id', v_worker_id
            )
        );


        RETURN v_request;

    END IF;


    -- ========================================================
    -- ACCIÓN: REJECTED
    -- ========================================================

    IF p_action = 'rejected' THEN

        IF v_request.status NOT IN (
            'pending',
            'in_review'
        ) THEN

            RAISE EXCEPTION
                'Solo una solicitud pendiente o en revisión puede rechazarse';

        END IF;


        v_new_status := 'rejected';


        UPDATE public.project_change_requests

        SET
            status = v_new_status,

            reviewed_by = v_worker_id,

            reviewed_at = CURRENT_TIMESTAMP,

            review_notes =
                NULLIF(
                    btrim(p_review_notes),
                    ''
                ),

            updated_at = CURRENT_TIMESTAMP

        WHERE id = p_request_id

        RETURNING *
        INTO v_request;


        INSERT INTO public.activity_log (
            user_id,
            company_id,
            action,
            resource_type,
            resource_id,
            description,
            metadata
        )
        VALUES (
            auth.uid(),
            v_project.company_id,
            'project.change_request_rejected',
            'project_change_request',
            v_request.id,
            'Solicitud de cambio rechazada por un trabajador',
            jsonb_build_object(
                'project_id', v_project.id,
                'worker_id', v_worker_id
            )
        );


        RETURN v_request;

    END IF;


    -- ========================================================
    -- ACCIÓN: COMPLETED
    -- ========================================================

    IF p_action = 'completed' THEN

        IF v_request.status <> 'accepted' THEN

            RAISE EXCEPTION
                'Una solicitud debe estar aceptada antes de marcarse como completada';

        END IF;


        v_new_status := 'completed';


        UPDATE public.project_change_requests

        SET
            status = v_new_status,

            completed_by = v_worker_id,

            completed_at = CURRENT_TIMESTAMP,

            review_notes = COALESCE(
                NULLIF(btrim(p_review_notes), ''),
                review_notes
            ),

            updated_at = CURRENT_TIMESTAMP

        WHERE id = p_request_id

        RETURNING *
        INTO v_request;


        INSERT INTO public.activity_log (
            user_id,
            company_id,
            action,
            resource_type,
            resource_id,
            description,
            metadata
        )
        VALUES (
            auth.uid(),
            v_project.company_id,
            'project.change_request_completed',
            'project_change_request',
            v_request.id,
            'Cambio de proyecto realizado y solicitud completada',
            jsonb_build_object(
                'project_id', v_project.id,
                'worker_id', v_worker_id
            )
        );


        RETURN v_request;

    END IF;


    -- --------------------------------------------------------
    -- FALLBACK
    -- --------------------------------------------------------

    RAISE EXCEPTION
        'No se pudo resolver la solicitud';

END;
$$;


ALTER FUNCTION "public"."resolve_project_change_request"("p_request_id" "uuid", "p_action" "text", "p_review_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_to_custom_maintenance_clarification"("p_proposal_id" "uuid", "p_informacion_adicional" "text" DEFAULT NULL::"text", "p_request_data" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."maintenance_custom_proposals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$

DECLARE
    v_proposal public.maintenance_custom_proposals;

BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Debes iniciar sesión';
    END IF;

    IF public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Esta operación está destinada a clientes';
    END IF;

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION
            'El usuario no está activo';
    END IF;

    SELECT *
    INTO v_proposal
    FROM public.maintenance_custom_proposals
    WHERE id = p_proposal_id
      AND user_id = auth.uid()
      AND company_id = public.current_user_company_id()
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La propuesta no existe o no tienes acceso a ella';
    END IF;

    IF v_proposal.status <> 'clarification_requested' THEN
        RAISE EXCEPTION
            'La propuesta no está esperando información adicional';
    END IF;

    PERFORM public.enforce_security_rate_limit(
        'maintenance_proposal_clarification:' || auth.uid()::TEXT || ':' || p_proposal_id::TEXT,
        10,
        86400
    );



    IF p_request_data IS NOT NULL
       AND jsonb_typeof(p_request_data) <> 'object'
    THEN
        RAISE EXCEPTION
            'request_data debe ser un objeto JSON';
    END IF;

    UPDATE public.maintenance_custom_proposals
    SET
        informacion_adicional =
            COALESCE(
                NULLIF(BTRIM(p_informacion_adicional), ''),
                informacion_adicional
            ),

        request_data =
            CASE
                WHEN p_request_data IS NULL
                THEN request_data
                ELSE p_request_data
            END,

        status = 'submitted',

        submitted_at = CURRENT_TIMESTAMP,

        updated_at = CURRENT_TIMESTAMP

    WHERE id = v_proposal.id

    RETURNING *
    INTO v_proposal;


    INSERT INTO public.maintenance_custom_proposal_events (
        proposal_id,
        actor_id,
        actor_type,
        event_type,
        old_status,
        new_status,
        notes,
        metadata
    )
    VALUES (
        v_proposal.id,
        auth.uid(),
        'client',
        'clarification_resubmitted',
        'clarification_requested',
        'submitted',
        NULLIF(BTRIM(p_informacion_adicional), ''),
        NULL
    );


    RETURN v_proposal;

END;
$$;


ALTER FUNCTION "public"."respond_to_custom_maintenance_clarification"("p_proposal_id" "uuid", "p_informacion_adicional" "text", "p_request_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_to_custom_maintenance_proposal"("p_proposal_id" "uuid", "p_status" "text", "p_quoted_monthly_price" numeric DEFAULT NULL::numeric, "p_quoted_hours_monthly" numeric DEFAULT NULL::numeric, "p_quoted_scope_level" "text" DEFAULT NULL::"text", "p_quoted_service_level" "text" DEFAULT NULL::"text", "p_quoted_sla" "text" DEFAULT NULL::"text", "p_quoted_response_time" "text" DEFAULT NULL::"text", "p_quoted_support_hours" "text" DEFAULT NULL::"text", "p_quoted_description" "text" DEFAULT NULL::"text", "p_quoted_terms" "text" DEFAULT NULL::"text", "p_quoted_valid_until" "date" DEFAULT NULL::"date") RETURNS "public"."maintenance_custom_proposals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_proposal public.maintenance_custom_proposals;
    v_status TEXT;
BEGIN

    PERFORM public.require_current_worker_permission(
        'maintenance_proposals.update'
    );

    v_status :=
        LOWER(
            BTRIM(
                COALESCE(
                    p_status,
                    ''
                )
            )
        );

    IF v_status NOT IN (
        'in_review',
        'quoted',
        'rejected'
    ) THEN
        RAISE EXCEPTION
            'Estado de respuesta no válido';
    END IF;

    SELECT *
    INTO v_proposal
    FROM public.maintenance_custom_proposals
    WHERE id = p_proposal_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Propuesta no encontrada';
    END IF;

    IF v_status = 'quoted' THEN

        IF p_quoted_monthly_price IS NULL
           OR p_quoted_monthly_price <= 0
        THEN
            RAISE EXCEPTION
                'El precio mensual propuesto debe ser mayor que 0';
        END IF;

        IF p_quoted_valid_until IS NULL THEN
            RAISE EXCEPTION
                'La propuesta cotizada debe tener fecha de validez';
        END IF;

    END IF;

    UPDATE public.maintenance_custom_proposals
    SET
        status = v_status,

        quoted_monthly_price =
            CASE
                WHEN v_status = 'quoted'
                THEN ROUND(
                    p_quoted_monthly_price,
                    2
                )
                ELSE quoted_monthly_price
            END,

        quoted_hours_monthly =
            CASE
                WHEN v_status = 'quoted'
                THEN p_quoted_hours_monthly
                ELSE quoted_hours_monthly
            END,

        quoted_scope_level =
            CASE
                WHEN v_status = 'quoted'
                THEN NULLIF(
                    BTRIM(p_quoted_scope_level),
                    ''
                )
                ELSE quoted_scope_level
            END,

        quoted_service_level =
            CASE
                WHEN v_status = 'quoted'
                THEN NULLIF(
                    BTRIM(p_quoted_service_level),
                    ''
                )
                ELSE quoted_service_level
            END,

        quoted_sla =
            CASE
                WHEN v_status = 'quoted'
                THEN NULLIF(
                    BTRIM(p_quoted_sla),
                    ''
                )
                ELSE quoted_sla
            END,

        quoted_response_time =
            CASE
                WHEN v_status = 'quoted'
                THEN NULLIF(
                    BTRIM(p_quoted_response_time),
                    ''
                )
                ELSE quoted_response_time
            END,

        quoted_support_hours =
            CASE
                WHEN v_status = 'quoted'
                THEN NULLIF(
                    BTRIM(p_quoted_support_hours),
                    ''
                )
                ELSE quoted_support_hours
            END,

        quoted_description =
            CASE
                WHEN v_status = 'quoted'
                THEN NULLIF(
                    BTRIM(p_quoted_description),
                    ''
                )
                ELSE quoted_description
            END,

        quoted_terms =
            CASE
                WHEN v_status = 'quoted'
                THEN NULLIF(
                    BTRIM(p_quoted_terms),
                    ''
                )
                ELSE quoted_terms
            END,

        quoted_valid_until =
            CASE
                WHEN v_status = 'quoted'
                THEN p_quoted_valid_until
                ELSE quoted_valid_until
            END,

        quote_snapshot =
            CASE
                WHEN v_status = 'quoted'
                THEN jsonb_build_object(
                    'monthly_price',
                    ROUND(
                        p_quoted_monthly_price,
                        2
                    ),
                    'currency',
                    quoted_currency,
                    'hours_monthly',
                    p_quoted_hours_monthly,
                    'scope_level',
                    NULLIF(
                        BTRIM(p_quoted_scope_level),
                        ''
                    ),
                    'service_level',
                    NULLIF(
                        BTRIM(p_quoted_service_level),
                        ''
                    ),
                    'sla',
                    NULLIF(
                        BTRIM(p_quoted_sla),
                        ''
                    ),
                    'response_time',
                    NULLIF(
                        BTRIM(p_quoted_response_time),
                        ''
                    ),
                    'support_hours',
                    NULLIF(
                        BTRIM(p_quoted_support_hours),
                        ''
                    ),
                    'description',
                    NULLIF(
                        BTRIM(p_quoted_description),
                        ''
                    ),
                    'terms',
                    NULLIF(
                        BTRIM(p_quoted_terms),
                        ''
                    ),
                    'valid_until',
                    p_quoted_valid_until,
                    'captured_at',
                    CURRENT_TIMESTAMP
                )
                ELSE quote_snapshot
            END,

        reviewed_at =
            CASE
                WHEN reviewed_at IS NULL
                THEN CURRENT_TIMESTAMP
                ELSE reviewed_at
            END,

        quoted_at =
            CASE
                WHEN v_status = 'quoted'
                THEN CURRENT_TIMESTAMP
                ELSE quoted_at
            END,

        updated_at = CURRENT_TIMESTAMP

    WHERE id = v_proposal.id

    RETURNING *
    INTO v_proposal;

    RETURN v_proposal;

END;
$$;


ALTER FUNCTION "public"."respond_to_custom_maintenance_proposal"("p_proposal_id" "uuid", "p_status" "text", "p_quoted_monthly_price" numeric, "p_quoted_hours_monthly" numeric, "p_quoted_scope_level" "text", "p_quoted_service_level" "text", "p_quoted_sla" "text", "p_quoted_response_time" "text", "p_quoted_support_hours" "text", "p_quoted_description" "text", "p_quoted_terms" "text", "p_quoted_valid_until" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_to_quotation"("p_estado" "text", "p_quotation_id" "uuid") RETURNS "public"."quotations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_state public.quotation_workflow_state%ROWTYPE;
  v_version public.quotation_official_versions%ROWTYPE;
  v_quotation public.quotations%ROWTYPE;
  v_result public.quotations%ROWTYPE;
  v_action text;
BEGIN
  v_action := initcap(lower(btrim(COALESCE(p_estado, ''))));
  IF v_action NOT IN ('Aceptado', 'Rechazado') THEN
    RAISE EXCEPTION 'Respuesta no válida';
  END IF;

  -- Bloquear primero quotations y después el estado, en el mismo orden que
  -- request_quotation_changes/publish para reducir el riesgo de deadlocks.
  SELECT * INTO v_quotation
  FROM public.quotations
  WHERE id = p_quotation_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Presupuesto no encontrado'; END IF;

  -- Compatibilidad con presupuestos antiguos/no migrados.
  SELECT * INTO v_state
  FROM public.quotation_workflow_state
  WHERE quotation_id = p_quotation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    IF public.current_user_is_worker() THEN
      PERFORM public.require_current_worker_permission('quotations.update');
    END IF;
    RETURN public.respond_to_quotation__legacy_113(v_action, p_quotation_id);
  END IF;

  IF auth.uid() IS NULL OR public.current_user_is_worker() THEN
    RAISE EXCEPTION 'La respuesta formal debe realizarla el cliente autenticado';
  END IF;
  IF NOT public.current_user_is_active() THEN
    RAISE EXCEPTION 'La cuenta no está activa';
  END IF;
  IF v_state.workflow_status <> 'presented' THEN
    RAISE EXCEPTION 'No puedes responder mientras el presupuesto está en revisión o ya ha sido resuelto';
  END IF;

  IF NOT (
    v_quotation.user_id = auth.uid()
    OR EXISTS (
      SELECT 1 FROM public.clients c
      WHERE c.id = v_quotation.client_id AND c.profile_id = auth.uid()
    )
  ) THEN
    RAISE EXCEPTION 'No tienes acceso a este presupuesto';
  END IF;

  SELECT * INTO v_version
  FROM public.quotation_official_versions
  WHERE id = v_state.current_version_id
    AND quotation_id = p_quotation_id
    AND is_current = true
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No se encuentra la versión oficial actual'; END IF;

  IF v_version.document_path IS NULL OR v_version.document_sha256 IS NULL
     OR v_quotation.document_path IS DISTINCT FROM v_version.document_path
     OR lower(COALESCE(v_quotation.document_sha256, '')) IS DISTINCT FROM lower(COALESCE(v_version.document_sha256, '')) THEN
    RAISE EXCEPTION 'El PDF de la versión oficial no está generado o no coincide con su huella digital';
  END IF;

  PERFORM public.enforce_security_rate_limit(
    'quotation_response:' || v_action || ':' || auth.uid()::text, 10, 3600
  );

  -- Mantiene las validaciones, el acuse PDF, la instantánea y la aceptación
  -- contractual de la función legacy actual.
  v_result := public.respond_to_quotation__legacy_113(v_action, p_quotation_id);

  UPDATE public.quotation_workflow_state
  SET workflow_status = CASE WHEN v_action = 'Aceptado' THEN 'accepted' ELSE 'rejected' END,
      updated_at = now(),
      updated_by = auth.uid()
  WHERE quotation_id = p_quotation_id;

  UPDATE public.quotation_official_versions
  SET client_response = v_action,
      responded_by = auth.uid(),
      responded_at = now()
  WHERE id = v_version.id;

  -- Notificación al trabajador que publicó la versión vigente.
  INSERT INTO public.notifications (user_id, project_id, tipo, titulo, mensaje, metadata)
  VALUES (
    v_version.published_by,
    v_quotation.project_id,
    'quotation',
    CASE WHEN v_action = 'Aceptado' THEN 'Presupuesto aceptado' ELSE 'Presupuesto rechazado' END,
    'El cliente ha ' || CASE WHEN v_action = 'Aceptado' THEN 'aceptado' ELSE 'rechazado' END
      || ' el presupuesto ' || COALESCE(v_quotation.numero_presupuesto, '')
      || ' (' || v_version.version_label || ').',
    jsonb_build_object(
      'event', CASE WHEN v_action = 'Aceptado' THEN 'quotation_accepted' ELSE 'quotation_rejected' END,
      'quotation_id', v_quotation.id,
      'version_id', v_version.id,
      'version_label', v_version.version_label
    )
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."respond_to_quotation"("p_estado" "text", "p_quotation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_to_quotation__legacy_113"("p_estado" "text", "p_quotation_id" "uuid") RETURNS "public"."quotations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$

DECLARE

    v_quotation public.quotations;
    v_normalized_state TEXT;
    v_headers JSONB := '{}'::JSONB;
    v_ip TEXT;
    v_user_agent TEXT;
    v_terms_document_id UUID;
    v_terms_version TEXT;
    v_terms_snapshot TEXT;
    v_terms_hash TEXT;
    v_snapshot JSONB;
    v_snapshot_hash TEXT;
    v_acknowledgement_text_version TEXT :=
        'quotation_document_acknowledgement_v1';

BEGIN

    -- ========================================================
    -- 1. AUTENTICACIÓN
    -- ========================================================

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;

    IF NOT public.current_user_is_active() THEN
        RAISE EXCEPTION
            'Acceso denegado: la cuenta no está activa';
    END IF;


    -- ========================================================
    -- 2. VALIDAR ESTADO
    -- ========================================================

    v_normalized_state :=
        INITCAP(
            LOWER(
                TRIM(
                    COALESCE(p_estado, '')
                )
            )
        );

    IF v_normalized_state NOT IN (
        'Aceptado',
        'Rechazado'
    ) THEN
        RAISE EXCEPTION
            'Estado de respuesta no válido. Debe ser Aceptado o Rechazado';
    END IF;


    -- ========================================================
    -- 3. BLOQUEAR PRESUPUESTO
    -- ========================================================

    SELECT *
    INTO v_quotation
    FROM public.quotations
    WHERE id = p_quotation_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Presupuesto no encontrado';
    END IF;


    -- ========================================================
    -- 4. SOLO PENDIENTE
    -- ========================================================

    IF LOWER(TRIM(v_quotation.estado)) <> 'pendiente' THEN
        RAISE EXCEPTION
            'Este presupuesto ya ha sido respondido y no puede modificarse';
    END IF;


    -- ========================================================
    -- 5. COMPROBAR ACCESO
    -- ========================================================

    IF NOT public.current_user_is_worker() THEN

        IF v_quotation.client_id IS NULL
           OR NOT EXISTS (
                SELECT 1
                FROM public.clients c
                WHERE c.id = v_quotation.client_id
                  AND c.profile_id = auth.uid()
           )
        THEN
            RAISE EXCEPTION
                'Acceso denegado al presupuesto';
        END IF;

    END IF;


    -- ========================================================
    -- 6. RECHAZADO
    -- ========================================================

    IF v_normalized_state = 'Rechazado' THEN

        UPDATE public.quotations
        SET
            estado = 'Rechazado',
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_quotation.id
        RETURNING *
        INTO v_quotation;

        RETURN v_quotation;

    END IF;


    -- ========================================================
    -- 7. ACEPTACIÓN — PDF
    -- ========================================================

    IF v_quotation.document_path IS NULL
       OR TRIM(v_quotation.document_path) = ''
    THEN
        RAISE EXCEPTION
            'No se puede aceptar el presupuesto porque no tiene un PDF asociado';
    END IF;


    IF v_quotation.document_sha256 IS NULL
       OR TRIM(v_quotation.document_sha256) = ''
    THEN
        RAISE EXCEPTION
            'No se puede aceptar el presupuesto porque el PDF todavía no está preparado para su aceptación';
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM public.quotation_document_acknowledgements qa
        WHERE qa.quotation_id = v_quotation.id
          AND qa.user_id = auth.uid()
          AND qa.company_id = v_quotation.company_id
          AND qa.document_path =
              TRIM(v_quotation.document_path)
          AND qa.document_sha256 =
              LOWER(TRIM(v_quotation.document_sha256))
          AND qa.acknowledgement_text_version =
              v_acknowledgement_text_version
    ) THEN

        RAISE EXCEPTION
            'Debe leer y aceptar el PDF del presupuesto antes de aceptarlo';

    END IF;


    -- ========================================================
    -- 8. EVITAR DUPLICADO CONTRACTUAL
    -- ========================================================

    IF EXISTS (
        SELECT 1
        FROM public.quotation_acceptances qa
        WHERE qa.quotation_id = v_quotation.id
    ) THEN

        RAISE EXCEPTION
            'Este presupuesto ya tiene una aceptación contractual registrada';

    END IF;


    -- ========================================================
    -- 9. OBTENER TÉRMINOS CONTRACTUALES VIGENTES
    -- ========================================================

    IF to_regclass('public.legal_documents') IS NULL THEN

        RAISE EXCEPTION
            'La infraestructura de documentos legales no está instalada';

    END IF;


    EXECUTE $sql$

        SELECT
            id,
            version,
            content,
            content_hash

        FROM public.legal_documents

        WHERE document_type = 'contract_terms'

          AND is_current = TRUE

          AND effective_from <= clock_timestamp()

          AND (
              effective_until IS NULL
              OR effective_until > clock_timestamp()
          )

        ORDER BY
            effective_from DESC,
            created_at DESC

        LIMIT 1

    $sql$

    INTO
        v_terms_document_id,
        v_terms_version,
        v_terms_snapshot,
        v_terms_hash;


    IF v_terms_document_id IS NULL THEN

        RAISE EXCEPTION
            'No existen Condiciones Generales de Contratación vigentes';

    END IF;


    IF v_terms_snapshot IS NULL
       OR v_terms_hash IS NULL
    THEN

        RAISE EXCEPTION
            'Las Condiciones Generales vigentes no tienen contenido íntegro y hash';

    END IF;


    -- ========================================================
    -- 10. CABECERAS
    -- ========================================================

    BEGIN

        v_headers := COALESCE(
            NULLIF(
                current_setting(
                    'request.headers',
                    TRUE
                ),
                ''
            )::JSONB,
            '{}'::JSONB
        );

    EXCEPTION WHEN OTHERS THEN

        v_headers := '{}'::JSONB;

    END;


    v_ip :=
        COALESCE(

            NULLIF(
                TRIM(
                    v_headers->>'cf-connecting-ip'
                ),
                ''
            ),

            NULLIF(
                TRIM(
                    v_headers->>'x-real-ip'
                ),
                ''
            ),

            NULLIF(
                TRIM(
                    SPLIT_PART(
                        COALESCE(
                            v_headers->>'x-forwarded-for',
                            ''
                        ),
                        ',',
                        1
                    )
                ),
                ''
            )

        );


    v_user_agent :=
        NULLIF(
            LEFT(
                TRIM(
                    COALESCE(
                        v_headers->>'user-agent',
                        ''
                    )
                ),
                2000
            ),
            ''
        );


    -- ========================================================
    -- 11. SNAPSHOT + HASH DEL PRESUPUESTO
    -- ========================================================

    v_snapshot :=
        to_jsonb(v_quotation);


    v_snapshot_hash :=
        encode(
            digest(
                convert_to(
                    v_snapshot::TEXT,
                    'UTF8'
                ),
                'sha256'
            ),
            'hex'
        );


    -- ========================================================
    -- 12. REGISTRAR ACEPTACIÓN CONTRACTUAL
    -- ========================================================

    INSERT INTO public.quotation_acceptances (

        quotation_id,
        user_id,
        company_id,
        accepted_at,
        previous_state,
        resulting_state,
        quotation_version,
        quotation_snapshot,
        quotation_snapshot_hash,
        contract_terms_document_id,
        contract_terms_version,
        contract_terms_snapshot,
        contract_terms_hash,
        observed_ip,
        user_agent

    )

    VALUES (

        v_quotation.id,
        auth.uid(),
        v_quotation.company_id,
        clock_timestamp(),
        v_quotation.estado,
        'Aceptado',
        v_quotation.quotation_version,
        v_snapshot,
        v_snapshot_hash,
        v_terms_document_id,
        v_terms_version,
        v_terms_snapshot,
        v_terms_hash,
        v_ip,
        v_user_agent

    );


    -- ========================================================
    -- 13. CAMBIAR ESTADO
    -- ========================================================

    UPDATE public.quotations

    SET
        estado = 'Aceptado',
        updated_at = CURRENT_TIMESTAMP

    WHERE id = v_quotation.id

    RETURNING *
    INTO v_quotation;


    RETURN v_quotation;

END;

$_$;


ALTER FUNCTION "public"."respond_to_quotation__legacy_113"("p_estado" "text", "p_quotation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."respond_to_quotation__legacy_113"("p_estado" "text", "p_quotation_id" "uuid") IS 'Permite responder un presupuesto. Pendiente->Rechazado mantiene el flujo existente; Pendiente->Aceptado registra una aceptación contractual inmutable y congela el presupuesto.';



CREATE OR REPLACE FUNCTION "public"."review_custom_maintenance_proposal"("p_proposal_id" "uuid", "p_action" "text", "p_quoted_monthly_price" numeric DEFAULT NULL::numeric, "p_quoted_currency" "text" DEFAULT 'EUR'::"text", "p_quoted_hours_monthly" numeric DEFAULT NULL::numeric, "p_quoted_scope_level" "text" DEFAULT NULL::"text", "p_quoted_service_level" "text" DEFAULT NULL::"text", "p_quoted_sla" "text" DEFAULT NULL::"text", "p_quoted_response_time" "text" DEFAULT NULL::"text", "p_quoted_support_hours" "text" DEFAULT NULL::"text", "p_quoted_description" "text" DEFAULT NULL::"text", "p_quoted_terms" "text" DEFAULT NULL::"text", "p_quoted_valid_until" "date" DEFAULT NULL::"date", "p_response_notes" "text" DEFAULT NULL::"text", "p_clarification_message" "text" DEFAULT NULL::"text") RETURNS "public"."maintenance_custom_proposals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
    v_proposal public.maintenance_custom_proposals;
    v_action TEXT :=
        LOWER(
            BTRIM(
                COALESCE(
                    p_action,
                    ''
                )
            )
        );
    v_currency TEXT :=
        UPPER(
            BTRIM(
                COALESCE(
                    p_quoted_currency,
                    'EUR'
                )
            )
        );
    v_document
        public.maintenance_custom_proposal_documents;
BEGIN

    PERFORM public.require_current_worker_permission(
        'maintenance_proposals.update'
    );

    IF v_action NOT IN (
        'in_review',
        'quoted',
        'clarification_requested',
        'rejected'
    ) THEN
        RAISE EXCEPTION
            'Acción de revisión no válida';
    END IF;

    SELECT *
    INTO v_proposal
    FROM public.maintenance_custom_proposals
    WHERE id = p_proposal_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Propuesta personalizada no encontrada';
    END IF;

    PERFORM public.enforce_security_rate_limit(
        'maintenance_proposal_review:' ||
        auth.uid()::TEXT ||
        ':' ||
        p_proposal_id::TEXT,
        20,
        3600
    );

    IF v_action = 'in_review' THEN

        IF v_proposal.status NOT IN (
            'submitted',
            'clarification_requested'
        ) THEN
            RAISE EXCEPTION
                'La propuesta no puede pasar a revisión desde su estado actual';
        END IF;

        UPDATE public.maintenance_custom_proposals
        SET
            status = 'in_review',
            reviewed_by = auth.uid(),
            reviewed_at = COALESCE(
                reviewed_at,
                CURRENT_TIMESTAMP
            ),
            clarification_requested_at = NULL,
            clarification_requested_by = NULL,
            clarification_message = NULL,
            response_notes =
                NULLIF(
                    BTRIM(p_response_notes),
                    ''
                ),
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_proposal.id
        RETURNING *
        INTO v_proposal;

        RETURN v_proposal;

    END IF;

    IF v_action = 'rejected' THEN

        IF v_proposal.status <> 'in_review' THEN
            RAISE EXCEPTION
                'Solo se puede rechazar una propuesta que está en revisión';
        END IF;

        IF NULLIF(
            BTRIM(p_response_notes),
            ''
        ) IS NULL THEN
            RAISE EXCEPTION
                'Debes indicar el motivo del rechazo';
        END IF;

        UPDATE public.maintenance_custom_proposals
        SET
            status = 'rejected',
            reviewed_by = auth.uid(),
            reviewed_at = COALESCE(
                reviewed_at,
                CURRENT_TIMESTAMP
            ),
            rejected_at = CURRENT_TIMESTAMP,
            rejected_by = auth.uid(),
            rejection_reason =
                BTRIM(p_response_notes),
            response_notes =
                BTRIM(p_response_notes),
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_proposal.id
        RETURNING *
        INTO v_proposal;

        PERFORM public.emit_maintenance_custom_proposal_notification(
            v_proposal.id,
            'Tu solicitud de mantenimiento ha sido revisada',
            'Modira ha revisado tu solicitud de mantenimiento personalizado. Consulta el detalle de la respuesta en tu área de cliente.',
            jsonb_build_object(
                'proposal_id',
                v_proposal.id,
                'status',
                'rejected',
                'action',
                'view_maintenance_proposal'
            )
        );

        RETURN v_proposal;

    END IF;

    IF v_action = 'clarification_requested' THEN

        IF v_proposal.status <> 'in_review' THEN
            RAISE EXCEPTION
                'Solo se puede solicitar información adicional durante la revisión';
        END IF;

        IF NULLIF(
            BTRIM(p_clarification_message),
            ''
        ) IS NULL THEN
            RAISE EXCEPTION
                'Debes indicar qué información adicional necesita Modira';
        END IF;

        UPDATE public.maintenance_custom_proposals
        SET
            status = 'clarification_requested',
            reviewed_by = auth.uid(),
            reviewed_at = COALESCE(
                reviewed_at,
                CURRENT_TIMESTAMP
            ),
            clarification_requested_at =
                CURRENT_TIMESTAMP,
            clarification_requested_by =
                auth.uid(),
            clarification_message =
                BTRIM(p_clarification_message),
            response_notes =
                NULLIF(
                    BTRIM(p_response_notes),
                    ''
                ),
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_proposal.id
        RETURNING *
        INTO v_proposal;

        PERFORM public.emit_maintenance_custom_proposal_notification(
            v_proposal.id,
            'Necesitamos información adicional',
            'Modira necesita información adicional para poder preparar tu propuesta de mantenimiento. Consulta la solicitud en tu área de cliente.',
            jsonb_build_object(
                'proposal_id',
                v_proposal.id,
                'status',
                'clarification_requested',
                'action',
                'view_maintenance_proposal'
            )
        );

        RETURN v_proposal;

    END IF;

    IF v_action = 'quoted' THEN

        IF v_proposal.status <> 'in_review' THEN
            RAISE EXCEPTION
                'Solo se puede enviar una cotización desde una propuesta en revisión';
        END IF;

        IF p_quoted_monthly_price IS NULL
           OR p_quoted_monthly_price <= 0
        THEN
            RAISE EXCEPTION
                'El precio mensual cotizado debe ser mayor que 0';
        END IF;

        IF p_quoted_valid_until IS NULL THEN
            RAISE EXCEPTION
                'La propuesta cotizada debe tener fecha de validez';
        END IF;

        IF p_quoted_valid_until < CURRENT_DATE THEN
            RAISE EXCEPTION
                'La fecha de validez de la propuesta no puede estar en el pasado';
        END IF;

        IF v_currency !~ '^[A-Z]{3}$' THEN
            RAISE EXCEPTION
                'La moneda de la propuesta no es válida';
        END IF;

        IF v_proposal.current_document_id IS NULL THEN
            RAISE EXCEPTION
                'Debes adjuntar el PDF de respuesta de Modira antes de enviar la propuesta';
        END IF;

        SELECT *
        INTO v_document
        FROM public.maintenance_custom_proposal_documents
        WHERE id = v_proposal.current_document_id
          AND proposal_id = v_proposal.id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'El documento actual de la propuesta no existe';
        END IF;

        IF v_document.document_sha256 IS NULL
           OR BTRIM(v_document.document_sha256) = ''
        THEN
            RAISE EXCEPTION
                'El PDF todavía no tiene una huella SHA-256 válida';
        END IF;

        UPDATE public.maintenance_custom_proposal_documents
        SET published_at = CURRENT_TIMESTAMP
        WHERE id = v_document.id;

        UPDATE public.maintenance_custom_proposals
        SET
            status = 'quoted',
            quoted_monthly_price =
                ROUND(
                    p_quoted_monthly_price,
                    2
                ),
            quoted_currency = v_currency,
            quoted_hours_monthly =
                p_quoted_hours_monthly,
            quoted_scope_level =
                NULLIF(
                    BTRIM(p_quoted_scope_level),
                    ''
                ),
            quoted_service_level =
                NULLIF(
                    BTRIM(p_quoted_service_level),
                    ''
                ),
            quoted_sla =
                NULLIF(
                    BTRIM(p_quoted_sla),
                    ''
                ),
            quoted_response_time =
                NULLIF(
                    BTRIM(p_quoted_response_time),
                    ''
                ),
            quoted_support_hours =
                NULLIF(
                    BTRIM(p_quoted_support_hours),
                    ''
                ),
            quoted_description =
                NULLIF(
                    BTRIM(p_quoted_description),
                    ''
                ),
            quoted_terms =
                NULLIF(
                    BTRIM(p_quoted_terms),
                    ''
                ),
            quoted_valid_until =
                p_quoted_valid_until,
            quote_snapshot =
                jsonb_build_object(
                    'monthly_price',
                    ROUND(
                        p_quoted_monthly_price,
                        2
                    ),
                    'currency',
                    v_currency,
                    'hours_monthly',
                    p_quoted_hours_monthly,
                    'scope_level',
                    NULLIF(
                        BTRIM(p_quoted_scope_level),
                        ''
                    ),
                    'service_level',
                    NULLIF(
                        BTRIM(p_quoted_service_level),
                        ''
                    ),
                    'sla',
                    NULLIF(
                        BTRIM(p_quoted_sla),
                        ''
                    ),
                    'response_time',
                    NULLIF(
                        BTRIM(p_quoted_response_time),
                        ''
                    ),
                    'support_hours',
                    NULLIF(
                        BTRIM(p_quoted_support_hours),
                        ''
                    ),
                    'description',
                    NULLIF(
                        BTRIM(p_quoted_description),
                        ''
                    ),
                    'terms',
                    NULLIF(
                        BTRIM(p_quoted_terms),
                        ''
                    ),
                    'valid_until',
                    p_quoted_valid_until,
                    'document_id',
                    v_document.id,
                    'document_version',
                    v_document.version,
                    'document_path',
                    v_document.document_path,
                    'document_sha256',
                    v_document.document_sha256,
                    'captured_at',
                    CURRENT_TIMESTAMP
                ),
            quoted_by = auth.uid(),
            quoted_at = CURRENT_TIMESTAMP,
            reviewed_by = auth.uid(),
            reviewed_at = COALESCE(
                reviewed_at,
                CURRENT_TIMESTAMP
            ),
            response_version =
                response_version + 1,
            response_notes =
                NULLIF(
                    BTRIM(p_response_notes),
                    ''
                ),
            clarification_requested_at = NULL,
            clarification_requested_by = NULL,
            clarification_message = NULL,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_proposal.id
        RETURNING *
        INTO v_proposal;

        INSERT INTO public.maintenance_custom_proposal_events (
            proposal_id,
            actor_id,
            actor_type,
            event_type,
            notes,
            metadata
        )
        VALUES (
            v_proposal.id,
            auth.uid(),
            'worker',
            'document_published',
            'El PDF de respuesta ha quedado publicado para el cliente.',
            jsonb_build_object(
                'document_id',
                v_document.id,
                'document_version',
                v_document.version,
                'document_sha256',
                v_document.document_sha256
            )
        );

        PERFORM public.emit_maintenance_custom_proposal_notification(
            v_proposal.id,
            'Tu propuesta de mantenimiento está disponible',
            'Modira ha preparado una propuesta de mantenimiento personalizada para ti. Revisa las condiciones y el PDF antes de continuar.',
            jsonb_build_object(
                'proposal_id',
                v_proposal.id,
                'status',
                'quoted',
                'document_id',
                v_document.id,
                'document_version',
                v_document.version,
                'action',
                'view_maintenance_proposal'
            )
        );

        RETURN v_proposal;

    END IF;

    RAISE EXCEPTION
        'No se ha podido procesar la revisión de la propuesta';

END;
$_$;


ALTER FUNCTION "public"."review_custom_maintenance_proposal"("p_proposal_id" "uuid", "p_action" "text", "p_quoted_monthly_price" numeric, "p_quoted_currency" "text", "p_quoted_hours_monthly" numeric, "p_quoted_scope_level" "text", "p_quoted_service_level" "text", "p_quoted_sla" "text", "p_quoted_response_time" "text", "p_quoted_support_hours" "text", "p_quoted_description" "text", "p_quoted_terms" "text", "p_quoted_valid_until" "date", "p_response_notes" "text", "p_clarification_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_internal_task"("p_task_id" "uuid", "p_decision" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "public"."internal_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.internal_tasks;
    v_worker_id UUID;
    v_old_status TEXT;
    v_old_progress INTEGER;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.review'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:review:' || auth.uid()::TEXT,
        60,
        3600
    );


    IF NOT public.internal_task_current_worker_is_direction() THEN
        RAISE EXCEPTION
            'Solo Dirección puede revisar tareas';
    END IF;


    IF p_decision NOT IN (
        'approved',
        'returned'
    ) THEN
        RAISE EXCEPTION
            'La decisión debe ser approved o returned';
    END IF;


    v_worker_id := public.internal_task_current_worker_id();


    SELECT *
    INTO v_task
    FROM public.internal_tasks
    WHERE id = p_task_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tarea no existe';
    END IF;


    IF v_task.status <> 'pending_review' THEN
        RAISE EXCEPTION
            'Solo se pueden revisar tareas pendientes de revisión';
    END IF;


    v_old_status := v_task.status;
    v_old_progress := v_task.progress;


    IF p_decision = 'approved' THEN

        UPDATE public.internal_tasks
        SET
            status = 'completed',
            progress = 100,
            completed_at = CURRENT_TIMESTAMP,
            completed_by_worker_id = v_worker_id,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = p_task_id
        RETURNING *
        INTO v_task;


        PERFORM public.internal_task_record_update(
            p_task_id,
            v_worker_id,
            'review_approved',
            v_old_status,
            v_old_progress,
            'completed',
            100,
            p_comment
        );

    ELSE

        UPDATE public.internal_tasks
        SET
            status = 'in_progress',
            completed_at = NULL,
            completed_by_worker_id = NULL,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = p_task_id
        RETURNING *
        INTO v_task;


        PERFORM public.internal_task_record_update(
            p_task_id,
            v_worker_id,
            'review_returned',
            v_old_status,
            v_old_progress,
            'in_progress',
            v_task.progress,
            p_comment
        );

    END IF;


    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."review_internal_task"("p_task_id" "uuid", "p_decision" "text", "p_comment" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_internal_task"("p_task_id" "uuid", "p_decision" "text", "p_comment" "text") IS 'Direction-only task review. Approves pending review to completed or returns it to in_progress.';



CREATE OR REPLACE FUNCTION "public"."review_project_task"("p_task_id" "uuid", "p_approved" boolean, "p_comment" "text" DEFAULT NULL::"text") RETURNS "public"."project_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.project_tasks;
    v_comment TEXT;
    v_old_status TEXT;
    v_old_progress INTEGER;
BEGIN

    IF public.current_project_task_worker_id() IS NULL THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.update'
    );

    IF NOT public.current_worker_is_direction() THEN
        RAISE EXCEPTION
            'Solo Dirección puede revisar tareas';
    END IF;

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:review:' || auth.uid()::TEXT,
        60,
        3600
    );

    IF p_approved IS NULL THEN
        RAISE EXCEPTION
            'Debe indicarse si la tarea ha sido aprobada';
    END IF;

    v_comment := NULLIF(BTRIM(p_comment), '');

    IF v_comment IS NOT NULL
       AND LENGTH(v_comment) > 5000
    THEN
        RAISE EXCEPTION
            'El comentario no puede superar 5000 caracteres';
    END IF;

    SELECT *
    INTO v_task
    FROM public.project_tasks
    WHERE id = p_task_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Tarea no encontrada';
    END IF;

    IF v_task.status <> 'pending_review' THEN
        RAISE EXCEPTION
            'La tarea no está pendiente de revisión';
    END IF;

    v_old_status := v_task.status;
    v_old_progress := v_task.progress;

    IF p_approved THEN

        UPDATE public.project_tasks
        SET
            status = 'completed',
            progress = 100,
            completed_at = CURRENT_TIMESTAMP,
            completed_by_worker_id =
                public.current_project_task_worker_id()
        WHERE id = v_task.id;

    ELSE

        UPDATE public.project_tasks
        SET
            status = 'in_progress',
            progress = 100,
            submitted_for_review_at = NULL
        WHERE id = v_task.id;

    END IF;

    SELECT *
    INTO v_task
    FROM public.project_tasks
    WHERE id = p_task_id;

    PERFORM public.record_project_task_update(
        v_task.id,
        CASE
            WHEN p_approved
                THEN 'review_approved'
            ELSE 'review_returned'
        END,
        v_old_status,
        v_old_progress,
        v_task.status,
        v_task.progress,
        v_comment
    );

    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."review_project_task"("p_task_id" "uuid", "p_approved" boolean, "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_recurring_expense_template"("p_template_id" "uuid", "p_decision" "text") RETURNS "public"."recurring_expense_templates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_template public.recurring_expense_templates;
BEGIN
  PERFORM public.require_expense_permission('expenses.approve');
  PERFORM public.consume_expense_worker_rate_limit('expenses:recurring_review');

  IF p_decision NOT IN ('approved','rejected') THEN
    RAISE EXCEPTION 'La decisión debe ser approved o rejected';
  END IF;

  SELECT * INTO v_template
  FROM public.recurring_expense_templates
  WHERE id = p_template_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'La configuración recurrente no existe'; END IF;
  IF v_template.approval_status <> 'pending_review' THEN
    RAISE EXCEPTION 'Solo se pueden revisar configuraciones pendientes de aprobación';
  END IF;

  UPDATE public.recurring_expense_templates
  SET approval_status = p_decision,
      approved_by = CASE WHEN p_decision = 'approved' THEN auth.uid() ELSE NULL END,
      approved_at = CASE WHEN p_decision = 'approved' THEN CURRENT_TIMESTAMP ELSE NULL END,
      updated_by = auth.uid(),
      updated_at = CURRENT_TIMESTAMP
  WHERE id = p_template_id
  RETURNING * INTO v_template;

  RETURN v_template;
END;
$$;


ALTER FUNCTION "public"."review_recurring_expense_template"("p_template_id" "uuid", "p_decision" "text") OWNER TO "postgres";


