CREATE OR REPLACE FUNCTION "public"."save_quotation_workflow_draft"("p_draft_id" "uuid", "p_content" "jsonb") RETURNS "public"."quotation_workflow_drafts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_draft public.quotation_workflow_drafts%ROWTYPE;
  v_new_content jsonb;
  v_permission text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.current_user_is_worker() THEN
    RAISE EXCEPTION 'Acceso denegado: se requiere un trabajador autenticado';
  END IF;

  IF p_draft_id IS NULL THEN
    RAISE EXCEPTION 'El borrador es obligatorio';
  END IF;

  SELECT * INTO v_draft
  FROM public.quotation_workflow_drafts
  WHERE id = p_draft_id
  FOR UPDATE;

  IF NOT FOUND OR v_draft.draft_status <> 'draft' THEN
    RAISE EXCEPTION 'El borrador no existe o ya no se puede editar';
  END IF;

  v_permission := CASE WHEN v_draft.quotation_id IS NULL THEN 'quotations.create' ELSE 'quotations.update' END;
  PERFORM public.require_current_worker_permission(v_permission);

  v_new_content := public.validate_quotation_workflow_content(v_draft.content || COALESCE(p_content, '{}'::jsonb));
  PERFORM public.rate_limit_quotation_workflow_field_changes(auth.uid(), v_draft.content, v_new_content);

  UPDATE public.quotation_workflow_drafts
  SET content = v_new_content,
      updated_at = now()
  WHERE id = p_draft_id
  RETURNING * INTO v_draft;

  RETURN v_draft;
END;
$$;


ALTER FUNCTION "public"."save_quotation_workflow_draft"("p_draft_id" "uuid", "p_content" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."security_rate_limit_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_rate_key TEXT;
BEGIN

    IF auth.uid() IS NULL THEN
        RETURN NEW;
    END IF;


    v_user_id := auth.uid();


    IF public.current_user_is_worker() THEN
        RETURN NEW;
    END IF;


    v_rate_key :=
        TG_TABLE_SCHEMA
        || ':'
        || TG_TABLE_NAME
        || ':'
        || v_user_id::TEXT;


    -- ========================================================
    -- PROJECTS — 10 / HORA
    -- ========================================================

    IF TG_TABLE_NAME = 'projects' THEN

        PERFORM public.enforce_security_rate_limit(
            v_rate_key,
            10,
            3600
        );

        RETURN NEW;
    END IF;


    -- ========================================================
    -- COMPANY CHANGE REQUESTS — 3 / 24 HORAS
    -- ========================================================

    IF TG_TABLE_NAME = 'company_change_requests' THEN

        PERFORM public.enforce_security_rate_limit(
            v_rate_key,
            3,
            86400
        );

        RETURN NEW;
    END IF;


    -- ========================================================
    -- PROJECT CHANGE REQUESTS — 10 / HORA
    -- ========================================================

    IF TG_TABLE_NAME = 'project_change_requests' THEN

        PERFORM public.enforce_security_rate_limit(
            v_rate_key,
            10,
            3600
        );

        RETURN NEW;
    END IF;


    -- ========================================================
    -- SUPPORT TICKETS — 5 / HORA
    -- ========================================================

    IF TG_TABLE_NAME = 'support_tickets' THEN

        PERFORM public.enforce_security_rate_limit(
            v_rate_key,
            5,
            3600
        );

        RETURN NEW;
    END IF;


    -- ========================================================
    -- AUTOMATIONS — 10 / HORA
    -- ========================================================

    IF TG_TABLE_NAME = 'automations' THEN

        PERFORM public.enforce_security_rate_limit(
            v_rate_key,
            10,
            3600
        );

        RETURN NEW;
    END IF;


    -- ========================================================
    -- CLIENTS — 100 / HORA
    -- ========================================================

    IF TG_TABLE_NAME = 'clients' THEN

        PERFORM public.enforce_security_rate_limit(
            v_rate_key,
            100,
            3600
        );

        RETURN NEW;
    END IF;


    -- ========================================================
    -- MAINTENANCE CONTRACTS — 50 / HORA
    -- ========================================================

    IF TG_TABLE_NAME = 'maintenance_contracts' THEN

        PERFORM public.enforce_security_rate_limit(
            v_rate_key,
            50,
            3600
        );

        RETURN NEW;
    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."security_rate_limit_trigger"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."companies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_code" character varying(50) NOT NULL,
    "company_name" "text" NOT NULL,
    "legal_name" "text",
    "cif_vat" "text",
    "billing_email" character varying(320),
    "phone" "text",
    "website" "text",
    "logo_url" "text",
    "address" "text",
    "postal_code" "text",
    "city" "text",
    "province" "text",
    "country" character varying(2) DEFAULT 'ES'::character varying NOT NULL,
    "industry" "text",
    "employees" integer,
    "timezone" character varying(64) DEFAULT 'Europe/Madrid'::character varying NOT NULL,
    "language" character varying(10) DEFAULT 'es'::character varying NOT NULL,
    "currency" character varying(3) DEFAULT 'EUR'::character varying NOT NULL,
    "stripe_customer_id" "text",
    "subscription_plan" "text",
    "subscription_status" character varying(50),
    "trial_ends_at" timestamp with time zone,
    "created_by" "uuid",
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "iva_recomendado_aplicado" boolean DEFAULT true NOT NULL,
    "iva_recomendado_porcentaje" numeric(5,2) DEFAULT 21 NOT NULL,
    "iva_recomendado_updated_by" "uuid",
    "iva_recomendado_updated_at" timestamp with time zone,
    "iva_aprobado_aplicado" boolean DEFAULT false NOT NULL,
    "iva_aprobado_porcentaje" numeric(5,2) DEFAULT 0 NOT NULL,
    "iva_aprobado_por" "uuid",
    "iva_aprobado_at" timestamp with time zone,
    "iva_recomendado_por" "uuid",
    "worker_notes" "text",
    CONSTRAINT "companies_iva_aprobado_check" CHECK (((("iva_aprobado_aplicado" = true) AND ("iva_aprobado_porcentaje" >= (0)::numeric) AND ("iva_aprobado_porcentaje" <= (100)::numeric)) OR (("iva_aprobado_aplicado" = false) AND ("iva_aprobado_porcentaje" = (0)::numeric)))),
    CONSTRAINT "companies_iva_recomendado_porcentaje_check" CHECK (((("iva_recomendado_aplicado" = true) AND ("iva_recomendado_porcentaje" >= (0)::numeric) AND ("iva_recomendado_porcentaje" <= (100)::numeric)) OR (("iva_recomendado_aplicado" = false) AND ("iva_recomendado_porcentaje" = (0)::numeric)))),
    CONSTRAINT "companies_worker_notes_max_length" CHECK ((("worker_notes" IS NULL) OR ("length"("worker_notes") <= 5000)))
);


ALTER TABLE "public"."companies" OWNER TO "postgres";


COMMENT ON COLUMN "public"."companies"."iva_recomendado_aplicado" IS 'Indica si el worker recomienda aplicar IVA de forma general a la empresa. Esta recomendación es independiente de cualquier IVA aprobado mediante solicitud del cliente y del IVA de mantenimiento.';



COMMENT ON COLUMN "public"."companies"."iva_recomendado_porcentaje" IS 'Porcentaje de IVA general recomendado por el worker. Se utiliza como valor predeterminado cuando no existe un tratamiento de IVA aprobado por solicitud del cliente.';



COMMENT ON COLUMN "public"."companies"."iva_recomendado_updated_by" IS 'Worker que estableció o modificó el IVA recomendado de la empresa.';



COMMENT ON COLUMN "public"."companies"."iva_recomendado_updated_at" IS 'Fecha y hora de la última modificación de la recomendación de IVA general del worker.';



COMMENT ON COLUMN "public"."companies"."iva_aprobado_aplicado" IS 'Indica si la empresa tiene actualmente un tratamiento de IVA general aprobado mediante una solicitud del cliente. Es independiente del IVA recomendado por el worker y del IVA de mantenimiento.';



COMMENT ON COLUMN "public"."companies"."iva_aprobado_porcentaje" IS 'Porcentaje de IVA general aprobado actualmente para la empresa. Se utiliza como configuración predeterminada para nuevos presupuestos y facturas normales, pero el worker puede sobrescribirlo manualmente. No modifica registros históricos.';



COMMENT ON COLUMN "public"."companies"."iva_aprobado_por" IS 'Usuario de Auth del worker que aprobó el tratamiento de IVA general actualmente vigente.';



COMMENT ON COLUMN "public"."companies"."iva_aprobado_at" IS 'Fecha y hora de aprobación del tratamiento de IVA general actualmente vigente.';



COMMENT ON COLUMN "public"."companies"."iva_recomendado_por" IS 'Usuario de Auth del worker que estableció la recomendación de IVA general.';



CREATE OR REPLACE FUNCTION "public"."set_company_iva_recommendation"("p_company_id" "uuid", "p_iva_aplicado" boolean, "p_iva_porcentaje" numeric) RETURNS "public"."companies"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'companies.update'
    );

    RETURN public.set_company_iva_recommendation__legacy_113(
        p_company_id,
        p_iva_aplicado,
        p_iva_porcentaje
    );

END;
$$;


ALTER FUNCTION "public"."set_company_iva_recommendation"("p_company_id" "uuid", "p_iva_aplicado" boolean, "p_iva_porcentaje" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_company_iva_recommendation__legacy_113"("p_company_id" "uuid", "p_iva_aplicado" boolean, "p_iva_porcentaje" numeric) RETURNS "public"."companies"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_company public.companies;

BEGIN

    -- --------------------------------------------------------
    -- WORKER
    -- --------------------------------------------------------

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    -- --------------------------------------------------------
    -- VALIDAR PORCENTAJE
    -- --------------------------------------------------------

    IF p_iva_porcentaje IS NULL
       OR p_iva_porcentaje < 0
       OR p_iva_porcentaje > 100
    THEN
        RAISE EXCEPTION
            'El porcentaje de IVA debe estar entre 0 y 100';
    END IF;


    -- --------------------------------------------------------
    -- EMPRESA
    -- --------------------------------------------------------

    SELECT *
    INTO v_company
    FROM public.companies
    WHERE id = p_company_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La empresa no existe';
    END IF;


    -- --------------------------------------------------------
    -- ACTUALIZAR
    -- --------------------------------------------------------

    UPDATE public.companies
    SET
        iva_recomendado_aplicado = COALESCE(p_iva_aplicado, TRUE),
        iva_recomendado_porcentaje =
            ROUND(p_iva_porcentaje, 2),
        iva_recomendado_updated_by =
            auth.uid(),
        iva_recomendado_updated_at =
            CURRENT_TIMESTAMP,
        updated_at =
            CURRENT_TIMESTAMP
    WHERE id = p_company_id
    RETURNING *
    INTO v_company;


    RETURN v_company;

END;
$$;


ALTER FUNCTION "public"."set_company_iva_recommendation__legacy_113"("p_company_id" "uuid", "p_iva_aplicado" boolean, "p_iva_porcentaje" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_company_worker_notes"("p_company_id" "uuid", "p_worker_notes" "text") RETURNS "public"."companies"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_company public.companies;
    v_notes TEXT;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado.';
    END IF;

    PERFORM public.require_current_worker_permission(
        'companies.update'
    );

    IF p_company_id IS NULL THEN
        RAISE EXCEPTION 'La empresa es obligatoria.';
    END IF;

    v_notes := NULLIF(BTRIM(COALESCE(p_worker_notes, '')), '');

    IF v_notes IS NOT NULL
       AND LENGTH(v_notes) > 5000
    THEN
        RAISE EXCEPTION
            'Las notas de empresa no pueden superar 5000 caracteres.';
    END IF;

    UPDATE public.companies
    SET
        worker_notes = v_notes,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_company_id
    RETURNING *
    INTO v_company;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La empresa no existe.';
    END IF;

    RETURN v_company;
END;
$$;


ALTER FUNCTION "public"."set_company_worker_notes"("p_company_id" "uuid", "p_worker_notes" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."expense_approval_rules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "category_id" "uuid",
    "minimum_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "requires_approval" boolean DEFAULT true NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "expense_approval_rules_minimum_amount_check" CHECK (("minimum_amount" >= (0)::numeric))
);


ALTER TABLE "public"."expense_approval_rules" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_expense_approval_rule"("p_category_id" "uuid", "p_minimum_amount" numeric, "p_requires_approval" boolean, "p_is_active" boolean DEFAULT true) RETURNS "public"."expense_approval_rules"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rule public.expense_approval_rules;
BEGIN
  PERFORM public.require_expense_permission('expenses.approval_rules.manage');
  PERFORM public.consume_expense_worker_rate_limit('expenses:approval_rule');

  IF p_minimum_amount IS NULL OR p_minimum_amount < 0 THEN
    RAISE EXCEPTION 'El límite mínimo debe ser un importe igual o superior a 0';
  END IF;

  INSERT INTO public.expense_approval_rules (
    category_id, minimum_amount, requires_approval, is_active,
    created_by, updated_by
  ) VALUES (
    p_category_id, ROUND(p_minimum_amount, 2), COALESCE(p_requires_approval, true),
    COALESCE(p_is_active, true), auth.uid(), auth.uid()
  )
  ON CONFLICT ((COALESCE(category_id, '00000000-0000-0000-0000-000000000000'::uuid)))
  DO UPDATE SET
    minimum_amount = EXCLUDED.minimum_amount,
    requires_approval = EXCLUDED.requires_approval,
    is_active = EXCLUDED.is_active,
    updated_by = auth.uid(),
    updated_at = CURRENT_TIMESTAMP
  RETURNING * INTO v_rule;

  RETURN v_rule;
END;
$$;


ALTER FUNCTION "public"."set_expense_approval_rule"("p_category_id" "uuid", "p_minimum_amount" numeric, "p_requires_approval" boolean, "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_internal_task_visibility"("p_task_id" "uuid", "p_worker_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_role_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_worker_id UUID;
    v_role_id UUID;
    v_actor UUID;
    v_task public.internal_tasks;
    v_result JSONB;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.manage_visibility'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:visibility_write:' || auth.uid()::TEXT,
        60,
        3600
    );


    IF NOT public.internal_task_current_worker_is_direction() THEN
        RAISE EXCEPTION
            'Solo Dirección puede gestionar la visibilidad';
    END IF;


    v_actor := public.internal_task_current_worker_id();


    SELECT *
    INTO v_task
    FROM public.internal_tasks
    WHERE id = p_task_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tarea no existe';
    END IF;


    DELETE FROM public.internal_task_user_access
    WHERE task_id = p_task_id;


    DELETE FROM public.internal_task_role_access
    WHERE task_id = p_task_id;


    IF p_worker_ids IS NOT NULL THEN

        FOREACH v_worker_id IN ARRAY p_worker_ids
        LOOP

            IF NOT EXISTS (
                SELECT 1
                FROM public.workers w
                WHERE w.id = v_worker_id
                  AND w.is_active = TRUE
            ) THEN
                RAISE EXCEPTION
                    'Uno de los trabajadores seleccionados no existe o no está activo';
            END IF;


            INSERT INTO public.internal_task_user_access (
                task_id,
                worker_id
            )
            VALUES (
                p_task_id,
                v_worker_id
            )
            ON CONFLICT DO NOTHING;

        END LOOP;

    END IF;


    IF p_role_ids IS NOT NULL THEN

        FOREACH v_role_id IN ARRAY p_role_ids
        LOOP

            IF NOT EXISTS (
                SELECT 1
                FROM public.worker_roles wr
                WHERE wr.id = v_role_id
                  AND wr.is_active = TRUE
            ) THEN
                RAISE EXCEPTION
                    'Uno de los roles seleccionados no existe o no está activo';
            END IF;


            INSERT INTO public.internal_task_role_access (
                task_id,
                role_id
            )
            VALUES (
                p_task_id,
                v_role_id
            )
            ON CONFLICT DO NOTHING;

        END LOOP;

    END IF;


    PERFORM public.internal_task_record_update(
        p_task_id,
        v_actor,
        'visibility_changed',
        v_task.status,
        v_task.progress,
        v_task.status,
        v_task.progress,
        COALESCE(
            BTRIM(p_comment),
            'Visibilidad de la tarea actualizada'
        )
    );


    SELECT jsonb_build_object(
        'workers',
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'worker_id', a.worker_id,
                        'display_name', w.display_name
                    )
                    ORDER BY w.display_name
                )
                FROM public.internal_task_user_access a
                JOIN public.workers w
                  ON w.id = a.worker_id
                WHERE a.task_id = p_task_id
            ),
            '[]'::JSONB
        ),

        'roles',
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'role_id', a.role_id,
                        'code', wr.code,
                        'name', wr.name
                    )
                    ORDER BY wr.name
                )
                FROM public.internal_task_role_access a
                JOIN public.worker_roles wr
                  ON wr.id = a.role_id
                WHERE a.task_id = p_task_id
            ),
            '[]'::JSONB
        )
    )
    INTO v_result;


    RETURN v_result;

END;
$$;


ALTER FUNCTION "public"."set_internal_task_visibility"("p_task_id" "uuid", "p_worker_ids" "uuid"[], "p_role_ids" "uuid"[], "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_invoice_document_hash"("p_invoice_id" "uuid", "p_document_sha256" "text") RETURNS "public"."invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_invoice public.invoices;
    v_hash TEXT;
BEGIN

    PERFORM public.require_current_worker_permission(
        'invoices.update'
    );

    v_hash :=
        LOWER(
            TRIM(
                COALESCE(
                    p_document_sha256,
                    ''
                )
            )
        );

    IF v_hash = '' THEN
        RAISE EXCEPTION
            'La huella digital del documento es obligatoria';
    END IF;

    IF v_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION
            'La huella digital del documento no es un SHA-256 válido';
    END IF;

    SELECT *
    INTO v_invoice
    FROM public.invoices
    WHERE id = p_invoice_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La factura no existe';
    END IF;

    IF v_invoice.document_path IS NULL
       OR TRIM(v_invoice.document_path) = ''
    THEN
        RAISE EXCEPTION
            'La factura no tiene un documento PDF asociado';
    END IF;

    UPDATE public.invoices
    SET
        document_sha256 = v_hash,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_invoice_id
    RETURNING *
    INTO v_invoice;

    RETURN v_invoice;

END;
$_$;


ALTER FUNCTION "public"."set_invoice_document_hash"("p_invoice_id" "uuid", "p_document_sha256" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_invoice_document_hash"("p_invoice_id" "uuid", "p_document_sha256" "text") IS 'Registra el SHA-256 calculado server-side del PDF real asociado a una factura. Solo puede utilizarla un trabajador activo y únicamente modifica invoices.document_sha256.';



CREATE OR REPLACE FUNCTION "public"."set_invoice_rectification_by_worker"("p_invoice_id" "uuid", "p_rectifies_invoice_id" "uuid", "p_rectification_reason" "text", "p_rectification_customer_data_source" "text" DEFAULT 'original_invoice'::"text") RETURNS "public"."invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_invoice public.invoices;
    v_original public.invoices;

    v_can_create BOOLEAN := FALSE;
    v_can_update BOOLEAN := FALSE;

    v_reason TEXT;
    v_customer_data_source TEXT;

    v_customer_legal_name TEXT;
    v_customer_tax_id TEXT;
    v_customer_address TEXT;
    v_customer_postal_code TEXT;
    v_customer_city TEXT;
    v_customer_province TEXT;
    v_customer_country TEXT;
    v_customer_contact_name TEXT;

    v_client_company_id UUID;

BEGIN

    -- ========================================================
    -- 1. AUTENTICACIÓN Y PERMISOS
    -- ========================================================

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    SELECT COALESCE(
        public.current_worker_has_permission('invoices.create'),
        FALSE
    )
    INTO v_can_create;


    SELECT COALESCE(
        public.current_worker_has_permission('invoices.update'),
        FALSE
    )
    INTO v_can_update;


    IF NOT v_can_create AND NOT v_can_update THEN
        RAISE EXCEPTION
            'No tienes permiso para gestionar rectificaciones de facturas';
    END IF;


    -- ========================================================
    -- 2. BLOQUEAR LA FACTURA QUE SE QUIERE RECTIFICAR
    -- ========================================================

    SELECT *
    INTO v_invoice
    FROM public.invoices
    WHERE id = p_invoice_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Factura no encontrada';
    END IF;


    -- No se permite modificar una factura cuya aceptación
    -- documental ya esté registrada.

    IF EXISTS (
        SELECT 1
        FROM public.invoice_document_acknowledgements a
        WHERE a.invoice_id = v_invoice.id
    ) THEN
        RAISE EXCEPTION
            'La factura ya tiene una aceptación documental y sus datos no pueden modificarse';
    END IF;


    -- No se debe cambiar la rectificación de un documento
    -- oficial ya generado. Primero debe existir un flujo
    -- explícito de corrección del documento.

    IF (
        v_invoice.document_path IS NOT NULL
        OR v_invoice.document_sha256 IS NOT NULL
    )
    AND (
        v_invoice.rectifies_invoice_id
            IS DISTINCT FROM p_rectifies_invoice_id
        OR v_invoice.rectification_reason
            IS DISTINCT FROM NULLIF(
                TRIM(COALESCE(p_rectification_reason, '')),
                ''
            )
        OR v_invoice.rectification_customer_data_source
            IS DISTINCT FROM COALESCE(
                NULLIF(
                    TRIM(p_rectification_customer_data_source),
                    ''
                ),
                'original_invoice'
            )
    ) THEN
        RAISE EXCEPTION
            'La factura ya tiene un documento oficial. No se puede modificar su rectificación sin un procedimiento explícito de nueva emisión';
    END IF;


    -- ========================================================
    -- 3. VALIDAR EL ORIGEN DE LOS DATOS FISCALES
    -- ========================================================

    v_customer_data_source := COALESCE(
        NULLIF(
            TRIM(p_rectification_customer_data_source),
            ''
        ),
        'original_invoice'
    );


    IF v_customer_data_source NOT IN (
        'original_invoice',
        'current_company'
    ) THEN
        RAISE EXCEPTION
            'El origen de los datos fiscales debe ser original_invoice o current_company';
    END IF;


    -- ========================================================
    -- 4. ELIMINAR LA RELACIÓN DE RECTIFICACIÓN
    -- ========================================================
    -- Si no se selecciona una factura original, se limpia
    -- también el motivo y se restaura el origen predeterminado.
    -- ========================================================

    IF p_rectifies_invoice_id IS NULL THEN

        UPDATE public.invoices
        SET
            rectifies_invoice_id = NULL,
            rectification_reason = NULL,
            rectification_customer_data_source = 'original_invoice'
        WHERE id = v_invoice.id
        RETURNING *
        INTO v_invoice;

        RETURN v_invoice;

    END IF;


    -- ========================================================
    -- 5. VALIDAR EL MOTIVO
    -- ========================================================

    IF p_rectifies_invoice_id = p_invoice_id THEN
        RAISE EXCEPTION
            'Una factura no puede rectificarse a sí misma';
    END IF;


    v_reason := TRIM(
        COALESCE(p_rectification_reason, '')
    );


    IF v_reason = '' THEN
        RAISE EXCEPTION
            'El motivo de rectificación es obligatorio';
    END IF;


    IF LENGTH(v_reason) > 2000 THEN
        RAISE EXCEPTION
            'El motivo de rectificación no puede superar 2000 caracteres';
    END IF;


    -- ========================================================
    -- 6. VALIDAR LA FACTURA ORIGINAL
    -- ========================================================

    SELECT *
    INTO v_original
    FROM public.invoices
    WHERE id = p_rectifies_invoice_id
    FOR SHARE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La factura original que se quiere rectificar no existe';
    END IF;


    IF v_original.company_id
        IS DISTINCT FROM v_invoice.company_id
    THEN
        RAISE EXCEPTION
            'La factura original debe pertenecer a la misma empresa';
    END IF;


    IF v_original.rectifies_invoice_id IS NOT NULL THEN
        RAISE EXCEPTION
            'La factura original seleccionada ya es una factura rectificativa';
    END IF;


    -- ========================================================
    -- 7. CONSERVAR LOS DATOS FISCALES ORIGINALES
    -- ========================================================
    -- Por defecto, la rectificativa utiliza exactamente los
    -- datos del destinatario guardados en la factura original.
    -- No se consulta ni modifica public.companies.
    -- ========================================================

    v_customer_legal_name :=
        v_original.customer_legal_name;

    v_customer_tax_id :=
        v_original.customer_tax_id;

    v_customer_address :=
        v_original.customer_address;

    v_customer_postal_code :=
        v_original.customer_postal_code;

    v_customer_city :=
        v_original.customer_city;

    v_customer_province :=
        v_original.customer_province;

    v_customer_country :=
        v_original.customer_country;

    v_customer_contact_name :=
        v_original.customer_contact_name;


    -- ========================================================
    -- 8. DATOS FISCALES ACTUALES DEL DESTINATARIO
    -- ========================================================
    -- Opción B:
    --
    -- current_company consulta el cliente asociado a la factura
    -- original en public.clients.
    --
    -- No se copian datos de public.companies a customer_*,
    -- porque esos datos pertenecen al emisor.
    -- ========================================================

    IF v_customer_data_source = 'current_company' THEN

        IF v_original.client_id IS NULL THEN
            RAISE EXCEPTION
                'La factura original no tiene un cliente asociado. No se pueden recuperar sus datos fiscales actuales';
        END IF;


        SELECT
            c.company_id,

            COALESCE(
                NULLIF(TRIM(c.empresa), ''),
                NULLIF(TRIM(c.nombre), '')
            ),

            NULLIF(TRIM(c.cif_vat), ''),
            NULLIF(TRIM(c.direccion), ''),
            NULLIF(TRIM(c.codigo_postal), ''),
            NULLIF(TRIM(c.ciudad), ''),
            NULLIF(TRIM(c.provincia), ''),

            COALESCE(
                NULLIF(TRIM(c.pais), ''),
                'ES'
            ),

            NULLIF(TRIM(c.nombre), '')

        INTO
            v_client_company_id,
            v_customer_legal_name,
            v_customer_tax_id,
            v_customer_address,
            v_customer_postal_code,
            v_customer_city,
            v_customer_province,
            v_customer_country,
            v_customer_contact_name

        FROM public.clients c

        WHERE c.id = v_original.client_id;


        IF NOT FOUND THEN
            RAISE EXCEPTION
                'No se encuentra el cliente asociado a la factura original';
        END IF;


        IF v_client_company_id
            IS DISTINCT FROM v_original.company_id
        THEN
            RAISE EXCEPTION
                'El cliente de la factura original no pertenece a la empresa correspondiente';
        END IF;


        -- Evitamos emitir una rectificativa con datos fiscales
        -- actuales incompletos.

        IF NULLIF(TRIM(COALESCE(v_customer_legal_name, '')), '') IS NULL
           OR NULLIF(TRIM(COALESCE(v_customer_tax_id, '')), '') IS NULL
           OR NULLIF(TRIM(COALESCE(v_customer_address, '')), '') IS NULL
           OR NULLIF(TRIM(COALESCE(v_customer_postal_code, '')), '') IS NULL
           OR NULLIF(TRIM(COALESCE(v_customer_city, '')), '') IS NULL
           OR NULLIF(TRIM(COALESCE(v_customer_country, '')), '') IS NULL
        THEN
            RAISE EXCEPTION
                'El cliente no tiene todos los datos fiscales actuales obligatorios';
        END IF;

    END IF;


    -- ========================================================
    -- 9. GUARDAR LA RECTIFICACIÓN Y EL SNAPSHOT DEL DESTINATARIO
    -- ========================================================
    -- Solo se actualiza la factura rectificativa.
    --
    -- La factura original permanece intacta.
    -- Los campos issuer_* permanecen intactos.
    -- ========================================================

    UPDATE public.invoices

    SET
        rectifies_invoice_id =
            p_rectifies_invoice_id,

        rectification_reason =
            v_reason,

        rectification_customer_data_source =
            v_customer_data_source,

        customer_legal_name =
            v_customer_legal_name,

        customer_tax_id =
            v_customer_tax_id,

        customer_address =
            v_customer_address,

        customer_postal_code =
            v_customer_postal_code,

        customer_city =
            v_customer_city,

        customer_province =
            v_customer_province,

        customer_country =
            v_customer_country,

        customer_contact_name =
            v_customer_contact_name

    WHERE id = v_invoice.id

    RETURNING *
    INTO v_invoice;


    RETURN v_invoice;

END;

$$;


ALTER FUNCTION "public"."set_invoice_rectification_by_worker"("p_invoice_id" "uuid", "p_rectifies_invoice_id" "uuid", "p_rectification_reason" "text", "p_rectification_customer_data_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_maintenance_invoice_document_hash"("p_invoice_id" "uuid", "p_sha256" "text") RETURNS "public"."maintenance_invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_invoice public.maintenance_invoices;
  v_hash TEXT;
BEGIN
    PERFORM public.require_current_worker_permission('maintenance.update');
  IF NOT public.current_user_is_worker() THEN
    RAISE EXCEPTION
      'Acceso denegado: se requiere un trabajador activo';
  END IF;

  v_hash := LOWER(TRIM(COALESCE(p_sha256, '')));

  IF v_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION
      'La huella digital del documento no es un SHA-256 válido';
  END IF;

  SELECT *
  INTO v_invoice
  FROM public.maintenance_invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'La factura de mantenimiento no existe';
  END IF;

  IF v_invoice.document_path IS NULL THEN
    RAISE EXCEPTION
      'La factura todavía no tiene document_path';
  END IF;

  IF v_invoice.document_sha256 IS NOT NULL
     AND LOWER(v_invoice.document_sha256) <> v_hash
  THEN
    RAISE EXCEPTION
      'La factura ya tiene una huella SHA-256 diferente; no se permite sustituirla';
  END IF;

  UPDATE public.maintenance_invoices
  SET
    document_sha256 = v_hash,
    updated_at = CURRENT_TIMESTAMP
  WHERE id = p_invoice_id
  RETURNING *
  INTO v_invoice;

  RETURN v_invoice;
END;
$_$;


ALTER FUNCTION "public"."set_maintenance_invoice_document_hash"("p_invoice_id" "uuid", "p_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_payroll_audit_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'pg_temp'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.created_at := CURRENT_TIMESTAMP;
        NEW.updated_at := CURRENT_TIMESTAMP;
        IF auth.uid() IS NOT NULL THEN
            NEW.created_by := auth.uid();
            NEW.updated_by := auth.uid();
        END IF;
    ELSE
        NEW.created_at := OLD.created_at;
        NEW.created_by := OLD.created_by;
        NEW.updated_at := CURRENT_TIMESTAMP;
        IF auth.uid() IS NOT NULL THEN
            NEW.updated_by := auth.uid();
        ELSE
            NEW.updated_by := OLD.updated_by;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_payroll_audit_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_payroll_document_audit_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'pg_temp'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.created_at := CURRENT_TIMESTAMP;
        IF auth.uid() IS NOT NULL THEN
            NEW.uploaded_by := auth.uid();
        END IF;
    ELSE
        NEW.created_at := OLD.created_at;
        NEW.uploaded_by := OLD.uploaded_by;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_payroll_document_audit_fields"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."profiles" (
    "id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "email" character varying(320),
    "empresa" "text",
    "telefono" "text",
    "rol" "text" DEFAULT 'user'::"text" NOT NULL,
    "company_id" "uuid",
    "fecha_registro" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "fecha_ultimo_login" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    CONSTRAINT "profiles_nombre_length_check" CHECK ((("nombre" IS NULL) OR ("length"("nombre") <= 200))),
    CONSTRAINT "profiles_rol_check" CHECK (("rol" = ANY (ARRAY['user'::"text", 'admin'::"text"]))),
    CONSTRAINT "profiles_status_check" CHECK (("status" = ANY (ARRAY['pending_legal'::"text", 'active'::"text", 'blocked'::"text"]))),
    CONSTRAINT "profiles_telefono_length_check" CHECK ((("telefono" IS NULL) OR ("length"("telefono") <= 32)))
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


COMMENT ON COLUMN "public"."profiles"."status" IS 'Estado de acceso de la cuenta. active permite operar; blocked bloquea el acceso a las operaciones protegidas.';



CREATE OR REPLACE FUNCTION "public"."set_profile_status"("p_user_id" "uuid", "p_status" "text") RETURNS "public"."profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'system.workers.manage'
    );

    RETURN public.set_profile_status__legacy_113(
        p_user_id,
        p_status
    );

END;
$$;


ALTER FUNCTION "public"."set_profile_status"("p_user_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_profile_status__legacy_113"("p_user_id" "uuid", "p_status" "text") RETURNS "public"."profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_profile public.profiles;
    v_target_role TEXT;
    v_target_is_worker BOOLEAN;
    v_caller_is_admin BOOLEAN;
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo de MODIRA';
    END IF;

    IF p_user_id IS NULL THEN
        RAISE EXCEPTION
            'El usuario objetivo es obligatorio';
    END IF;

    IF p_status NOT IN ('active', 'blocked') THEN
        RAISE EXCEPTION
            'Estado de cuenta no válido';
    END IF;

    IF p_user_id = auth.uid() THEN
        RAISE EXCEPTION
            'No puedes modificar el estado de tu propia cuenta';
    END IF;

    SELECT
        p.rol
    INTO
        v_target_role
    FROM public.profiles p
    WHERE p.id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El perfil indicado no existe';
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM public.workers w
        WHERE w.auth_user_id = p_user_id
    )
    INTO v_target_is_worker;

    v_caller_is_admin := public.current_user_is_admin();

    -- Ningún worker puede gestionar un admin.
    -- Ningún admin puede gestionar otro admin.
    IF v_target_role = 'admin' THEN
        RAISE EXCEPTION
            'No puedes modificar el estado de una cuenta administradora';
    END IF;

    -- Un worker normal no puede gestionar otros workers.
    IF v_target_is_worker
       AND NOT v_caller_is_admin
    THEN
        RAISE EXCEPTION
            'Un trabajador no puede modificar el estado de otro trabajador';
    END IF;

    UPDATE public.profiles
    SET
        status = p_status,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_user_id
    RETURNING *
    INTO v_profile;

    IF p_status = 'blocked' THEN
        PERFORM public.revoke_user_sessions(p_user_id);
    END IF;

    RETURN v_profile;

END;
$$;


ALTER FUNCTION "public"."set_profile_status__legacy_113"("p_user_id" "uuid", "p_status" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_profile_status__legacy_113"("p_user_id" "uuid", "p_status" "text") IS 'Permite a un trabajador activo de MODIRA bloquear o desbloquear una cuenta de usuario. El bloqueo revoca las sesiones Auth existentes.';



CREATE OR REPLACE FUNCTION "public"."set_project_milestone_status"("p_milestone_id" "uuid", "p_estado" "text") RETURNS "public"."project_milestones"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

    v_milestone public.project_milestones;

BEGIN
    PERFORM public.require_current_worker_permission('project_milestones.update');

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- WORKER ACTIVO
    -- --------------------------------------------------------

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    -- --------------------------------------------------------
    -- ESTADO
    -- --------------------------------------------------------

    IF p_estado IS NULL
       OR p_estado NOT IN (
            'pendiente',
            'en_curso',
            'completado'
       )
    THEN
        RAISE EXCEPTION
            'El estado del hito no es válido';
    END IF;


    -- --------------------------------------------------------
    -- OBTENER HITO
    -- --------------------------------------------------------

    SELECT *
    INTO v_milestone
    FROM public.project_milestones
    WHERE id = p_milestone_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El hito indicado no existe';
    END IF;


    -- --------------------------------------------------------
    -- ACTUALIZAR ESTADO
    -- --------------------------------------------------------

    UPDATE public.project_milestones
    SET
        estado = p_estado
    WHERE id = p_milestone_id
    RETURNING *
    INTO v_milestone;


    RETURN v_milestone;

END;
$$;


ALTER FUNCTION "public"."set_project_milestone_status"("p_milestone_id" "uuid", "p_estado" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_project_task_visibility"("p_task_id" "uuid", "p_worker_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_role_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_count INTEGER := 0;
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión';
    END IF;

    IF NOT public.current_worker_is_direction() THEN
        RAISE EXCEPTION
            'Solo Dirección puede configurar la visibilidad de las tareas';
    END IF;

    IF p_task_id IS NULL THEN
        RAISE EXCEPTION 'La tarea es obligatoria';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.project_tasks
        WHERE id = p_task_id
    ) THEN
        RAISE EXCEPTION 'Tarea no encontrada';
    END IF;

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:visibility:' || auth.uid()::TEXT,
        60,
        600
    );

    -- Validar workers antes de modificar nada.
    IF EXISTS (
        SELECT 1
        FROM unnest(COALESCE(p_worker_ids, ARRAY[]::UUID[])) AS x(id)
        WHERE NOT EXISTS (
            SELECT 1
            FROM public.workers w
            WHERE w.id = x.id
              AND w.is_active = TRUE
        )
    ) THEN
        RAISE EXCEPTION
            'La visibilidad contiene un trabajador inexistente o inactivo';
    END IF;

    -- Validar roles antes de modificar nada.
    IF EXISTS (
        SELECT 1
        FROM unnest(COALESCE(p_role_ids, ARRAY[]::UUID[])) AS x(id)
        WHERE NOT EXISTS (
            SELECT 1
            FROM public.worker_roles wr
            WHERE wr.id = x.id
              AND wr.is_active = TRUE
        )
    ) THEN
        RAISE EXCEPTION
            'La visibilidad contiene un rol inexistente o inactivo';
    END IF;

    -- Reemplazo atómico de la configuración.
    DELETE FROM public.project_task_visibility
    WHERE task_id = p_task_id;

    INSERT INTO public.project_task_visibility (
        task_id,
        worker_id
    )
    SELECT
        p_task_id,
        x.id
    FROM (
        SELECT DISTINCT id
        FROM unnest(COALESCE(p_worker_ids, ARRAY[]::UUID[])) AS u(id)
    ) x;

    INSERT INTO public.project_task_visibility (
        task_id,
        role_id
    )
    SELECT
        p_task_id,
        x.id
    FROM (
        SELECT DISTINCT id
        FROM unnest(COALESCE(p_role_ids, ARRAY[]::UUID[])) AS u(id)
    ) x;

    SELECT COUNT(*)
    INTO v_count
    FROM public.project_task_visibility
    WHERE task_id = p_task_id;

    RETURN v_count;

END;
$$;


ALTER FUNCTION "public"."set_project_task_visibility"("p_task_id" "uuid", "p_worker_ids" "uuid"[], "p_role_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_quotation_document_hash"("p_quotation_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") RETURNS "public"."quotations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_quotation public.quotations;
    v_expected_path TEXT;
    v_hash TEXT;
BEGIN

    PERFORM public.require_current_worker_permission(
        'quotations.update'
    );

    v_hash :=
        LOWER(
            TRIM(
                COALESCE(
                    p_document_sha256,
                    ''
                )
            )
        );

    IF v_hash = '' THEN
        RAISE EXCEPTION
            'El SHA-256 del documento es obligatorio';
    END IF;

    IF v_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION
            'El SHA-256 del documento no es válido';
    END IF;

    SELECT *
    INTO v_quotation
    FROM public.quotations
    WHERE id = p_quotation_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Presupuesto no encontrado';
    END IF;

    v_expected_path :=
        v_quotation.company_id::TEXT
        || '/'
        || v_quotation.numero_presupuesto
        || '.pdf';

    IF p_document_path IS NULL
       OR TRIM(p_document_path) = ''
    THEN
        RAISE EXCEPTION
            'La ruta del documento es obligatoria';
    END IF;

    IF TRIM(p_document_path) <> v_expected_path THEN
        RAISE EXCEPTION
            'La ruta del documento no coincide con el presupuesto';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM storage.objects
        WHERE bucket_id = 'quotations'
          AND name = v_expected_path
    ) THEN
        RAISE EXCEPTION
            'El documento no existe en el bucket de presupuestos';
    END IF;

    IF v_quotation.document_path IS DISTINCT FROM v_expected_path THEN
        RAISE EXCEPTION
            'El documento no está asociado al presupuesto';
    END IF;

    UPDATE public.quotations
    SET
        document_sha256 = v_hash,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = v_quotation.id
    RETURNING *
    INTO v_quotation;

    RETURN v_quotation;

END;
$_$;


ALTER FUNCTION "public"."set_quotation_document_hash"("p_quotation_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_quotation_document_hash"("p_quotation_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") IS 'Establece el SHA-256 del PDF actualmente asociado a un presupuesto. Solo puede ejecutarla un worker activo.';



CREATE TABLE IF NOT EXISTS "public"."quotation_official_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "quotation_id" "uuid" NOT NULL,
    "version_major" integer NOT NULL,
    "version_minor" integer DEFAULT 0 NOT NULL,
    "version_label" "text" NOT NULL,
    "content_snapshot" "jsonb" NOT NULL,
    "document_path" "text",
    "document_sha256" "text",
    "is_current" boolean DEFAULT true NOT NULL,
    "published_by" "uuid" NOT NULL,
    "published_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_notified_at" timestamp with time zone,
    "client_response" "text",
    "responded_by" "uuid",
    "responded_at" timestamp with time zone,
    CONSTRAINT "quotation_official_versions_client_response_check" CHECK ((("client_response" IS NULL) OR ("client_response" = ANY (ARRAY['Aceptado'::"text", 'Rechazado'::"text"])))),
    CONSTRAINT "quotation_official_versions_content_snapshot_check" CHECK (("jsonb_typeof"("content_snapshot") = 'object'::"text")),
    CONSTRAINT "quotation_official_versions_document_path_check" CHECK ((("document_path" IS NULL) OR ("length"("document_path") <= 500))),
    CONSTRAINT "quotation_official_versions_document_sha256_check" CHECK ((("document_sha256" IS NULL) OR ("document_sha256" ~ '^[0-9a-fA-F]{64}$'::"text"))),
    CONSTRAINT "quotation_official_versions_label_check" CHECK (("version_label" ~ '^V[1-9][0-9]*(\.[1-9][0-9]*)?$'::"text")),
    CONSTRAINT "quotation_official_versions_response_consistency_check" CHECK (((("client_response" IS NULL) AND ("responded_by" IS NULL) AND ("responded_at" IS NULL)) OR (("client_response" IS NOT NULL) AND ("responded_by" IS NOT NULL) AND ("responded_at" IS NOT NULL)))),
    CONSTRAINT "quotation_official_versions_version_major_check" CHECK (("version_major" >= 1)),
    CONSTRAINT "quotation_official_versions_version_minor_check" CHECK (("version_minor" >= 0))
);


ALTER TABLE "public"."quotation_official_versions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_quotation_official_version_document"("p_version_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") RETURNS "public"."quotation_official_versions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_version public.quotation_official_versions%ROWTYPE;
  v_quotation public.quotations%ROWTYPE;
  v_object storage.objects%ROWTYPE;
  v_expected_path text;
BEGIN
  IF public.current_worker_has_permission('quotations.update') THEN
    PERFORM public.require_current_worker_permission('quotations.update');
  ELSE
    PERFORM public.require_current_worker_permission('quotations.create');
  END IF;
  PERFORM public.enforce_security_rate_limit(
    'quotation_workflow:document:' || auth.uid()::text, 20, 3600
  );

  IF p_version_id IS NULL OR p_document_path IS NULL OR btrim(p_document_path) = '' THEN
    RAISE EXCEPTION 'La versión y la ruta del documento son obligatorias';
  END IF;
  IF p_document_sha256 IS NULL OR p_document_sha256 !~* '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'El SHA-256 del documento no es válido';
  END IF;

  SELECT * INTO v_version
  FROM public.quotation_official_versions
  WHERE id = p_version_id
  FOR UPDATE;
  IF NOT FOUND OR NOT v_version.is_current THEN
    RAISE EXCEPTION 'Solo se puede adjuntar el PDF a la versión oficial actual';
  END IF;

  SELECT * INTO v_quotation
  FROM public.quotations
  WHERE id = v_version.quotation_id
  FOR UPDATE;
  IF NOT FOUND OR v_quotation.estado <> 'Pendiente' THEN
    RAISE EXCEPTION 'El presupuesto no está disponible para adjuntar una versión documental';
  END IF;

  v_expected_path := v_quotation.company_id::text || '/' || v_quotation.numero_presupuesto || '/' || v_version.version_label || '.pdf';
  IF p_document_path <> v_expected_path THEN
    RAISE EXCEPTION 'La ruta del PDF no corresponde a la versión oficial indicada';
  END IF;

  SELECT * INTO v_object
  FROM storage.objects
  WHERE bucket_id = 'quotations' AND name = p_document_path;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'El PDF no existe en el bucket quotations';
  END IF;
  IF lower(COALESCE(v_object.metadata->>'mimetype', '')) <> 'application/pdf' THEN
    RAISE EXCEPTION 'El documento debe ser un PDF';
  END IF;
  IF v_object.metadata ? 'size' AND (v_object.metadata->>'size') ~ '^[0-9]+$'
     AND (v_object.metadata->>'size')::bigint > 10485760 THEN
    RAISE EXCEPTION 'El PDF no puede superar 10 MiB';
  END IF;

  IF v_version.document_path IS NOT NULL
     AND (v_version.document_path IS DISTINCT FROM p_document_path
       OR v_version.document_sha256 IS DISTINCT FROM lower(p_document_sha256)) THEN
    RAISE EXCEPTION 'El documento de una versión oficial publicada es inmutable';
  END IF;

  UPDATE public.quotation_official_versions
  SET document_path = p_document_path,
      document_sha256 = lower(p_document_sha256)
  WHERE id = p_version_id
  RETURNING * INTO v_version;

  -- Mantener el documento actual de quotations alineado con la versión publicada.
  UPDATE public.quotations
  SET document_path = p_document_path,
      document_sha256 = lower(p_document_sha256),
      updated_at = now()
  WHERE id = v_quotation.id;

  -- Notificar solo cuando el PDF y su SHA-256 ya están registrados.
  -- client_notified_at evita duplicados si la Edge Function reintenta.
  IF v_version.client_notified_at IS NULL THEN
    PERFORM public.emit_project_client_notification(
      v_quotation.project_id,
      'quotation',
      'Nuevo presupuesto disponible',
      'Se ha publicado la versión ' || v_version.version_label || ' del presupuesto ' || COALESCE(v_quotation.numero_presupuesto, '') || '.',
      jsonb_build_object(
        'event', 'quotation_published',
        'quotation_id', v_quotation.id,
        'version_id', v_version.id,
        'version_label', v_version.version_label
      )
    );
    UPDATE public.quotation_official_versions
    SET client_notified_at = now()
    WHERE id = v_version.id
    RETURNING * INTO v_version;
  END IF;

  RETURN v_version;
END;
$_$;


ALTER FUNCTION "public"."set_quotation_official_version_document"("p_version_id" "uuid", "p_document_path" "text", "p_document_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_recurring_expense_template_status"("p_template_id" "uuid", "p_status" "text") RETURNS "public"."recurring_expense_templates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_template public.recurring_expense_templates;
BEGIN
  PERFORM public.require_expense_permission('expenses.recurring.update');
  PERFORM public.consume_expense_worker_rate_limit('expenses:recurring_status');

  IF p_status NOT IN ('active','paused','cancelled') THEN
    RAISE EXCEPTION 'Estado de recurrencia no válido';
  END IF;

  UPDATE public.recurring_expense_templates
  SET lifecycle_status = p_status,
      updated_by = auth.uid(),
      updated_at = CURRENT_TIMESTAMP
  WHERE id = p_template_id
  RETURNING * INTO v_template;

  IF NOT FOUND THEN RAISE EXCEPTION 'La configuración recurrente no existe'; END IF;
  RETURN v_template;
END;
$$;


ALTER FUNCTION "public"."set_recurring_expense_template_status"("p_template_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_internal_task"("p_task_id" "uuid") RETURNS "public"."internal_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.internal_tasks;
    v_worker_id UUID;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.update'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:start:' || auth.uid()::TEXT,
        60,
        3600
    );


    v_worker_id := public.internal_task_current_worker_id();


    SELECT *
    INTO v_task
    FROM public.internal_tasks
    WHERE id = p_task_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tarea no existe';
    END IF;


    IF v_task.assigned_to_worker_id IS DISTINCT FROM v_worker_id THEN
        RAISE EXCEPTION
            'Solo el trabajador responsable puede iniciar esta tarea';
    END IF;


    IF v_task.status <> 'to_do' THEN
        RAISE EXCEPTION
            'La tarea no está en estado to_do';
    END IF;


    UPDATE public.internal_tasks
    SET
        status = 'in_progress',
        started_at = COALESCE(started_at, CURRENT_TIMESTAMP),
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_task_id
    RETURNING *
    INTO v_task;


    PERFORM public.internal_task_record_update(
        p_task_id,
        v_worker_id,
        'started',
        'to_do',
        v_task.progress,
        'in_progress',
        v_task.progress,
        NULL
    );


    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."start_internal_task"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_project_task"("p_task_id" "uuid") RETURNS "public"."project_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.project_tasks;
    v_worker_id UUID;
BEGIN

    v_worker_id := public.current_project_task_worker_id();

    IF v_worker_id IS NULL THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.update'
    );

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:start:' || auth.uid()::TEXT,
        60,
        3600
    );

    SELECT *
    INTO v_task
    FROM public.project_tasks
    WHERE id = p_task_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Tarea no encontrada';
    END IF;

    IF v_task.assigned_to_worker_id IS DISTINCT FROM v_worker_id THEN
        RAISE EXCEPTION
            'Solo el trabajador asignado puede iniciar la tarea';
    END IF;

    IF v_task.status <> 'to_do' THEN
        RAISE EXCEPTION
            'La tarea no está pendiente de inicio';
    END IF;

    UPDATE public.project_tasks
    SET
        status = 'in_progress',
        started_at = COALESCE(started_at, CURRENT_TIMESTAMP)
    WHERE id = v_task.id
    RETURNING *
    INTO v_task;

    PERFORM public.record_project_task_update(
        v_task.id,
        'started',
        'to_do',
        v_task.progress,
        v_task.status,
        v_task.progress,
        NULL
    );

    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."start_project_task"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_quotation_workflow_draft"("p_project_id" "uuid", "p_quotation_id" "uuid" DEFAULT NULL::"uuid", "p_draft_kind" "text" DEFAULT 'initial'::"text") RETURNS "public"."quotation_workflow_drafts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_project public.projects%ROWTYPE;
  v_quotation public.quotations%ROWTYPE;
  v_state public.quotation_workflow_state%ROWTYPE;
  v_version public.quotation_official_versions%ROWTYPE;
  v_draft public.quotation_workflow_drafts%ROWTYPE;
  v_content jsonb;
  v_permission text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.current_user_is_worker() THEN
    RAISE EXCEPTION 'Acceso denegado: se requiere un trabajador autenticado';
  END IF;

  IF p_draft_kind IS NULL OR p_draft_kind NOT IN ('initial', 'correction', 'requested_change') THEN
    RAISE EXCEPTION 'Tipo de borrador no válido';
  END IF;

  IF p_draft_kind = 'initial' THEN
    IF p_quotation_id IS NOT NULL OR p_project_id IS NULL THEN
      RAISE EXCEPTION 'Un borrador inicial requiere proyecto y no puede tener presupuesto publicado';
    END IF;
    v_permission := 'quotations.create';
  ELSE
    IF p_quotation_id IS NULL THEN
      RAISE EXCEPTION 'La revisión requiere un presupuesto existente';
    END IF;
    v_permission := 'quotations.update';
  END IF;
  PERFORM public.require_current_worker_permission(v_permission);

  PERFORM public.enforce_security_rate_limit(
    'quotation_draft:start:' || auth.uid()::text, 20, 3600
  );

  IF p_draft_kind = 'initial' THEN
    SELECT * INTO v_project
    FROM public.projects
    WHERE id = p_project_id
    FOR SHARE;

    IF NOT FOUND OR v_project.company_id IS NULL OR v_project.user_id IS NULL THEN
      RAISE EXCEPTION 'El proyecto no existe o no tiene empresa/cliente válido';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = v_project.user_id) THEN
      RAISE EXCEPTION 'El cliente del proyecto no existe';
    END IF;

    v_content := public.validate_quotation_workflow_content('{}'::jsonb);
  ELSE
    SELECT * INTO v_quotation
    FROM public.quotations
    WHERE id = p_quotation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Presupuesto no encontrado';
    END IF;

    IF p_project_id IS NOT NULL AND p_project_id <> v_quotation.project_id THEN
      RAISE EXCEPTION 'El proyecto no corresponde al presupuesto';
    END IF;

    SELECT * INTO v_project
    FROM public.projects
    WHERE id = v_quotation.project_id
    FOR SHARE;
    IF NOT FOUND OR v_project.company_id IS DISTINCT FROM v_quotation.company_id THEN
      RAISE EXCEPTION 'El proyecto no corresponde a la empresa del presupuesto';
    END IF;

    SELECT * INTO v_state
    FROM public.quotation_workflow_state
    WHERE quotation_id = p_quotation_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'El presupuesto todavía no utiliza el nuevo flujo de versiones';
    END IF;

    IF p_draft_kind = 'correction' AND v_state.workflow_status <> 'presented' THEN
      RAISE EXCEPTION 'Solo se puede preparar una corrección antes de la respuesta del cliente';
    END IF;
    IF p_draft_kind = 'requested_change' AND v_state.workflow_status <> 'in_review' THEN
      RAISE EXCEPTION 'No existe una solicitud de cambio pendiente de atender';
    END IF;

    SELECT * INTO v_version
    FROM public.quotation_official_versions
    WHERE id = v_state.current_version_id AND quotation_id = p_quotation_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'No se encuentra la versión oficial actual';
    END IF;

    v_content := public.validate_quotation_workflow_content(
      jsonb_build_object(
        'titulo', COALESCE(v_version.content_snapshot->'titulo', '""'::jsonb),
        'descripcion_detallada', COALESCE(v_version.content_snapshot->'descripcion_detallada', 'null'::jsonb),
        'servicios_incluidos', COALESCE(v_version.content_snapshot->'servicios_incluidos', '[]'::jsonb),
        'iva_porcentaje', COALESCE(v_version.content_snapshot->'iva_porcentaje', '21'::jsonb),
        'irpf_aplicado', COALESCE(v_version.content_snapshot->'irpf_aplicado', 'false'::jsonb),
        'irpf_porcentaje', COALESCE(v_version.content_snapshot->'irpf_porcentaje', '0'::jsonb),
        'fecha_validez', COALESCE(v_version.content_snapshot->'fecha_validez', 'null'::jsonb),
        'notas', COALESCE(v_version.content_snapshot->'notas', 'null'::jsonb)
      )
    );
  END IF;

  IF p_quotation_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.quotation_workflow_drafts d
    WHERE d.quotation_id = p_quotation_id AND d.draft_status = 'draft'
  ) THEN
    RAISE EXCEPTION 'Ya existe un borrador activo para este presupuesto; recupera ese borrador';
  END IF;

  INSERT INTO public.quotation_workflow_drafts (
    company_id, project_id, quotation_id, created_by, draft_kind,
    draft_status, content, based_on_version_id
  )
  VALUES (
    v_project.company_id, v_project.id, p_quotation_id, auth.uid(), p_draft_kind,
    'draft', v_content, CASE WHEN p_quotation_id IS NOT NULL THEN v_version.id ELSE NULL END
  )
  RETURNING * INTO v_draft;

  RETURN v_draft;
END;
$$;


ALTER FUNCTION "public"."start_quotation_workflow_draft"("p_project_id" "uuid", "p_quotation_id" "uuid", "p_draft_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_audit_request"("p_nombre" "text", "p_email" "text", "p_empresa" "text", "p_empleados" "text", "p_proceso" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RAISE EXCEPTION
        'La solicitud de auditoría requiere confirmación de la información de privacidad y de las condiciones de la auditoría gratuita';
END;
$$;


ALTER FUNCTION "public"."submit_audit_request"("p_nombre" "text", "p_email" "text", "p_empresa" "text", "p_empleados" "text", "p_proceso" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_audit_request"("p_nombre" "text", "p_email" "text", "p_empresa" "text", "p_empleados" "text", "p_proceso" "text") IS 'Firma legacy deliberadamente bloqueada: la solicitud de auditoría requiere las confirmaciones legales de la nueva firma.';



CREATE OR REPLACE FUNCTION "public"."submit_audit_request"("p_nombre" "text", "p_email" "text", "p_empresa" "text", "p_empleados" "text", "p_proceso" "text", "p_privacy_acknowledged" boolean, "p_audit_terms_accepted" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_nombre TEXT;
    v_email TEXT;
    v_empresa TEXT;
    v_empleados TEXT;
    v_proceso TEXT;

    v_headers JSONB := '{}'::JSONB;

    v_ip TEXT;
    v_identity_key TEXT;

    v_window_started_at TIMESTAMPTZ;
    v_request_count INTEGER;

    v_now TIMESTAMPTZ := clock_timestamp();

    v_request_id UUID;

    v_privacy_id UUID;
    v_privacy_hash TEXT;

    v_audit_terms_id UUID;
    v_audit_terms_hash TEXT;
BEGIN

    -- --------------------------------------------------------
    -- 1. VALIDACIÓN DE ENTRADA
    -- --------------------------------------------------------

    v_nombre := NULLIF(TRIM(p_nombre), '');
    v_email := NULLIF(TRIM(p_email), '');
    v_empresa := NULLIF(TRIM(p_empresa), '');
    v_empleados := NULLIF(TRIM(p_empleados), '');
    v_proceso := NULLIF(TRIM(p_proceso), '');

    IF v_nombre IS NULL
       OR LENGTH(v_nombre) > 200
    THEN
        RAISE EXCEPTION
            'Datos de la solicitud no válidos.';
    END IF;

    IF v_email IS NULL
       OR LENGTH(v_email) > 320
       OR v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
    THEN
        RAISE EXCEPTION
            'Datos de la solicitud no válidos.';
    END IF;

    IF v_empresa IS NULL
       OR LENGTH(v_empresa) > 200
    THEN
        RAISE EXCEPTION
            'Datos de la solicitud no válidos.';
    END IF;

    IF v_empleados IS NULL
       OR LENGTH(v_empleados) > 50
    THEN
        RAISE EXCEPTION
            'Datos de la solicitud no válidos.';
    END IF;

    IF v_proceso IS NULL
       OR LENGTH(v_proceso) > 4000
    THEN
        RAISE EXCEPTION
            'Datos de la solicitud no válidos.';
    END IF;


    -- --------------------------------------------------------
    -- 2. LAS CASILLAS SON OBLIGATORIAS
    -- --------------------------------------------------------

    IF COALESCE(
        p_privacy_acknowledged,
        FALSE
    ) <> TRUE
    THEN
        RAISE EXCEPTION
            'Debes confirmar que has sido informado/a sobre el tratamiento de tus datos';
    END IF;

    IF COALESCE(
        p_audit_terms_accepted,
        FALSE
    ) <> TRUE
    THEN
        RAISE EXCEPTION
            'Debes aceptar las condiciones de la auditoría gratuita';
    END IF;


    -- --------------------------------------------------------
    -- 3. DOCUMENTO DE PRIVACIDAD VIGENTE
    -- --------------------------------------------------------

    SELECT
        id,
        content_hash
    INTO
        v_privacy_id,
        v_privacy_hash
    FROM public.legal_documents
    WHERE document_type = 'privacy_information'
      AND is_current = TRUE
      AND effective_from <= clock_timestamp()
      AND (
          effective_until IS NULL
          OR effective_until > clock_timestamp()
      )
    ORDER BY
        effective_from DESC,
        created_at DESC
    LIMIT 1;

    IF v_privacy_id IS NULL THEN
        RAISE EXCEPTION
            'No existe Información de Privacidad vigente';
    END IF;


    -- --------------------------------------------------------
    -- 4. DOCUMENTO DE CONDICIONES DE AUDITORÍA VIGENTE
    -- --------------------------------------------------------

    SELECT
        id,
        content_hash
    INTO
        v_audit_terms_id,
        v_audit_terms_hash
    FROM public.legal_documents
    WHERE document_type = 'audit_terms'
      AND is_current = TRUE
      AND effective_from <= clock_timestamp()
      AND (
          effective_until IS NULL
          OR effective_until > clock_timestamp()
      )
    ORDER BY
        effective_from DESC,
        created_at DESC
    LIMIT 1;

    IF v_audit_terms_id IS NULL THEN
        RAISE EXCEPTION
            'No existen Condiciones de la Auditoría Gratuita vigentes';
    END IF;


    -- --------------------------------------------------------
    -- 5. CABECERAS OBSERVADAS POR EL BACKEND
    -- --------------------------------------------------------

    BEGIN
        v_headers := COALESCE(
            NULLIF(
                current_setting(
                    'request.headers',
                    TRUE
                ),
                ''
            )::JSONB,
            '{}'::JSONB
        );
    EXCEPTION WHEN OTHERS THEN
        v_headers := '{}'::JSONB;
    END;

    v_ip :=
        COALESCE(
            NULLIF(
                TRIM(
                    v_headers->>'cf-connecting-ip'
                ),
                ''
            ),
            NULLIF(
                TRIM(
                    v_headers->>'x-real-ip'
                ),
                ''
            ),
            NULLIF(
                TRIM(
                    SPLIT_PART(
                        COALESCE(
                            v_headers->>'x-forwarded-for',
                            ''
                        ),
                        ',',
                        1
                    )
                ),
                ''
            ),
            'unknown'
        );


    -- --------------------------------------------------------
    -- 6. IDENTIDAD DERIVADA DE LA IP OBSERVADA
    -- --------------------------------------------------------

    v_identity_key :=
        'audit:' ||
        encode(
            extensions.digest(
                convert_to(v_ip, 'UTF8'),
                'sha256'
            ),
            'hex'
        );


    -- --------------------------------------------------------
    -- 7. RATE LIMIT: 3 SOLICITUDES / HORA / IDENTIDAD
    -- --------------------------------------------------------

    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            v_identity_key,
            28
        )
    );

    SELECT
        window_started_at,
        request_count
    INTO
        v_window_started_at,
        v_request_count
    FROM public.public_form_rate_limits
    WHERE identity_key = v_identity_key
      AND form_key = 'audit_request'
    FOR UPDATE;

    IF NOT FOUND THEN

        INSERT INTO public.public_form_rate_limits (
            identity_key,
            form_key,
            window_started_at,
            request_count
        )
        VALUES (
            v_identity_key,
            'audit_request',
            v_now,
            1
        );

    ELSE

        IF EXTRACT(
            EPOCH FROM (
                v_now - v_window_started_at
            )
        ) >= 3600
        THEN

            UPDATE public.public_form_rate_limits
            SET
                window_started_at = v_now,
                request_count = 1,
                updated_at = v_now
            WHERE identity_key = v_identity_key
              AND form_key = 'audit_request';

        ELSIF v_request_count >= 3 THEN

            RAISE EXCEPTION
                'Demasiadas solicitudes. Por favor, inténtalo de nuevo más tarde.';

        ELSE

            UPDATE public.public_form_rate_limits
            SET
                request_count = request_count + 1,
                updated_at = v_now
            WHERE identity_key = v_identity_key
              AND form_key = 'audit_request';

        END IF;

    END IF;


    -- --------------------------------------------------------
    -- 8. INSERTAR SOLICITUD
    -- --------------------------------------------------------

    INSERT INTO public.audit_requests (
        nombre,
        email,
        empresa,
        empleados,
        proceso,
        estado
    )
    VALUES (
        v_nombre,
        v_email,
        v_empresa,
        v_empleados,
        v_proceso,
        'nuevo'
    )
    RETURNING id
    INTO v_request_id;


    -- --------------------------------------------------------
    -- 9. REGISTRAR PRIVACIDAD
    -- --------------------------------------------------------

    INSERT INTO public.legal_acceptances (
        user_id,
        company_id,
        document_id,
        action_type,
        accepted_at,
        ip,
        user_agent,
        context,
        source,
        document_hash,
        identity_key,
        metadata
    )
    VALUES (
        auth.uid(),
        NULL,
        v_privacy_id,
        'acknowledged',
        v_now,
        NULLIF(v_ip, 'unknown'),
        NULLIF(
            LEFT(
                TRIM(
                    COALESCE(
                        v_headers->>'user-agent',
                        ''
                    )
                ),
                2000
            ),
            ''
        ),
        'audit_request',
        'public_form',
        v_privacy_hash,
        v_identity_key,
        jsonb_build_object(
            'audit_request_id',
            v_request_id
        )
    );


    -- --------------------------------------------------------
    -- 10. REGISTRAR CONDICIONES DE AUDITORÍA
    -- --------------------------------------------------------

    INSERT INTO public.legal_acceptances (
        user_id,
        company_id,
        document_id,
        action_type,
        accepted_at,
        ip,
        user_agent,
        context,
        source,
        document_hash,
        identity_key,
        metadata
    )
    VALUES (
        auth.uid(),
        NULL,
        v_audit_terms_id,
        'accepted',
        v_now,
        NULLIF(v_ip, 'unknown'),
        NULLIF(
            LEFT(
                TRIM(
                    COALESCE(
                        v_headers->>'user-agent',
                        ''
                    )
                ),
                2000
            ),
            ''
        ),
        'audit_request',
        'public_form',
        v_audit_terms_hash,
        v_identity_key,
        jsonb_build_object(
            'audit_request_id',
            v_request_id
        )
    );


    RETURN v_request_id;

END;
$_$;


ALTER FUNCTION "public"."submit_audit_request"("p_nombre" "text", "p_email" "text", "p_empresa" "text", "p_empleados" "text", "p_proceso" "text", "p_privacy_acknowledged" boolean, "p_audit_terms_accepted" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_audit_request"("p_nombre" "text", "p_email" "text", "p_empresa" "text", "p_empleados" "text", "p_proceso" "text", "p_privacy_acknowledged" boolean, "p_audit_terms_accepted" boolean) IS 'Solicitud pública de auditoría gratuita con confirmación obligatoria de Información de Privacidad y Condiciones de la Auditoría Gratuita. Mantiene el rate limit de 028 y registra las evidencias legales versionadas.';



CREATE OR REPLACE FUNCTION "public"."submit_custom_maintenance_proposal"("p_proposal_id" "uuid") RETURNS "public"."maintenance_custom_proposals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_proposal public.maintenance_custom_proposals;

BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Debes iniciar sesión';
    END IF;


    SELECT *
    INTO v_proposal
    FROM public.maintenance_custom_proposals
    WHERE id = p_proposal_id
      AND user_id = auth.uid()
      AND company_id = public.current_user_company_id()
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La propuesta no existe o no tienes acceso a ella';
    END IF;


    IF v_proposal.status <> 'draft' THEN
        RAISE EXCEPTION
            'La propuesta no se encuentra en estado borrador';
    END IF;


    UPDATE public.maintenance_custom_proposals
    SET
        status = 'submitted',
        submitted_at = CURRENT_TIMESTAMP,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = v_proposal.id
    RETURNING *
    INTO v_proposal;


    RETURN v_proposal;

END;
$$;


ALTER FUNCTION "public"."submit_custom_maintenance_proposal"("p_proposal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_expense_for_review"("p_expense_id" "uuid") RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_expense public.expenses;
  v_new_status text;
BEGIN
  PERFORM public.require_expense_permission('expenses.update');
  PERFORM public.consume_expense_worker_rate_limit('expenses:submit_review');

  SELECT *
    INTO v_expense
  FROM public.expenses
  WHERE id = p_expense_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'El gasto % no existe', p_expense_id;
  END IF;

  -- Aceptar draft y pending_review permite normalizar el estado que haya
  -- asignado create_expense antes de aplicar la regla de Dirección.
  IF v_expense.status NOT IN ('draft', 'pending_review') THEN
    RAISE EXCEPTION
      'Solo se pueden registrar gastos en estado draft o pending_review';
  END IF;

  IF v_expense.total_amount <= 0 THEN
    RAISE EXCEPTION 'El gasto debe tener un importe total superior a 0';
  END IF;

  v_new_status := CASE
    WHEN public.expense_requires_approval(
      v_expense.total_amount,
      v_expense.category_id
    )
      THEN 'pending_review'
    ELSE 'pending_payment'
  END;

  UPDATE public.expenses
  SET status = v_new_status,
      updated_by = auth.uid(),
      updated_at = CURRENT_TIMESTAMP
  WHERE id = p_expense_id
  RETURNING * INTO v_expense;

  RETURN v_expense;
END;
$$;


ALTER FUNCTION "public"."submit_expense_for_review"("p_expense_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_internal_task_for_review"("p_task_id" "uuid", "p_comment" "text" DEFAULT NULL::"text") RETURNS "public"."internal_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.internal_tasks;
    v_worker_id UUID;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.update'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:submit_review:' || auth.uid()::TEXT,
        30,
        3600
    );


    v_worker_id := public.internal_task_current_worker_id();


    SELECT *
    INTO v_task
    FROM public.internal_tasks
    WHERE id = p_task_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tarea no existe';
    END IF;


    IF v_task.assigned_to_worker_id IS DISTINCT FROM v_worker_id THEN
        RAISE EXCEPTION
            'Solo el trabajador responsable puede enviar la tarea a revisión';
    END IF;


    IF v_task.status <> 'in_progress' THEN
        RAISE EXCEPTION
            'Solo una tarea en progreso puede enviarse a revisión';
    END IF;


    IF v_task.progress <> 100 THEN
        RAISE EXCEPTION
            'Una tarea debe estar al 100%% antes de enviarse a revisión';
    END IF;


    UPDATE public.internal_tasks
    SET
        status = 'pending_review',
        progress = 100,
        submitted_for_review_at = CURRENT_TIMESTAMP,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_task_id
    RETURNING *
    INTO v_task;


    PERFORM public.internal_task_record_update(
        p_task_id,
        v_worker_id,
        'submitted_for_review',
        'in_progress',
        100,
        'pending_review',
        100,
        p_comment
    );


    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."submit_internal_task_for_review"("p_task_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_project_task_for_review"("p_task_id" "uuid", "p_comment" "text" DEFAULT NULL::"text") RETURNS "public"."project_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.project_tasks;
    v_worker_id UUID;
    v_comment TEXT;
BEGIN

    v_worker_id := public.current_project_task_worker_id();

    IF v_worker_id IS NULL THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.update'
    );

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:submit_review:' || auth.uid()::TEXT,
        30,
        3600
    );

    v_comment := NULLIF(BTRIM(p_comment), '');

    IF v_comment IS NOT NULL
       AND LENGTH(v_comment) > 5000
    THEN
        RAISE EXCEPTION
            'El comentario no puede superar 5000 caracteres';
    END IF;

    SELECT *
    INTO v_task
    FROM public.project_tasks
    WHERE id = p_task_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Tarea no encontrada';
    END IF;

    IF v_task.assigned_to_worker_id IS DISTINCT FROM v_worker_id THEN
        RAISE EXCEPTION
            'Solo el trabajador asignado puede enviar la tarea a revisión';
    END IF;

    IF v_task.status <> 'in_progress' THEN
        RAISE EXCEPTION
            'La tarea debe estar en curso para enviarla a revisión';
    END IF;

    IF v_task.progress <> 100 THEN
        RAISE EXCEPTION
            'La tarea debe tener un progreso del 100%% antes de enviarla a revisión';
    END IF;

    UPDATE public.project_tasks
    SET
        status = 'pending_review',
        progress = 100,
        submitted_for_review_at = CURRENT_TIMESTAMP
    WHERE id = v_task.id
    RETURNING *
    INTO v_task;

    PERFORM public.record_project_task_update(
        v_task.id,
        'submitted_for_review',
        'in_progress',
        100,
        v_task.status,
        v_task.progress,
        v_comment
    );

    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."submit_project_task_for_review"("p_task_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_automatic_expense_payment_amount"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.total_amount IS DISTINCT FROM OLD.total_amount THEN
    IF NEW.total_amount > 0 THEN
      UPDATE public.expense_payments
      SET amount = ROUND(NEW.total_amount, 2)
      WHERE expense_id = NEW.id
        AND is_automatic = true
        AND status = 'pending';
    END IF;

    PERFORM public.sync_expense_payment_status(NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_automatic_expense_payment_amount"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_expense_allocation_percentages"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

  IF NEW.total_amount IS DISTINCT FROM OLD.total_amount THEN

    PERFORM public.refresh_expense_allocation_percentages(
      NEW.id
    );

  END IF;


  RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."sync_expense_allocation_percentages"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_expense_amounts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

  NEW.subtotal :=
    ROUND(
      GREATEST(
        COALESCE(NEW.subtotal, 0),
        0
      ),
      2
    );


  NEW.total_tax :=
    ROUND(
      GREATEST(
        COALESCE(NEW.total_tax, 0),
        0
      ),
      2
    );


  NEW.total_withholding :=
    ROUND(
      GREATEST(
        COALESCE(NEW.total_withholding, 0),
        0
      ),
      2
    );


  NEW.total_amount :=
    ROUND(
      GREATEST(
        NEW.subtotal
        + NEW.total_tax
        - NEW.total_withholding,
        0
      ),
      2
    );


  RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."sync_expense_amounts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_expense_payment_status"("p_expense_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_total_amount NUMERIC(14,2);

  v_paid_amount NUMERIC(14,2);

  v_current_status TEXT;

  v_new_status TEXT;

BEGIN

  IF p_expense_id IS NULL THEN

    RAISE EXCEPTION
      'sync_expense_payment_status: expense_id es obligatorio';

  END IF;


  SELECT
    total_amount,
    status

  INTO
    v_total_amount,
    v_current_status

  FROM public.expenses

  WHERE id = p_expense_id

  FOR UPDATE;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'sync_expense_payment_status: el gasto % no existe',
      p_expense_id;

  END IF;


  v_total_amount :=
    ROUND(
      GREATEST(
        COALESCE(v_total_amount, 0),
        0
      ),
      2
    );


  v_paid_amount :=
    public.get_expense_paid_amount(
      p_expense_id
    );


  -- ----------------------------------------------------------
  -- No tocar estados que todavía no pertenecen al ciclo
  -- de pago.
  -- ----------------------------------------------------------

  IF v_current_status IN (
    'draft',
    'pending_review',
    'rejected',
    'cancelled'
  ) THEN

    RETURN;

  END IF;


  -- ----------------------------------------------------------
  -- Si el gasto no tiene importe:
  -- no se considera automáticamente pagado.
  -- ----------------------------------------------------------

  IF v_total_amount <= 0 THEN

    RETURN;

  END IF;


  -- ----------------------------------------------------------
  -- Determinar nuevo estado
  -- ----------------------------------------------------------

  IF v_paid_amount >= v_total_amount THEN

    v_new_status := 'paid';

  ELSIF v_paid_amount > 0 THEN

    v_new_status := 'partially_paid';

  ELSE

    v_new_status := 'pending_payment';

  END IF;


  -- ----------------------------------------------------------
  -- Actualizar solamente si ha cambiado
  -- ----------------------------------------------------------

  IF v_current_status IS DISTINCT FROM v_new_status THEN

    UPDATE public.expenses

    SET
      status = v_new_status,
      updated_at = CURRENT_TIMESTAMP

    WHERE id = p_expense_id;

  END IF;

END;
$$;


ALTER FUNCTION "public"."sync_expense_payment_status"("p_expense_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_expense_status_from_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
