  v_expense_id UUID;

BEGIN

  IF TG_OP = 'DELETE' THEN

    v_expense_id := OLD.expense_id;

  ELSE

    v_expense_id := NEW.expense_id;

  END IF;


  PERFORM public.sync_expense_payment_status(
    v_expense_id
  );


  RETURN COALESCE(NEW, OLD);

END;
$$;


