CREATE OR REPLACE FUNCTION "public"."sync_invoice_amounts"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    -- ========================================================
    -- 1. NORMALIZAR BASE
    -- ========================================================

    NEW.subtotal := ROUND(
        COALESCE(NEW.subtotal, 0),
        2
    );

    IF NEW.subtotal < 0 THEN
        RAISE EXCEPTION
            'La base imponible no puede ser negativa';
    END IF;


    -- ========================================================
    -- 2. CALCULAR IVA
    -- ========================================================

    IF COALESCE(NEW.iva_aplicado, FALSE) = FALSE THEN

        NEW.iva_porcentaje := 0;
        NEW.iva_importe := 0;

    ELSE

        NEW.iva_porcentaje := ROUND(
            COALESCE(NEW.iva_porcentaje, 0),
            2
        );

        IF NEW.iva_porcentaje < 0
           OR NEW.iva_porcentaje > 100
        THEN
            RAISE EXCEPTION
                'El porcentaje de IVA debe estar entre 0 y 100';
        END IF;

        NEW.iva_importe := ROUND(
            NEW.subtotal * NEW.iva_porcentaje / 100,
            2
        );

    END IF;


    -- ========================================================
    -- 3. CALCULAR TOTAL BRUTO
    -- ========================================================

    NEW.monto := ROUND(
        NEW.subtotal + NEW.iva_importe,
        2
    );


    -- ========================================================
    -- 4. CALCULAR IRPF
    -- ========================================================

    IF COALESCE(NEW.irpf_aplicado, FALSE) = FALSE THEN

        NEW.irpf_porcentaje := 0;
        NEW.irpf_importe := 0;

    ELSE

        NEW.irpf_porcentaje := ROUND(
            COALESCE(NEW.irpf_porcentaje, 0),
            2
        );

        IF NEW.irpf_porcentaje <= 0
           OR NEW.irpf_porcentaje > 100
        THEN
            RAISE EXCEPTION
                'El porcentaje de IRPF debe ser mayor que 0 y menor o igual que 100';
        END IF;

        NEW.irpf_importe := ROUND(
            NEW.subtotal * NEW.irpf_porcentaje / 100,
            2
        );

    END IF;


    -- ========================================================
    -- 5. CALCULAR IMPORTE REAL A PAGAR
    -- ========================================================

    NEW.importe_a_pagar := ROUND(
        GREATEST(
            NEW.monto - NEW.irpf_importe,
            0
        ),
        2
    );


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."sync_invoice_amounts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_invoice_company_on_profile_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    -- --------------------------------------------------------
    -- Solo nos interesa cuando el cliente obtiene una empresa.
    --
    -- NULL → empresa
    --
    -- También permitimos que la lógica sea idempotente:
    -- si ya tenía una empresa, solamente se actualizarán
    -- facturas que todavía estén NULL.
    -- --------------------------------------------------------

    IF NEW.company_id IS NOT NULL THEN

        UPDATE public.invoices
        SET
            company_id = NEW.company_id,
            updated_at = CURRENT_TIMESTAMP
        WHERE user_id = NEW.id
          AND company_id IS NULL;

    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."sync_invoice_company_on_profile_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_legal_document_hash"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF NEW.content IS NULL
       OR btrim(NEW.content) = ''
    THEN
        RAISE EXCEPTION
            'El contenido del documento legal es obligatorio';
    END IF;

    NEW.content_hash :=
        encode(
            extensions.digest(
                convert_to(NEW.content, 'UTF8'),
                'sha256'
            ),
            'hex'
        );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_legal_document_hash"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_profile_to_client"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_client_id UUID;
BEGIN

    -- --------------------------------------------------------
    -- Solo sincronizamos usuarios normales.
    --
    -- Los workers de Modira no deben convertirse
    -- automáticamente en clientes.
    -- --------------------------------------------------------

    IF NEW.rol <> 'user' THEN
        RETURN NEW;
    END IF;


    -- --------------------------------------------------------
    -- Si el perfil todavía no tiene empresa asociada,
    -- no podemos crear un cliente dentro de una empresa.
    -- --------------------------------------------------------

    IF NEW.company_id IS NULL THEN
        RETURN NEW;
    END IF;


    -- --------------------------------------------------------
    -- 1. Buscar primero un cliente ya vinculado directamente
    --    al perfil.
    -- --------------------------------------------------------

    SELECT c.id
    INTO v_client_id
    FROM public.clients c
    WHERE c.profile_id = NEW.id
    LIMIT 1;


    -- --------------------------------------------------------
    -- 2. Si todavía no existe vínculo, intentar encontrar un
    --    cliente existente por empresa + email.
    --
    --    Esto evita crear duplicados para usuarios/clientes que
    --    ya existían antes de ejecutar esta migración.
    -- --------------------------------------------------------

    IF v_client_id IS NULL
       AND NEW.email IS NOT NULL
    THEN

        SELECT c.id
        INTO v_client_id
        FROM public.clients c
        WHERE c.company_id = NEW.company_id
          AND c.profile_id IS NULL
          AND c.email IS NOT NULL
          AND LOWER(TRIM(c.email)) = LOWER(TRIM(NEW.email))
        ORDER BY c.created_at ASC
        LIMIT 1;

    END IF;


    -- --------------------------------------------------------
    -- 3. Si encontramos un cliente existente, vincularlo y
    --    actualizar únicamente los datos procedentes del
    --    perfil.
    --
    --    NO modificamos:
    --      contacto_principal
    --      cif_vat
    --      direccion
    --      codigo_postal
    --      ciudad
    --      provincia
    --      pais
    --      sector
    --      notas
    --      etiquetas
    --      is_active
    --
    --    Esos campos pueden ser gestionados desde la zona
    --    correspondiente de clientes.
    -- --------------------------------------------------------

    IF v_client_id IS NOT NULL THEN

        UPDATE public.clients
        SET
            profile_id = NEW.id,
            company_id = NEW.company_id,
            nombre = NEW.nombre,
            empresa = NEW.empresa,
            email = NEW.email,
            telefono = NEW.telefono,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_client_id;


        RETURN NEW;

    END IF;


    -- --------------------------------------------------------
    -- 4. Si no existe ningún cliente, crearlo.
    -- --------------------------------------------------------

    INSERT INTO public.clients (
        profile_id,
        company_id,
        nombre,
        empresa,
        email,
        telefono,
        is_active
    )
    VALUES (
        NEW.id,
        NEW.company_id,
        NEW.nombre,
        NEW.empresa,
        NEW.email,
        NEW.telefono,
        TRUE
    );


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."sync_profile_to_client"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_profile_to_client"() IS 'Sincroniza automáticamente perfiles de usuarios de Modira con sus clientes asociados.';



CREATE OR REPLACE FUNCTION "public"."sync_project_client_from_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_client_id UUID;
    v_client_count INTEGER;

BEGIN

    -- --------------------------------------------------------
    -- Si no hay propietario todavía, no podemos determinar
    -- el cliente.
    -- --------------------------------------------------------

    IF NEW.user_id IS NULL THEN
        RETURN NEW;
    END IF;


    -- --------------------------------------------------------
    -- El propietario debe pertenecer a la empresa.
    --
    -- Esto queda además protegido por 084.
    -- --------------------------------------------------------

    IF NEW.company_id IS NULL THEN
        RETURN NEW;
    END IF;


    -- --------------------------------------------------------
    -- Buscar el cliente correspondiente al perfil propietario.
    -- --------------------------------------------------------

   SELECT
    COUNT(*)
INTO
    v_client_count
FROM public.clients c
WHERE c.profile_id = NEW.user_id
  AND c.company_id = NEW.company_id;


IF v_client_count = 1 THEN

    SELECT c.id
    INTO v_client_id
    FROM public.clients c
    WHERE c.profile_id = NEW.user_id
      AND c.company_id = NEW.company_id
    LIMIT 1;

    NEW.client_id := v_client_id;

    RETURN NEW;

END IF;


    -- --------------------------------------------------------
    -- Si existe exactamente un cliente correspondiente,
    -- utilizarlo.
    -- --------------------------------------------------------

 


    -- --------------------------------------------------------
    -- Si no existe cliente correspondiente:
    --
    -- No inventamos un client_id.
    --
    -- El proyecto puede existir, pero un presupuesto Pendiente
    -- será rechazado por la protección 059 hasta que exista
    -- una relación cliente válida.
    -- --------------------------------------------------------

    IF v_client_count = 0 THEN

        NEW.client_id := NULL;

        RETURN NEW;

    END IF;


    -- --------------------------------------------------------
    -- Si existen varios clientes para el mismo perfil/empresa,
    -- la relación es ambigua y no debemos elegir uno al azar.
    -- --------------------------------------------------------

    RAISE EXCEPTION
        'El propietario del proyecto tiene varios clientes asociados dentro de la misma empresa';


END;
$$;


ALTER FUNCTION "public"."sync_project_client_from_owner"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_project_milestone_timestamps"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    -- --------------------------------------------------------
    -- UPDATED_AT
    -- --------------------------------------------------------

    NEW.updated_at := CURRENT_TIMESTAMP;


    -- --------------------------------------------------------
    -- COMPLETED_AT
    -- --------------------------------------------------------

    IF NEW.estado = 'completado' THEN

        IF OLD.estado IS DISTINCT FROM 'completado'
           OR NEW.completed_at IS NULL
        THEN
            NEW.completed_at := CURRENT_TIMESTAMP;
        END IF;

    ELSE

        NEW.completed_at := NULL;

    END IF;


    RETURN NEW;

END;
$$;


