CREATE OR REPLACE FUNCTION "public"."sync_quotation_amounts"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_base NUMERIC(12,2);
    v_iva_porcentaje NUMERIC(5,2);
    v_iva_importe NUMERIC(12,2);
    v_irpf_porcentaje NUMERIC(5,2);
BEGIN
    v_base :=
        ROUND(
            GREATEST(COALESCE(NEW.precio_base, 0), 0),
            2
        );

    v_iva_porcentaje :=
        ROUND(
            GREATEST(COALESCE(NEW.iva_porcentaje, 0), 0),
            2
        );

    v_irpf_porcentaje :=
        ROUND(
            GREATEST(
                CASE
                    WHEN COALESCE(NEW.irpf_aplicado, FALSE)
                        THEN COALESCE(NEW.irpf_porcentaje, 0)
                    ELSE 0
                END,
                0
            ),
            2
        );

    v_iva_importe :=
        ROUND(
            v_base * v_iva_porcentaje / 100,
            2
        );

    NEW.precio_base :=
        v_base;

    NEW.iva_porcentaje :=
        v_iva_porcentaje;

    NEW.precio_total :=
        ROUND(
            v_base + v_iva_importe,
            2
        );

    NEW.irpf_porcentaje :=
        v_irpf_porcentaje;

    NEW.irpf_importe :=
        CASE
            WHEN COALESCE(NEW.irpf_aplicado, FALSE)
                THEN ROUND(
                    v_base * v_irpf_porcentaje / 100,
                    2
                )
            ELSE 0
        END;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_quotation_amounts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unassign_maintenance_contract_project"("p_contract_id" "uuid", "p_project_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
  v_company_id UUID;

BEGIN

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF NOT public.current_user_is_active() THEN
    RAISE EXCEPTION 'El usuario no está activo';
  END IF;

  IF public.current_user_is_worker() THEN
    RAISE EXCEPTION
      'Un worker debe utilizar la RPC de gestión de mantenimiento';
  END IF;


  SELECT company_id
  INTO v_company_id
  FROM public.maintenance_contracts
  WHERE id = p_contract_id;

  IF v_company_id IS NULL THEN
    RAISE EXCEPTION
      'El contrato de mantenimiento no existe';
  END IF;

  IF v_company_id IS DISTINCT FROM public.current_user_company_id() THEN
    RAISE EXCEPTION
      'El contrato no pertenece a la empresa del usuario actual';
  END IF;


  DELETE FROM public.maintenance_contract_projects
  WHERE maintenance_contract_id = p_contract_id
    AND project_id = p_project_id;

  RETURN FOUND;

END;
$$;


ALTER FUNCTION "public"."unassign_maintenance_contract_project"("p_contract_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."unassign_maintenance_contract_project"("p_contract_id" "uuid", "p_project_id" "uuid") IS 'Permite al cliente activo retirar una asociación proyecto-contrato de su empresa.';



CREATE OR REPLACE FUNCTION "public"."update_audit_request"("p_request_id" "uuid", "p_estado" "text", "p_notas_internas" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_request public.audit_requests%ROWTYPE;
BEGIN
    -- Autenticación obligatoria.
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required'
            USING ERRCODE = '42501';
    END IF;

    -- Debe ser un trabajador.
    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION 'Worker access required'
            USING ERRCODE = '42501';
    END IF;

    -- El permiso se comprueba en el servidor.
    IF NOT public.current_worker_has_permission(
        'system.audit.update'
    ) THEN
        RAISE EXCEPTION 'Missing permission: system.audit.update'
            USING ERRCODE = '42501';
    END IF;

    -- Identificador obligatorio.
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION 'Request ID is required'
            USING ERRCODE = '22023';
    END IF;

    -- Solo se admiten los cinco estados acordados.
    IF p_estado IS NULL
       OR p_estado NOT IN (
           'nuevo',
           'en_revision',
           'en_seguimiento',
           'completado',
           'descartado'
       ) THEN
        RAISE EXCEPTION 'Invalid audit request status'
            USING ERRCODE = '22023';
    END IF;

    -- Límite de tamaño de las notas internas.
    IF p_notas_internas IS NOT NULL
       AND length(p_notas_internas) > 5000 THEN
        RAISE EXCEPTION
            'Internal notes cannot exceed 5000 characters'
            USING ERRCODE = '22023';
    END IF;

    -- Actualiza exclusivamente estado y notas.
    -- updated_at lo gestiona el trigger existente.
    UPDATE public.audit_requests
    SET
        estado = p_estado,
        notas_internas = NULLIF(
            btrim(p_notas_internas),
            ''
        )
    WHERE id = p_request_id
    RETURNING *
    INTO v_request;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Audit request not found'
            USING ERRCODE = 'P0002';
    END IF;

    RETURN to_jsonb(v_request);
END;
$$;


ALTER FUNCTION "public"."update_audit_request"("p_request_id" "uuid", "p_estado" "text", "p_notas_internas" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_expense"("p_expense_id" "uuid", "p_expense_date" "date", "p_description" "text", "p_expense_type" "text", "p_category_id" "uuid", "p_supplier_id" "uuid", "p_project_id" "uuid", "p_currency" "text", "p_subtotal" numeric) RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE

  v_expense public.expenses;

BEGIN

  PERFORM public.require_expense_permission(
    'expenses.update'
  );

  PERFORM public.consume_expense_worker_rate_limit(
    'expenses:update'
  );


  SELECT *
  INTO v_expense

  FROM public.expenses

  WHERE id = p_expense_id

  FOR UPDATE;


  IF NOT FOUND THEN
    RAISE EXCEPTION
      'El gasto % no existe',
      p_expense_id;
  END IF;


  IF v_expense.status IN (
    'paid',
    'cancelled'
  ) THEN

    RAISE EXCEPTION
      'No se puede modificar un gasto en estado %',
      v_expense.status;

  END IF;


  IF p_description IS NULL
     OR BTRIM(p_description) = '' THEN

    RAISE EXCEPTION
      'La descripción del gasto es obligatoria';

  END IF;


  IF LENGTH(BTRIM(p_description)) > 2000 THEN

    RAISE EXCEPTION
      'La descripción no puede superar 2.000 caracteres';

  END IF;


  IF p_currency IS NULL
     OR p_currency !~ '^[A-Z]{3}$' THEN

    RAISE EXCEPTION
      'La moneda debe tener formato ISO de 3 letras';

  END IF;


  IF p_subtotal IS NULL
     OR p_subtotal < 0 THEN

    RAISE EXCEPTION
      'El subtotal no puede ser negativo';

  END IF;


  UPDATE public.expenses

  SET
    expense_date = COALESCE(
      p_expense_date,
      expense_date
    ),

    description = BTRIM(p_description),

    expense_type = p_expense_type,

    category_id = p_category_id,

    supplier_id = p_supplier_id,

    project_id = p_project_id,

    currency = p_currency,

    subtotal = ROUND(
      p_subtotal,
      2
    ),

    updated_by = auth.uid(),

    updated_at = CURRENT_TIMESTAMP

  WHERE id = p_expense_id

  RETURNING *
  INTO v_expense;


  RETURN v_expense;

END;
$_$;


ALTER FUNCTION "public"."update_expense"("p_expense_id" "uuid", "p_expense_date" "date", "p_description" "text", "p_expense_type" "text", "p_category_id" "uuid", "p_supplier_id" "uuid", "p_project_id" "uuid", "p_currency" "text", "p_subtotal" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_expense"("p_expense_id" "uuid", "p_expense_date" "date", "p_description" "text", "p_expense_type" "text", "p_category_id" "uuid", "p_supplier_id" "uuid", "p_project_id" "uuid", "p_currency" "text", "p_subtotal" numeric) IS 'Updates an internal Modira expense through a controlled worker RPC.';



CREATE OR REPLACE FUNCTION "public"."update_internal_task"("p_task_id" "uuid", "p_changes" "jsonb", "p_comment" "text" DEFAULT NULL::"text") RETURNS "public"."internal_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.internal_tasks;
    v_old_status TEXT;
    v_old_progress INTEGER;
    v_worker_id UUID;
    v_new_assigned UUID;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.update'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:update:' || auth.uid()::TEXT,
        120,
        600
    );


    IF p_changes IS NULL
       OR jsonb_typeof(p_changes) <> 'object'
    THEN
        RAISE EXCEPTION
            'Los cambios deben ser un objeto JSON';
    END IF;


    IF NOT public.internal_task_can_current_worker_view(p_task_id) THEN
        RAISE EXCEPTION
            'No tienes acceso a esta tarea';
    END IF;


    v_worker_id := public.internal_task_current_worker_id();


    SELECT *
    INTO v_task
    FROM public.internal_tasks
    WHERE id = p_task_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tarea no existe';
    END IF;


    v_old_status := v_task.status;
    v_old_progress := v_task.progress;


    IF NOT public.internal_task_current_worker_is_direction()
       AND NOT public.internal_task_current_worker_is_developer()
    THEN
        RAISE EXCEPTION
            'Este trabajador solo puede modificar el progreso mediante su operación específica';
    END IF;


    IF p_changes ? 'title' THEN

        IF NULLIF(BTRIM(p_changes ->> 'title'), '') IS NULL THEN
            RAISE EXCEPTION
                'El título no puede estar vacío';
        END IF;

        IF LENGTH(p_changes ->> 'title') > 200 THEN
            RAISE EXCEPTION
                'El título no puede superar 200 caracteres';
        END IF;

    END IF;


    IF p_changes ? 'description'
       AND p_changes ->> 'description' IS NOT NULL
       AND LENGTH(p_changes ->> 'description') > 5000
    THEN
        RAISE EXCEPTION
            'La descripción no puede superar 5000 caracteres';
    END IF;


    IF p_changes ? 'priority'
       AND p_changes ->> 'priority' NOT IN (
           'low',
           'normal',
           'high',
           'urgent'
       )
    THEN
        RAISE EXCEPTION
            'Prioridad no válida';
    END IF;


    IF p_changes ? 'assigned_to_worker_id' THEN

        IF NOT public.internal_task_current_worker_is_direction() THEN
            RAISE EXCEPTION
                'Solo Dirección puede reasignar una tarea existente';
        END IF;


        IF p_changes ->> 'assigned_to_worker_id' IS NULL THEN
            v_new_assigned := NULL;
        ELSE
            v_new_assigned :=
                (p_changes ->> 'assigned_to_worker_id')::UUID;

            IF NOT EXISTS (
                SELECT 1
                FROM public.workers w
                WHERE w.id = v_new_assigned
                  AND w.is_active = TRUE
            ) THEN
                RAISE EXCEPTION
                    'El trabajador asignado no existe o no está activo';
            END IF;

        END IF;

    END IF;


    UPDATE public.internal_tasks
    SET
        title = CASE
            WHEN p_changes ? 'title'
            THEN BTRIM(p_changes ->> 'title')
            ELSE title
        END,

        description = CASE
            WHEN p_changes ? 'description'
            THEN NULLIF(BTRIM(p_changes ->> 'description'), '')
            ELSE description
        END,

        priority = CASE
            WHEN p_changes ? 'priority'
            THEN p_changes ->> 'priority'
            ELSE priority
        END,

        due_at = CASE
            WHEN p_changes ? 'due_at'
            THEN NULLIF(p_changes ->> 'due_at', '')::TIMESTAMPTZ
            ELSE due_at
        END,

        assigned_to_worker_id = CASE
            WHEN p_changes ? 'assigned_to_worker_id'
            THEN v_new_assigned
            ELSE assigned_to_worker_id
        END,

        updated_at = CURRENT_TIMESTAMP

    WHERE id = p_task_id

    RETURNING *
    INTO v_task;


    PERFORM public.internal_task_record_update(
        p_task_id,
        v_worker_id,
        CASE
            WHEN p_changes ? 'assigned_to_worker_id'
            THEN 'reassigned'
            ELSE 'updated'
        END,
        v_old_status,
        v_old_progress,
        v_task.status,
        v_task.progress,
        p_comment
    );


    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."update_internal_task"("p_task_id" "uuid", "p_changes" "jsonb", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_internal_task_progress"("p_task_id" "uuid", "p_progress" integer, "p_comment" "text" DEFAULT NULL::"text") RETURNS "public"."internal_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.internal_tasks;
    v_worker_id UUID;
    v_old_progress INTEGER;
BEGIN

    PERFORM public.require_current_worker_permission(
        'internal_tasks.update'
    );


    PERFORM public.enforce_security_rate_limit(
        'internal_tasks:progress:' || auth.uid()::TEXT,
        120,
        600
    );


    IF p_progress IS NULL
       OR p_progress < 0
       OR p_progress > 100
    THEN
        RAISE EXCEPTION
            'El progreso debe estar entre 0 y 100';
    END IF;


    v_worker_id := public.internal_task_current_worker_id();


    SELECT *
    INTO v_task
    FROM public.internal_tasks
    WHERE id = p_task_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tarea no existe';
    END IF;


    IF v_task.assigned_to_worker_id IS DISTINCT FROM v_worker_id THEN
        RAISE EXCEPTION
            'Solo el trabajador responsable puede actualizar el progreso';
    END IF;


    IF v_task.status NOT IN (
        'to_do',
        'in_progress'
    ) THEN
        RAISE EXCEPTION
            'No puedes modificar el progreso en el estado actual de la tarea';
    END IF;


    v_old_progress := v_task.progress;


    UPDATE public.internal_tasks
    SET
        progress = p_progress,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_task_id
    RETURNING *
    INTO v_task;


    PERFORM public.internal_task_record_update(
        p_task_id,
        v_worker_id,
        'progress_updated',
        v_task.status,
        v_old_progress,
        v_task.status,
        v_task.progress,
        p_comment
    );


    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."update_internal_task_progress"("p_task_id" "uuid", "p_progress" integer, "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_internal_task_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN

    NEW.updated_at := CURRENT_TIMESTAMP;

    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."update_internal_task_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_invoice_by_worker"("p_invoice_id" "uuid", "p_company_id" "uuid", "p_project_id" "uuid", "p_fecha_emision" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_fecha_vencimiento" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_descripcion" "text" DEFAULT NULL::"text", "p_subtotal" numeric DEFAULT 0, "p_iva_aplicado" boolean DEFAULT true, "p_iva_porcentaje" numeric DEFAULT 21, "p_irpf_aplicado" boolean DEFAULT false, "p_irpf_porcentaje" numeric DEFAULT 0, "p_estado" "text" DEFAULT 'pendiente'::"text") RETURNS "public"."invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE

    v_invoice public.invoices;

    v_project_user_id UUID;
    v_project_client_id UUID;
    v_project_company_id UUID;

    v_subtotal NUMERIC(12,2);
    v_iva_porcentaje NUMERIC(5,2);
    v_irpf_porcentaje NUMERIC(5,2);

    v_normalized_status TEXT;

    -- --------------------------------------------------------
    -- Fiscal issuer
    -- --------------------------------------------------------

    v_issuer_legal_name TEXT;
    v_issuer_tax_id TEXT;
    v_issuer_address TEXT;
    v_issuer_postal_code TEXT;
    v_issuer_city TEXT;
    v_issuer_province TEXT;
    v_issuer_country TEXT;

    -- --------------------------------------------------------
    -- Fiscal customer
    -- --------------------------------------------------------

    v_customer_legal_name TEXT;
    v_customer_tax_id TEXT;
    v_customer_address TEXT;
    v_customer_postal_code TEXT;
    v_customer_city TEXT;
    v_customer_province TEXT;
    v_customer_country TEXT;
    v_customer_contact_name TEXT;

BEGIN


    -- ========================================================
    -- 1. PERMISSION
    -- ========================================================

    PERFORM public.require_current_worker_permission(
        'invoices.update'
    );


    -- ========================================================
    -- 2. LOCK INVOICE
    -- ========================================================

    SELECT *
    INTO v_invoice
    FROM public.invoices
    WHERE id = p_invoice_id
    FOR UPDATE;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'Factura no encontrada';

    END IF;


    -- ========================================================
    -- 3. COMPANY
    -- ========================================================

    IF p_company_id IS NULL THEN

        RAISE EXCEPTION
            'La empresa es obligatoria';

    END IF;


    SELECT
        COALESCE(
            NULLIF(TRIM(c.legal_name), ''),
            NULLIF(TRIM(c.company_name), '')
        ),
        NULLIF(TRIM(c.cif_vat), ''),
        NULLIF(TRIM(c.address), ''),
        NULLIF(TRIM(c.postal_code), ''),
        NULLIF(TRIM(c.city), ''),
        NULLIF(TRIM(c.province), ''),
        COALESCE(
            NULLIF(TRIM(c.country), ''),
            'ES'
        )
    INTO
        v_issuer_legal_name,
        v_issuer_tax_id,
        v_issuer_address,
        v_issuer_postal_code,
        v_issuer_city,
        v_issuer_province,
        v_issuer_country
    FROM public.companies c
    WHERE c.id = p_company_id;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'La empresa indicada no existe';

    END IF;


    -- ========================================================
    -- 4. PROJECT
    -- ========================================================

    IF p_project_id IS NULL THEN

        RAISE EXCEPTION
            'El proyecto es obligatorio';

    END IF;


    SELECT
        user_id,
        client_id,
        company_id
    INTO
        v_project_user_id,
        v_project_client_id,
        v_project_company_id
    FROM public.projects
    WHERE id = p_project_id;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'El proyecto indicado no existe';

    END IF;


    IF v_project_company_id IS DISTINCT FROM p_company_id THEN

        RAISE EXCEPTION
            'El proyecto no pertenece a la empresa seleccionada';

    END IF;


    -- ========================================================
    -- 5. CLIENT SNAPSHOT
    -- ========================================================

    IF v_project_client_id IS NOT NULL THEN

        SELECT
            COALESCE(
                NULLIF(TRIM(c.empresa), ''),
                NULLIF(TRIM(c.nombre), '')
            ),
            NULLIF(TRIM(c.cif_vat), ''),
            NULLIF(TRIM(c.direccion), ''),
            NULLIF(TRIM(c.codigo_postal), ''),
            NULLIF(TRIM(c.ciudad), ''),
            NULLIF(TRIM(c.provincia), ''),
            COALESCE(
                NULLIF(TRIM(c.pais), ''),
                'ES'
            ),
            NULLIF(TRIM(c.nombre), '')
        INTO
            v_customer_legal_name,
            v_customer_tax_id,
            v_customer_address,
            v_customer_postal_code,
            v_customer_city,
            v_customer_province,
            v_customer_country,
            v_customer_contact_name
        FROM public.clients c
        WHERE c.id = v_project_client_id
          AND c.company_id = p_company_id;


        IF NOT FOUND THEN

            RAISE EXCEPTION
                'El cliente del proyecto no existe o no pertenece a la empresa seleccionada';

        END IF;

    END IF;


    -- ========================================================
    -- 6. SUBTOTAL
    -- ========================================================

    v_subtotal :=
        ROUND(
            COALESCE(
                p_subtotal,
                0
            ),
            2
        );


    IF v_subtotal < 0 THEN

        RAISE EXCEPTION
            'La base imponible no puede ser negativa';

    END IF;


    -- ========================================================
    -- 7. IVA
    -- ========================================================

    IF p_iva_aplicado IS NULL THEN

        p_iva_aplicado := TRUE;

    END IF;


    v_iva_porcentaje :=
        ROUND(
            COALESCE(
                p_iva_porcentaje,
                0
            ),
            2
        );


    IF p_iva_aplicado THEN

        IF v_iva_porcentaje < 0
           OR v_iva_porcentaje > 100
        THEN

            RAISE EXCEPTION
                'El porcentaje de IVA debe estar entre 0 y 100';

        END IF;

    ELSE

        v_iva_porcentaje := 0;

    END IF;


    -- ========================================================
    -- 8. IRPF
    -- ========================================================

    IF p_irpf_aplicado IS NULL THEN

        p_irpf_aplicado := FALSE;

    END IF;


    v_irpf_porcentaje :=
        ROUND(
            COALESCE(
                p_irpf_porcentaje,
                0
            ),
            2
        );


    IF p_irpf_aplicado THEN

        IF v_irpf_porcentaje <= 0
           OR v_irpf_porcentaje > 100
        THEN

            RAISE EXCEPTION
                'El porcentaje de IRPF debe ser mayor que 0 y menor o igual que 100';

        END IF;

    ELSE

        v_irpf_porcentaje := 0;

    END IF;


    -- ========================================================
    -- 9. STATUS
    -- ========================================================

    v_normalized_status :=
        LOWER(
            TRIM(
                COALESCE(
                    p_estado,
                    'pendiente'
                )
            )
        );


    IF v_normalized_status NOT IN (
        'pendiente',
        'pagada',
        'vencida',
        'cancelada'
    ) THEN

        RAISE EXCEPTION
            'Estado de factura no válido';

    END IF;


    -- ========================================================
    -- 10. UPDATE
    -- ========================================================

    UPDATE public.invoices
    SET

        user_id = v_project_user_id,

        company_id = p_company_id,

        project_id = p_project_id,

        client_id = v_project_client_id,

        fecha_emision =
            COALESCE(
                p_fecha_emision,
                fecha_emision
            ),

        fecha_vencimiento =
            p_fecha_vencimiento,

        descripcion =
            NULLIF(
                TRIM(
                    COALESCE(
                        p_descripcion,
                        ''
                    )
                ),
                ''
            ),

        subtotal =
            v_subtotal,

        iva_aplicado =
            p_iva_aplicado,

        iva_porcentaje =
            v_iva_porcentaje,

        irpf_aplicado =
            p_irpf_aplicado,

        irpf_porcentaje =
            v_irpf_porcentaje,

        estado =
            v_normalized_status,

        -- ----------------------------------------------------
        -- Fiscal snapshot — issuer
        -- ----------------------------------------------------

        issuer_legal_name =
            v_issuer_legal_name,

        issuer_tax_id =
            v_issuer_tax_id,

        issuer_address =
            v_issuer_address,

        issuer_postal_code =
            v_issuer_postal_code,

        issuer_city =
            v_issuer_city,

        issuer_province =
            v_issuer_province,

        issuer_country =
            v_issuer_country,

        -- ----------------------------------------------------
        -- Fiscal snapshot — customer
        -- ----------------------------------------------------

        customer_legal_name =
            v_customer_legal_name,

        customer_tax_id =
            v_customer_tax_id,

        customer_address =
            v_customer_address,

        customer_postal_code =
            v_customer_postal_code,

        customer_city =
            v_customer_city,

        customer_province =
            v_customer_province,

        customer_country =
            v_customer_country,

        customer_contact_name =
            v_customer_contact_name,

        updated_at =
            CURRENT_TIMESTAMP

    WHERE id = p_invoice_id

    RETURNING *
    INTO v_invoice;


    -- ========================================================
    -- 11. RETURN
    -- ========================================================

    RETURN v_invoice;


END;
$$;


ALTER FUNCTION "public"."update_invoice_by_worker"("p_invoice_id" "uuid", "p_company_id" "uuid", "p_project_id" "uuid", "p_fecha_emision" timestamp with time zone, "p_fecha_vencimiento" timestamp with time zone, "p_descripcion" "text", "p_subtotal" numeric, "p_iva_aplicado" boolean, "p_iva_porcentaje" numeric, "p_irpf_aplicado" boolean, "p_irpf_porcentaje" numeric, "p_estado" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_invoice_by_worker"("p_invoice_id" "uuid", "p_company_id" "uuid", "p_project_id" "uuid", "p_fecha_emision" timestamp with time zone, "p_fecha_vencimiento" timestamp with time zone, "p_descripcion" "text", "p_subtotal" numeric, "p_iva_aplicado" boolean, "p_iva_porcentaje" numeric, "p_irpf_aplicado" boolean, "p_irpf_porcentaje" numeric, "p_estado" "text") IS 'Permite a un trabajador activo editar una factura sin modificar su numero_factura. Los importes fiscales son recalculados por el trigger de facturación.';



CREATE OR REPLACE FUNCTION "public"."update_maintenance_contract_iva"("p_contract_id" "uuid", "p_iva_aplicado" boolean, "p_iva_porcentaje" numeric) RETURNS "public"."maintenance_contracts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'maintenance.update'
    );

    RETURN public.update_maintenance_contract_iva__legacy_113(
        p_contract_id,
        p_iva_aplicado,
        p_iva_porcentaje
    );

END;
$$;


ALTER FUNCTION "public"."update_maintenance_contract_iva"("p_contract_id" "uuid", "p_iva_aplicado" boolean, "p_iva_porcentaje" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_maintenance_contract_iva__legacy_113"("p_contract_id" "uuid", "p_iva_aplicado" boolean, "p_iva_porcentaje" numeric) RETURNS "public"."maintenance_contracts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_contract public.maintenance_contracts;
BEGIN

    -- --------------------------------------------------------
    -- WORKER
    -- --------------------------------------------------------

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    -- --------------------------------------------------------
    -- IVA
    -- --------------------------------------------------------

    IF p_iva_porcentaje IS NULL
       OR p_iva_porcentaje < 0
       OR p_iva_porcentaje > 100
    THEN
        RAISE EXCEPTION
            'El porcentaje de IVA debe estar entre 0 y 100';
    END IF;


    -- --------------------------------------------------------
    -- BLOQUEAR CONTRATO
    -- --------------------------------------------------------

    SELECT *
    INTO v_contract
    FROM public.maintenance_contracts
    WHERE id = p_contract_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Contrato de mantenimiento no encontrado';
    END IF;


    -- --------------------------------------------------------
    -- ACTUALIZAR
    -- --------------------------------------------------------

    UPDATE public.maintenance_contracts
    SET
        iva_aplicado =
            COALESCE(p_iva_aplicado, TRUE),

        iva_porcentaje =
            ROUND(p_iva_porcentaje, 2),

        iva_source =
            'worker',

        iva_configured_by =
            auth.uid(),

        iva_configured_at =
            CURRENT_TIMESTAMP,

        updated_at =
            CURRENT_TIMESTAMP

    WHERE id = p_contract_id
    RETURNING *
    INTO v_contract;


    RETURN v_contract;

END;
$$;


ALTER FUNCTION "public"."update_maintenance_contract_iva__legacy_113"("p_contract_id" "uuid", "p_iva_aplicado" boolean, "p_iva_porcentaje" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_project_by_worker"("p_project_id" "uuid", "p_nombre" "text" DEFAULT NULL::"text", "p_estado" "text" DEFAULT NULL::"text", "p_descripcion" "text" DEFAULT NULL::"text") RETURNS "public"."projects"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'projects.update'
    );


    RETURN public.update_project_by_worker__legacy_113(
        p_project_id,
        p_nombre,
        p_estado,
        p_descripcion
    );

END;
$$;


ALTER FUNCTION "public"."update_project_by_worker"("p_project_id" "uuid", "p_nombre" "text", "p_estado" "text", "p_descripcion" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_project_by_worker__legacy_113"("p_project_id" "uuid", "p_nombre" "text" DEFAULT NULL::"text", "p_estado" "text" DEFAULT NULL::"text") RETURNS "public"."projects"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_project public.projects;
BEGIN
    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION 'Acceso denegado: se requiere un trabajador activo';
    END IF;

    IF p_estado IS NOT NULL
       AND p_estado NOT IN (
           'Pendiente',
           'Activo',
           'Pausado',
           'Entregado',
           'Completado'
       )
    THEN
        RAISE EXCEPTION 'Estado de proyecto no válido: %', p_estado;
    END IF;

    IF p_nombre IS NOT NULL AND TRIM(p_nombre) = '' THEN
        RAISE EXCEPTION 'El nombre del proyecto no puede estar vacío';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.projects p
        WHERE p.id = p_project_id
    ) THEN
        RAISE EXCEPTION 'Proyecto no encontrado';
    END IF;

    UPDATE public.projects
    SET
        nombre = CASE
            WHEN p_nombre IS NULL THEN nombre
            ELSE TRIM(p_nombre)
        END,
        estado = COALESCE(p_estado, estado),
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_project_id
    RETURNING * INTO v_project;

    RETURN v_project;
END;
$$;


ALTER FUNCTION "public"."update_project_by_worker__legacy_113"("p_project_id" "uuid", "p_nombre" "text", "p_estado" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_project_by_worker__legacy_113"("p_project_id" "uuid", "p_nombre" "text" DEFAULT NULL::"text", "p_estado" "text" DEFAULT NULL::"text", "p_descripcion" "text" DEFAULT NULL::"text") RETURNS "public"."projects"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_project public.projects;
BEGIN

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    IF p_estado IS NOT NULL
       AND p_estado NOT IN (
           'Pendiente',
           'Activo',
           'Pausado',
           'Entregado',
           'Completado'
       )
    THEN
        RAISE EXCEPTION
            'Estado de proyecto no válido: %',
            p_estado;
    END IF;


    IF p_nombre IS NOT NULL
       AND TRIM(p_nombre) = ''
    THEN
        RAISE EXCEPTION
            'El nombre del proyecto no puede estar vacío';
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM public.projects p
        WHERE p.id = p_project_id
    ) THEN
        RAISE EXCEPTION
            'Proyecto no encontrado';
    END IF;


    UPDATE public.projects
    SET
        nombre = CASE
            WHEN p_nombre IS NULL THEN nombre
            ELSE TRIM(p_nombre)
        END,

        estado = COALESCE(
            p_estado,
            estado
        ),

        descripcion = CASE
            WHEN p_descripcion IS NULL THEN descripcion
            ELSE NULLIF(
                TRIM(p_descripcion),
                ''
            )
        END,

        updated_at = CURRENT_TIMESTAMP

    WHERE id = p_project_id

    RETURNING *
    INTO v_project;


    RETURN v_project;

END;
$$;


ALTER FUNCTION "public"."update_project_by_worker__legacy_113"("p_project_id" "uuid", "p_nombre" "text", "p_estado" "text", "p_descripcion" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_project_milestone"("p_milestone_id" "uuid", "p_nombre" "text", "p_descripcion" "text" DEFAULT NULL::"text", "p_fecha_prevista" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_orden" integer DEFAULT NULL::integer, "p_estado" "text" DEFAULT NULL::"text") RETURNS "public"."project_milestones"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'project_milestones.update'
    );

    RETURN public.update_project_milestone__legacy_113(
        p_milestone_id,
        p_nombre,
        p_descripcion,
        p_fecha_prevista,
        p_orden,
        p_estado
    );

END;
$$;


ALTER FUNCTION "public"."update_project_milestone"("p_milestone_id" "uuid", "p_nombre" "text", "p_descripcion" "text", "p_fecha_prevista" timestamp with time zone, "p_orden" integer, "p_estado" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_project_milestone__legacy_113"("p_milestone_id" "uuid", "p_nombre" "text", "p_descripcion" "text" DEFAULT NULL::"text", "p_fecha_prevista" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_orden" integer DEFAULT NULL::integer, "p_estado" "text" DEFAULT NULL::"text") RETURNS "public"."project_milestones"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

    v_milestone public.project_milestones;

BEGIN

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- WORKER ACTIVO
    -- --------------------------------------------------------

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    -- --------------------------------------------------------
    -- ID
    -- --------------------------------------------------------

    IF p_milestone_id IS NULL THEN
        RAISE EXCEPTION
            'El hito es obligatorio';
    END IF;


    -- --------------------------------------------------------
    -- NOMBRE
    -- --------------------------------------------------------

    IF p_nombre IS NULL
       OR LENGTH(BTRIM(p_nombre)) = 0
       OR LENGTH(p_nombre) > 200
    THEN
        RAISE EXCEPTION
            'El nombre del hito no es válido';
    END IF;


    -- --------------------------------------------------------
    -- DESCRIPCIÓN
    -- --------------------------------------------------------

    IF p_descripcion IS NOT NULL
       AND LENGTH(p_descripcion) > 2000
    THEN
        RAISE EXCEPTION
            'La descripción del hito no puede superar 2000 caracteres';
    END IF;


    -- --------------------------------------------------------
    -- FECHA
    -- --------------------------------------------------------

    IF p_fecha_prevista IS NULL THEN
        RAISE EXCEPTION
            'La fecha prevista del hito es obligatoria';
    END IF;


    -- --------------------------------------------------------
    -- ORDEN
    -- --------------------------------------------------------

    IF p_orden IS NOT NULL
       AND (
            p_orden < 1
            OR p_orden > 10000
       )
    THEN
        RAISE EXCEPTION
            'El orden del hito no es válido';
    END IF;


    -- --------------------------------------------------------
    -- ESTADO
    -- --------------------------------------------------------

    IF p_estado IS NULL
       OR p_estado NOT IN (
            'pendiente',
            'en_curso',
            'completado'
       )
    THEN
        RAISE EXCEPTION
            'El estado del hito no es válido';
    END IF;


    -- --------------------------------------------------------
    -- OBTENER HITO
    -- --------------------------------------------------------

    SELECT *
    INTO v_milestone
    FROM public.project_milestones
    WHERE id = p_milestone_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El hito indicado no existe';
    END IF;


    -- --------------------------------------------------------
    -- ACTUALIZAR
    -- --------------------------------------------------------

    UPDATE public.project_milestones
    SET
        nombre = BTRIM(p_nombre),

        descripcion =
            NULLIF(BTRIM(p_descripcion), ''),

        fecha_prevista =
            p_fecha_prevista,

        orden =
            COALESCE(p_orden, orden),

        estado =
            p_estado

    WHERE id = p_milestone_id

    RETURNING *
    INTO v_milestone;


    RETURN v_milestone;

END;
$$;


ALTER FUNCTION "public"."update_project_milestone__legacy_113"("p_milestone_id" "uuid", "p_nombre" "text", "p_descripcion" "text", "p_fecha_prevista" timestamp with time zone, "p_orden" integer, "p_estado" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_project_task"("p_task_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_milestone_id" "uuid" DEFAULT NULL::"uuid", "p_priority" "text" DEFAULT NULL::"text", "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."project_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.project_tasks;
    v_old_task public.project_tasks;
    v_title TEXT;
    v_description TEXT;
    v_priority TEXT;
BEGIN

    IF public.current_project_task_worker_id() IS NULL THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.update'
    );

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:update:' || auth.uid()::TEXT,
        120,
        600
    );

    SELECT *
    INTO v_task
    FROM public.project_tasks
    WHERE id = p_task_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Tarea no encontrada';
    END IF;

    v_old_task := v_task;

    -- --------------------------------------------------------
    -- TÍTULO
    -- --------------------------------------------------------

    IF p_title IS NOT NULL THEN

        v_title := NULLIF(BTRIM(p_title), '');

        IF v_title IS NULL THEN
            RAISE EXCEPTION
                'El título no puede estar vacío';
        END IF;

        IF LENGTH(v_title) > 200 THEN
            RAISE EXCEPTION
                'El título no puede superar 200 caracteres';
        END IF;

    ELSE
        v_title := v_task.title;
    END IF;

    -- --------------------------------------------------------
    -- DESCRIPCIÓN
    -- --------------------------------------------------------

    IF p_description IS NOT NULL THEN

        v_description := NULLIF(BTRIM(p_description), '');

        IF v_description IS NOT NULL
           AND LENGTH(v_description) > 5000
        THEN
            RAISE EXCEPTION
                'La descripción no puede superar 5000 caracteres';
        END IF;

    ELSE
        v_description := v_task.description;
    END IF;

    -- --------------------------------------------------------
    -- PRIORIDAD
    -- --------------------------------------------------------

    IF p_priority IS NOT NULL THEN

        v_priority := LOWER(BTRIM(p_priority));

        IF v_priority NOT IN (
            'low',
            'normal',
            'high',
            'urgent'
        ) THEN
            RAISE EXCEPTION
                'Prioridad no válida';
        END IF;

    ELSE
        v_priority := v_task.priority;
    END IF;

    -- --------------------------------------------------------
    -- MILESTONE
    -- --------------------------------------------------------

    IF p_milestone_id IS NOT NULL THEN

        IF NOT EXISTS (
            SELECT 1
            FROM public.project_milestones pm
            WHERE pm.id = p_milestone_id
              AND pm.project_id = v_task.project_id
        ) THEN
            RAISE EXCEPTION
                'El hito no existe o no pertenece al proyecto';
        END IF;

    END IF;

    UPDATE public.project_tasks
    SET
        title = v_title,
        description = v_description,
        milestone_id = p_milestone_id,
        priority = v_priority,
        due_at = p_due_at
    WHERE id = v_task.id
    RETURNING *
    INTO v_task;

    PERFORM public.record_project_task_update(
        v_task.id,
        'updated',
        v_old_task.status,
        v_old_task.progress,
        v_task.status,
        v_task.progress,
        NULL
    );

    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."update_project_task"("p_task_id" "uuid", "p_title" "text", "p_description" "text", "p_milestone_id" "uuid", "p_priority" "text", "p_due_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_project_task_progress"("p_task_id" "uuid", "p_progress" integer) RETURNS "public"."project_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_task public.project_tasks;
    v_worker_id UUID;
    v_old_progress INTEGER;
BEGIN

    v_worker_id := public.current_project_task_worker_id();

    IF v_worker_id IS NULL THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;

    PERFORM public.require_current_worker_permission(
        'project_tasks.update'
    );

    PERFORM public.enforce_security_rate_limit(
        'project_tasks:progress:' || auth.uid()::TEXT,
        120,
        600
    );

    IF p_progress IS NULL
       OR p_progress < 0
       OR p_progress > 100
    THEN
        RAISE EXCEPTION
            'El progreso debe estar entre 0 y 100';
    END IF;

    SELECT *
    INTO v_task
    FROM public.project_tasks
    WHERE id = p_task_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Tarea no encontrada';
    END IF;

    IF v_task.assigned_to_worker_id IS DISTINCT FROM v_worker_id THEN
        RAISE EXCEPTION
            'Solo el trabajador asignado puede actualizar el progreso';
    END IF;

    IF v_task.status <> 'in_progress' THEN
        RAISE EXCEPTION
            'Solo se puede actualizar el progreso de una tarea en curso';
    END IF;

    v_old_progress := v_task.progress;

    UPDATE public.project_tasks
    SET
        progress = p_progress
    WHERE id = v_task.id
    RETURNING *
    INTO v_task;

    PERFORM public.record_project_task_update(
        v_task.id,
        'progress_updated',
        v_task.status,
        v_old_progress,
        v_task.status,
        v_task.progress,
        NULL
    );

    RETURN v_task;

END;
$$;


ALTER FUNCTION "public"."update_project_task_progress"("p_task_id" "uuid", "p_progress" integer) OWNER TO "postgres";


