ALTER FUNCTION "public"."update_project_update"("p_update_id" "uuid", "p_titulo" "text", "p_contenido" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_project_update__legacy_113"("p_update_id" "uuid", "p_titulo" "text", "p_contenido" "text") RETURNS "public"."project_updates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_update public.project_updates;
BEGIN

    -- --------------------------------------------------------
    -- AUTENTICACIÓN
    -- --------------------------------------------------------

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Usuario no autenticado';
    END IF;


    -- --------------------------------------------------------
    -- SOLO WORKERS ACTIVOS
    -- --------------------------------------------------------

    IF NOT public.current_user_is_worker() THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere un trabajador activo';
    END IF;


    -- --------------------------------------------------------
    -- VALIDAR ID
    -- --------------------------------------------------------

    IF p_update_id IS NULL THEN
        RAISE EXCEPTION
            'La actualización es obligatoria';
    END IF;


    -- --------------------------------------------------------
    -- VALIDAR TÍTULO
    -- --------------------------------------------------------

    IF p_titulo IS NULL
       OR LENGTH(BTRIM(p_titulo)) = 0
       OR LENGTH(p_titulo) > 200
    THEN
        RAISE EXCEPTION
            'El título de la actualización no es válido';
    END IF;


    -- --------------------------------------------------------
    -- VALIDAR CONTENIDO
    -- --------------------------------------------------------

    IF p_contenido IS NULL
       OR LENGTH(BTRIM(p_contenido)) = 0
       OR LENGTH(p_contenido) > 5000
    THEN
        RAISE EXCEPTION
            'El contenido de la actualización no es válido';
    END IF;


    -- --------------------------------------------------------
    -- OBTENER ACTUALIZACIÓN
    --
    -- FOR UPDATE bloquea la fila durante la operación.
    -- --------------------------------------------------------

    SELECT *
    INTO v_update
    FROM public.project_updates
    WHERE id = p_update_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La actualización indicada no existe';
    END IF;


    -- --------------------------------------------------------
    -- ACTUALIZAR
    -- --------------------------------------------------------

    UPDATE public.project_updates
    SET
        titulo = BTRIM(p_titulo),
        contenido = BTRIM(p_contenido)
    WHERE id = p_update_id
    RETURNING *
    INTO v_update;


    -- --------------------------------------------------------
    -- NOTIFICAR AL CLIENTE
    --
    -- IMPORTANTE:
    --
    -- No recibimos ningún user_id desde el frontend.
    --
    -- emit_project_client_notification() recibe el
    -- project_id y determina internamente el cliente
    -- propietario del proyecto.
    --
    -- Esto evita que el frontend pueda indicar
    -- arbitrariamente a qué usuario enviar la notificación.
    -- --------------------------------------------------------

    PERFORM public.emit_project_client_notification(
        v_update.project_id,
        'project_update',
        v_update.titulo,
        'Se ha modificado una actualización de tu proyecto.',
        jsonb_build_object(
            'project_update_id', v_update.id,
            'event', 'project_update_updated'
        )
    );


    -- --------------------------------------------------------
    -- DEVOLVER ACTUALIZACIÓN
    -- --------------------------------------------------------

    RETURN v_update;

END;
$$;


ALTER FUNCTION "public"."update_project_update__legacy_113"("p_update_id" "uuid", "p_titulo" "text", "p_contenido" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_project_update__legacy_113"("p_update_id" "uuid", "p_titulo" "text", "p_contenido" "text") IS 'Modifica una actualización existente y genera una nueva notificación para el cliente del proyecto. Solo puede ejecutarla un trabajador activo.';



CREATE OR REPLACE FUNCTION "public"."update_quotation_by_worker"("p_quotation_id" "uuid", "p_project_id" "uuid", "p_titulo" "text", "p_descripcion_detallada" "text", "p_servicios_incluidos" "jsonb", "p_iva_porcentaje" numeric, "p_irpf_aplicado" boolean, "p_irpf_porcentaje" numeric, "p_estado" "text", "p_fecha_emision" timestamp with time zone, "p_fecha_validez" timestamp with time zone, "p_notas" "text") RETURNS "public"."quotations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_quotation public.quotations;
    v_project public.projects%ROWTYPE;

    v_title TEXT;
    v_description TEXT;
    v_notes TEXT;
    v_state TEXT;

    v_iva NUMERIC(5,2);
    v_irpf NUMERIC(5,2);
    v_irpf_applied BOOLEAN;

    v_subtotal NUMERIC(12,2);
    v_iva_importe NUMERIC(12,2);
    v_irpf_importe NUMERIC(12,2);
    v_total NUMERIC(12,2);

    v_service JSONB;
    v_service_description TEXT;
    v_quantity NUMERIC;
    v_price NUMERIC;

    v_fecha_emision TIMESTAMPTZ;
    -- --------------------------------------------------------
    -- Fiscal issuer snapshot
    -- --------------------------------------------------------
    v_issuer_legal_name TEXT;
    v_issuer_tax_id TEXT;
    v_issuer_address TEXT;
    v_issuer_postal_code TEXT;
    v_issuer_city TEXT;
    v_issuer_province TEXT;
    v_issuer_country TEXT;

    -- --------------------------------------------------------
    -- Fiscal customer snapshot
    -- --------------------------------------------------------
    v_customer_legal_name TEXT;
    v_customer_tax_id TEXT;
    v_customer_address TEXT;
    v_customer_postal_code TEXT;
    v_customer_city TEXT;
    v_customer_province TEXT;
    v_customer_country TEXT;
    v_customer_contact_name TEXT;

BEGIN

    PERFORM public.require_current_worker_permission(
        'quotations.update'
    );

    SELECT *
    INTO v_quotation
    FROM public.quotations
    WHERE id = p_quotation_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Presupuesto no encontrado';
    END IF;

    SELECT *
    INTO v_project
    FROM public.projects
    WHERE id = p_project_id
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El proyecto seleccionado no existe';
    END IF;

    IF v_project.company_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto seleccionado no tiene empresa';
    END IF;

    IF v_project.user_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto seleccionado no tiene un usuario propietario válido';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM auth.users u
        WHERE u.id = v_project.user_id
    ) THEN
        RAISE EXCEPTION
            'El propietario del proyecto no existe';
    END IF;

    IF v_project.client_id IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
            FROM public.clients c
            WHERE c.id = v_project.client_id
              AND c.company_id = v_project.company_id
       )
    THEN
        RAISE EXCEPTION
            'El cliente del proyecto no pertenece a la empresa';
    END IF;


    -- ========================================================
    -- FISCAL SNAPSHOT
    -- ========================================================
    --
    -- El presupuesto conserva una fotografía de los datos
    -- fiscales del emisor y del cliente usados para su documento.
    -- El cliente del proyecto puede ser NULL y, en ese caso,
    -- el snapshot del cliente permanece NULL.
    --
    -- ========================================================

    SELECT
        COALESCE(
            NULLIF(TRIM(c.legal_name), ''),
            NULLIF(TRIM(c.company_name), '')
        ),
        NULLIF(TRIM(c.cif_vat), ''),
        NULLIF(TRIM(c.address), ''),
        NULLIF(TRIM(c.postal_code), ''),
        NULLIF(TRIM(c.city), ''),
        NULLIF(TRIM(c.province), ''),
        COALESCE(
            NULLIF(TRIM(c.country), ''),
            'ES'
        )
    INTO
        v_issuer_legal_name,
        v_issuer_tax_id,
        v_issuer_address,
        v_issuer_postal_code,
        v_issuer_city,
        v_issuer_province,
        v_issuer_country
    FROM public.companies c
    WHERE c.id = v_project.company_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La empresa del proyecto no existe';
    END IF;

    IF v_project.client_id IS NOT NULL THEN

        SELECT
            COALESCE(
                NULLIF(TRIM(c.empresa), ''),
                NULLIF(TRIM(c.nombre), '')
            ),
            NULLIF(TRIM(c.cif_vat), ''),
            NULLIF(TRIM(c.direccion), ''),
            NULLIF(TRIM(c.codigo_postal), ''),
            NULLIF(TRIM(c.ciudad), ''),
            NULLIF(TRIM(c.provincia), ''),
            COALESCE(
                NULLIF(TRIM(c.pais), ''),
                'ES'
            ),
            NULLIF(TRIM(c.nombre), '')
        INTO
            v_customer_legal_name,
            v_customer_tax_id,
            v_customer_address,
            v_customer_postal_code,
            v_customer_city,
            v_customer_province,
            v_customer_country,
            v_customer_contact_name
        FROM public.clients c
        WHERE c.id = v_project.client_id
          AND c.company_id = v_project.company_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'El cliente del proyecto no existe o no pertenece a la empresa seleccionada';
        END IF;

    END IF;

    v_title :=
        NULLIF(
            BTRIM(p_titulo),
            ''
        );

    IF v_title IS NULL THEN
        RAISE EXCEPTION
            'El título del presupuesto es obligatorio';
    END IF;

    IF LENGTH(v_title) > 300 THEN
        RAISE EXCEPTION
            'El título no puede superar 300 caracteres';
    END IF;

    v_description :=
        NULLIF(
            BTRIM(
                COALESCE(
                    p_descripcion_detallada,
                    ''
                )
            ),
            ''
        );

    IF v_description IS NOT NULL
       AND LENGTH(v_description) > 10000
    THEN
        RAISE EXCEPTION
            'La descripción del presupuesto no puede superar 10000 caracteres';
    END IF;

    v_notes :=
        NULLIF(
            BTRIM(
                COALESCE(
                    p_notas,
                    ''
                )
            ),
            ''
        );

    IF v_notes IS NOT NULL
       AND LENGTH(v_notes) > 10000
    THEN
        RAISE EXCEPTION
            'Las notas del presupuesto no pueden superar 10000 caracteres';
    END IF;

    v_state :=
        INITCAP(
            LOWER(
                BTRIM(
                    COALESCE(
                        p_estado,
                        'Pendiente'
                    )
                )
            )
        );

    IF v_state NOT IN (
        'Pendiente',
        'Aceptado',
        'Rechazado'
    ) THEN
        RAISE EXCEPTION
            'Estado de presupuesto no válido';
    END IF;

    v_iva :=
        ROUND(
            COALESCE(
                p_iva_porcentaje,
                0
            ),
            2
        );

    IF v_iva < 0 OR v_iva > 100 THEN
        RAISE EXCEPTION
            'El porcentaje de IVA debe estar entre 0 y 100';
    END IF;

    v_irpf_applied :=
        COALESCE(
            p_irpf_aplicado,
            FALSE
        );

    v_irpf :=
        ROUND(
            COALESCE(
                p_irpf_porcentaje,
                0
            ),
            2
        );

    IF NOT v_irpf_applied THEN

        IF v_irpf <> 0 THEN
            RAISE EXCEPTION
                'Si el IRPF no se aplica, el porcentaje debe ser 0';
        END IF;

        v_irpf := 0;

    ELSE

        IF v_irpf <= 0 OR v_irpf > 100 THEN
            RAISE EXCEPTION
                'El porcentaje de IRPF debe ser mayor que 0 y menor o igual que 100';
        END IF;

    END IF;

    IF p_servicios_incluidos IS NULL
       OR jsonb_typeof(p_servicios_incluidos) <> 'array'
    THEN
        RAISE EXCEPTION
            'Los servicios incluidos deben ser un array JSON';
    END IF;

    IF jsonb_array_length(p_servicios_incluidos) = 0 THEN
        RAISE EXCEPTION
            'Debe existir al menos un servicio';
    END IF;

    IF jsonb_array_length(p_servicios_incluidos) > 100 THEN
        RAISE EXCEPTION
            'El presupuesto no puede contener más de 100 servicios';
    END IF;

    v_subtotal := 0;

    FOR v_service IN
        SELECT value
        FROM jsonb_array_elements(
            p_servicios_incluidos
        )
    LOOP

        IF jsonb_typeof(v_service) <> 'object' THEN
            RAISE EXCEPTION
                'Cada servicio debe ser un objeto JSON';
        END IF;

        v_service_description :=
            NULLIF(
                BTRIM(
                    COALESCE(
                        v_service->>'descripcion',
                        ''
                    )
                ),
                ''
            );

        IF v_service_description IS NULL THEN
            RAISE EXCEPTION
                'Todos los servicios deben tener una descripción';
        END IF;

        IF LENGTH(v_service_description) > 2000 THEN
            RAISE EXCEPTION
                'La descripción de un servicio no puede superar 2000 caracteres';
        END IF;

        IF NOT (v_service ? 'cantidad')
           OR NOT (v_service ? 'precio')
        THEN
            RAISE EXCEPTION
                'Cada servicio debe contener cantidad y precio';
        END IF;

        BEGIN

            v_quantity :=
                (v_service->>'cantidad')::NUMERIC;

            v_price :=
                (v_service->>'precio')::NUMERIC;

        EXCEPTION
            WHEN invalid_text_representation
              OR numeric_value_out_of_range
        THEN
            RAISE EXCEPTION
                'Cantidad o precio de servicio no válidos';
        END;

        IF v_quantity IS NULL
           OR v_quantity <= 0
           OR v_quantity > 1000000
        THEN
            RAISE EXCEPTION
                'La cantidad de un servicio debe ser mayor que 0';
        END IF;

        IF v_price IS NULL
           OR v_price < 0
           OR v_price > 100000000
        THEN
            RAISE EXCEPTION
                'El precio de un servicio no puede ser negativo';
        END IF;

        v_subtotal :=
            v_subtotal
            + ROUND(
                v_quantity * v_price,
                2
            );

        IF v_subtotal > 1000000000 THEN
            RAISE EXCEPTION
                'El importe total del presupuesto supera el límite permitido';
        END IF;

    END LOOP;

    v_subtotal :=
        ROUND(
            v_subtotal,
            2
        );

    v_iva_importe :=
        ROUND(
            v_subtotal * (v_iva / 100),
            2
        );

    IF v_irpf_applied THEN
        v_irpf_importe :=
            ROUND(
                v_subtotal * (v_irpf / 100),
                2
            );
    ELSE
        v_irpf_importe := 0;
    END IF;

    v_total :=
        ROUND(
            v_subtotal
            + v_iva_importe
            - v_irpf_importe,
            2
        );

    IF v_total < 0 THEN
        RAISE EXCEPTION
            'El total del presupuesto no puede ser negativo';
    END IF;

    v_fecha_emision :=
        COALESCE(
            p_fecha_emision,
            v_quotation.fecha_emision
        );

    UPDATE public.quotations
    SET
        company_id = v_project.company_id,
        user_id = v_project.user_id,
        project_id = v_project.id,
        client_id = v_project.client_id,
        titulo = v_title,
        descripcion_detallada = v_description,
        servicios_incluidos = p_servicios_incluidos,
        precio_base = v_subtotal,
        iva_porcentaje = v_iva,
        precio_total = v_total,
        irpf_aplicado = v_irpf_applied,
        irpf_porcentaje = v_irpf,
        irpf_importe = v_irpf_importe,
        estado = v_state,
        fecha_emision = v_fecha_emision,
        fecha_validez = p_fecha_validez,
        notas = v_notes,

        issuer_legal_name = v_issuer_legal_name,
        issuer_tax_id = v_issuer_tax_id,
        issuer_address = v_issuer_address,
        issuer_postal_code = v_issuer_postal_code,
        issuer_city = v_issuer_city,
        issuer_province = v_issuer_province,
        issuer_country = v_issuer_country,

        customer_legal_name = v_customer_legal_name,
        customer_tax_id = v_customer_tax_id,
        customer_address = v_customer_address,
        customer_postal_code = v_customer_postal_code,
        customer_city = v_customer_city,
        customer_province = v_customer_province,
        customer_country = v_customer_country,
        customer_contact_name = v_customer_contact_name,

        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_quotation_id
    RETURNING *
    INTO v_quotation;

    RETURN v_quotation;

END;
$$;


ALTER FUNCTION "public"."update_quotation_by_worker"("p_quotation_id" "uuid", "p_project_id" "uuid", "p_titulo" "text", "p_descripcion_detallada" "text", "p_servicios_incluidos" "jsonb", "p_iva_porcentaje" numeric, "p_irpf_aplicado" boolean, "p_irpf_porcentaje" numeric, "p_estado" "text", "p_fecha_emision" timestamp with time zone, "p_fecha_validez" timestamp with time zone, "p_notas" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_recurring_expense_template"("p_template_id" "uuid", "p_description" "text", "p_expense_type" "text", "p_category_id" "uuid", "p_supplier_id" "uuid", "p_project_id" "uuid", "p_currency" "text", "p_frequency" "text", "p_start_date" "date", "p_end_date" "date", "p_day_of_month" smallint, "p_subtotal" numeric, "p_total_tax" numeric, "p_total_withholding" numeric, "p_tax_config" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."recurring_expense_templates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_template public.recurring_expense_templates;
  v_total numeric(14,2);
  v_approval_status text;
BEGIN
  PERFORM public.require_expense_permission('expenses.recurring.update');
  PERFORM public.consume_expense_worker_rate_limit('expenses:recurring_update');

  SELECT * INTO v_template
  FROM public.recurring_expense_templates
  WHERE id = p_template_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'La configuración recurrente no existe'; END IF;
  IF v_template.lifecycle_status = 'cancelled' THEN
    RAISE EXCEPTION 'No se puede modificar una recurrencia cancelada';
  END IF;
  IF p_description IS NULL OR length(btrim(p_description)) NOT BETWEEN 1 AND 5000 THEN
    RAISE EXCEPTION 'La descripción debe tener entre 1 y 5000 caracteres';
  END IF;
  IF p_frequency NOT IN ('weekly','monthly','quarterly','yearly') THEN
    RAISE EXCEPTION 'Periodicidad no válida';
  END IF;
  IF p_start_date IS NULL OR (p_end_date IS NOT NULL AND p_end_date < p_start_date) THEN
    RAISE EXCEPTION 'El intervalo de fechas no es válido';
  END IF;
  IF p_subtotal IS NULL OR p_subtotal < 0 OR COALESCE(p_total_tax,0) < 0 OR COALESCE(p_total_withholding,0) < 0 THEN
    RAISE EXCEPTION 'Los importes no pueden ser negativos';
  END IF;
  IF COALESCE(p_currency, 'EUR') !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'La moneda debe ser un código ISO de tres letras en mayúsculas';
  END IF;
  IF p_tax_config IS NOT NULL AND jsonb_typeof(p_tax_config) <> 'array' THEN
    RAISE EXCEPTION 'La configuración de impuestos debe ser una lista JSON';
  END IF;

  v_total := GREATEST(ROUND(COALESCE(p_subtotal,0) + COALESCE(p_total_tax,0) - COALESCE(p_total_withholding,0), 2), 0);
  v_approval_status := CASE WHEN public.expense_requires_approval(v_total, p_category_id) THEN 'pending_review' ELSE 'approved' END;

  UPDATE public.recurring_expense_templates
  SET description = btrim(p_description),
      expense_type = p_expense_type,
      category_id = p_category_id,
      supplier_id = p_supplier_id,
      project_id = p_project_id,
      currency = COALESCE(p_currency, 'EUR'),
      frequency = p_frequency,
      start_date = p_start_date,
      end_date = p_end_date,
      day_of_month = p_day_of_month,
      subtotal = ROUND(p_subtotal,2),
      total_tax = ROUND(COALESCE(p_total_tax,0),2),
      total_withholding = ROUND(COALESCE(p_total_withholding,0),2),
      total_amount = v_total,
      tax_config = COALESCE(p_tax_config,'[]'::jsonb),
      approval_status = v_approval_status,
      approved_by = NULL,
      approved_at = NULL,
      updated_by = auth.uid(),
      updated_at = CURRENT_TIMESTAMP
  WHERE id = p_template_id
  RETURNING * INTO v_template;

  UPDATE public.recurring_expense_forecasts
  SET description = v_template.description,
      currency = v_template.currency,
      subtotal = v_template.subtotal,
      total_tax = v_template.total_tax,
      total_withholding = v_template.total_withholding,
      total_amount = v_template.total_amount,
      category_id = v_template.category_id,
      supplier_id = v_template.supplier_id,
      project_id = v_template.project_id,
      tax_config = v_template.tax_config
  WHERE recurring_template_id = p_template_id
    AND occurrence_date >= CURRENT_DATE
    AND status = 'pending';

  RETURN v_template;
END;
$_$;


ALTER FUNCTION "public"."update_recurring_expense_template"("p_template_id" "uuid", "p_description" "text", "p_expense_type" "text", "p_category_id" "uuid", "p_supplier_id" "uuid", "p_project_id" "uuid", "p_currency" "text", "p_frequency" "text", "p_start_date" "date", "p_end_date" "date", "p_day_of_month" smallint, "p_subtotal" numeric, "p_total_tax" numeric, "p_total_withholding" numeric, "p_tax_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_updated_at_column"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_updated_at_column"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_worker_custom_role"("p_role_id" "uuid", "p_name" "text", "p_description" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_name text;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required'
            USING ERRCODE = '42501';
    END IF;

    IF NOT public.current_user_can_manage_worker_roles() THEN
        RAISE EXCEPTION 'Insufficient permissions to update worker roles'
            USING ERRCODE = '42501';
    END IF;

    v_name := BTRIM(COALESCE(p_name, ''));

    IF p_role_id IS NULL OR v_name = '' THEN
        RAISE EXCEPTION 'Role id and name are required'
            USING ERRCODE = '22023';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.worker_roles r
        WHERE r.id = p_role_id
          AND r.is_system_role = FALSE
    ) THEN
        RAISE EXCEPTION 'Role not found or system roles cannot be edited'
            USING ERRCODE = '42501';
    END IF;

    UPDATE public.worker_roles
    SET
        name = v_name,
        description = NULLIF(BTRIM(COALESCE(p_description, '')), ''),
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_role_id
      AND is_system_role = FALSE;

    RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."update_worker_custom_role"("p_role_id" "uuid", "p_name" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_automation_run_company"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
v_company_id UUID;
BEGIN
SELECT company_id
INTO v_company_id
FROM public.automations
WHERE id = NEW.automation_id;
IF v_company_id IS NULL THEN
RAISE EXCEPTION
'La automatización indicada no existe';
END IF;
IF v_company_id <> NEW.company_id THEN
RAISE EXCEPTION
'automation_runs.company_id no coincide con la empresa de
la automatización';
END IF;
RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_automation_run_company"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_custom_maintenance_contract"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_plan public.maintenance_plans;
    v_proposal public.maintenance_custom_proposals;

BEGIN

    SELECT *
    INTO v_plan
    FROM public.maintenance_plans
    WHERE id = NEW.plan_id;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El plan de mantenimiento no existe';
    END IF;


    IF v_plan.es_personalizado = TRUE THEN

        IF NEW.agreed_monthly_price IS NULL
           OR NEW.agreed_monthly_price <= 0
        THEN
            RAISE EXCEPTION
                'Un contrato personalizado debe tener un precio mensual acordado';
        END IF;


        IF NEW.maintenance_custom_proposal_id IS NULL THEN
            RAISE EXCEPTION
                'Un contrato personalizado debe estar vinculado a una propuesta';
        END IF;


        SELECT *
        INTO v_proposal
        FROM public.maintenance_custom_proposals
        WHERE id = NEW.maintenance_custom_proposal_id;


        IF NOT FOUND THEN
            RAISE EXCEPTION
                'La propuesta personalizada no existe';
        END IF;


        IF v_proposal.status <> 'accepted' THEN
            RAISE EXCEPTION
                'La propuesta personalizada todavía no ha sido aceptada';
        END IF;


        IF v_proposal.company_id IS DISTINCT FROM NEW.company_id THEN
            RAISE EXCEPTION
                'La propuesta no pertenece a la empresa del contrato';
        END IF;


        IF v_proposal.user_id IS DISTINCT FROM NEW.user_id THEN
            RAISE EXCEPTION
                'La propuesta no pertenece al usuario del contrato';
        END IF;


        IF v_proposal.quoted_monthly_price IS DISTINCT FROM NEW.agreed_monthly_price THEN
            RAISE EXCEPTION
                'El precio del contrato no coincide con el precio aceptado de la propuesta';
        END IF;

    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_custom_maintenance_contract"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_custom_maintenance_proposal_content"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_limits RECORD;
    v_total_words INTEGER := 0;
    v_request_data_bytes INTEGER := 0;
    v_text TEXT;
BEGIN

    SELECT *
    INTO v_limits
    FROM public.maintenance_custom_proposal_security_limits();

    -- --------------------------------------------------------
    -- TÍTULO
    -- --------------------------------------------------------

    IF NEW.titulo IS NULL
       OR LENGTH(BTRIM(NEW.titulo)) = 0
    THEN
        RAISE EXCEPTION
            'El título de la propuesta es obligatorio';
    END IF;

    IF LENGTH(NEW.titulo) > 300 THEN
        RAISE EXCEPTION
            'El título no puede superar 300 caracteres';
    END IF;


    -- --------------------------------------------------------
    -- CAMPOS DE TEXTO DEL CLIENTE
    -- --------------------------------------------------------

    IF NEW.descripcion_necesidad IS NOT NULL
       AND LENGTH(NEW.descripcion_necesidad) > 6000
    THEN
        RAISE EXCEPTION
            'La descripción de la necesidad no puede superar 6000 caracteres';
    END IF;

    IF NEW.objetivos IS NOT NULL
       AND LENGTH(NEW.objetivos) > 5000
    THEN
        RAISE EXCEPTION
            'Los objetivos no pueden superar 5000 caracteres';
    END IF;

    IF NEW.prioridades IS NOT NULL
       AND LENGTH(NEW.prioridades) > 4000
    THEN
        RAISE EXCEPTION
            'Las prioridades no pueden superar 4000 caracteres';
    END IF;

    IF NEW.soluciones_actuales IS NOT NULL
       AND LENGTH(NEW.soluciones_actuales) > 6000
    THEN
        RAISE EXCEPTION
            'Las soluciones actuales no pueden superar 6000 caracteres';
    END IF;

    IF NEW.proyectos_relacionados IS NOT NULL
       AND LENGTH(NEW.proyectos_relacionados) > 5000
    THEN
        RAISE EXCEPTION
            'Los proyectos relacionados no pueden superar 5000 caracteres';
    END IF;

    IF NEW.automatizaciones_actuales IS NOT NULL
       AND LENGTH(NEW.automatizaciones_actuales) > 6000
    THEN
        RAISE EXCEPTION
            'Las automatizaciones actuales no pueden superar 6000 caracteres';
    END IF;

    IF NEW.integraciones_actuales IS NOT NULL
       AND LENGTH(NEW.integraciones_actuales) > 6000
    THEN
        RAISE EXCEPTION
            'Las integraciones actuales no pueden superar 6000 caracteres';
    END IF;

    IF NEW.tecnologias IS NOT NULL
       AND LENGTH(NEW.tecnologias) > 4000
    THEN
        RAISE EXCEPTION
            'Las tecnologías no pueden superar 4000 caracteres';
    END IF;

    IF NEW.sistemas_criticos IS NOT NULL
       AND LENGTH(NEW.sistemas_criticos) > 6000
    THEN
        RAISE EXCEPTION
            'Los sistemas críticos no pueden superar 6000 caracteres';
    END IF;

    IF NEW.alcance_tecnico_solicitado IS NOT NULL
       AND LENGTH(NEW.alcance_tecnico_solicitado) > 8000
    THEN
        RAISE EXCEPTION
            'El alcance técnico no puede superar 8000 caracteres';
    END IF;

    IF NEW.tipo_trabajo IS NOT NULL
       AND LENGTH(NEW.tipo_trabajo) > 500
    THEN
        RAISE EXCEPTION
            'El tipo de trabajo no puede superar 500 caracteres';
    END IF;

    IF NEW.nivel_soporte_solicitado IS NOT NULL
       AND LENGTH(NEW.nivel_soporte_solicitado) > 1000
    THEN
        RAISE EXCEPTION
            'El nivel de soporte no puede superar 1000 caracteres';
    END IF;

    IF NEW.tiempo_respuesta_deseado IS NOT NULL
       AND LENGTH(NEW.tiempo_respuesta_deseado) > 1000
    THEN
        RAISE EXCEPTION
            'El tiempo de respuesta no puede superar 1000 caracteres';
    END IF;

    IF NEW.horario_soporte IS NOT NULL
       AND LENGTH(NEW.horario_soporte) > 1500
    THEN
        RAISE EXCEPTION
            'El horario de soporte no puede superar 1500 caracteres';
    END IF;

    IF NEW.sla_solicitado IS NOT NULL
       AND LENGTH(NEW.sla_solicitado) > 2000
    THEN
        RAISE EXCEPTION
            'El SLA solicitado no puede superar 2000 caracteres';
    END IF;

    IF NEW.nivel_criticidad IS NOT NULL
       AND LENGTH(NEW.nivel_criticidad) > 1000
    THEN
        RAISE EXCEPTION
            'El nivel de criticidad no puede superar 1000 caracteres';
    END IF;

    IF NEW.impacto_incidencia IS NOT NULL
       AND LENGTH(NEW.impacto_incidencia) > 3000
    THEN
        RAISE EXCEPTION
            'El impacto de una incidencia no puede superar 3000 caracteres';
    END IF;

    IF NEW.requisitos_seguridad IS NOT NULL
       AND LENGTH(NEW.requisitos_seguridad) > 6000
    THEN
        RAISE EXCEPTION
            'Los requisitos de seguridad no pueden superar 6000 caracteres';
    END IF;

    IF NEW.informacion_adicional IS NOT NULL
       AND LENGTH(NEW.informacion_adicional) > 6000
    THEN
        RAISE EXCEPTION
            'La información adicional no puede superar 6000 caracteres';
    END IF;


    -- --------------------------------------------------------
    -- HORAS MENSUALES
    -- --------------------------------------------------------

    IF NEW.horas_mensuales_solicitadas IS NOT NULL THEN

        IF NEW.horas_mensuales_solicitadas <= 0 THEN
            RAISE EXCEPTION
                'Las horas mensuales solicitadas deben ser mayores que 0';
        END IF;

        IF NEW.horas_mensuales_solicitadas > v_limits.max_hours_monthly THEN
            RAISE EXCEPTION
                'Las horas mensuales solicitadas no pueden superar % horas',
                v_limits.max_hours_monthly;
        END IF;

    END IF;


    -- --------------------------------------------------------
    -- REQUEST_DATA
    -- --------------------------------------------------------

    IF NEW.request_data IS NULL
       OR jsonb_typeof(NEW.request_data) <> 'object'
    THEN
        RAISE EXCEPTION
            'request_data debe ser un objeto JSON';
    END IF;

    v_request_data_bytes := pg_column_size(NEW.request_data);

    IF v_request_data_bytes > v_limits.max_request_data_bytes THEN
        RAISE EXCEPTION
            'Los datos adicionales de la propuesta superan el límite permitido de % KB',
            ROUND(v_limits.max_request_data_bytes / 1024.0, 0);
    END IF;


    -- --------------------------------------------------------
    -- LÍMITE TOTAL DE PALABRAS
    -- --------------------------------------------------------
    --
    -- Se cuentan las palabras de los campos descriptivos.
    -- Los campos cortos/categóricos también quedan protegidos
    -- por sus límites de caracteres anteriores.
    --

    FOREACH v_text IN ARRAY ARRAY[
        NEW.titulo,
        NEW.descripcion_necesidad,
        NEW.objetivos,
        NEW.prioridades,
        NEW.soluciones_actuales,
        NEW.proyectos_relacionados,
        NEW.automatizaciones_actuales,
        NEW.integraciones_actuales,
        NEW.tecnologias,
        NEW.sistemas_criticos,
        NEW.alcance_tecnico_solicitado,
        NEW.tipo_trabajo,
        NEW.nivel_soporte_solicitado,
        NEW.tiempo_respuesta_deseado,
        NEW.horario_soporte,
        NEW.sla_solicitado,
        NEW.nivel_criticidad,
        NEW.impacto_incidencia,
        NEW.requisitos_seguridad,
        NEW.informacion_adicional
    ]
    LOOP
        IF v_text IS NOT NULL AND BTRIM(v_text) <> '' THEN
            v_total_words :=
                v_total_words
                + COALESCE(
                    array_length(
                        regexp_split_to_array(
                            BTRIM(v_text),
                            '\s+'
                        ),
                        1
                    ),
                    0
                );
        END IF;
    END LOOP;


    IF v_total_words > v_limits.max_total_words THEN
        RAISE EXCEPTION
            'La propuesta supera el límite total de % palabras',
            v_limits.max_total_words;
    END IF;


    -- --------------------------------------------------------
    -- LIMITAR CAMPOS DE COTIZACIÓN DE MODIRA
    -- --------------------------------------------------------
    --
    -- También protegemos el contenido introducido por trabajadores
    -- para evitar que request/response termine almacenando cantidades
    -- arbitrarias de texto.
    --

    IF NEW.quoted_scope_level IS NOT NULL
       AND LENGTH(NEW.quoted_scope_level) > 1000
    THEN
        RAISE EXCEPTION
            'El nivel de alcance cotizado no puede superar 1000 caracteres';
    END IF;

    IF NEW.quoted_service_level IS NOT NULL
       AND LENGTH(NEW.quoted_service_level) > 1500
    THEN
        RAISE EXCEPTION
            'El nivel de servicio cotizado no puede superar 1500 caracteres';
    END IF;

    IF NEW.quoted_sla IS NOT NULL
       AND LENGTH(NEW.quoted_sla) > 2500
    THEN
        RAISE EXCEPTION
            'El SLA cotizado no puede superar 2500 caracteres';
    END IF;

    IF NEW.quoted_response_time IS NOT NULL
       AND LENGTH(NEW.quoted_response_time) > 1000
    THEN
        RAISE EXCEPTION
            'El tiempo de respuesta cotizado no puede superar 1000 caracteres';
    END IF;

    IF NEW.quoted_support_hours IS NOT NULL
       AND LENGTH(NEW.quoted_support_hours) > 1500
    THEN
        RAISE EXCEPTION
            'El horario de soporte cotizado no puede superar 1500 caracteres';
    END IF;

    IF NEW.quoted_description IS NOT NULL
       AND LENGTH(NEW.quoted_description) > 8000
    THEN
        RAISE EXCEPTION
            'La descripción de la cotización no puede superar 8000 caracteres';
    END IF;

    IF NEW.quoted_terms IS NOT NULL
       AND LENGTH(NEW.quoted_terms) > 12000
    THEN
        RAISE EXCEPTION
            'Los términos de la cotización no pueden superar 12000 caracteres';
    END IF;


    -- --------------------------------------------------------
    -- PRECIO COTIZADO
    -- --------------------------------------------------------

    IF NEW.quoted_monthly_price IS NOT NULL THEN
        IF NEW.quoted_monthly_price < 0
           OR NEW.quoted_monthly_price > 1000000
        THEN
            RAISE EXCEPTION
                'El precio mensual cotizado está fuera del rango permitido';
        END IF;
    END IF;


    -- --------------------------------------------------------
    -- HORAS COTIZADAS
    -- --------------------------------------------------------

    IF NEW.quoted_hours_monthly IS NOT NULL THEN

        IF NEW.quoted_hours_monthly <= 0 THEN
            RAISE EXCEPTION
                'Las horas mensuales cotizadas deben ser mayores que 0';
        END IF;

        IF NEW.quoted_hours_monthly > v_limits.max_hours_monthly THEN
            RAISE EXCEPTION
                'Las horas mensuales cotizadas no pueden superar % horas',
                v_limits.max_hours_monthly;
        END IF;

    END IF;


    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_custom_maintenance_proposal_content"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_expense_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_expense_total NUMERIC(14,2);

  v_direct_project_id UUID;

  v_allocated_amount NUMERIC(14,2);

  v_new_allocated_amount NUMERIC(14,2);

  v_percentage NUMERIC(7,4);

BEGIN

  -- ==========================================================
  -- DELETE
  -- ==========================================================

  IF TG_OP = 'DELETE' THEN

    RETURN OLD;

  END IF;


  -- ==========================================================
  -- Bloquear el gasto.
  --
  -- Esto evita carreras entre dos asignaciones simultáneas.
  -- ==========================================================

  SELECT
    total_amount,
    project_id

  INTO
    v_expense_total,
    v_direct_project_id

  FROM public.expenses

  WHERE id = NEW.expense_id

  FOR UPDATE;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El gasto % no existe',
      NEW.expense_id;

  END IF;


  v_expense_total :=
    ROUND(
      GREATEST(
        COALESCE(v_expense_total, 0),
        0
      ),
      2
    );


  -- ==========================================================
  -- No permitir asignación directa + allocations.
  -- ==========================================================

  IF v_direct_project_id IS NOT NULL THEN

    RAISE EXCEPTION
      'El gasto % ya está asociado directamente al proyecto %. No puede utilizar expense_allocations.',
      NEW.expense_id,
      v_direct_project_id;

  END IF;


  -- ==========================================================
  -- El importe debe ser positivo.
  -- ==========================================================

  IF NEW.amount <= 0 THEN

    RAISE EXCEPTION
      'El importe de una asignación debe ser mayor que 0';

  END IF;


  -- ==========================================================
  -- Calcular lo ya asignado.
  --
  -- En UPDATE se excluye la propia fila.
  -- ==========================================================

  SELECT
    ROUND(
      COALESCE(
        SUM(amount),
        0
      ),
      2
    )

  INTO
    v_allocated_amount

  FROM public.expense_allocations

  WHERE expense_id = NEW.expense_id

    AND id IS DISTINCT FROM NEW.id;


  v_new_allocated_amount :=
    ROUND(
      v_allocated_amount + NEW.amount,
      2
    );


  -- ==========================================================
  -- No superar el total del gasto.
  -- ==========================================================

  IF v_new_allocated_amount > v_expense_total THEN

    RAISE EXCEPTION
      'Las asignaciones del gasto superan su importe total. Total del gasto: %, ya asignado: %, nueva asignación: %',
      v_expense_total,
      v_allocated_amount,
      NEW.amount;

  END IF;


  -- ==========================================================
  -- Calcular porcentaje automáticamente.
  --
  -- No confiamos en el porcentaje enviado por el frontend.
  -- ==========================================================

  IF v_expense_total > 0 THEN

    v_percentage :=
      ROUND(
        (
          NEW.amount
          / v_expense_total
        ) * 100,
        4
      );

  ELSE

    v_percentage := 0;

  END IF;


  NEW.percentage := v_percentage;


  RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_expense_allocation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_expense_document_storage_path"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_first_segment TEXT;
BEGIN

  v_first_segment :=
    split_part(
      TRIM(BOTH '/' FROM NEW.storage_path),
      '/',
      1
    );


  IF v_first_segment <> NEW.expense_id::TEXT THEN

    RAISE EXCEPTION
      'La ruta del documento no pertenece al gasto indicado';

  END IF;


  IF NEW.storage_path !~* '\.pdf$' THEN

    RAISE EXCEPTION
      'Los documentos de gastos deben ser archivos PDF';

  END IF;


  RETURN NEW;

END;
$_$;


ALTER FUNCTION "public"."validate_expense_document_storage_path"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_expense_payment_amount"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_total_amount NUMERIC(14,2);

  v_paid_amount NUMERIC(14,2);

  v_new_paid_amount NUMERIC(14,2);

BEGIN

  -- ----------------------------------------------------------
  -- Solo necesitamos comprobar el límite cuando el pago
  -- pasa a succeeded.
  -- ----------------------------------------------------------

  IF NEW.status <> 'succeeded' THEN

    RETURN NEW;

  END IF;


  SELECT
    total_amount

  INTO
    v_total_amount

  FROM public.expenses

  WHERE id = NEW.expense_id

  FOR UPDATE;


  IF NOT FOUND THEN

    RAISE EXCEPTION
      'El gasto asociado al pago no existe';

  END IF;


  v_total_amount :=
    ROUND(
      GREATEST(
        COALESCE(v_total_amount, 0),
        0
      ),
      2
    );


  -- ----------------------------------------------------------
  -- Pagos succeeded anteriores.
  --
  -- En UPDATE excluimos el propio registro para evitar
  -- contabilizarlo dos veces.
  -- ----------------------------------------------------------

  SELECT
    ROUND(
      COALESCE(
        SUM(amount),
        0
      ),
      2
    )

  INTO
    v_paid_amount

  FROM public.expense_payments

  WHERE expense_id = NEW.expense_id

    AND status = 'succeeded'

    AND id IS DISTINCT FROM NEW.id;


  v_new_paid_amount :=
    ROUND(
      v_paid_amount + NEW.amount,
      2
    );


  IF v_new_paid_amount > v_total_amount THEN

    RAISE EXCEPTION
      'El pago de % supera el importe pendiente del gasto. Total del gasto: %, ya pagado: %, nuevo pago: %',
      NEW.amount,
      v_total_amount,
      v_paid_amount,
      NEW.amount;

  END IF;


  RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_expense_payment_amount"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_expense_payment_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

  IF TG_OP = 'UPDATE' THEN

    -- --------------------------------------------------------
    -- No se permite modificar el gasto al que pertenece
    -- --------------------------------------------------------

    IF NEW.expense_id IS DISTINCT FROM OLD.expense_id THEN

      RAISE EXCEPTION
        'No se puede cambiar el expense_id de un pago existente';

    END IF;


    -- --------------------------------------------------------
    -- Un pago confirmado es inmutable
    -- --------------------------------------------------------

    IF OLD.status = 'succeeded' THEN

      IF NEW.status IS DISTINCT FROM OLD.status THEN

        RAISE EXCEPTION
          'Un pago succeeded no puede cambiar de estado';

      END IF;


      IF NEW.amount IS DISTINCT FROM OLD.amount THEN

        RAISE EXCEPTION
          'No se puede modificar el importe de un pago succeeded';

      END IF;


      IF NEW.payment_date IS DISTINCT FROM OLD.payment_date THEN

        RAISE EXCEPTION
          'No se puede modificar la fecha de un pago succeeded';

      END IF;


      IF NEW.payment_method IS DISTINCT FROM OLD.payment_method THEN

        RAISE EXCEPTION
          'No se puede modificar el método de un pago succeeded';

      END IF;


      IF NEW.reference IS DISTINCT FROM OLD.reference THEN

        RAISE EXCEPTION
          'No se puede modificar la referencia de un pago succeeded';

      END IF;

    END IF;


    -- --------------------------------------------------------
    -- Estados finales no pueden reabrirse
    -- --------------------------------------------------------

    IF OLD.status IN ('failed', 'cancelled')
       AND NEW.status IS DISTINCT FROM OLD.status THEN

      RAISE EXCEPTION
        'Un pago % no puede cambiar posteriormente de estado',
        OLD.status;

    END IF;


    -- --------------------------------------------------------
    -- pending solamente puede pasar a un estado final
    -- --------------------------------------------------------

    IF OLD.status = 'pending'
       AND NEW.status NOT IN (
         'pending',
         'succeeded',
         'failed',
         'cancelled'
       ) THEN

      RAISE EXCEPTION
        'Transición de estado de pago no válida';

    END IF;

  END IF;


  RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_expense_payment_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_expense_project_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_allocation_count INTEGER;

BEGIN

  -- ----------------------------------------------------------
  -- Si no hay proyecto directo, no hay nada que comprobar.
  -- ----------------------------------------------------------

  IF NEW.project_id IS NULL THEN

    RETURN NEW;

  END IF;


  -- ----------------------------------------------------------
  -- Comprobar si existen allocations.
  -- ----------------------------------------------------------

  SELECT COUNT(*)
  INTO v_allocation_count

  FROM public.expense_allocations

  WHERE expense_id = NEW.id;


  IF v_allocation_count > 0 THEN

    RAISE EXCEPTION
      'El gasto % ya tiene asignaciones a proyectos. No puede establecerse project_id directamente.',
      NEW.id;

  END IF;


  RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_expense_project_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_expense_total_against_allocations"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE

  v_allocated NUMERIC(14,2);

BEGIN

  IF NEW.total_amount IS DISTINCT FROM OLD.total_amount THEN

    SELECT
      ROUND(
        COALESCE(
          SUM(amount),
          0
        ),
        2
      )

    INTO
      v_allocated

    FROM public.expense_allocations

    WHERE expense_id = NEW.id;


    IF v_allocated > NEW.total_amount THEN

      RAISE EXCEPTION
        'No se puede reducir el total del gasto % por debajo de las asignaciones existentes. Total nuevo: %, asignado: %',
        NEW.id,
        NEW.total_amount,
        v_allocated;

    END IF;

  END IF;


  RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_expense_total_against_allocations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_maintenance_contract_activation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    IF LOWER(COALESCE(NEW.estado, '')) = 'activo'
       AND LOWER(COALESCE(OLD.estado, '')) IS DISTINCT FROM 'activo'
    THEN

        IF EXISTS (
            SELECT 1
            FROM public.maintenance_contract_projects mcp
            JOIN public.maintenance_contracts other_mc
              ON other_mc.id = mcp.maintenance_contract_id
            WHERE mcp.maintenance_contract_id = NEW.id
              AND other_mc.id <> NEW.id
              AND other_mc.estado = 'activo'
        ) THEN
            RAISE EXCEPTION
                'No se puede activar el contrato porque alguno de sus proyectos ya tiene otro contrato activo.';
        END IF;

        IF EXISTS (
            SELECT 1
            FROM public.maintenance_contract_projects mcp
            JOIN public.maintenance_contract_projects other_mcp
              ON other_mcp.project_id = mcp.project_id
             AND other_mcp.maintenance_contract_id <> mcp.maintenance_contract_id
            JOIN public.maintenance_contracts other_mc
              ON other_mc.id = other_mcp.maintenance_contract_id
            WHERE mcp.maintenance_contract_id = NEW.id
              AND other_mc.estado = 'activo'
        ) THEN
            RAISE EXCEPTION
                'No se puede activar el contrato porque uno de sus proyectos ya está cubierto por otro contrato activo.';
        END IF;

    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_maintenance_contract_activation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_maintenance_contract_automation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_contract_company UUID;
  v_automation_company UUID;
BEGIN
  SELECT company_id
  INTO v_contract_company
  FROM public.maintenance_contracts
  WHERE id = NEW.maintenance_contract_id;

  SELECT company_id
  INTO v_automation_company
  FROM public.automations
  WHERE id = NEW.automation_id;

  IF v_contract_company IS NULL
     OR v_automation_company IS NULL
     OR v_contract_company IS DISTINCT FROM v_automation_company
  THEN
    RAISE EXCEPTION
      'La automatización no pertenece a la misma empresa que el contrato de mantenimiento';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_maintenance_contract_automation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_maintenance_contract_fiscal_data"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_company public.companies;
BEGIN
  SELECT *
  INTO v_company
  FROM public.companies
  WHERE id = NEW.company_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'La empresa del contrato de mantenimiento no existe';
  END IF;

  IF NULLIF(BTRIM(v_company.cif_vat), '') IS NULL THEN
    RAISE EXCEPTION
      'La empresa debe tener NIF/CIF/VAT antes de contratar mantenimiento';
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_company.legal_name, v_company.company_name)), '') IS NULL THEN
    RAISE EXCEPTION
      'La empresa debe tener razón social antes de contratar mantenimiento';
  END IF;

  IF NULLIF(BTRIM(v_company.address), '') IS NULL
     OR NULLIF(BTRIM(v_company.postal_code), '') IS NULL
     OR NULLIF(BTRIM(v_company.city), '') IS NULL
  THEN
    RAISE EXCEPTION
      'La empresa debe tener dirección fiscal, código postal y ciudad antes de contratar mantenimiento';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_maintenance_contract_fiscal_data"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_maintenance_contract_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_project_id UUID;
    v_other_contract_id UUID;
BEGIN

    -- ========================================================
    -- 1. LOCK DEL CONTRATO
    -- ========================================================

    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            'maintenance-contract:' ||
            NEW.id::TEXT,
            0
        )
    );


    -- ========================================================
    -- 2. SI EL CONTRATO NO ESTÁ VIVO
    -- ========================================================

    IF NOT public.is_live_maintenance_contract_status(
        NEW.estado
    ) THEN

        RETURN NEW;

    END IF;


    -- ========================================================
    -- 3. UN CONTRATO VIVO → COMO MÁXIMO UN PROYECTO
    -- ========================================================

    SELECT mcp.project_id
    INTO v_project_id
    FROM public.maintenance_contract_projects mcp
    WHERE mcp.maintenance_contract_id = NEW.id
    ORDER BY mcp.created_at, mcp.id
    OFFSET 1
    LIMIT 1;


    IF v_project_id IS NOT NULL THEN

        RAISE EXCEPTION
            'El contrato de mantenimiento % tiene más de un proyecto asociado y no puede permanecer activo/pausado.',
            NEW.id;

    END IF;


    -- ========================================================
    -- 4. COMPROBAR CONFLICTO DE PROYECTO
    -- ========================================================

    IF EXISTS (
        SELECT 1
        FROM public.maintenance_contract_projects mcp
        JOIN public.maintenance_contracts other_mc
          ON other_mc.id = mcp.maintenance_contract_id
        WHERE mcp.maintenance_contract_id = NEW.id
          AND mcp.project_id IS NOT NULL
          AND other_mc.id <> NEW.id
        LIMIT 1
    ) THEN

        SELECT other_mc.id
        INTO v_other_contract_id
        FROM public.maintenance_contract_projects mcp
        JOIN public.maintenance_contracts other_mc
          ON other_mc.id = mcp.maintenance_contract_id
        WHERE mcp.project_id IN (
            SELECT mcp2.project_id
            FROM public.maintenance_contract_projects mcp2
            WHERE mcp2.maintenance_contract_id = NEW.id
        )
          AND other_mc.id <> NEW.id
          AND public.is_live_maintenance_contract_status(
              other_mc.estado
          )
        LIMIT 1;


        IF v_other_contract_id IS NOT NULL THEN

            RAISE EXCEPTION
                'El contrato de mantenimiento % intenta quedar activo/pausado sobre un proyecto que ya pertenece al contrato activo/pausado %.',
                NEW.id,
                v_other_contract_id;

        END IF;

    END IF;


    -- ========================================================
    -- 5. LOCK DE LOS PROYECTOS ASOCIADOS
    -- ========================================================
    --
    -- Se hace después del lock del contrato para mantener el mismo
    -- orden de bloqueo que utiliza la función de relaciones.
    -- ========================================================

    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            'maintenance-project:' ||
            mcp.project_id::TEXT,
            0
        )
    )
    FROM public.maintenance_contract_projects mcp
    WHERE mcp.maintenance_contract_id = NEW.id;


    -- ========================================================
    -- 6. COMPROBACIÓN DEFINITIVA TRAS LOS LOCKS
    -- ========================================================

    SELECT other_mc.id
    INTO v_other_contract_id
    FROM public.maintenance_contract_projects mcp
    JOIN public.maintenance_contracts other_mc
      ON other_mc.id = mcp.maintenance_contract_id
    WHERE mcp.maintenance_contract_id = NEW.id
      AND public.is_live_maintenance_contract_status(
          other_mc.estado
      )
      AND EXISTS (
          SELECT 1
          FROM public.maintenance_contract_projects other_mcp
          WHERE other_mcp.project_id = mcp.project_id
            AND other_mcp.maintenance_contract_id <> NEW.id
      )
    LIMIT 1;


    IF v_other_contract_id IS NOT NULL THEN

        RAISE EXCEPTION
            'El proyecto asociado al contrato % ya está cubierto por el contrato activo/pausado %.',
            NEW.id,
            v_other_contract_id;

    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_maintenance_contract_integrity"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_maintenance_contract_integrity"() IS 'Protege la activación/pausa de contratos de mantenimiento para impedir que un contrato vivo tenga múltiples proyectos o que comparta proyecto con otro contrato vivo.';



CREATE OR REPLACE FUNCTION "public"."validate_maintenance_contract_project"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_contract_company_id UUID;
    v_project_company_id UUID;
    v_contract_status TEXT;
BEGIN

    -- --------------------------------------------------------
    -- El contrato debe existir
    -- --------------------------------------------------------

    SELECT
        mc.company_id,
        mc.estado
    INTO
        v_contract_company_id,
        v_contract_status
    FROM public.maintenance_contracts mc
    WHERE mc.id = NEW.maintenance_contract_id;

    IF v_contract_company_id IS NULL THEN
        RAISE EXCEPTION
            'El contrato de mantenimiento no existe.';
    END IF;


    -- --------------------------------------------------------
    -- El proyecto debe existir y pertenecer a la misma empresa
    -- --------------------------------------------------------

    SELECT p.company_id
    INTO v_project_company_id
    FROM public.projects p
    WHERE p.id = NEW.project_id;

    IF v_project_company_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto de mantenimiento no existe.';
    END IF;


    IF v_project_company_id IS DISTINCT FROM v_contract_company_id THEN
        RAISE EXCEPTION
            'El proyecto no pertenece a la misma empresa que el contrato.';
    END IF;


    -- --------------------------------------------------------
    -- Un proyecto no puede tener dos contratos ACTIVOS
    -- --------------------------------------------------------

    IF LOWER(COALESCE(v_contract_status, '')) = 'activo' THEN

        IF EXISTS (
            SELECT 1
            FROM public.maintenance_contract_projects mcp
            JOIN public.maintenance_contracts mc
              ON mc.id = mcp.maintenance_contract_id
            WHERE mcp.project_id = NEW.project_id
              AND mc.estado = 'activo'
              AND mc.id <> NEW.maintenance_contract_id
        ) THEN

            RAISE EXCEPTION
                'El proyecto ya tiene otro contrato de mantenimiento activo.';
        END IF;

    END IF;


    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_maintenance_contract_project"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_maintenance_contract_project_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_contract_status TEXT;
    v_contract_is_live BOOLEAN;

    v_existing_project_id UUID;
    v_existing_contract_id UUID;

BEGIN

    -- ========================================================
    -- 1. OBTENER ESTADO DEL CONTRATO
    -- ========================================================

    SELECT mc.estado
    INTO v_contract_status
    FROM public.maintenance_contracts mc
    WHERE mc.id = NEW.maintenance_contract_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El contrato de mantenimiento indicado no existe';
    END IF;


    v_contract_is_live :=
        public.is_live_maintenance_contract_status(
            v_contract_status
        );


    -- ========================================================
    -- 2. LOCK DEL CONTRATO
    -- ========================================================
    --
    -- Siempre bloqueamos primero el contrato y después el proyecto.
    -- Esto mantiene un orden consistente y reduce el riesgo de deadlocks
    -- cuando existen operaciones concurrentes.
    -- ========================================================

    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            'maintenance-contract:' ||
            NEW.maintenance_contract_id::TEXT,
            0
        )
    );


    -- ========================================================
    -- 3. LOCK DEL PROYECTO
    -- ========================================================

    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            'maintenance-project:' ||
            NEW.project_id::TEXT,
            0
        )
    );


    -- ========================================================
    -- 4. SI EL CONTRATO NO ESTÁ VIVO
    -- ========================================================
    --
    -- Los contratos históricos pueden conservar relaciones.
    --
    -- Por tanto:
    --
    -- CANCELADO + PROYECTO
    --
    -- sigue siendo válido.
    -- ========================================================

    IF NOT v_contract_is_live THEN

        RETURN NEW;

    END IF;


    -- ========================================================
    -- 5. UN CONTRATO VIVO → COMO MÁXIMO UN PROYECTO
    -- ========================================================

    SELECT mcp.project_id
    INTO v_existing_project_id
    FROM public.maintenance_contract_projects mcp
    WHERE mcp.maintenance_contract_id =
          NEW.maintenance_contract_id
      AND mcp.id IS DISTINCT FROM NEW.id
    LIMIT 1;


    IF v_existing_project_id IS NOT NULL THEN

        RAISE EXCEPTION
            'El contrato de mantenimiento % ya está asociado al proyecto %. Un contrato activo o pausado solo puede cubrir un proyecto.',
            NEW.maintenance_contract_id,
            v_existing_project_id;

    END IF;


    -- ========================================================
    -- 6. UN PROYECTO VIVO → COMO MÁXIMO UN CONTRATO VIVO
    -- ========================================================

    SELECT mcp.maintenance_contract_id
    INTO v_existing_contract_id
    FROM public.maintenance_contract_projects mcp
    JOIN public.maintenance_contracts mc
      ON mc.id = mcp.maintenance_contract_id
    WHERE mcp.project_id = NEW.project_id
      AND mcp.id IS DISTINCT FROM NEW.id
      AND public.is_live_maintenance_contract_status(
          mc.estado
      )
    LIMIT 1;


    IF v_existing_contract_id IS NOT NULL THEN

        RAISE EXCEPTION
            'El proyecto % ya está asociado al contrato de mantenimiento activo/pausado %. No puede existir más de un contrato de mantenimiento activo por proyecto.',
            NEW.project_id,
            v_existing_contract_id;

    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_maintenance_contract_project_integrity"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_maintenance_contract_project_integrity"() IS 'Protección de integridad contrato-proyecto: un contrato activo/pausado solo puede cubrir un proyecto y un proyecto solo puede tener un contrato activo/pausado. Incluye advisory locks para evitar carreras concurrentes.';



CREATE OR REPLACE FUNCTION "public"."validate_maintenance_invoice_project"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_contract_company_id UUID;
  v_project_company_id UUID;
BEGIN
  IF NEW.project_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.maintenance_contract_id IS NULL THEN
    RAISE EXCEPTION
      'Una factura de mantenimiento con project_id debe tener maintenance_contract_id';
  END IF;

  SELECT company_id
  INTO v_contract_company_id
  FROM public.maintenance_contracts
  WHERE id = NEW.maintenance_contract_id;

  IF v_contract_company_id IS NULL THEN
    RAISE EXCEPTION
      'El contrato de mantenimiento de la factura no existe o no tiene empresa';
  END IF;

  SELECT company_id
  INTO v_project_company_id
  FROM public.projects
  WHERE id = NEW.project_id;

  IF v_project_company_id IS NULL THEN
    RAISE EXCEPTION
      'El proyecto de la factura no existe o no tiene empresa';
  END IF;

  IF v_project_company_id IS DISTINCT FROM v_contract_company_id THEN
    RAISE EXCEPTION
      'El proyecto de la factura no pertenece a la misma empresa que el contrato';
  END IF;

  -- Para una factura de un periodo nuevo exigimos que el proyecto esté
  -- asociado al contrato en el momento de emisión.
  IF NOT EXISTS (
    SELECT 1
    FROM public.maintenance_contract_projects mcp
    WHERE mcp.maintenance_contract_id = NEW.maintenance_contract_id
      AND mcp.project_id = NEW.project_id
  ) THEN
    RAISE EXCEPTION
      'El proyecto de la factura no está asociado al contrato de mantenimiento';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_maintenance_invoice_project"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_maintenance_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice public.maintenance_invoices;
BEGIN
  IF NEW.maintenance_invoice_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT *
  INTO v_invoice
  FROM public.maintenance_invoices
  WHERE id = NEW.maintenance_invoice_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'La factura de mantenimiento no existe';
  END IF;

  IF NEW.company_id IS DISTINCT FROM v_invoice.company_id THEN
    RAISE EXCEPTION
      'El payment no pertenece a la misma empresa que la factura de mantenimiento';
  END IF;

  IF NEW.amount < 0 THEN
    RAISE EXCEPTION 'El importe del payment no puede ser negativo';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_maintenance_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_maintenance_project_change_request"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_contract public.maintenance_contracts;
  v_current_project_id UUID;
  v_requested_company_id UUID;
BEGIN
  SELECT *
  INTO v_contract
  FROM public.maintenance_contracts
  WHERE id = NEW.maintenance_contract_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'El contrato de mantenimiento no existe';
  END IF;

  IF NEW.company_id IS DISTINCT FROM v_contract.company_id THEN
    RAISE EXCEPTION 'La solicitud no pertenece a la empresa del contrato';
  END IF;

  IF NOT public.is_live_maintenance_contract_status(v_contract.estado) THEN
    RAISE EXCEPTION 'Solo se puede solicitar un cambio sobre un mantenimiento activo o pausado';
  END IF;

  SELECT mcp.project_id
  INTO v_current_project_id
  FROM public.maintenance_contract_projects mcp
  WHERE mcp.maintenance_contract_id = v_contract.id
  ORDER BY mcp.created_at DESC
  LIMIT 1;

  IF v_current_project_id IS NULL THEN
    RAISE EXCEPTION 'El contrato no tiene un proyecto actual asociado';
  END IF;

  IF NEW.current_project_id IS DISTINCT FROM v_current_project_id THEN
    RAISE EXCEPTION 'El proyecto actual de la solicitud ya no coincide con el proyecto del contrato';
  END IF;

  IF NEW.requested_project_id = v_current_project_id THEN
    RAISE EXCEPTION 'El proyecto solicitado ya es el proyecto actual';
  END IF;

  SELECT p.company_id
  INTO v_requested_company_id
  FROM public.projects p
  WHERE p.id = NEW.requested_project_id;

  IF v_requested_company_id IS NULL THEN
    RAISE EXCEPTION 'El proyecto solicitado no existe o no tiene empresa';
  END IF;

  IF v_requested_company_id IS DISTINCT FROM v_contract.company_id THEN
    RAISE EXCEPTION 'El proyecto solicitado no pertenece a la misma empresa que el contrato';
  END IF;

  -- El proyecto solicitado no puede estar ocupado por otro contrato vivo.
  IF EXISTS (
    SELECT 1
    FROM public.maintenance_contract_projects mcp
    JOIN public.maintenance_contracts other_mc
      ON other_mc.id = mcp.maintenance_contract_id
    WHERE mcp.project_id = NEW.requested_project_id
      AND other_mc.id <> v_contract.id
      AND public.is_live_maintenance_contract_status(other_mc.estado)
  ) THEN
    RAISE EXCEPTION
      'El proyecto solicitado ya está asociado a otro contrato de mantenimiento activo o pausado';
  END IF;

  -- Si ya existe una transición programada distinta, no permitimos
  -- sobrescribirla mediante otra solicitud.
  IF v_contract.pending_project_id IS NOT NULL
     AND v_contract.pending_project_id IS DISTINCT FROM NEW.requested_project_id
  THEN
    RAISE EXCEPTION
      'El contrato ya tiene otro cambio de proyecto pendiente';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_maintenance_project_change_request"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_pending_quotation_client"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_project public.projects;
    v_client public.clients;
BEGIN

    -- --------------------------------------------------------
    -- Solo aplicamos esta regla a presupuestos Pendiente.
    --
    -- Aceptados/Rechazados conservan su histórico.
    -- --------------------------------------------------------

    IF LOWER(TRIM(COALESCE(NEW.estado, ''))) <> 'pendiente' THEN
        RETURN NEW;
    END IF;


    -- --------------------------------------------------------
    -- Proyecto obligatorio
    -- --------------------------------------------------------

    IF NEW.project_id IS NULL THEN
        RAISE EXCEPTION
            'Un presupuesto Pendiente debe estar asociado a un proyecto';
    END IF;


    -- --------------------------------------------------------
    -- Obtener proyecto real
    -- --------------------------------------------------------

    SELECT *
    INTO v_project
    FROM public.projects
    WHERE id = NEW.project_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El proyecto del presupuesto no existe';
    END IF;


    -- --------------------------------------------------------
    -- El proyecto debe tener cliente
    -- --------------------------------------------------------

    IF v_project.client_id IS NULL THEN
        RAISE EXCEPTION
            'El proyecto del presupuesto debe tener un cliente antes de publicar el presupuesto';
    END IF;


    -- --------------------------------------------------------
    -- El quotation debe utilizar exactamente ese cliente
    -- --------------------------------------------------------

    IF NEW.client_id IS NULL THEN
        RAISE EXCEPTION
            'Un presupuesto Pendiente debe tener cliente';
    END IF;


    IF NEW.client_id IS DISTINCT FROM v_project.client_id THEN
        RAISE EXCEPTION
            'El cliente del presupuesto no coincide con el cliente del proyecto';
    END IF;


    -- --------------------------------------------------------
    -- La empresa también debe derivar del proyecto
    -- --------------------------------------------------------

    IF NEW.company_id IS DISTINCT FROM v_project.company_id THEN
        RAISE EXCEPTION
            'La empresa del presupuesto no coincide con la empresa del proyecto';
    END IF;


    -- --------------------------------------------------------
    -- Validar cliente real
    -- --------------------------------------------------------

    SELECT *
    INTO v_client
    FROM public.clients
    WHERE id = NEW.client_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El cliente del presupuesto no existe';
    END IF;


    IF v_client.company_id IS DISTINCT FROM v_project.company_id THEN
        RAISE EXCEPTION
            'El cliente del presupuesto no pertenece a la empresa del proyecto';
    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_pending_quotation_client"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_pending_quotation_client"() IS 'Garantiza que todo presupuesto Pendiente tenga un cliente válido derivado del proyecto y perteneciente a la misma empresa.';



CREATE OR REPLACE FUNCTION "public"."validate_project_client_company"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_client_company UUID;
    v_client_profile UUID;

BEGIN

    -- Un proyecto puede existir sin cliente mientras no se
    -- publique un presupuesto Pendiente.
    IF NEW.client_id IS NULL THEN
        RETURN NEW;
    END IF;


    SELECT
        c.company_id,
        c.profile_id
    INTO
        v_client_company,
        v_client_profile
    FROM public.clients c
    WHERE c.id = NEW.client_id;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El cliente asociado al proyecto no existe';
    END IF;


    -- El cliente debe pertenecer a la empresa del proyecto.

    IF NEW.company_id IS NOT NULL
       AND v_client_company IS DISTINCT FROM NEW.company_id
    THEN
        RAISE EXCEPTION
            'El cliente del proyecto debe pertenecer a la empresa del proyecto';
    END IF;


    -- El cliente debe corresponder al propietario del proyecto.

    IF NEW.user_id IS NOT NULL
       AND v_client_profile IS DISTINCT FROM NEW.user_id
    THEN
        RAISE EXCEPTION
            'El cliente del proyecto debe corresponder al propietario del proyecto';
    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_project_client_company"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_project_owner_company"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$

DECLARE
    v_owner_company UUID;

BEGIN

    IF NEW.user_id IS NULL THEN
        RETURN NEW;
    END IF;


    SELECT company_id
    INTO v_owner_company
    FROM public.profiles
    WHERE id = NEW.user_id;


    IF v_owner_company IS NULL THEN
        RAISE EXCEPTION
            'El propietario del proyecto no tiene empresa asociada';
    END IF;


    IF NEW.company_id IS NOT NULL
       AND v_owner_company IS DISTINCT FROM NEW.company_id
    THEN
        RAISE EXCEPTION
            'El propietario del proyecto debe pertenecer a la empresa del proyecto';
    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_project_owner_company"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_project_task_assignee"("p_worker_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    IF p_worker_id IS NULL THEN
        RETURN;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.workers w
        WHERE w.id = p_worker_id
          AND w.is_active = TRUE
    ) THEN
        RAISE EXCEPTION
            'El trabajador asignado no existe o no está activo';
    END IF;

END;
$$;


