CREATE OR REPLACE FUNCTION "public"."validate_project_task_milestone"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_milestone_project_id UUID;
BEGIN

    -- --------------------------------------------------------
    -- No hay hito: tarea general del proyecto.
    -- --------------------------------------------------------

    IF NEW.milestone_id IS NULL THEN
        RETURN NEW;
    END IF;


    -- --------------------------------------------------------
    -- Obtener proyecto del hito.
    -- --------------------------------------------------------

    SELECT pm.project_id
    INTO v_milestone_project_id
    FROM public.project_milestones pm
    WHERE pm.id = NEW.milestone_id;


    -- --------------------------------------------------------
    -- El hito indicado debe existir.
    -- --------------------------------------------------------

    IF v_milestone_project_id IS NULL THEN
        RAISE EXCEPTION
            'El hito indicado no existe';
    END IF;


    -- --------------------------------------------------------
    -- El hito debe pertenecer al mismo proyecto.
    -- --------------------------------------------------------

    IF v_milestone_project_id IS DISTINCT FROM NEW.project_id THEN
        RAISE EXCEPTION
            'El hito indicado no pertenece al proyecto de la tarea';
    END IF;


    RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."validate_project_task_milestone"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_quotation_workflow_content"("p_content" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_key text;
  v_result jsonb;
  v_number numeric;
BEGIN
  IF p_content IS NULL OR jsonb_typeof(p_content) <> 'object' THEN
    RAISE EXCEPTION 'El contenido del borrador debe ser un objeto JSON';
  END IF;

  FOR v_key IN SELECT jsonb_object_keys(p_content)
  LOOP
    IF v_key NOT IN (
      'titulo', 'descripcion_detallada', 'servicios_incluidos',
      'iva_porcentaje', 'irpf_aplicado', 'irpf_porcentaje',
      'fecha_validez', 'notas'
    ) THEN
      RAISE EXCEPTION 'El campo % no es editable en el borrador', v_key;
    END IF;
  END LOOP;

  v_result := jsonb_build_object(
    'titulo', '',
    'descripcion_detallada', NULL,
    'servicios_incluidos', '[]'::jsonb,
    'iva_porcentaje', 21,
    'irpf_aplicado', false,
    'irpf_porcentaje', 0,
    'fecha_validez', NULL,
    'notas', NULL
  ) || p_content;

  -- Normalizar campos opcionales vacíos que suelen llegar así desde formularios web.
  IF jsonb_typeof(v_result->'descripcion_detallada') = 'string'
     AND btrim(v_result->>'descripcion_detallada') = '' THEN
    v_result := jsonb_set(v_result, '{descripcion_detallada}', 'null'::jsonb, true);
  END IF;
  IF jsonb_typeof(v_result->'fecha_validez') = 'string'
     AND btrim(v_result->>'fecha_validez') = '' THEN
    v_result := jsonb_set(v_result, '{fecha_validez}', 'null'::jsonb, true);
  END IF;
  IF jsonb_typeof(v_result->'notas') = 'string'
     AND btrim(v_result->>'notas') = '' THEN
    v_result := jsonb_set(v_result, '{notas}', 'null'::jsonb, true);
  END IF;

  IF jsonb_typeof(v_result->'titulo') <> 'string'
     OR length(v_result->>'titulo') > 200 THEN
    RAISE EXCEPTION 'El título debe ser texto y no superar 200 caracteres';
  END IF;

  IF v_result->'descripcion_detallada' <> 'null'::jsonb THEN
    IF jsonb_typeof(v_result->'descripcion_detallada') <> 'string'
       OR length(v_result->>'descripcion_detallada') > 10000 THEN
      RAISE EXCEPTION 'La descripción no puede superar 10000 caracteres';
    END IF;
  END IF;

  IF jsonb_typeof(v_result->'servicios_incluidos') <> 'array' THEN
    RAISE EXCEPTION 'Los servicios deben ser un array de hasta 100 elementos';
  END IF;
  IF jsonb_array_length(v_result->'servicios_incluidos') > 100 THEN
    RAISE EXCEPTION 'Los servicios deben ser un array de hasta 100 elementos';
  END IF;

  IF jsonb_typeof(v_result->'irpf_aplicado') <> 'boolean' THEN
    RAISE EXCEPTION 'irpf_aplicado debe ser booleano';
  END IF;

  BEGIN
    v_number := (v_result->>'iva_porcentaje')::numeric;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'El porcentaje de IVA no es válido';
  END;
  IF v_number < 0 OR v_number > 100 THEN
    RAISE EXCEPTION 'El porcentaje de IVA debe estar entre 0 y 100';
  END IF;
  v_result := jsonb_set(v_result, '{iva_porcentaje}', to_jsonb(round(v_number, 2)), true);

  BEGIN
    v_number := (v_result->>'irpf_porcentaje')::numeric;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'El porcentaje de IRPF no es válido';
  END;
  IF v_number < 0 OR v_number > 100 THEN
    RAISE EXCEPTION 'El porcentaje de IRPF debe estar entre 0 y 100';
  END IF;
  IF (v_result->>'irpf_aplicado')::boolean = false AND v_number <> 0 THEN
    RAISE EXCEPTION 'Si el IRPF no se aplica, su porcentaje debe ser 0';
  END IF;
  IF (v_result->>'irpf_aplicado')::boolean = true AND v_number <= 0 THEN
    RAISE EXCEPTION 'Si el IRPF se aplica, su porcentaje debe ser mayor que 0';
  END IF;
  v_result := jsonb_set(v_result, '{irpf_porcentaje}', to_jsonb(round(v_number, 2)), true);

  IF v_result->'notas' <> 'null'::jsonb THEN
    IF jsonb_typeof(v_result->'notas') <> 'string'
       OR length(v_result->>'notas') > 5000 THEN
      RAISE EXCEPTION 'Las notas no pueden superar 5000 caracteres';
    END IF;
  END IF;

  IF v_result->'fecha_validez' <> 'null'::jsonb THEN
    IF jsonb_typeof(v_result->'fecha_validez') <> 'string' THEN
      RAISE EXCEPTION 'La fecha de validez debe ser texto ISO o null';
    END IF;
    BEGIN
      PERFORM (v_result->>'fecha_validez')::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'La fecha de validez no es válida';
    END;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."validate_quotation_workflow_content"("p_content" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."version_quotation_before_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- Un presupuesto aceptado está contractualmente congelado.
    IF OLD.estado = 'Aceptado' THEN
        RAISE EXCEPTION
            'El presupuesto aceptado está contractualmente congelado y no puede modificarse';
    END IF;

    -- Solo versionar ediciones de presupuestos que continúan pendientes.
    IF OLD.estado = 'Pendiente'
       AND NEW.estado = 'Pendiente' THEN

        -- Incrementar únicamente si cambia el contenido del presupuesto.
        -- Los cambios exclusivos de document_path, document_sha256 o
        -- updated_at no incrementan la versión.
        IF OLD.company_id IS DISTINCT FROM NEW.company_id
           OR OLD.user_id IS DISTINCT FROM NEW.user_id
           OR OLD.project_id IS DISTINCT FROM NEW.project_id
           OR OLD.client_id IS DISTINCT FROM NEW.client_id
           OR OLD.numero_presupuesto IS DISTINCT FROM NEW.numero_presupuesto
           OR OLD.titulo IS DISTINCT FROM NEW.titulo
           OR OLD.descripcion_detallada IS DISTINCT FROM NEW.descripcion_detallada
           OR OLD.servicios_incluidos IS DISTINCT FROM NEW.servicios_incluidos
           OR OLD.precio_base IS DISTINCT FROM NEW.precio_base
           OR OLD.iva_porcentaje IS DISTINCT FROM NEW.iva_porcentaje
           OR OLD.precio_total IS DISTINCT FROM NEW.precio_total
           OR OLD.irpf_aplicado IS DISTINCT FROM NEW.irpf_aplicado
           OR OLD.irpf_porcentaje IS DISTINCT FROM NEW.irpf_porcentaje
           OR OLD.irpf_importe IS DISTINCT FROM NEW.irpf_importe
           OR OLD.fecha_emision IS DISTINCT FROM NEW.fecha_emision
           OR OLD.fecha_validez IS DISTINCT FROM NEW.fecha_validez
           OR OLD.notas IS DISTINCT FROM NEW.notas
           OR OLD.issuer_legal_name IS DISTINCT FROM NEW.issuer_legal_name
           OR OLD.issuer_tax_id IS DISTINCT FROM NEW.issuer_tax_id
           OR OLD.issuer_address IS DISTINCT FROM NEW.issuer_address
           OR OLD.issuer_postal_code IS DISTINCT FROM NEW.issuer_postal_code
           OR OLD.issuer_city IS DISTINCT FROM NEW.issuer_city
           OR OLD.issuer_province IS DISTINCT FROM NEW.issuer_province
           OR OLD.issuer_country IS DISTINCT FROM NEW.issuer_country
           OR OLD.customer_legal_name IS DISTINCT FROM NEW.customer_legal_name
           OR OLD.customer_tax_id IS DISTINCT FROM NEW.customer_tax_id
           OR OLD.customer_address IS DISTINCT FROM NEW.customer_address
           OR OLD.customer_postal_code IS DISTINCT FROM NEW.customer_postal_code
           OR OLD.customer_city IS DISTINCT FROM NEW.customer_city
           OR OLD.customer_province IS DISTINCT FROM NEW.customer_province
           OR OLD.customer_country IS DISTINCT FROM NEW.customer_country
           OR OLD.customer_contact_name IS DISTINCT FROM NEW.customer_contact_name
        THEN
            NEW.quotation_version := OLD.quotation_version + 1;
        ELSE
            NEW.quotation_version := OLD.quotation_version;
        END IF;

    ELSE
        -- Al cambiar de estado, se conserva la versión actual.
        NEW.quotation_version := OLD.quotation_version;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."version_quotation_before_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."worker_assign_maintenance_contract_project"("p_contract_id" "uuid", "p_project_id" "uuid") RETURNS "public"."maintenance_contract_projects"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_contract public.maintenance_contracts;
    v_project public.projects;
    v_row public.maintenance_contract_projects;
BEGIN

    PERFORM public.require_current_worker_permission(
        'maintenance.update'
    );

    SELECT *
    INTO v_contract
    FROM public.maintenance_contracts
    WHERE id = p_contract_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El contrato de mantenimiento no existe';
    END IF;

    SELECT *
    INTO v_project
    FROM public.projects
    WHERE id = p_project_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El proyecto no existe';
    END IF;

    IF v_project.company_id IS NULL
       OR v_project.company_id IS DISTINCT FROM v_contract.company_id
    THEN
        RAISE EXCEPTION
            'El proyecto no pertenece a la empresa del contrato';
    END IF;

    INSERT INTO public.maintenance_contract_projects (
        maintenance_contract_id,
        project_id
    )
    VALUES (
        p_contract_id,
        p_project_id
    )
    ON CONFLICT (
        maintenance_contract_id,
        project_id
    )
    DO NOTHING
    RETURNING *
    INTO v_row;

    IF v_row.id IS NULL THEN

        SELECT *
        INTO v_row
        FROM public.maintenance_contract_projects
        WHERE maintenance_contract_id = p_contract_id
          AND project_id = p_project_id;

    END IF;

    RETURN v_row;

END;
$$;


ALTER FUNCTION "public"."worker_assign_maintenance_contract_project"("p_contract_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."worker_assign_maintenance_contract_project"("p_contract_id" "uuid", "p_project_id" "uuid") IS 'Permite a un worker asociar un proyecto de la misma empresa a un contrato de mantenimiento.';



CREATE OR REPLACE FUNCTION "public"."worker_can_read_maintenance_proposal_storage_path"("p_storage_path" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$

BEGIN

    IF auth.uid() IS NULL THEN
        RETURN FALSE;
    END IF;

    IF NOT public.current_user_is_worker() THEN
        RETURN FALSE;
    END IF;

    IF p_storage_path IS NULL
       OR p_storage_path !~
          '^[0-9a-fA-F-]{36}/[^/]+\.pdf$'
    THEN
        RETURN FALSE;
    END IF;

    RETURN EXISTS (
        SELECT 1
        FROM public.maintenance_custom_proposals p
        WHERE p.id::TEXT = SPLIT_PART(
            p_storage_path,
            '/',
            1
        )
    );

END;
$_$;


ALTER FUNCTION "public"."worker_can_read_maintenance_proposal_storage_path"("p_storage_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."worker_can_write_maintenance_proposal_storage_path"("p_storage_path" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$

BEGIN

    IF auth.uid() IS NULL THEN
        RETURN FALSE;
    END IF;

    IF NOT public.current_user_is_worker() THEN
        RETURN FALSE;
    END IF;

    IF p_storage_path IS NULL THEN
        RETURN FALSE;
    END IF;

    -- Formato:
    -- <proposal_uuid>/<archivo>.pdf
    IF p_storage_path !~
       '^[0-9a-fA-F-]{36}/[^/]+\.pdf$'
    THEN
        RETURN FALSE;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.maintenance_custom_proposals p
        WHERE p.id::TEXT = SPLIT_PART(
            p_storage_path,
            '/',
            1
        )
        AND p.status IN (
            'submitted',
            'in_review',
            'clarification_requested'
        )
    ) THEN
        RETURN FALSE;
    END IF;

    PERFORM public.enforce_security_rate_limit(
        'maintenance_proposal_storage_upload:' || auth.uid()::TEXT,
        20,
        3600
    );

    RETURN TRUE;

END;
$_$;


ALTER FUNCTION "public"."worker_can_write_maintenance_proposal_storage_path"("p_storage_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."worker_can_write_quotation_storage_path"("p_storage_path" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  v_allowed boolean := false;
BEGIN
  IF auth.uid() IS NULL OR NOT public.current_user_is_worker() OR p_storage_path IS NULL THEN
    RETURN false;
  END IF;

  -- Ruta histórica: <company_uuid>/<numero_presupuesto>.pdf
  IF p_storage_path ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[^/]+\.pdf$' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.quotations q
      WHERE q.company_id::text || '/' || q.numero_presupuesto || '.pdf' = p_storage_path
    ) INTO v_allowed;
    IF v_allowed THEN RETURN true; END IF;
  END IF;

  -- Ruta nueva: <company_uuid>/<numero_presupuesto>/Vn[.m].pdf
  IF p_storage_path ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[^/]+/v[1-9][0-9]*(\.[1-9][0-9]*)?\.pdf$' THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.quotation_official_versions ov
      JOIN public.quotations q ON q.id = ov.quotation_id
      WHERE lower(q.company_id::text || '/' || q.numero_presupuesto || '/' || ov.version_label || '.pdf') = lower(p_storage_path)
        AND (
          public.current_worker_has_permission('quotations.update')
          OR public.current_worker_has_permission('quotations.create')
        )
    ) INTO v_allowed;
    IF v_allowed THEN RETURN true; END IF;
  END IF;

  RETURN false;
END;
$_$;


ALTER FUNCTION "public"."worker_can_write_quotation_storage_path"("p_storage_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."worker_unassign_maintenance_contract_project"("p_contract_id" "uuid", "p_project_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN

    PERFORM public.require_current_worker_permission(
        'maintenance.update'
    );

    IF NOT EXISTS (
        SELECT 1
        FROM public.maintenance_contracts
        WHERE id = p_contract_id
    ) THEN
        RAISE EXCEPTION
            'El contrato de mantenimiento no existe';
    END IF;

    DELETE FROM public.maintenance_contract_projects
    WHERE maintenance_contract_id = p_contract_id
      AND project_id = p_project_id;

    RETURN FOUND;

END;
$$;


