    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "company_iva_change_requests_iva_check" CHECK (((("requested_iva_aplicado" = true) AND ("requested_iva_porcentaje" >= (0)::numeric) AND ("requested_iva_porcentaje" <= (100)::numeric)) OR (("requested_iva_aplicado" = false) AND ("requested_iva_porcentaje" = (0)::numeric)))),
    CONSTRAINT "company_iva_change_requests_reason_length_check" CHECK (((("char_length"("reason") >= 1) AND ("char_length"("reason") <= 2000)) AND ("pg_column_size"("reason") <= 16384))),
    CONSTRAINT "company_iva_change_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'in_review'::"text", 'approved'::"text", 'rejected'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "company_iva_change_requests_worker_notes_length_check" CHECK ((("worker_notes" IS NULL) OR (("char_length"("worker_notes") <= 2000) AND ("pg_column_size"("worker_notes") <= 16384))))
);


ALTER TABLE "public"."company_iva_change_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."company_iva_change_requests" IS 'Solicitudes de tratamiento de IVA general realizadas por clientes para su empresa. El sistema es independiente del IVA recomendado por workers y del IVA específico de mantenimiento.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."id" IS 'Identificador único de la solicitud de IVA general.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."company_id" IS 'Empresa para la que se solicita el tratamiento fiscal. Se obtiene de la empresa actual del usuario y no debe ser proporcionada arbitrariamente por el frontend.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."user_id" IS 'Usuario cliente que presentó la solicitud de IVA general.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."requested_iva_aplicado" IS 'Indica si el cliente solicita que se aplique IVA en el tratamiento fiscal general de la empresa.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."requested_iva_porcentaje" IS 'Porcentaje de IVA general solicitado por el cliente. Debe estar entre 0 y 100 cuando el IVA está aplicado y debe ser 0 cuando no está aplicado.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."reason" IS 'Justificación proporcionada por el cliente para solicitar el tratamiento de IVA indicado. Máximo 2.000 caracteres y 16 KiB.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."status" IS 'Estado de la solicitud: pending, in_review, approved, rejected o cancelled.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."reviewed_by" IS 'Usuario de Auth del worker que resolvió la solicitud.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."reviewed_at" IS 'Fecha y hora en que el worker resolvió la solicitud.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."worker_notes" IS 'Notas internas introducidas por el worker al revisar o resolver la solicitud. Máximo 2.000 caracteres y 16 KiB.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."created_at" IS 'Fecha y hora de creación de la solicitud.';



COMMENT ON COLUMN "public"."company_iva_change_requests"."updated_at" IS 'Fecha y hora de la última modificación de la solicitud.';



