    "employer_social_security" numeric(12,2) DEFAULT 0 NOT NULL,
    "other_employer_costs" numeric(12,2) DEFAULT 0 NOT NULL,
    "total_employer_cost" numeric(12,2) GENERATED ALWAYS AS ((("gross_salary" + "employer_social_security") + "other_employer_costs")) STORED,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "payment_date" "date",
    "notes" "text",
    "created_by" "uuid",
