    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "payroll_records_nonnegative_amounts" CHECK ((("gross_salary" >= (0)::numeric) AND ("employee_deductions" >= (0)::numeric) AND ("net_salary" >= (0)::numeric) AND ("employer_social_security" >= (0)::numeric) AND ("other_employer_costs" >= (0)::numeric))),
    CONSTRAINT "payroll_records_payment_date_matches_status" CHECK ((("status" = 'paid'::"text") = ("payment_date" IS NOT NULL))),
    CONSTRAINT "payroll_records_valid_period" CHECK (((("period_year" >= 2000) AND ("period_year" <= 2200)) AND (("period_month" >= 1) AND ("period_month" <= 12)))),
    CONSTRAINT "payroll_records_valid_status" CHECK (("status" = ANY (ARRAY['draft'::"text", 'approved'::"text", 'paid'::"text", 'cancelled'::"text"])))
);

