CREATE OR REPLACE VIEW "public"."payroll_financial_summary" WITH ("security_invoker"='true') AS
 SELECT "period_year",
    "period_month",
    "count"(*) AS "payroll_count",
    ("sum"("gross_salary"))::numeric(14,2) AS "gross_salary_total",
    ("sum"("employer_social_security"))::numeric(14,2) AS "employer_social_security_total",
    ("sum"("other_employer_costs"))::numeric(14,2) AS "other_employer_costs_total",
    ("sum"("total_employer_cost"))::numeric(14,2) AS "total_employer_cost"
   FROM "public"."payroll_records" "pr"
  WHERE ("status" = ANY (ARRAY['approved'::"text", 'paid'::"text"]))
  GROUP BY "period_year", "period_month";


ALTER VIEW "public"."payroll_financial_summary" OWNER TO "postgres";


