CREATE OR REPLACE VIEW "public"."project_progress" WITH ("security_invoker"='true') AS
 SELECT "p"."id" AS "project_id",
    ("count"("pm"."id"))::integer AS "total_milestones",
    ("count"("pm"."id") FILTER (WHERE ("pm"."estado" = 'completado'::"text")))::integer AS "completed_milestones",
        CASE
            WHEN ("count"("pm"."id") = 0) THEN 0
            ELSE ("round"(((("count"("pm"."id") FILTER (WHERE ("pm"."estado" = 'completado'::"text")))::numeric / ("count"("pm"."id"))::numeric) * (100)::numeric)))::integer
        END AS "progress_percentage"
   FROM ("public"."projects" "p"
     LEFT JOIN "public"."project_milestones" "pm" ON (("pm"."project_id" = "p"."id")))
  GROUP BY "p"."id";


ALTER VIEW "public"."project_progress" OWNER TO "postgres";


COMMENT ON VIEW "public"."project_progress" IS 'Progreso calculado de cada proyecto a partir de sus hitos completados. No almacena un porcentaje físico en projects.';



