CREATE TABLE IF NOT EXISTS "public"."stripe_webhook_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "stripe_event_id" character varying(255) NOT NULL,
    "event_type" character varying(255) NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "status" "text" DEFAULT 'processed'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "processing_started_at" timestamp with time zone,
    "processed_at" timestamp with time zone,
    "last_error" "text",
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "stripe_webhook_events_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "stripe_webhook_events_processed_state_check" CHECK (((("status" = 'processed'::"text") AND ("processed_at" IS NOT NULL)) OR ("status" = ANY (ARRAY['processing'::"text", 'failed'::"text"])))),
    CONSTRAINT "stripe_webhook_events_processing_state_check" CHECK (((("status" = 'processing'::"text") AND ("processing_started_at" IS NOT NULL)) OR (("status" = ANY (ARRAY['processed'::"text", 'failed'::"text"])) AND ("processing_started_at" IS NULL)))),
    CONSTRAINT "stripe_webhook_events_status_check" CHECK (("status" = ANY (ARRAY['processing'::"text", 'processed'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."stripe_webhook_events" OWNER TO "postgres";


